package com.irc;

import java.util.ArrayList;
import java.util.List;

/**
 * The buffers the user has looked at, for Alt+/ (back to the last one) and
 * {@code Alt+<} / {@code Alt+>} (walk the history).
 *
 * Entries are ordered by when they were last shown, oldest first, each buffer once. Walking the
 * history moves {@link #cursor} without reordering; switching buffers any other way moves the
 * buffer being left and the one being opened to the end, so {@code Alt+<} always steps back to the
 * buffer shown just before.
 */
class BufferHistory {

    private final int capacity;
    private final List<BufferKey> entries = new ArrayList<>();
    /** Index of the shown buffer in {@link #entries}; -1 when it isn't there. */
    private int cursor = -1;
    private BufferKey current;
    /** The buffer shown before {@link #current}, however the user got there. */
    private BufferKey previous;

    BufferHistory(int capacity) {
        this.capacity = capacity;
    }

    /** Records that {@code key} is now shown. Showing the same buffer again changes nothing. */
    void visit(BufferKey key) {
        if (key == null || key.equals(current)) return;
        if (current != null) previous = current;
        current = key;
        if (cursor >= 0 && entries.get(cursor).equals(key)) return;
        if (cursor >= 0 && cursor < entries.size() - 1) entries.add(entries.remove(cursor));
        entries.remove(key);
        entries.add(key);
        if (entries.size() > capacity) entries.remove(0);
        cursor = entries.size() - 1;
    }

    /** The buffer shown before the current one, or null when there is none. */
    BufferKey last() {
        return previous;
    }

    /** Steps back through the history; returns the buffer to show, or null at the oldest. */
    BufferKey back() {
        if (cursor <= 0) return null;
        return entries.get(--cursor);
    }

    /** Steps forward through the history; returns the buffer to show, or null at the newest. */
    BufferKey forward() {
        if (cursor < 0 || cursor >= entries.size() - 1) return null;
        return entries.get(++cursor);
    }

    /** Forgets a closed buffer. */
    void remove(BufferKey key) {
        int index = entries.indexOf(key);
        if (index >= 0) {
            entries.remove(index);
            if (index == cursor) cursor = -1;
            else if (index < cursor) cursor--;
        }
        if (key.equals(previous)) previous = null;
        if (key.equals(current)) current = null;
    }

    /** Follows a buffer renamed in place, such as a query whose nick changed. */
    void rename(BufferKey oldKey, BufferKey newKey) {
        int index = entries.indexOf(oldKey);
        if (index >= 0) entries.set(index, newKey);
        if (oldKey.equals(previous)) previous = newKey;
        if (oldKey.equals(current)) current = newKey;
    }
}

package com.irc;

import java.util.Locale;
import java.util.Objects;

/**
 * A buffer's identity: the network it lives on and its name there. Names compare exactly, as tab
 * titles always have; case-insensitive lookups (rosters, topics) go through {@link #folded()}.
 */
final class BufferKey {
    private final String networkId;
    private final String name;

    private BufferKey(String networkId, String name) {
        this.networkId = Objects.requireNonNull(networkId, "networkId");
        this.name = Objects.requireNonNull(name, "name");
    }

    static BufferKey of(String networkId, String name) {
        return new BufferKey(networkId, name);
    }

    static BufferKey swiftIrc(String name) {
        return new BufferKey(NetworkConfig.SWIFTIRC_ID, name);
    }

    String getNetworkId() {
        return networkId;
    }

    String getName() {
        return name;
    }

    /** The same buffer with its name lower-cased, for maps that must ignore IRC name casing. */
    BufferKey folded() {
        return new BufferKey(networkId, name.toLowerCase(Locale.ROOT));
    }

    boolean isChannel() {
        return name.startsWith("#") || name.startsWith("&");
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof BufferKey)) return false;
        BufferKey other = (BufferKey) o;
        return networkId.equals(other.networkId) && name.equals(other.name);
    }

    @Override
    public int hashCode() {
        return Objects.hash(networkId, name);
    }

    /** The bare name: JTree and list renderers display a key through toString. */
    @Override
    public String toString() {
        return name;
    }
}

package com.irc;

import javax.swing.BorderFactory;
import javax.swing.JButton;
import javax.swing.JDialog;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.JTable;
import javax.swing.JTextField;
import javax.swing.KeyStroke;
import javax.swing.ListSelectionModel;
import javax.swing.RowSorter;
import javax.swing.SortOrder;
import javax.swing.SwingConstants;
import javax.swing.event.DocumentEvent;
import javax.swing.event.DocumentListener;
import javax.swing.table.DefaultTableCellRenderer;
import javax.swing.table.TableRowSorter;
import java.awt.BorderLayout;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.Window;
import java.awt.event.KeyEvent;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.Collections;
import java.util.List;
import java.util.function.BiConsumer;
import java.util.function.Consumer;

/**
 * The channel browser: the server's LIST result as a sortable, filterable table.
 *
 * Non-modal and reused across requests, so a repeated /list refreshes this window instead of
 * stacking new ones. It stays open after a join - browsing and joining are usually iterative.
 *
 * All data logic lives in {@link ChannelListTableModel}; this class is wiring only.
 */
public class ChannelListDialog extends JDialog {
    private final ChannelListTableModel model = new ChannelListTableModel();
    private final JTable table = new JTable(model);
    private final JTextField filterField = new JTextField();
    private final JLabel statusLabel = new JLabel();
    private final BiConsumer<String, String> onJoin;

    /** The query behind the current contents, replayed by Refresh. */
    private String query = "";
    private boolean truncated = false;

    public ChannelListDialog(Window owner, BiConsumer<String, String> onJoin, Consumer<String> onRefresh) {
        super(owner, "Channel List");
        this.onJoin = onJoin;
        setDefaultCloseOperation(HIDE_ON_CLOSE);

        table.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);
        table.setAutoCreateRowSorter(false);
        table.setFillsViewportHeight(true);

        TableRowSorter<ChannelListTableModel> sorter = new TableRowSorter<>(model);
        table.setRowSorter(sorter);
        sorter.setSortKeys(Collections.singletonList(
                new RowSorter.SortKey(1, SortOrder.DESCENDING)));

        table.getColumnModel().getColumn(0).setPreferredWidth(180);
        table.getColumnModel().getColumn(1).setPreferredWidth(60);
        table.getColumnModel().getColumn(2).setPreferredWidth(440);
        table.getColumnModel().getColumn(2).setCellRenderer(new TopicRenderer());

        table.addMouseListener(new MouseAdapter() {
            @Override
            public void mouseClicked(MouseEvent e) {
                if (e.getClickCount() == 2) {
                    joinSelected();
                }
            }
        });
        table.getInputMap(JTable.WHEN_ANCESTOR_OF_FOCUSED_COMPONENT)
                .put(KeyStroke.getKeyStroke(KeyEvent.VK_ENTER, 0), "joinSelected");
        table.getActionMap().put("joinSelected", new javax.swing.AbstractAction() {
            @Override
            public void actionPerformed(java.awt.event.ActionEvent e) {
                joinSelected();
            }
        });

        filterField.getDocument().addDocumentListener(new DocumentListener() {
            @Override
            public void insertUpdate(DocumentEvent e) {
                refilter();
            }

            @Override
            public void removeUpdate(DocumentEvent e) {
                refilter();
            }

            @Override
            public void changedUpdate(DocumentEvent e) {
                refilter();
            }
        });

        JPanel top = new JPanel(new BorderLayout(6, 0));
        top.setBorder(BorderFactory.createEmptyBorder(6, 6, 6, 6));
        top.add(new JLabel("Filter:"), BorderLayout.WEST);
        top.add(filterField, BorderLayout.CENTER);

        JButton refreshButton = new JButton("Refresh");
        refreshButton.addActionListener(e -> {
            if (onRefresh != null) {
                onRefresh.accept(query);
            }
        });
        JButton joinButton = new JButton("Join");
        joinButton.addActionListener(e -> joinSelected());

        JPanel buttons = new JPanel();
        buttons.add(joinButton);
        buttons.add(refreshButton);

        statusLabel.setHorizontalAlignment(SwingConstants.LEFT);
        statusLabel.setBorder(BorderFactory.createEmptyBorder(0, 8, 0, 0));

        JPanel bottom = new JPanel(new BorderLayout());
        bottom.add(statusLabel, BorderLayout.CENTER);
        bottom.add(buttons, BorderLayout.EAST);

        setLayout(new BorderLayout());
        add(top, BorderLayout.NORTH);
        add(new JScrollPane(table), BorderLayout.CENTER);
        add(bottom, BorderLayout.SOUTH);
        setPreferredSize(new Dimension(700, 450));
        pack();
        setLocationRelativeTo(owner);
    }

    /** Replaces the contents. {@code query} is what Refresh will replay. */
    public void setEntries(List<ChannelListEntry> entries, String query, boolean truncated) {
        this.query = query != null ? query : "";
        this.truncated = truncated;
        model.setEntries(entries);
        updateStatus();
    }

    public void showDialog() {
        setVisible(true);
        toFront();
        filterField.requestFocusInWindow();
    }

    private void refilter() {
        model.setFilter(filterField.getText());
        updateStatus();
    }

    private void updateStatus() {
        StringBuilder status = new StringBuilder();
        status.append(model.getTotalCount()).append(" channels");
        if (model.getShownCount() != model.getTotalCount()) {
            status.append(" · ").append(model.getShownCount()).append(" shown");
        }
        if (truncated) {
            status.append(" · truncated");
        }
        statusLabel.setText(status.toString());
    }

    /** Joins the selected channel with no key; a keyed channel falls into the 475 prompt. */
    private void joinSelected() {
        int viewRow = table.getSelectedRow();
        if (viewRow < 0 || onJoin == null) {
            return;
        }
        ChannelListEntry entry = model.getEntryAt(table.convertRowIndexToModel(viewRow));
        onJoin.accept(entry.getName(), "");
    }

    /**
     * Puts the full topic in a tooltip. Most real topics are longer than the Topic column is wide
     * and render as "Ask about quest hel...", with no other way to read the rest.
     *
     * Package-private rather than private so the tooltip can be asserted without constructing this
     * dialog, which needs a {@link Window} and so throws on a headless machine.
     */
    static class TopicRenderer extends DefaultTableCellRenderer {
        @Override
        public Component getTableCellRendererComponent(JTable table, Object value, boolean isSelected,
                                                       boolean hasFocus, int row, int column) {
            Component rendered = super.getTableCellRendererComponent(
                    table, value, isSelected, hasFocus, row, column);
            String text = value != null ? value.toString() : "";
            // Null, not "": an empty tooltip still pops an empty box open on hover.
            setToolTipText(text.isEmpty() ? null : text);
            return rendered;
        }
    }
}

package com.irc;

import lombok.Getter;

/** One row of a server's LIST reply: a channel, its user count, and its topic. Immutable. */
@Getter
public class ChannelListEntry {
    private final String name;
    private final int userCount;
    private final String topic;

    public ChannelListEntry(String name, int userCount, String topic) {
        this.name = name;
        this.userCount = userCount;
        this.topic = topic;
    }
}

package com.irc;

import javax.swing.table.AbstractTableModel;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Locale;

/**
 * The channel browser's data layer: the full LIST result, the filtered view of it, and the
 * mapping from a table row back to its entry.
 *
 * This is deliberately separate from {@link ChannelListDialog} so it can be unit-tested without
 * constructing a Window, which throws HeadlessException on a headless machine.
 *
 * Topics are stripped of IRC formatting codes once, up front - when the entries are set, not when
 * a cell is painted or a filter is applied. The filter then matches the same stripped text the
 * user is looking at, rather than raw codes they cannot see, without re-running the stripper per
 * row per keystroke: at the 20,000-row cap that would be 20,000 regex passes for every character
 * typed into the filter box, all of it on the EDT.
 */
public class ChannelListTableModel extends AbstractTableModel {
    private static final String[] COLUMNS = {"Channel", "Users", "Topic"};

    private List<Row> allRows = Collections.emptyList();
    private List<Row> shownRows = Collections.emptyList();
    private String filter = "";

    /**
     * An entry plus everything derived from it that the table and the filter would otherwise
     * recompute on every repaint and every keystroke.
     *
     * The precomputation lives here rather than on {@link ChannelListEntry} because that class is
     * immutable and shared with the client's LIST snapshot, which has no interest in display
     * concerns.
     */
    private static final class Row {
        private final ChannelListEntry entry;
        private final String topic;
        private final String nameLower;
        private final String topicLower;

        private Row(ChannelListEntry entry) {
            this.entry = entry;
            this.topic = displayTopic(entry);
            String name = entry.getName() != null ? entry.getName() : "";
            this.nameLower = name.toLowerCase(Locale.ROOT);
            this.topicLower = this.topic.toLowerCase(Locale.ROOT);
        }

        /** {@code needle} must already be trimmed, lower-cased and non-empty. */
        private boolean matches(String needle) {
            return nameLower.contains(needle) || topicLower.contains(needle);
        }
    }

    /** Replaces the backing data and reapplies the active filter. */
    public void setEntries(List<ChannelListEntry> entries) {
        List<Row> rows = new ArrayList<>(entries != null ? entries.size() : 0);
        if (entries != null) {
            for (ChannelListEntry entry : entries) {
                rows.add(new Row(entry));
            }
        }
        allRows = rows;
        applyFilter();
    }

    /** Narrows the view. A null or blank filter shows everything. */
    public void setFilter(String filter) {
        this.filter = filter != null ? filter : "";
        applyFilter();
    }

    private void applyFilter() {
        String needle = needle(filter);
        if (needle.isEmpty()) {
            shownRows = allRows;
        } else {
            List<Row> matched = new ArrayList<>();
            for (Row row : allRows) {
                if (row.matches(needle)) {
                    matched.add(row);
                }
            }
            shownRows = matched;
        }
        fireTableDataChanged();
    }

    /** The comparable form of a filter string. Empty means "match everything". */
    private static String needle(String filter) {
        return filter == null ? "" : filter.trim().toLowerCase(Locale.ROOT);
    }

    /**
     * Case-insensitive substring match against the channel name and the stripped topic.
     *
     * Off the hot path - the model filters against precomputed rows - but kept as the single
     * definition of the rule, and testable without a table.
     */
    public static boolean matches(ChannelListEntry entry, String filter) {
        String needle = needle(filter);
        return needle.isEmpty() || new Row(entry).matches(needle);
    }

    /** The topic as the user sees it: formatting codes removed, never null. */
    static String displayTopic(ChannelListEntry entry) {
        String topic = entry.getTopic();
        if (topic == null) {
            return "";
        }
        String stripped = IrcFormatting.stripCodes(topic);
        return stripped != null ? stripped : "";
    }

    /** The entry behind a model row. Callers must convert view rows first. */
    public ChannelListEntry getEntryAt(int rowIndex) {
        return shownRows.get(rowIndex).entry;
    }

    public int getTotalCount() {
        return allRows.size();
    }

    public int getShownCount() {
        return shownRows.size();
    }

    @Override
    public int getRowCount() {
        return shownRows.size();
    }

    @Override
    public int getColumnCount() {
        return COLUMNS.length;
    }

    @Override
    public String getColumnName(int column) {
        return COLUMNS[column];
    }

    /**
     * Users is Integer so TableRowSorter sorts it numerically. As String, 9 would outrank 412.
     */
    @Override
    public Class<?> getColumnClass(int columnIndex) {
        return columnIndex == 1 ? Integer.class : String.class;
    }

    @Override
    public Object getValueAt(int rowIndex, int columnIndex) {
        Row row = shownRows.get(rowIndex);
        switch (columnIndex) {
            case 0:
                return row.entry.getName();
            case 1:
                return row.entry.getUserCount();
            case 2:
                return row.topic;
            default:
                return "";
        }
    }

    @Override
    public boolean isCellEditable(int rowIndex, int columnIndex) {
        return false;
    }
}

package com.irc;

import java.awt.Component;
import java.awt.Container;
import java.awt.event.ContainerEvent;
import java.awt.event.ContainerListener;
import java.awt.event.FocusAdapter;
import java.awt.event.FocusEvent;
import java.awt.event.FocusListener;
import java.awt.event.KeyEvent;
import java.awt.event.KeyListener;
import java.util.function.IntConsumer;

/**
 * WeeChat-style buffer number keys, active while focus is inside {@code root}: Alt+1 to Alt+9 jump
 * straight to that buffer and Alt+0 to the tenth, and Alt+J followed by two digits jumps to any
 * buffer (Alt+J 1 1 for the eleventh). Alt+H marks every buffer read. Alt+/ goes back to the
 * buffer shown last, and {@code Alt+<} / {@code Alt+>} (or Alt+, / Alt+.) walk back and forth
 * through the buffers visited. Alt+Up / Alt+Down move to the buffer above or below, wrapping
 * around at either end.
 *
 * A key listener on every component under {@code root} rather than key bindings, because the
 * KEY_TYPED that follows a handled key press must be swallowed too: otherwise the digits after
 * Alt+J land in the input box, as does the character macOS produces for Option+digit. Consuming
 * the event in a listener stops Swing's key bindings, text entry included.
 */
final class ChannelNumberKeys implements KeyListener, ContainerListener {
    private final Component root;
    /** A pending Alt+J doesn't survive focus moving elsewhere. */
    private final FocusListener focusListener = new FocusAdapter() {
        @Override
        public void focusLost(FocusEvent e) { reset(); }
    };
    private final IntConsumer jump;
    private final Runnable markAllRead;
    private final Runnable lastBuffer;
    private final Runnable historyBack;
    private final Runnable historyForward;
    /** Receives -1 for the buffer above, +1 for the one below. */
    private final IntConsumer step;
    /** Digits typed since Alt+J; null when no jump is pending. */
    private String digits;
    private boolean swallowTyped;

    ChannelNumberKeys(Component root, IntConsumer jump, Runnable markAllRead, Runnable lastBuffer,
                      Runnable historyBack, Runnable historyForward, IntConsumer step) {
        this.root = root;
        this.jump = jump;
        this.markAllRead = markAllRead;
        this.lastBuffer = lastBuffer;
        this.historyBack = historyBack;
        this.historyForward = historyForward;
        this.step = step;
    }

    void install() {
        attach(root);
    }

    void uninstall() {
        detach(root);
        reset();
    }

    @Override
    public void keyPressed(KeyEvent e) {
        if (handle(e)) e.consume();
    }

    @Override
    public void keyTyped(KeyEvent e) {
        if (handle(e)) e.consume();
    }

    @Override
    public void keyReleased(KeyEvent e) {}

    @Override
    public void componentAdded(ContainerEvent e) { attach(e.getChild()); }

    @Override
    public void componentRemoved(ContainerEvent e) { detach(e.getChild()); }

    private void attach(Component component) {
        // Removing first keeps a component that is re-added from getting a second listener.
        detach(component);
        component.addKeyListener(this);
        component.addFocusListener(focusListener);
        if (component instanceof Container) {
            Container container = (Container) component;
            container.addContainerListener(this);
            for (Component child : container.getComponents()) attach(child);
        }
    }

    private void detach(Component component) {
        component.removeKeyListener(this);
        component.removeFocusListener(focusListener);
        if (component instanceof Container) {
            Container container = (Container) component;
            container.removeContainerListener(this);
            for (Component child : container.getComponents()) detach(child);
        }
    }

    private void reset() {
        digits = null;
        swallowTyped = false;
    }

    /** Returns true when the event belongs to a channel jump and must not reach the component. */
    boolean handle(KeyEvent e) {
        if (e.getID() == KeyEvent.KEY_TYPED) return swallowTyped;
        if (e.getID() != KeyEvent.KEY_PRESSED) return false;

        swallowTyped = false;
        int code = e.getKeyCode();
        int digit = digitOf(code);
        if (digits != null) {
            if (isModifier(code)) return false;
            if (digit >= 0) {
                digits += digit;
                swallowTyped = true;
                if (digits.length() == 2) {
                    int number = Integer.parseInt(digits);
                    digits = null;
                    jump.accept(number);
                }
                return true;
            }
            digits = null;
            if (code == KeyEvent.VK_ESCAPE) return true;
        }
        if (!isPlainAlt(e)) return false;
        if (digit >= 0) {
            swallowTyped = true;
            jump.accept(digit == 0 ? 10 : digit);
            return true;
        }
        if (code == KeyEvent.VK_J) {
            digits = "";
            swallowTyped = true;
            return true;
        }
        if (code == KeyEvent.VK_H) {
            swallowTyped = true;
            markAllRead.run();
            return true;
        }
        if (code == KeyEvent.VK_SLASH || code == KeyEvent.VK_DIVIDE) {
            swallowTyped = true;
            lastBuffer.run();
            return true;
        }
        // Arrows type nothing, so there's no KEY_TYPED to swallow.
        if (code == KeyEvent.VK_UP || code == KeyEvent.VK_KP_UP) {
            step.accept(-1);
            return true;
        }
        if (code == KeyEvent.VK_DOWN || code == KeyEvent.VK_KP_DOWN) {
            step.accept(1);
            return true;
        }
        if (isLessThan(e)) {
            swallowTyped = true;
            historyBack.run();
            return true;
        }
        if (isGreaterThan(e)) {
            swallowTyped = true;
            historyForward.run();
            return true;
        }
        return false;
    }

    private static int digitOf(int code) {
        if (code >= KeyEvent.VK_0 && code <= KeyEvent.VK_9) return code - KeyEvent.VK_0;
        if (code >= KeyEvent.VK_NUMPAD0 && code <= KeyEvent.VK_NUMPAD9) return code - KeyEvent.VK_NUMPAD0;
        return -1;
    }

    /*
     * < and > sit on different keys by layout: Shift+comma and Shift+period on US keyboards, one
     * key of their own (with Shift for >) on many European ones. The key char settles it where
     * Alt leaves it alone; macOS Option changes the char, so the key codes cover that. Comma and
     * period count with or without Shift, so Alt+, and Alt+. work too.
     */
    private static boolean isLessThan(KeyEvent e) {
        int code = e.getKeyCode();
        boolean shift = e.isShiftDown();
        return e.getKeyChar() == '<' || (code == KeyEvent.VK_LESS && !shift) || code == KeyEvent.VK_COMMA;
    }

    private static boolean isGreaterThan(KeyEvent e) {
        int code = e.getKeyCode();
        boolean shift = e.isShiftDown();
        return e.getKeyChar() == '>' || code == KeyEvent.VK_GREATER || (code == KeyEvent.VK_LESS && shift)
                || code == KeyEvent.VK_PERIOD;
    }

    private static boolean isModifier(int code) {
        return code == KeyEvent.VK_ALT || code == KeyEvent.VK_SHIFT || code == KeyEvent.VK_CONTROL
                || code == KeyEvent.VK_META || code == KeyEvent.VK_ALT_GRAPH;
    }

    /** Alt alone: AltGr arrives as Ctrl+Alt on Windows and types characters, so it must not match. */
    private static boolean isPlainAlt(KeyEvent e) {
        int mods = e.getModifiersEx();
        int others = KeyEvent.CTRL_DOWN_MASK | KeyEvent.META_DOWN_MASK | KeyEvent.ALT_GRAPH_DOWN_MASK;
        return (mods & KeyEvent.ALT_DOWN_MASK) != 0 && (mods & others) == 0;
    }
}

package com.irc;

import lombok.Value;

import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;

/**
 * Who is in each channel and what membership modes they hold.
 *
 * Written from the socket reader thread and read from the Swing EDT, so every method is
 * synchronized and {@link #snapshot} hands back an unmodifiable copy rather than a live view.
 *
 * Channels and nicks are keyed by their ASCII-lowercased form because IRC treats them
 * case-insensitively, but the server's casing is preserved for display.
 */
class ChannelUserList {

    /**
     * One user as the UI should draw them: display nick, highest prefix, that prefix's rank, and
     * whether they are marked away.
     */
    @Value
    static class Entry {
        String nick;
        String prefix;
        int rank;
        boolean away;

        Entry(String nick, String prefix, int rank, boolean away) {
            this.nick = nick;
            this.prefix = prefix;
            this.rank = rank;
            this.away = away;
        }

        Entry(String nick, String prefix, int rank) {
            this(nick, prefix, rank, false);
        }
    }

    private static final class User {
        private String displayNick;
        private final Set<Character> modes = new LinkedHashSet<>();

        User(String displayNick) {
            this.displayNick = displayNick;
        }
    }

    private static final class Channel {
        private final String displayName;
        private final Map<String, User> users = new HashMap<>();

        Channel(String displayName) {
            this.displayName = displayName;
        }
    }

    private final ModeSpec spec;
    private final Map<String, Channel> live = new HashMap<>();
    private final Map<String, Channel> pending = new HashMap<>();
    /** Away is a property of the user, not the channel, so it is kept once per nick. */
    private final Set<String> away = new HashSet<>();

    ChannelUserList(ModeSpec spec) {
        this.spec = spec;
    }

    private static String key(String value) {
        return value.toLowerCase(Locale.ROOT);
    }

    /**
     * Accumulates one 353 line into the pending roster. Leading characters are consumed while
     * they are known prefixes, so "@+bob" yields both modes.
     */
    synchronized void addNames(String channel, List<String> rawEntries) {
        if (rawEntries == null) {
            return;
        }
        Channel buffer = pending.computeIfAbsent(key(channel), k -> new Channel(channel));
        for (String raw : rawEntries) {
            if (raw == null || raw.isEmpty()) {
                continue;
            }
            Set<Character> modes = new LinkedHashSet<>();
            int i = 0;
            while (i < raw.length()) {
                Character mode = spec.modeForPrefix(raw.charAt(i));
                if (mode == null) {
                    break;
                }
                modes.add(mode);
                i++;
            }
            String nick = raw.substring(i);
            if (nick.isEmpty()) {
                continue;
            }
            User user = buffer.users.computeIfAbsent(key(nick), k -> new User(nick));
            user.displayNick = nick;
            user.modes.addAll(modes);
        }
    }

    /** Commits the pending roster over the live one (366). Replaces rather than merges. */
    synchronized void endNames(String channel) {
        Channel buffer = pending.remove(key(channel));
        if (buffer != null) {
            live.put(key(channel), buffer);
        }
    }

    /**
     * A joining user starts out present. With away-notify the server follows the JOIN with an
     * AWAY when they are away, so a flag left over from before they parted cannot linger.
     */
    synchronized void join(String channel, String nick) {
        away.remove(key(nick));
        live.computeIfAbsent(key(channel), k -> new Channel(channel))
                .users.computeIfAbsent(key(nick), k -> new User(nick));
    }

    synchronized void part(String channel, String nick) {
        Channel ch = live.get(key(channel));
        if (ch != null) {
            ch.users.remove(key(nick));
        }
        if (!isVisible(nick)) {
            away.remove(key(nick));
        }
    }

    synchronized void kick(String channel, String nick) {
        part(channel, nick);
    }

    /** Removes the nick everywhere; returns the display names of the channels that changed. */
    synchronized List<String> quit(String nick) {
        List<String> affected = new ArrayList<>();
        for (Channel ch : live.values()) {
            if (ch.users.remove(key(nick)) != null) {
                affected.add(ch.displayName);
            }
        }
        away.remove(key(nick));
        return affected;
    }

    /** Re-keys the nick everywhere, keeping modes; returns the channels that changed. */
    synchronized List<String> rename(String oldNick, String newNick) {
        List<String> affected = new ArrayList<>();
        for (Channel ch : live.values()) {
            User user = ch.users.remove(key(oldNick));
            if (user == null) {
                continue;
            }
            user.displayNick = newNick;
            ch.users.put(key(newNick), user);
            affected.add(ch.displayName);
        }
        if (away.remove(key(oldNick))) {
            away.add(key(newNick));
        }
        return affected;
    }

    /**
     * Marks the nick away or back. Returns the channels whose roster shows them and so need a
     * redraw - empty when nothing changed, so a repeated AWAY costs nothing.
     */
    synchronized List<String> setAway(String nick, boolean isAway) {
        boolean changed = isAway ? away.add(key(nick)) : away.remove(key(nick));
        List<String> affected = new ArrayList<>();
        if (!changed) {
            return affected;
        }
        for (Channel ch : live.values()) {
            if (ch.users.containsKey(key(nick))) {
                affected.add(ch.displayName);
            }
        }
        return affected;
    }

    /**
     * Forgets every away mark, for when the server stops reporting changes. Returns the channels
     * that showed someone away.
     */
    synchronized List<String> clearAway() {
        List<String> affected = new ArrayList<>();
        for (Channel ch : live.values()) {
            for (String nick : ch.users.keySet()) {
                if (away.contains(nick)) {
                    affected.add(ch.displayName);
                    break;
                }
            }
        }
        away.clear();
        return affected;
    }

    /** Display names of every channel with a roster. */
    synchronized List<String> channels() {
        List<String> names = new ArrayList<>();
        for (Channel ch : live.values()) {
            names.add(ch.displayName);
        }
        return names;
    }

    synchronized boolean isAway(String nick) {
        return away.contains(key(nick));
    }

    private boolean isVisible(String nick) {
        for (Channel ch : live.values()) {
            if (ch.users.containsKey(key(nick))) {
                return true;
            }
        }
        return false;
    }

    /**
     * Applies a MODE change. {@code modeParams} is the MODE command's parameters minus the
     * target, e.g. {@code ["+mo", "bob"]}.
     *
     * Every letter that {@link ModeSpec#takesParameter} reports consumes one is consumed even
     * when we then discard it - that consumption is what keeps the remaining parameters aligned
     * with the remaining membership modes.
     */
    synchronized void applyModeChange(String channel, List<String> modeParams) {
        if (modeParams == null || modeParams.isEmpty()) {
            return;
        }
        Channel ch = live.get(key(channel));
        if (ch == null) {
            return;
        }

        String modeString = modeParams.get(0);
        int paramIndex = 1;
        boolean adding = true;

        for (int i = 0; i < modeString.length(); i++) {
            char letter = modeString.charAt(i);
            if (letter == '+') {
                adding = true;
                continue;
            }
            if (letter == '-') {
                adding = false;
                continue;
            }

            String param = null;
            if (spec.takesParameter(letter, adding)) {
                if (paramIndex >= modeParams.size()) {
                    return; // malformed: stop rather than misapply what is left
                }
                param = modeParams.get(paramIndex++);
            }

            if (param == null || !spec.isPrefixMode(letter)) {
                continue;
            }
            User user = ch.users.get(key(param));
            if (user == null) {
                continue;
            }
            if (adding) {
                user.modes.add(letter);
            } else {
                user.modes.remove(letter);
            }
        }
    }

    synchronized void removeChannel(String channel) {
        live.remove(key(channel));
        pending.remove(key(channel));
        away.removeIf(nick -> !isVisible(nick));
    }

    synchronized void clear() {
        live.clear();
        pending.clear();
        away.clear();
    }

    /** Users sorted by rank then case-insensitive nick. Unmodifiable. */
    synchronized List<Entry> snapshot(String channel) {
        Channel ch = live.get(key(channel));
        if (ch == null) {
            return Collections.emptyList();
        }

        List<Entry> entries = new ArrayList<>(ch.users.size());
        for (User user : ch.users.values()) {
            entries.add(entryFor(user));
        }

        entries.sort(Comparator.comparingInt(Entry::getRank)
                .thenComparing(Entry::getNick, String.CASE_INSENSITIVE_ORDER));
        return Collections.unmodifiableList(entries);
    }

    /** The nick's highest prefix in the channel ("@", "+", ...), or "" when it has none or is unknown. */
    synchronized String prefixOf(String channel, String nick) {
        Channel ch = live.get(key(channel));
        User user = ch == null ? null : ch.users.get(key(nick));
        return user == null ? "" : entryFor(user).getPrefix();
    }

    private Entry entryFor(User user) {
        char bestMode = '\0';
        int bestRank = Integer.MAX_VALUE;
        for (char mode : user.modes) {
            int rank = spec.rankOf(mode);
            if (rank < bestRank) {
                bestRank = rank;
                bestMode = mode;
            }
        }
        char prefixChar = bestMode == '\0' ? '\0' : spec.prefixFor(bestMode);
        String prefix = prefixChar == '\0' ? "" : String.valueOf(prefixChar);
        return new Entry(user.displayNick, prefix, bestRank, away.contains(key(user.displayNick)));
    }
}

package com.irc;

import java.util.ArrayList;
import java.util.List;

/**
 * Readline-style history for the side-panel input box, shared across channels.
 *
 * Entries are ordered oldest-first. {@code cursor == entries.size()} means "live" (not
 * browsing); {@code 0 <= cursor < size} points at the entry currently shown. When browsing
 * begins, the unsent text is stashed as {@link #draft} so stepping past the newest entry can
 * restore it.
 */
class InputHistory {

    private final int capacity;
    private final List<String> entries = new ArrayList<>();
    private int cursor;
    private String draft = "";

    InputHistory(int capacity) {
        this.capacity = capacity;
    }

    /** Records a sent line and resets browsing. Ignores blank lines and consecutive duplicates. */
    void add(String line) {
        if (line == null || line.isEmpty()) {
            return;
        }
        if (entries.isEmpty() || !entries.get(entries.size() - 1).equals(line)) {
            entries.add(line);
            if (entries.size() > capacity) {
                entries.remove(0);
            }
        }
        cursor = entries.size();
        draft = "";
    }

    /**
     * Up: returns the previous (older) entry. On the first press from "live" it stashes
     * {@code currentText} as the draft and returns the newest entry; further presses walk
     * older and clamp at the oldest. Returns {@code null} when there is no history.
     */
    String previous(String currentText) {
        if (entries.isEmpty()) {
            return null;
        }
        if (cursor == entries.size()) {
            draft = currentText == null ? "" : currentText;
            cursor = entries.size() - 1;
        } else if (cursor > 0) {
            cursor--;
        }
        return entries.get(cursor);
    }

    /**
     * Down: returns the next (newer) entry. Stepping past the newest exits browsing and returns
     * the stashed draft. Returns {@code null} when not currently browsing.
     */
    String next() {
        if (cursor >= entries.size()) {
            return null;
        }
        if (cursor < entries.size() - 1) {
            cursor++;
            return entries.get(cursor);
        }
        cursor = entries.size();
        return draft;
    }
}

package com.irc;

import lombok.Getter;
import lombok.extern.slf4j.Slf4j;

import javax.swing.*;
import java.awt.*;
import java.time.Duration;
import java.time.Instant;
import java.time.format.DateTimeParseException;
import java.util.List;
import java.util.Objects;
import java.util.function.Consumer;

/**
 * Adapter class to bridge between SimpleIrcClient
 */
@Slf4j
public class IrcAdapter {
    @Getter
    private SimpleIrcClient client;
    private String currentNick;
    private volatile Consumer<IrcMessage> messageConsumer;
    private IrcConfig config;
    private volatile IrcPanel panel;
    /** Set by {@link #detach}; nothing reaches the UI afterwards. */
    private volatile boolean detached;
    /**
     * The query behind the in-flight LIST, replayed by the dialog's Refresh button. Written on
     * the caller's thread ({@link #requestChannelList}) and read on the IRC reader thread when
     * {@code CHANNEL_LIST} fires - volatile so that handoff doesn't depend on the incidental
     * happens-before edge created by both sides passing through the same monitor.
     */
    private volatile String lastChannelListQuery = "";
    /** Lines stamped earlier than this before registration are replayed history (ZNC playback). */
    static final Duration PLAYBACK_THRESHOLD = Duration.ofSeconds(5);
    private String networkId = NetworkConfig.SWIFTIRC_ID;
    /** When this connection registered; null until it has. Set on the reader thread. */
    private volatile Instant registeredAt;

    public IrcAdapter() {
        client = new SimpleIrcClient();
    }

    /**
     * Initialize the client with the provided config
     */
    public void initialize(IrcConfig config, Consumer<IrcMessage> messageConsumer, IrcPanel panel, String currentNick) {
        initialize(config, NetworkConfig.swiftIrc(config), messageConsumer, panel, currentNick);
    }

    public void initialize(IrcConfig config, NetworkConfig network, Consumer<IrcMessage> messageConsumer,
                           IrcPanel panel, String currentNick) {
        this.messageConsumer = messageConsumer;
        this.currentNick = currentNick;
        this.config = config;
        this.panel = panel;
        this.networkId = network.getId();

        client = new SimpleIrcClient()
                .server(network.getHost(), network.getPort(), network.isTls())
                .credentials(currentNick, "runelite", currentNick)
                .serverPassword(network.getServerPassword())
                .verifyTls(network.isVerifyTls());

        if (!network.getSaslPassword().isEmpty()) {
            client.sasl(network.getSaslAccount(), network.getSaslPassword());
        }

        client.setRawLogging(config.logRawLines());

        setupEventHandlers();
    }

    public String getNetworkId() {
        return networkId;
    }

    /**
     * Connect to the IRC server
     */
    public void connect() {
        client.connect();
    }

    /**
     * Disconnect from the IRC server
     */
    public void disconnect(String reason) {
        client.disconnect(reason);
    }
    public void disconnect() {
        client.disconnect();
    }

    /**
     * Join a channel
     */
    public void joinChannel(String channel, String password) {
        client.executeWhenRegistered(() -> client.joinChannel(channel, password));
    }

    /**
     * Leave a channel
     */
    public void leaveChannel(String channel) {
        client.leaveChannel(channel);
    }

    /**
     * Leave a channel with a reason
     */
    public void leaveChannel(String channel, String reason) {
        client.leaveChannel(channel, reason);
    }

    /**
     * Send a message to a target (channel or user)
     */
    public void sendMessage(String target, String message) {
        client.sendMessage(target, message);
        processMessage(new IrcMessage(
                target,
                currentNick,
                message,
                IrcMessage.MessageType.PRIVATE,
                Instant.now(),
                client.getChannelPrefix(target, currentNick)
        ));
    }

    /**
     * Send an action (/me) to a target
     */
    public void sendAction(String target, String action) {
        client.sendAction(target, action);
        processMessage(new IrcMessage(
                target,
                "* " + currentNick,
                action,
                IrcMessage.MessageType.PRIVATE,
                Instant.now(),
                client.getChannelPrefix(target, currentNick)
        ));
    }

    /**
     * Send a notice to a target
     */
    public void sendNotice(String target, String message) {
        client.sendNotice(target, message);
        processMessage(new IrcMessage(
                "System",
                currentNick,
                "Notice to " + target + ": " + message,
                IrcMessage.MessageType.SYSTEM,
                Instant.now()
        ));
    }

    /**
     * Change nickname
     */
    public void setNick(String nick) {
        client.setNick(nick);
    }

    /**
     * Send a raw IRC command
     */
    public void sendRawLine(String command) {
        client.sendRawLine(command);
    }

    /**
     * Asks the server for its channel list. {@code query} is passed through verbatim so server
     * filters such as ">50" or "*quest*" work as the user typed them.
     */
    public void requestChannelList(String query) {
        String trimmed = query != null ? query.trim() : "";
        lastChannelListQuery = trimmed;
        // A run abandoned by an earlier request (server truncated its reply, no 323, connection
        // survives) must not have this request's rows appended onto its stale leftovers.
        client.resetChannelListRun();
        // No trailing space on a bare LIST: some servers read "LIST " as an empty filter.
        client.sendRawLine(trimmed.isEmpty() ? "LIST" : "LIST " + trimmed);
    }

    /**
     * True once the socket is up and the registration handshake has been written - NOT that the
     * server has accepted it. A command sent in the window between the handshake and RPL_WELCOME
     * (longer with SASL) will reach the server but may be answered with 451 ERR_NOTREGISTERED
     * rather than doing anything. Do not read this as "ready for commands".
     */
    /** Applies the raw-logging setting to a live connection, so it can be turned on mid-problem. */
    public void setRawLogging(boolean enabled) {
        if (client != null) {
            client.setRawLogging(enabled);
        }
    }

    public boolean isConnected() {
        return client.isConnected();
    }

    /**
     * Drops the reference to the panel, so an in-flight reply cannot drive a UI that is being
     * torn down. Without it a 323 arriving during shutdown still pops the channel browser for a
     * plugin that no longer exists.
     */
    public void clearPanel() {
        this.panel = null;
    }

    /**
     * Cuts this adapter off from the UI for good: NetworkManager has replaced or stopped it, and
     * a disconnect that completes late must not report "Disconnected" or clear the user list on
     * the live session that now owns this network id.
     */
    void detach() {
        detached = true;
        panel = null;
        messageConsumer = null;
    }

    /**
     * Get the current nickname
     */
    public String getNick() {
        return currentNick;
    }

    /**
     * Process and forward incoming messages to the plugin
     */
    private void processMessage(IrcMessage message) {
        Consumer<IrcMessage> consumer = messageConsumer;
        if (!detached && consumer != null) {
            consumer.accept(message.withNetworkId(networkId));
        }
    }

    /** The line's server-time, or null when absent or unreadable. */
    private static Instant serverTime(String tag) {
        if (tag == null || tag.isEmpty()) return null;
        try {
            return Instant.parse(tag);
        } catch (DateTimeParseException e) {
            return null;
        }
    }

    /** Older than registration by more than the threshold: replayed, not live. */
    private boolean isPlayback(Instant sent) {
        if (sent == null) return false;
        Instant reference = registeredAt != null ? registeredAt : Instant.now();
        return sent.isBefore(reference.minus(PLAYBACK_THRESHOLD));
    }

    /** Replayed lines keep the time they were sent; live ones are stamped by our clock, as on main. */
    private static Instant displayTime(IrcMessage.MessageType type, Instant sent) {
        return type == IrcMessage.MessageType.HISTORY ? sent : Instant.now();
    }

    /** The panel is read once: {@link #detach} may null it from another thread. */
    private String currentChannelOrSystem() {
        IrcPanel current = panel;
        return current != null ? current.getCurrentChannelOn(networkId) : "System";
    }

    private void cancelChannelListTimeout() {
        IrcPanel current = panel;
        if (current != null) SwingUtilities.invokeLater(current::cancelChannelListTimeout);
    }

    private void reportConnected(boolean connected) {
        IrcPanel target = panel;
        if (!detached && target != null) {
            SwingUtilities.invokeLater(() -> target.setNetworkConnected(networkId, connected));
        }
    }

    /**
     * Set up event handlers for the SimpleIrcClient
     */
    private void setupEventHandlers() {
        client.addEventListener(event -> {
            if (detached) return;
            String target = event.getTarget();
            String source = event.getSource();

            switch (event.getType()) {
                case CONNECT:
                    registeredAt = null;
                    processMessage(new IrcMessage("System", "System", "Connected to IRC server, registering...", IrcMessage.MessageType.SYSTEM, Instant.now()));
                    break;

                case REGISTERED:
                    registeredAt = Instant.now();
                    currentNick = client.getNick();
                    processMessage(new IrcMessage("System", "System", "Registration complete - ready for commands", IrcMessage.MessageType.SYSTEM, Instant.now()));
                    if (NetworkConfig.SWIFTIRC_ID.equals(networkId)) {
                        processMessage(new IrcMessage("System", "System", "Welcome to IRC! To chat in the current channel, use '" + config.prefix() + "' followed by your message in the game chatbox.", IrcMessage.MessageType.SYSTEM, Instant.now()));
                        processMessage(new IrcMessage("System", "System", "For a list of commands, type '/help' in the side panel input box.", IrcMessage.MessageType.SYSTEM, Instant.now()));
                    }
                    if (client.isSecure() && !client.isVerifyingTls()) {
                        processMessage(new IrcMessage("System", "System", "TLS certificate verification is off for this network.", IrcMessage.MessageType.SYSTEM, Instant.now()));
                    }
                    reportConnected(true);
                    break;

                case SASL_SUCCESS:
                    processMessage(new IrcMessage("System", "System", "Authenticated via SASL.", IrcMessage.MessageType.SYSTEM, Instant.now()));
                    break;

                case SASL_FAILED:
                    processMessage(new IrcMessage("System", "System", "SASL authentication failed: " + event.getMessage() + " (continuing unauthenticated).", IrcMessage.MessageType.SYSTEM, Instant.now()));
                    break;

                case DISCONNECT:
                    // The client records why the link went down; without it this line is
                    // indistinguishable from the user's own /quit.
                    String disconnectText = event.getMessage() != null && !event.getMessage().isEmpty()
                            ? "Disconnected from IRC (" + event.getMessage() + ")"
                            : "Disconnected from IRC";
                    processMessage(new IrcMessage("System", "System", disconnectText, IrcMessage.MessageType.SYSTEM, Instant.now()));
                    for (String channel : client.getChannels()) {
                        processMessage(new IrcMessage(channel, "System", disconnectText, IrcMessage.MessageType.SYSTEM, Instant.now()));
                    }
                    // Any outcome must cancel a pending LIST timeout, not just success - otherwise
                    // a disconnect while one is armed fires a spurious "no response" 30s later.
                    cancelChannelListTimeout();
                    reportConnected(false);
                    break;

                case MESSAGE:
                    if (Objects.equals(target, source)) {
                        switch (config.filterPMs()) {
                            case Current:
                                source = "[PM] " + source;
                                target = currentChannelOrSystem();
                                break;
                            case Status:
                                source = "[PM] " + source;
                                target = "System";
                                break;
                            case Private:
                                target = event.getSource();
                                break;
                        }
                    }
                    Instant chatSent = serverTime(event.getAdditionalData());
                    IrcMessage.MessageType chatType = isPlayback(chatSent) ? IrcMessage.MessageType.HISTORY : IrcMessage.MessageType.CHAT;
                    // Looked up by the original target: PMs have no channel, so they get no prefix.
                    processMessage(new IrcMessage(target, source, event.getMessage(), chatType, displayTime(chatType, chatSent),
                            client.getChannelPrefix(event.getTarget(), event.getSource())));
                    break;

                case ACTION: {
                    Instant sent = serverTime(event.getAdditionalData());
                    IrcMessage.MessageType actionType = isPlayback(sent) ? IrcMessage.MessageType.HISTORY : IrcMessage.MessageType.CHAT;
                    processMessage(new IrcMessage(event.getTarget(), "* " + event.getSource(), event.getMessage(), actionType, displayTime(actionType, sent),
                            client.getChannelPrefix(event.getTarget(), event.getSource())));
                    break;
                }

                case JOIN:
                    if (!config.hideConnectionMessages()) {
                        processMessage(new IrcMessage(
                                event.getTarget(),
                                "*",
                                event.getSource() + " has joined.",
                                IrcMessage.MessageType.JOIN,
                                Instant.now()
                        ));
                    }
                    break;

                case PART:
                    if (!config.hideConnectionMessages()) {
                        processMessage(new IrcMessage(event.getTarget(), event.getSource() + " parted", (event.getMessage() != null ? event.getMessage() : " "), IrcMessage.MessageType.PART, Instant.now()));
                    }
                    break;

                case QUIT:
                    if (!config.hideConnectionMessages() && event.getAdditionalData() != null && !event.getAdditionalData().isEmpty()) {
                        String[] channels = event.getAdditionalData().split(",");
                        for (String channel : channels) {
                            processMessage(new IrcMessage(channel, event.getSource() + " quit", event.getMessage() != null ? event.getMessage() : " ", IrcMessage.MessageType.QUIT, Instant.now()));
                        }
                    }
                    break;

                case NICK_CHANGE:
                    String oldNick = event.getSource();
                    String newNick = event.getMessage();

                    if (oldNick.equals(currentNick)) {
                        currentNick = newNick;
                    }

                    BufferKey oldQuery = BufferKey.of(networkId, oldNick);
                    IrcPanel renameTarget = panel;
                    if (renameTarget != null && renameTarget.isPane(oldQuery)) {
                        SwingUtilities.invokeLater(() -> renameTarget.renameChannel(oldQuery, newNick));
                    }

                    if (event.getAdditionalData() != null) {
                        String[] channels = event.getAdditionalData().split(",");
                        for (String channel : channels) {
                            if (channel != null && !channel.isEmpty()) {
                                processMessage(new IrcMessage(channel, oldNick + " is now known as", newNick, IrcMessage.MessageType.NICK_CHANGE, Instant.now()));
                            }
                        }
                    }
                    break;

                case KICK:
                    if (!config.hideConnectionMessages()) {
                        String[] kickParts = event.getMessage().split(" ", 2);
                        String kickedUser = kickParts[0];
                        String kickReason = kickParts.length > 1 ? kickParts[1] : "";
                        processMessage(new IrcMessage(event.getTarget(), event.getSource() + " kicked " + kickedUser, kickReason, IrcMessage.MessageType.KICK, Instant.now()));
                    }
                    break;

                case SERVER_NOTICE:
                case NOTICE:
                    if (source != null && source.endsWith(".SwiftIRC.net")) {
                        if (!config.filterServerNotices()) {
                            target = "System";
                        } else {
                            target = source;
                        }
                    } else {
                        source = "[N] " + source;
                        switch (config.filterNotices()) {
                            case Current:
                                target = currentChannelOrSystem();
                                break;
                            case Status:
                                target = "System";
                                break;
                            case Private:
                                target = source;
                                break;
                        }
                    }
                    processMessage(new IrcMessage(target, source, event.getMessage(), IrcMessage.MessageType.NOTICE, Instant.now()));
                    break;

                case CHANNEL_MODE:
                    processMessage(new IrcMessage(event.getTarget(), event.getSource(), event.getMessage(), IrcMessage.MessageType.MODE, Instant.now()));
                    break;

                case USER_MODE:
                    processMessage(new IrcMessage("System", currentNick, event.getMessage(), IrcMessage.MessageType.MODE, Instant.now()));
                    break;

                case TOPIC:
                    processMessage(new IrcMessage(event.getTarget(), IrcMessage.TOPIC_SENDER, event.getMessage(), IrcMessage.MessageType.TOPIC, Instant.now()));
                    break;

                case NAMES:
                    processMessage(new IrcMessage(event.getTarget(), "Users", event.getMessage(), IrcMessage.MessageType.JOIN, Instant.now()));
                    break;

                case USERS_CHANGED:
                    IrcPanel usersPanel = panel;
                    if (usersPanel != null) {
                        String usersChannel = event.getTarget();
                        // Snapshot on the IRC thread; it is immutable, so the EDT can hold it.
                        List<ChannelUserList.Entry> users = client.getChannelUsers(usersChannel);
                        SwingUtilities.invokeLater(() -> usersPanel.setChannelUsers(BufferKey.of(networkId, usersChannel), users));
                    }
                    break;

                case CHANNEL_LIST:
                    IrcPanel listPanel = panel;
                    if (listPanel != null) {
                        // Snapshot on the IRC thread; it is immutable, so the EDT can hold it.
                        List<ChannelListEntry> channelList = client.getChannelListSnapshot();
                        boolean truncated = client.isChannelListTruncated();
                        String listQuery = lastChannelListQuery;
                        SwingUtilities.invokeLater(
                                () -> listPanel.showChannelList(networkId, channelList, listQuery, truncated));
                    }
                    break;

                case CHANNEL_LIST_FAILED:
                    processMessage(new IrcMessage("System", "System",
                            "Channel list unavailable: " + event.getMessage(),
                            IrcMessage.MessageType.SYSTEM, Instant.now()));
                    cancelChannelListTimeout();
                    break;

                case NICK_IN_USE:
                    currentNick += "_";
                    processMessage(new IrcMessage("System", "System", "Nickname is already in use. Trying: " + currentNick, IrcMessage.MessageType.SYSTEM, Instant.now()));
                    sendRawLine("NICK " + currentNick);
                    break;

                case BAD_CHANNEL_KEY:
                    String badChannel = event.getTarget();
                    processMessage(new IrcMessage("System", "System", "Cannot join " + badChannel + ": " + event.getMessage(), IrcMessage.MessageType.SYSTEM, Instant.now()));
                    SwingUtilities.invokeLater(() -> {
                        Component parent = panel != null ? panel : null;
                        String password = JOptionPane.showInputDialog(parent, "Enter password for " + badChannel + ":", "Channel Key Required", JOptionPane.QUESTION_MESSAGE);
                        if (password != null && !password.isEmpty()) {
                            joinChannel(badChannel, password);
                        }
                    });
                    break;

                case WHOIS_REPLY:
                    processMessage(new IrcMessage("System", "WHOIS", event.getMessage(), IrcMessage.MessageType.SYSTEM, Instant.now()));
                    break;

                case SERVER_ERROR:
                    // Reported, but never disconnects: most error numerics (no such nick, not a
                    // channel operator) leave a perfectly healthy connection in place.
                    processMessage(new IrcMessage("System", "Error", event.getMessage(), IrcMessage.MessageType.SYSTEM, Instant.now()));
                    break;

                case ERROR:
                    processMessage(new IrcMessage("System", "Error", event.getMessage() != null ? event.getMessage() : "Unknown error", IrcMessage.MessageType.SYSTEM, Instant.now()));
                    disconnect();
                    break;

                case TOPIC_INFO:
                    processMessage(new IrcMessage(event.getTarget(), event.getSource(), event.getMessage(), IrcMessage.MessageType.TOPIC, Instant.now()));
                    break;

                case HISTORY_BATCH:
                    if (event.getHistoryMessages() != null && !event.getHistoryMessages().isEmpty()) {
                        for (SimpleIrcClient.IrcEvent accEvent : event.getHistoryMessages()) {
                            Instant timestamp;
                            try {
                                String timeStr = accEvent.getAdditionalData();
                                timestamp = (timeStr != null && !timeStr.isEmpty())
                                    ? Instant.parse(timeStr)
                                    : Instant.now();
                            } catch (Exception e) {
                                timestamp = Instant.now();
                            }
                            String sender = accEvent.getSource() != null ? accEvent.getSource() : "";
                            if (accEvent.getType() == SimpleIrcClient.IrcEvent.Type.ACTION) {
                                sender = "* " + sender;
                            }
                            processMessage(new IrcMessage(
                                event.getTarget(), sender, accEvent.getMessage(),
                                IrcMessage.MessageType.HISTORY, timestamp
                            ));
                        }
                        processMessage(new IrcMessage(
                            event.getTarget(), "*", "--- Begin of chat ---",
                            IrcMessage.MessageType.HISTORY_SEPARATOR, Instant.now()
                        ));
                    }
                    break;
            }
        });
    }
}

