    private static final Pattern MODERN_EMOJI_PATTERN = Pattern.compile("[" + "\uD83E\uDD70-\uD83E\uDDFF" +
            "\uD83E\uDE00-\uD83E\uDEFF" +
            "\uD83E\uDF00-\uD83E\uDFFF" +
            "\uD83E\uDD00-\uD83E\uDD6F" +
            "\uD83E\uDEC0-\uD83E\uDECF" + "\uD83E\uDED0-\uD83E\uDEFF" +
            "\uD83E\uDF00-\uD83E\uDF2F" +
            "\uD83E\uDF30-\uD83E\uDF5F" +
            "\uD83E\uDF60-\uD83E\uDF8F" +
            "\uFE0F" +
            "]" + "|\uD83C[\uDFFB-\uDFFF]" +
            "|\uD83E[\uDDB0-\uDDBF]"
    );

    public static String convertModernEmojis(String text) {
        if (text == null) return "";
        Matcher matcher = MODERN_EMOJI_PATTERN.matcher(text);
        if (!matcher.find()) {
            return text;
        }
        matcher.reset();
        StringBuffer sb = new StringBuffer();
        while (matcher.find()) {
            String modernEmoji = matcher.group();
            String replacement = EmojiParser.parseToAliases(modernEmoji, EmojiParser.FitzpatrickAction.PARSE);
            matcher.appendReplacement(sb, Matcher.quoteReplacement(replacement));
        }
        matcher.appendTail(sb);
        return sb.toString();
    }

    private enum IrcShortcut {
        COLOR(KeyStroke.getKeyStroke(KeyEvent.VK_K, Toolkit.getDefaultToolkit().getMenuShortcutKeyMaskEx()), "\u0003", "insertColorCode"),
        BOLD(KeyStroke.getKeyStroke(KeyEvent.VK_B, Toolkit.getDefaultToolkit().getMenuShortcutKeyMaskEx()), "\u0002", "insertBold"),
        ITALIC(KeyStroke.getKeyStroke(KeyEvent.VK_I, Toolkit.getDefaultToolkit().getMenuShortcutKeyMaskEx()), "\u001D", "insertItalic"),
        UNDERLINE(KeyStroke.getKeyStroke(KeyEvent.VK_U, Toolkit.getDefaultToolkit().getMenuShortcutKeyMaskEx()), "\u001F", "insertUnderline");

        private final KeyStroke keyStroke;
        private final String insertText;
        private final String actionKey;

        IrcShortcut(KeyStroke keyStroke, String insertText, String actionKey) {
            this.keyStroke = keyStroke;
            this.insertText = insertText;
            this.actionKey = actionKey;
        }
    }

    private class TextInsertAction extends AbstractAction {
        private final String textToInsert;

        TextInsertAction(String textToInsert) {
            this.textToInsert = textToInsert;
        }

        @Override
        public void actionPerformed(ActionEvent e) {
            String currentText = inputField.getText();
            int caretPosition = inputField.getCaretPosition();
            String newText;
            int newCaretPosition;
            if (inputField.getSelectedText() != null) {
                int selStart = inputField.getSelectionStart();
                int selEnd = inputField.getSelectionEnd();
                String selectedText = inputField.getSelectedText();
                newText = currentText.substring(0, selStart) + textToInsert + selectedText + textToInsert + currentText.substring(selEnd);
                newCaretPosition = selEnd + (textToInsert.length() * 2);
            } else {
                newText = currentText.substring(0, caretPosition) + textToInsert + currentText.substring(caretPosition);
                newCaretPosition = caretPosition + textToInsert.length();
            }
            inputField.setText(newText);
            inputField.setCaretPosition(newCaretPosition);
        }
    }

    private void setupShortcuts() {
        InputMap inputMap = inputField.getInputMap(JComponent.WHEN_FOCUSED);
        ActionMap actionMap = inputField.getActionMap();
        for (IrcShortcut shortcut : IrcShortcut.values()) {
            inputMap.put(shortcut.keyStroke, shortcut.actionKey);
            actionMap.put(shortcut.actionKey, new TextInsertAction(shortcut.insertText));
        }

        // Tab would otherwise move focus out of the input box.
        inputField.setFocusTraversalKeysEnabled(false);
        inputMap.put(KeyStroke.getKeyStroke(KeyEvent.VK_TAB, 0), "completeNext");
        actionMap.put("completeNext", new AbstractAction() {
            @Override
            public void actionPerformed(ActionEvent e) {
                completeInput(true);
            }
        });
        inputMap.put(KeyStroke.getKeyStroke(KeyEvent.VK_TAB, InputEvent.SHIFT_DOWN_MASK), "completePrevious");
        actionMap.put("completePrevious", new AbstractAction() {
            @Override
            public void actionPerformed(ActionEvent e) {
                completeInput(false);
            }
        });

        inputMap.put(KeyStroke.getKeyStroke(KeyEvent.VK_UP, 0), "historyPrevious");
        actionMap.put("historyPrevious", new AbstractAction() {
            @Override
            public void actionPerformed(ActionEvent e) {
                recallHistory(inputHistory.previous(inputField.getText()));
            }
        });
        inputMap.put(KeyStroke.getKeyStroke(KeyEvent.VK_DOWN, 0), "historyNext");
        actionMap.put("historyNext", new AbstractAction() {
            @Override
            public void actionPerformed(ActionEvent e) {
                recallHistory(inputHistory.next());
            }
        });
    }

    private void completeInput(boolean forward) {
        BufferKey current = getCurrentBuffer();
        String channel = current.getName();
        List<String> nicks = new ArrayList<>();
        for (ChannelUserList.Entry entry : channelUserSnapshots.getOrDefault(current.folded(), Collections.emptyList())) {
            nicks.add(entry.getNick());
        }
        // A PM buffer has no roster; the one other person is the buffer itself.
        if (!channel.startsWith("#") && !SYSTEM_TAB.equals(channel)) {
            nicks.add(channel);
        }
        List<String> channels = new ArrayList<>();
        for (BufferKey key : getBuffers()) {
            if (key.getNetworkId().equals(current.getNetworkId()) && key.getName().startsWith("#")) {
                channels.add(key.getName());
            }
        }
        TabCompleter.Result result = tabCompleter.complete(
                inputField.getText(), inputField.getCaretPosition(), nicks, channels, forward);
        if (result != null) {
            inputField.setText(result.text);
            inputField.setCaretPosition(result.caret);
        }
    }

    private void recallHistory(String text) {
        if (text == null) {
            return;
        }
        inputField.setText(text);
        inputField.setCaretPosition(text.length());
    }
}

package com.irc;

import javax.swing.JFrame;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import javax.swing.Timer;
import java.awt.BorderLayout;
import java.awt.Dimension;
import java.awt.Frame;
import java.awt.GraphicsDevice;
import java.awt.GraphicsEnvironment;
import java.awt.Rectangle;
import java.awt.Window;
import java.awt.event.ComponentAdapter;
import java.awt.event.ComponentEvent;
import java.awt.event.HierarchyEvent;
import java.awt.event.HierarchyListener;
import java.awt.event.WindowAdapter;
import java.awt.event.WindowEvent;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.atomic.AtomicReference;
import java.util.function.Consumer;
import java.util.function.Supplier;

/** Moves the live chat controls between hosts. All methods run on the Swing EDT. */
final class IrcPanelWindow {
    private final JPanel dockHost;
    private final JPanel content;
    private final Runnable beforeMove;
    private final Runnable hidePreviews;
    private final Runnable dockRequested;
    /** The saved {@link PopOutGeometry}, serialized. */
    private final Supplier<String> loadGeometry;
    private final Consumer<String> saveGeometry;
    private JFrame frame;
    /** The pop-out's bounds when last neither maximized nor minimized. */
    private Rectangle normalBounds;
    /** Saves once a move or resize settles, rather than on every step of a drag. */
    private final Timer saveTimer = new Timer(500, e -> saveGeometry());
    private final ComponentAdapter frameGeometryListener = new ComponentAdapter() {
        @Override
        public void componentMoved(ComponentEvent e) { geometryChanged(); }

        @Override
        public void componentResized(ComponentEvent e) { geometryChanged(); }
    };
    private Window observedWindow;
    private final WindowAdapter windowListener = new WindowAdapter() {
        @Override
        public void windowLostFocus(WindowEvent e) { hidePreviews.run(); }

        @Override
        public void windowDeactivated(WindowEvent e) { hidePreviews.run(); }

        @Override
        public void windowIconified(WindowEvent e) { hidePreviews.run(); }
    };
    private final ComponentAdapter componentListener = new ComponentAdapter() {
        @Override
        public void componentMoved(ComponentEvent e) { hidePreviews.run(); }

        @Override
        public void componentResized(ComponentEvent e) { hidePreviews.run(); }
    };
    private final HierarchyListener hierarchyListener = this::hierarchyChanged;

    private void hierarchyChanged(HierarchyEvent e) {
        if ((e.getChangeFlags() & (HierarchyEvent.PARENT_CHANGED | HierarchyEvent.SHOWING_CHANGED)) != 0) {
            observeWindow(SwingUtilities.getWindowAncestor(content));
            if (!content.isShowing()) {
                hidePreviews.run();
            }
        }
    }

    /** Remembers the pop-out's geometry only while this object lives. */
    IrcPanelWindow(JPanel dockHost, JPanel content, Runnable beforeMove,
                   Runnable hidePreviews, Runnable dockRequested) {
        this(dockHost, content, beforeMove, hidePreviews, dockRequested, new AtomicReference<>());
    }

    private IrcPanelWindow(JPanel dockHost, JPanel content, Runnable beforeMove,
                           Runnable hidePreviews, Runnable dockRequested, AtomicReference<String> memory) {
        this(dockHost, content, beforeMove, hidePreviews, dockRequested, memory::get, memory::set);
    }

    IrcPanelWindow(JPanel dockHost, JPanel content, Runnable beforeMove, Runnable hidePreviews,
                   Runnable dockRequested, Supplier<String> loadGeometry, Consumer<String> saveGeometry) {
        this.loadGeometry = loadGeometry;
        this.saveGeometry = saveGeometry;
        saveTimer.setRepeats(false);
        this.dockHost = dockHost;
        this.content = content;
        this.beforeMove = beforeMove;
        this.hidePreviews = hidePreviews;
        this.dockRequested = dockRequested;
        content.addHierarchyListener(hierarchyListener);
        observeWindow(SwingUtilities.getWindowAncestor(content));
    }

    void setDetached(boolean detached, boolean alwaysOnTop) {
        assert SwingUtilities.isEventDispatchThread();
        if (detached) {
            if (frame == null) {
                beforeMove.run();
                Window owner = SwingUtilities.getWindowAncestor(content);
                frame = new JFrame("Global Chat (IRC)");
                frame.setDefaultCloseOperation(JFrame.DO_NOTHING_ON_CLOSE);
                frame.setMinimumSize(new Dimension(640, 360));
                frame.setSize(960, 620);
                if (owner != null) {
                    frame.setIconImages(owner.getIconImages());
                }
                frame.setLocationRelativeTo(owner);
                // Reopen where it was last time, provided its title bar is on a screen still there.
                PopOutGeometry saved = PopOutGeometry.parse(loadGeometry.get());
                boolean restore = saved != null && saved.titleBarVisible(screens());
                if (restore) frame.setBounds(saved.bounds);
                normalBounds = frame.getBounds();
                if (restore && saved.maximized) frame.setExtendedState(Frame.MAXIMIZED_BOTH);
                frame.addWindowListener(new WindowAdapter() {
                    @Override
                    public void windowClosing(WindowEvent e) { dockRequested.run(); }
                });
                frame.addWindowStateListener(e -> geometryChanged());
                frame.addComponentListener(frameGeometryListener);
                frame.add(content, BorderLayout.CENTER);
                dockHost.revalidate();
                dockHost.repaint();
                frame.setAlwaysOnTop(alwaysOnTop);
                frame.setVisible(true);
            } else {
                frame.setAlwaysOnTop(alwaysOnTop);
            }
        } else if (frame != null) {
            beforeMove.run();
            saveTimer.stop();
            saveGeometry();
            dockHost.add(content, BorderLayout.CENTER);
            frame.dispose();
            frame = null;
            dockHost.revalidate();
            dockHost.repaint();
        }
    }

    private void geometryChanged() {
        if (frame == null) return;
        // Maximized or minimized bounds aren't worth keeping: un-maximizing goes back to these.
        if (frame.getExtendedState() == Frame.NORMAL) normalBounds = frame.getBounds();
        saveTimer.restart();
    }

    private void saveGeometry() {
        if (frame == null || normalBounds == null) return;
        boolean maximized = (frame.getExtendedState() & Frame.MAXIMIZED_BOTH) == Frame.MAXIMIZED_BOTH;
        saveGeometry.accept(new PopOutGeometry(normalBounds, maximized).serialize());
    }

    private static List<Rectangle> screens() {
        List<Rectangle> screens = new ArrayList<>();
        for (GraphicsDevice screen : GraphicsEnvironment.getLocalGraphicsEnvironment().getScreenDevices()) {
            screens.add(screen.getDefaultConfiguration().getBounds());
        }
        return screens;
    }

    void toFront() {
        assert SwingUtilities.isEventDispatchThread();
        if (frame == null) return;
        if ((frame.getExtendedState() & Frame.ICONIFIED) != 0) {
            frame.setExtendedState(frame.getExtendedState() & ~Frame.ICONIFIED);
        }
        frame.toFront();
        frame.requestFocus();
    }

    private void observeWindow(Window window) {
        if (observedWindow == window) return;
        if (observedWindow != null) {
            observedWindow.removeWindowFocusListener(windowListener);
            observedWindow.removeWindowListener(windowListener);
            observedWindow.removeComponentListener(componentListener);
        }
        observedWindow = window;
        if (window != null) {
            window.addWindowFocusListener(windowListener);
            window.addWindowListener(windowListener);
            window.addComponentListener(componentListener);
        }
    }

    void shutdown() {
        assert SwingUtilities.isEventDispatchThread();
        setDetached(false, false);
        content.removeHierarchyListener(hierarchyListener);
        observeWindow(null);
    }
}

