    /** Commands that work without a live connection to the buffer's network. */
    private static final Set<String> OFFLINE_COMMANDS = new HashSet<>(Arrays.asList(
            "go", "clear", "popout", "help", "networks", "c", "close", "leave", "part"));

    private static String passwordKey(String networkId, String channel) {
        return networkId + "\u0000" + channel.toLowerCase();
    }

    private void systemMessage(String networkId, String text) {
        processMessage(new IrcMessage("System", "System", text, IrcMessage.MessageType.SYSTEM, Instant.now())
                .withNetworkId(networkId));
    }

    private IrcAdapter adapterFor(String networkId) {
        return networks != null ? networks.get(networkId) : null;
    }

    private void setupPanel() {
        panel = injector.getInstance(IrcPanel.class);
        panel.init(
                this::handleMessageSend,
                this::handleChannelJoin,
                this::handleChannelLeave,
                this::handleReconnect,
                this::handleChannelListRequest,
                this::reportChannelListTimeout
        );
        panel.initializeGui();
    }

    /** The channels a freshly opened connection joins. */
    private void joinOnOpen(IrcAdapter adapter, NetworkConfig network) {
        String id = network.getId();
        // Each channel once whatever its casing, with the password to join it with.
        Map<String, String> names = new LinkedHashMap<>();
        Map<String, String> passwords = new HashMap<>();
        boolean firstOpen = openedThisSession.add(id);
        if (network.isBuiltIn()) {
            // Like main: the default channel is joined once per session; a reconnect only
            // rejoins open buffers, so a channel the user parted stays parted.
            if (firstOpen) {
                for (String channel : defaultChannel().split(",")) {
                    want(names, passwords, channel, config.channelPassword());
                }
            }
        } else {
            for (String channel : network.autojoinChannels()) {
                want(names, passwords, channel, channelPasswords.getOrDefault(passwordKey(id, channel), ""));
            }
        }
        // A reconnect rejoins whatever channel buffers are still open for this network.
        if (panel != null) {
            for (BufferKey key : panel.getBuffers()) {
                if (key.getNetworkId().equals(id) && key.getName().startsWith("#")) {
                    want(names, passwords, key.getName(),
                            channelPasswords.getOrDefault(passwordKey(id, key.getName()), ""));
                }
            }
        }
        // The saved order first, so the buffers open in it; anything it does not name after.
        List<String> order = OrderStore.parseChannelOrder(gson, config.channelOrder())
                .getOrDefault(id, Collections.emptyList());
        for (String channel : OrderStore.sortByOrder(new ArrayList<>(names.values()), order)) {
            joinChannel(adapter, id, channel, passwords.get(channel.toLowerCase()));
        }
    }

    private static void want(Map<String, String> names, Map<String, String> passwords, String channel, String password) {
        if (names.putIfAbsent(channel.toLowerCase(), channel) == null) passwords.put(channel.toLowerCase(), password);
    }

    /** The configured channel(s), normalized as joined. */
    private String defaultChannel() {
        String channel;
        if (config.channel().isEmpty()) {
            channel = "#rshelp";
        } else {
            channel = config.channel().toLowerCase();
            if (!channel.startsWith("#")) {
                channel = "#" + channel;
            }
        }
        return channel;
    }

    private void handleMessageSend(BufferKey buffer, String message) {
        if (message.startsWith("/") ||
                (message.startsWith(config.prefix())
                        && message.length() > config.prefix().length())) {
            handleCommand(buffer, message);
        } else {
            IrcAdapter adapter = adapterFor(buffer.getNetworkId());
            if (adapter == null) {
                systemMessage(buffer.getNetworkId(), "Not connected.");
                return;
            }
            adapter.sendMessage(buffer.getName(), message);
        }
    }

    private void handleCommand(BufferKey buffer, String command) {
        if (panel == null) return;
        String net = buffer.getNetworkId();
        String current = buffer.getName();

        String[] parts = command.split(" ", 2);
        String cmd = parts[0].toLowerCase().substring(1);
        String arg = parts.length > 1 ? parts[1].trim() : "";

        IrcAdapter adapter = adapterFor(net);
        if (adapter == null && !OFFLINE_COMMANDS.contains(cmd)) {
            systemMessage(net, "Not connected.");
            return;
        }

        switch (cmd) {
            case "join":
                if (arg.isEmpty()) {
                    // Join with nothing to join: browse the server's channels instead of
                    // silently doing nothing.
                    handleChannelListRequest(net, "");
                } else {
                    String chan = arg.split(" ")[0];
                    String password = arg.split(" ").length > 1 ? arg.split(" ")[1] : "";
                    joinChannel(adapter, net, chan.startsWith("#") ? chan : "#" + chan, password);
                }
                break;

            case "c":
            case "close":
            case "leave":
            case "part":
                closePane(adapter, buffer, arg);
                break;

            case "quit":
                adapter.disconnect(arg.isEmpty() ? "Quitting the plugin" : arg);
                break;

            case "go":
                if (!arg.isEmpty()) {
                    for (BufferKey key : panel.getBuffers()) {
                        if (key.getName().contains(arg)) {
                            SwingUtilities.invokeLater(() -> { if (panel != null) panel.setFocusedChannel(key); });
                            break;
                        }
                    }
                }
                break;

            case "msg":
            case "query":
                String[] msgParts = arg.split(" ", 2);
                if (msgParts.length > 0 && !msgParts[0].isEmpty()) {
                    BufferKey query = BufferKey.of(net, msgParts[0]);
                    SwingUtilities.invokeLater(() -> { if (panel != null) panel.addChannel(query); });
                    if (msgParts.length == 2) adapter.sendMessage(msgParts[0], msgParts[1]);
                }
                break;

            case "me":
                if (!arg.isEmpty()) {
                    adapter.sendAction(current, arg);
                }
                break;

            case "notice":
                String[] noticeParts = arg.split(" ", 2);
                if (noticeParts.length == 2) {
                    String target = noticeParts[0];
                    String noticeMsg = noticeParts[1];
                    adapter.sendNotice(target, noticeMsg);
                }
                break;

            case "whois":
                if (!arg.isEmpty()) {
                    adapter.sendRawLine("WHOIS " + arg);
                }
                break;

            case "whowas":
                if (!arg.isEmpty()) {
                    adapter.sendRawLine("WHOWAS " + arg);
                }
                break;

            case "away":
                if (arg.isEmpty()) {
                    adapter.sendRawLine("AWAY");
                } else {
                    adapter.sendRawLine("AWAY :" + arg);
                }
                break;

            case "names":
                if (current.startsWith("#")) adapter.sendRawLine("NAMES " + current);
                break;

            case "nick": {
                // A typed nick often has a space in it; underscore it rather than ignoring the
                // command, which is what refusing multi-word input used to look like.
                String requestedNick = sanitizeNick(arg);
                if (!requestedNick.isEmpty()) {
                    adapter.setNick(requestedNick);
                }
                break;
            }

            case "id": {
                String idCommand = identifyCommandFromArgs(arg);
                if (idCommand != null) {
                    // Both account and password supplied inline.
                    adapter.getClient().sendMessage("NickServ", idCommand);
                } else {
                    // A lone token is the account; no token means prompt for the account too.
                    String idAccount = arg.isEmpty() ? null : arg.trim().split("\\s+")[0];
                    promptForIdentify(adapter, idAccount);
                }
                break;
            }

            case "ns":
                if (!arg.isEmpty()) {
                    adapter.sendMessage("NickServ", arg);
                }
                break;

            case "cs":
                if (!arg.isEmpty()) {
                    adapter.sendMessage("ChanServ", arg);
                }
                break;

            case "bs":
                if (!arg.isEmpty()) {
                    adapter.sendMessage("BotServ", arg);
                }
                break;

            case "ms":
                if (!arg.isEmpty()) {
                    adapter.sendMessage("MemoServ", arg);
                }
                break;

            case "hs":
                if (!arg.isEmpty()) {
                    adapter.sendMessage("HostServ", arg);
                }
                break;

            case "mode":
                if (!arg.isEmpty()) {
                    mode(adapter, current, arg);
                } else {
                    mode(adapter, current, "");
                }
                break;

            case "umode":
            case "umode2":
                if (!arg.isEmpty()) {
                    adapter.sendRawLine("MODE " + adapter.getNick() + " :" + arg);
                } else {
                    adapter.sendRawLine("MODE " + adapter.getNick());
                }
                break;

            case "topic":
                adapter.sendRawLine(arg.isEmpty() ? "TOPIC " + current : "TOPIC " + current + " :" + arg);
                break;

            case "list":
                handleChannelListRequest(net, arg);
                break;

            case "clear":
                SwingUtilities.invokeLater(() -> { if (panel != null) panel.clearCurrentPane(); });
                break;

            case "popout":
                // Reachable from the chat box, so this works even when the sidebar is hidden.
                if (config.popOut()) {
                    SwingUtilities.invokeLater(() -> {
                        if (panel != null) panel.bringPopOutToFront();
                    });
                } else {
                    configManager.setConfiguration("irc", "popOut", true);
                }
                break;

            case "networks":
                SwingUtilities.invokeLater(() -> openNetworksDialog(null));
                break;

            case "help":
                showCommandHelp(net);
                break;

            default:
                systemMessage(net, "Unknown command: " + cmd);
                break;
        }
    }

    /**
     * Single entry point for both /list and the panel's Browse button.
     *
     * sendRawLine silently no-ops when the socket is down, so an unconnected /list would look
     * like nothing happened at all - check first and say so.
     */
    private void handleChannelListRequest(String networkId, String query) {
        if (panel == null) return;
        IrcAdapter adapter = adapterFor(networkId);
        if (adapter == null || !adapter.isConnected()) {
            systemMessage(networkId, "Not connected.");
            return;
        }
        systemMessage(networkId, "Requesting channel list...");
        panel.setChannelListNetworkId(networkId);
        // Arm before sending. sendRawLine writes and flushes synchronously, so arming afterwards
        // leaves a window - vanishingly small, but real - in which a 323 round-trips and queues
        // its cancel ahead of this arm, and the arm then fires "no response" over a rendered list.
        SwingUtilities.invokeLater(panel::armChannelListTimeout);
        adapter.requestChannelList(query);
    }

    /**
     * Reports a LIST that never came back, on the panel's behalf.
     *
     * Routed through processMessage rather than written straight to the panel so it reaches the
     * game chatbox too. "Requesting channel list..." above and a 263 refusal from the adapter both
     * go to both sinks; this used to be the one channel-list message that did not, which left a
     * user watching game chat with the sidebar collapsed seeing the request and never the outcome.
     */
    private void reportChannelListTimeout() {
        String networkId = panel != null ? panel.getChannelListNetworkId() : NetworkConfig.SWIFTIRC_ID;
        systemMessage(networkId, "No channel list response from the server.");
    }

    private void mode(IrcAdapter adapter, String current, String mode) {
        String[] split = mode.split(" ");
        if (mode.startsWith("#")) {
            adapter.sendRawLine("MODE " + mode);
        } else if (split.length > 0) {
            adapter.sendRawLine("MODE " + current + " " + mode);
        } else {
            adapter.sendRawLine("MODE " + current);
        }
    }

    /**
     * Makes a typed nick safe to send. Whitespace cannot reach the wire - {@code setNick} writes
     * "NICK " + nick as one raw line, so "foo bar" would go out as NICK with two parameters and the
     * server would take only "foo".
     *
     * A run of whitespace collapses to a single underscore: someone who typed three spaces did not
     * mean three underscores, and the server caps nick length. Returns "" when nothing usable is
     * left, so the caller can decline to send rather than sending a lone underscore.
     */
    static String sanitizeNick(String nick) {
        if (nick == null) {
            return "";
        }
        return nick.trim().replaceAll("\\s+", "_");
    }

    static String identifyCommand(String account, String password) {
        if (account != null && !account.isEmpty()) {
            return "identify " + account + " " + password;
        }
        return "identify " + password;
    }

    static String identifyCommandFromArgs(String arg) {
        String[] parts = (arg == null || arg.isEmpty()) ? new String[0] : arg.trim().split("\\s+");
        if (parts.length >= 2) {
            return identifyCommand(parts[0], parts[1]);
        }
        return null;
    }

    private void promptForIdentify(IrcAdapter adapter, String account) {

        SwingUtilities.invokeLater(() -> {
            String acct = account;
            if (acct == null) {
                acct = JOptionPane.showInputDialog(panel.getChatContent(),
                        "Enter your NickServ account (leave blank to identify by nick):",
                        "Account (optional)", JOptionPane.QUESTION_MESSAGE);
                if (acct == null) return; // cancelled
                acct = acct.trim();
            }

            JPasswordField passwordField = new JPasswordField();
            int result = JOptionPane.showConfirmDialog(panel.getChatContent(), passwordField,
                    "Enter your NickServ password", JOptionPane.OK_CANCEL_OPTION, JOptionPane.PLAIN_MESSAGE);
            if (result != JOptionPane.OK_OPTION) return;

            String password = new String(passwordField.getPassword());
            if (password.isEmpty()) return;

            adapter.getClient().sendMessage("NickServ", identifyCommand(acct, password));
        });
    }

    private void showCommandHelp(String networkId) {
        String[] helpLines = {
                "Available commands:",
                "/away [message] - Set or remove away status",
                "/go <channel> - Focus on this channel (uses regex)",
                "/join [#channel] - Join a channel, or browse the list if omitted",
                "/list [filter] - Browse the server's channel list (e.g. /list >50)",
                "/part [#channel] - Leave a channel (aliased as /leave)",
                "/popout - Open IRC in its own window",
                "/me <action> - Send action message",
                "/mode [#channel] [+modes|-modes] - Modify channel modes",
                "/msg <nick> <message> - Send private message",
                "/networks - Add, edit or remove IRC networks",
                "/notice <nick> <message> - Send notice",
                "/topic [#channel] [topic] - View or set the channel topic",
                "/umode [+modes|-modes] - Modify user modes",
                "/whois <nick> - Query user information",
                "/whowas <nick> - Look up a user who has left",
                "/bs <message> - Talk to BotServ",
                "/cs <message> - Talk to ChanServ",
                "/hs <message> - Talk to HostServ",
                "/ms <message> - Talk to MemoServ",
                "/ns <message> - Talk to NickServ",
                "/id [account] [password] - Identify to NickServ (prompts for the password if omitted)"
        };

        for (String line : helpLines) {
            systemMessage(networkId, line);
        }
    }

    private void joinChannel(IrcAdapter adapter, String networkId, String channels, String password) {
        if (adapter == null) return;
        for (String channel : channels.split(",")) {
            if (password != null && !password.isEmpty()) {
                channelPasswords.put(passwordKey(networkId, channel), password);
            }
            adapter.joinChannel(channel, password);
        }
    }

    private void closePane(IrcAdapter adapter, BufferKey buffer, String argument) {
        if (panel == null) return;
        String net = buffer.getNetworkId();
        String currentChannel = buffer.getName();
        if ("System".equalsIgnoreCase(currentChannel) && (argument.isEmpty() || !argument.split(" ", 2)[0].startsWith("#"))) {
            return;
        }
        String[] parts = argument.split(" ", 2);
        String target = parts[0];
        String reason = parts.length > 1 ? parts[1] : null;

        if (argument.isEmpty()) {
            if (currentChannel.startsWith("#")) {
                leaveChannel(adapter, BufferKey.of(net, currentChannel), null);
            } else {
                SwingUtilities.invokeLater(() -> panel.removeChannel(buffer));
            }
        } else if (target.startsWith("#")) {
            leaveChannel(adapter, BufferKey.of(net, target), reason);
        } else if (panel.isPane(BufferKey.of(net, target))) {
            SwingUtilities.invokeLater(() -> panel.removeChannel(BufferKey.of(net, target)));
        } else if (currentChannel.startsWith("#")) {
            leaveChannel(adapter, BufferKey.of(net, currentChannel), argument);
        }
    }

    /** Parts a channel when connected; the buffer closes either way. */
    private void leaveChannel(IrcAdapter adapter, BufferKey channel, String reason) {
        if (adapter != null && channel.getName().startsWith("#")) {
            if (reason != null) adapter.leaveChannel(channel.getName(), reason);
            else adapter.leaveChannel(channel.getName());
        }
        channelPasswords.remove(passwordKey(channel.getNetworkId(), channel.getName()));
        if (panel != null) {
            SwingUtilities.invokeLater(() -> { if (panel != null) panel.removeChannel(channel); });
        }
    }

    private void handleChannelJoin(String networkId, String channel, String password) {
        joinChannel(adapterFor(networkId), networkId, channel, password);
    }

    private void handleChannelLeave(BufferKey channel) {
        leaveChannel(adapterFor(channel.getNetworkId()), channel, null);
    }

    private void handleReconnect(String networkId) {
        reconnectNetwork(networkId);
    }

    /** Reconnects with the live settings for {@code networkId}, as main rebuilt from config. */
    private void reconnectNetwork(String networkId) {
        if (networks == null) return;
        for (NetworkConfig network : networkConfigs()) {
            if (network.getId().equals(networkId)) {
                networks.reconnect(network);
                return;
            }
        }
        networks.reconnect(networkId);
    }

    /** A colour code (the background, if any, is matched only to be dropped) or any other formatting code. */
    private static final Pattern CHATBOX_CODES =
            Pattern.compile("\\x03(?:(\\d\\d?)(?:,\\d\\d?)?)?|[\\x02\\x0F\\x11\\x15\\x16\\x1D\\x1E\\x1F]");

    /**
     * Builds the in-game chat box form of {@code text}. Uncoloured text uses the base colour: the
     * custom in-game colour if set, otherwise RuneLite's NORMAL chat colour. With IRC colours on,
     * colour codes become col tags; every other formatting code is stripped either way.
     */
    static String chatboxMessage(String text, IrcConfig config) {
        Color base = config.inGameTextColorEnabled() ? config.inGameTextColor() : null;
        ChatMessageBuilder builder = new ChatMessageBuilder();
        if (!config.ircColorsInGame()) {
            appendChatboxRun(builder, IrcFormatting.stripCodes(text), null, base);
            return builder.build();
        }

        Matcher matcher = CHATBOX_CODES.matcher(text);
        StringBuilder run = new StringBuilder();
        Color runColor = null;
        int last = 0;
        while (matcher.find()) {
            run.append(text, last, matcher.start());
            last = matcher.end();
            char code = matcher.group().charAt(0);
            if (code != '\u0003' && code != '\u000F') {
                continue;
            }
            // A reset, a bare colour code, or code 99 all mean "back to the default colour".
            Color next = code == '\u0003' ? chatboxColorById(matcher.group(1)) : null;
            if (!Objects.equals(next, runColor)) {
                appendChatboxRun(builder, run.toString(), runColor, base);
                run.setLength(0);
                runColor = next;
            }
        }
        run.append(text, last, text.length());
        appendChatboxRun(builder, run.toString(), runColor, base);
        return builder.build();
    }

    private static void appendChatboxRun(ChatMessageBuilder builder, String run, Color color, Color base) {
        if (run.isEmpty()) {
            return;
        }
        Color effective = color != null ? color : base;
        if (effective != null) {
            // Unlike append(String), append(Color, String) doesn't escape game tags like <img=1>.
            builder.append(effective, Text.escapeJagex(run));
        } else {
            builder.append(ChatColorType.NORMAL).append(run);
        }
    }

    /** The palette colour for an IRC colour code, or null for 99, no code, or an unknown code. */
    private static Color chatboxColorById(String id) {
        if (id == null || Integer.parseInt(id) > 98) {
            return null;
        }
        String html = IrcPanel.ChannelPane.htmlColorById(id);
        switch (html) {
            case "white":
                return Color.WHITE;
            case "black":
                return Color.BLACK;
            default:
                return Color.decode(html);
        }
    }

    /** Only the in-game network's live traffic is echoed into the game chatbox and overlay. */
    static boolean echoesInGame(IrcMessage message, String inGameNetworkId) {
        return inGameNetworkId.equals(message.getNetworkId())
                && message.getType() != IrcMessage.MessageType.HISTORY
                && message.getType() != IrcMessage.MessageType.HISTORY_SEPARATOR;
    }

    /** The network chosen for game chat; SwiftIRC when none is chosen or it was removed. */
    private String inGameNetwork() {
        String id = config.inGameNetwork();
        NetworkManager current = networks;
        return id != null && current != null && current.isKnown(id) ? id : NetworkConfig.SWIFTIRC_ID;
    }

    private void processMessage(IrcMessage message) {
        // An adapter that was removed can still deliver a line or two while it shuts down.
        NetworkManager current = networks;
        if (current != null && !current.isKnown(message.getNetworkId())) return;

        IrcMessage.MessageType[] chatBoxEvents = {IrcMessage.MessageType.QUIT, IrcMessage.MessageType.NICK_CHANGE};
        BufferKey target = message.getBuffer();

        if (echoesInGame(message, inGameNetwork()) && client.getGameState() == GameState.LOGGED_IN) {
            BufferKey focused = panel != null ? panel.getCurrentBuffer() : null;
            boolean activeChannelCondition = focused == null
                    || (focused.getNetworkId().equals(target.getNetworkId())
                    && focused.getName().equalsIgnoreCase(target.getName()));
            boolean isSystemEvent = message.getChannel().equals("System") && Arrays.binarySearch(chatBoxEvents, message.getType()) > -1;

            if (!config.activeChannelOnly() || (config.activeChannelOnly() && (activeChannelCondition || isSystemEvent))) {
                chatMessageManager.queue(QueuedMessage.builder()
                        .type(config.getChatboxType().getType())
                        .sender(message.getChannel())
                        .name(message.getDisplaySender())
                        .runeLiteFormattedMessage(chatboxMessage(
                                EmojiParser.parseToAliases(message.getContent()), config))
                        .timestamp((int) (message.getTimestamp().getEpochSecond()))
                        .build());
            }
        }

        if (panel != null) {
            SwingUtilities.invokeLater(() -> {
                if (panel != null) panel.addMessage(message);
            });
        }
    }

    private void updatePanelHost(boolean rebuildNavigation) {
        SwingUtilities.invokeLater(() -> {
            if (panel == null) return;
            clientToolbar.removeNavigation(panel.getNavigationButton());
            if (rebuildNavigation) panel.generateNavigationButton();
            panel.setDetached(config.popOut(), config.popOutAlwaysOnTop());
            if (config.sidePanel() && !config.popOut()) {
                clientToolbar.addNavigation(panel.getNavigationButton());
            }
        });
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged configChanged) {
        if (!configChanged.getGroup().equals("irc")) {
            return;
        }

        if ("sidePanel".equals(configChanged.getKey())
                || "popOut".equals(configChanged.getKey())
                || "panelPriority".equals(configChanged.getKey())) {
            updatePanelHost("panelPriority".equals(configChanged.getKey()));
        } else if ("popOutAlwaysOnTop".equals(configChanged.getKey())) {
            SwingUtilities.invokeLater(() -> {
                if (panel != null) {
                    panel.setDetached(config.popOut(), config.popOutAlwaysOnTop());
                }
            });
        } else if ("fontSize".equals(configChanged.getKey())) {
            SwingUtilities.invokeLater(() -> {
                if (panel != null) {
                    panel.updateFont();
                }
            });
        } else if ("chatBackgroundColor".equals(configChanged.getKey())
                || "chatTextColor".equals(configChanged.getKey())) {
            SwingUtilities.invokeLater(() -> {
                if (panel != null) {
                    panel.updateColors();
                }
            });
        } else if ("overlayEnabled".equals(configChanged.getKey())) {
            if (overlay != null) {
                overlay.setEnabled(config.overlayEnabled());
            }
        } else if (NetworkStore.CONFIG_KEY.equals(configChanged.getKey())
                || OrderStore.NETWORK_ORDER_KEY.equals(configChanged.getKey())
                || "swiftIrcEnabled".equals(configChanged.getKey())) {
            applyNetworks();
        } else if (OrderStore.CHANNEL_ORDER_KEY.equals(configChanged.getKey())) {
            applyChannelOrder();
        } else if ("server".equals(configChanged.getKey())
                || "accountName".equals(configChanged.getKey())
                || "password".equals(configChanged.getKey())
                || "channel".equals(configChanged.getKey())) {
            // Like main: picked up on the next Reconnect, not applied live.
            if (networks != null) networks.update(NetworkConfig.swiftIrc(config));
        } else if ("logRawLines".equals(configChanged.getKey())) {
            // Applied live: the connection failure worth capturing usually happens during
            // connect, so requiring a reconnect to arm the log would miss it.
            if (networks != null) {
                for (IrcAdapter adapter : networks.adapters()) adapter.setRawLogging(config.logRawLines());
            }
        } else if ("overlayDynamic".equals(configChanged.getKey())) {
            if (overlay != null) {
                overlayManager.remove(overlay);
                overlay = new IrcOverlay(client, panel, config, keyManager);
                overlayManager.add(overlay);
            }
        }
    }

    @Subscribe
    public void onScriptCallbackEvent(ScriptCallbackEvent event) {
        if (!"chatDefaultReturn".equals(event.getEventName()) || networks == null) {
            return;
        }

        String message = client.getVarcStrValue(VarClientID.CHATINPUT);
        Matcher matcher = VALID_WINKS.matcher(message);

        if (message.startsWith(config.prefix()) && !matcher.matches()) {
            final int[] intStack = client.getIntStack();
            int intStackCount = client.getIntStackSize();
            intStack[intStackCount - 3] = 1;

            BufferKey current = panel != null ? panel.getCurrentBuffer() : BufferKey.swiftIrc(this.config.channel());
            handleMessageSend(current, message.substring(1));
        }
    }

    @Subscribe
    public void onMenuEntryAdded(MenuEntryAdded entry) {
        // Only target chat message widgets
        if (entry.getType() != MenuAction.CC_OP.getId() && entry.getType() != MenuAction.CC_OP_LOW_PRIORITY.getId()) {
            return;
        }

        final int groupId = WidgetUtil.componentToInterface(entry.getActionParam1());
        final int childId = WidgetUtil.componentToId(entry.getActionParam1());

        // Make sure we're in the chatbox
        if (groupId != InterfaceID.CHATBOX) {
            return;
        }

        if (!entry.getOption().equals("Report")) {
            return;
        }

        final Widget widget = client.getWidget(groupId, childId);
        if (widget == null) {
            return;
        }

        final Widget parent = widget.getParent();
        if (parent == null || InterfaceID.Chatbox.SCROLLAREA != parent.getId()) {
            return;
        }

        // Get child id of first chat message static child so we can subtract this offset to link to dynamic child
        final int first = WidgetUtil.componentToId(InterfaceID.Chatbox.LINE0);

        // Convert current message static widget id to dynamic widget id of message node with message contents
        final int dynamicChildId = (childId - first) * 4 + 1;

        // Extract message contents from the specific widget being right-clicked
        final Widget messageContents = parent.getChild(dynamicChildId);
        if (messageContents == null) {
            return;
        }

        String currentMessage = messageContents.getText();
        if (currentMessage == null) {
            return;
        }

        // Remove formatting tags and check for URLs in this specific message
        String cleanMessage = Text.removeTags(currentMessage);
        List<String> urls = extractUrls(cleanMessage);

        if (!urls.isEmpty()) {
            // Add menu entries for each URL found in this specific message
            for (int i = 0; i < urls.size(); i++) {
                final String url = urls.get(i);

                client.createMenuEntry(1)
                        .setOption("Open URL: " + url.substring(0, Math.min(25, url.length())) + (url.length() > 25 ? "..." : ""))
                        .setTarget(entry.getTarget())
                        .setType(MenuAction.RUNELITE)
                        .onClick(e -> LinkBrowser.browse(url));
            }
        }
    }

    private List<String> extractUrls(String message) {
        List<String> urls = new ArrayList<>();
        Matcher matcher = IrcPanel.VALID_LINK.matcher(message);

        while (matcher.find()) {
            String url = matcher.group().trim();
            // Ensure URLs have proper protocol
            if (!url.startsWith("http://") && !url.startsWith("https://")) {
                if (url.startsWith("www.")) {
                    url = "https://" + url;
                } else {
                    url = "https://" + url;
                }
            }
            urls.add(url);
        }

        return urls;
    }
}

package com.irc;

import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * The server's mode vocabulary, learned from RPL_ISUPPORT (numeric 005).
 *
 * Two tokens matter. {@code PREFIX=(qaohv)~&@%+} positionally pairs membership mode letters with
 * their display prefixes, and the position doubles as the rank (0 = most privileged).
 * {@code CHANMODES=A,B,C,D} says which mode letters consume a parameter, which is what makes
 * {@code MODE #chan +mo bob} apply "o" to "bob" rather than to whatever came next.
 *
 * Falls back to the widely-supported defaults below when a server sends no 005, or sends one
 * that omits or mangles a token. Mode letters absent from both tables are assumed parameterless.
 */
class ModeSpec {

    private static final String DEFAULT_PREFIX = "(qaohv)~&@%+";
    private static final String DEFAULT_CHANMODES = "beI,k,l,imnpst";

    private final Map<Character, Character> prefixByMode = new HashMap<>();
    private final Map<Character, Character> modeByPrefix = new HashMap<>();
    private final Map<Character, Integer> rankByMode = new HashMap<>();

    private String typeA = "";
    private String typeB = "";
    private String typeC = "";

    static ModeSpec defaults() {
        ModeSpec spec = new ModeSpec();
        spec.parsePrefix(DEFAULT_PREFIX);
        spec.parseChanmodes(DEFAULT_CHANMODES);
        return spec;
    }

    /**
     * Applies the token list from a 005 line. The leading nick and the trailing human-readable
     * description are not {@code KEY=VALUE} pairs and are skipped, as is any token we do not use.
     */
    void applyIsupport(List<String> tokens) {
        if (tokens == null) {
            return;
        }
        for (String token : tokens) {
            if (token == null) {
                continue;
            }
            int equals = token.indexOf('=');
            if (equals <= 0) {
                continue;
            }
            String key = token.substring(0, equals);
            String value = token.substring(equals + 1);
            if ("PREFIX".equals(key)) {
                parsePrefix(value);
            } else if ("CHANMODES".equals(key)) {
                parseChanmodes(value);
            }
        }
    }

    /** Parses {@code (modes)prefixes}; leaves the current table untouched if it does not parse. */
    private void parsePrefix(String value) {
        int close = value.indexOf(')');
        if (!value.startsWith("(") || close < 0) {
            return;
        }
        String modes = value.substring(1, close);
        String prefixes = value.substring(close + 1);
        if (modes.length() != prefixes.length() || modes.isEmpty()) {
            return;
        }

        prefixByMode.clear();
        modeByPrefix.clear();
        rankByMode.clear();
        for (int i = 0; i < modes.length(); i++) {
            prefixByMode.put(modes.charAt(i), prefixes.charAt(i));
            modeByPrefix.put(prefixes.charAt(i), modes.charAt(i));
            rankByMode.put(modes.charAt(i), i);
        }
    }

    /** Parses {@code A,B,C,D}. Type D is not stored - it is the "no parameter" default. Leaves the current table untouched if it does not parse. */
    private void parseChanmodes(String value) {
        String[] groups = value.split(",", -1);
        if (groups.length < 4) {
            return;
        }
        typeA = groups[0];
        typeB = groups[1];
        typeC = groups[2];
    }

    boolean isPrefixMode(char modeLetter) {
        return prefixByMode.containsKey(modeLetter);
    }

    char prefixFor(char modeLetter) {
        Character prefix = prefixByMode.get(modeLetter);
        return prefix == null ? '\0' : prefix;
    }

    Character modeForPrefix(char prefixChar) {
        return modeByPrefix.get(prefixChar);
    }

    int rankOf(char modeLetter) {
        Integer rank = rankByMode.get(modeLetter);
        return rank == null ? Integer.MAX_VALUE : rank;
    }

    boolean takesParameter(char modeLetter, boolean adding) {
        if (isPrefixMode(modeLetter)) {
            return true;
        }
        if (typeA.indexOf(modeLetter) >= 0 || typeB.indexOf(modeLetter) >= 0) {
            return true;
        }
        if (typeC.indexOf(modeLetter) >= 0) {
            return adding;
        }
        return false;
    }
}

package com.irc;

import lombok.Builder;
import lombok.Value;

import java.util.ArrayList;
import java.util.List;
import java.util.Objects;

/**
 * One IRC network the plugin connects to. Extra networks are stored by {@link NetworkStore};
 * the built-in SwiftIRC entry is rebuilt from the Connection settings by {@link #swiftIrc}.
 */
@Value
@Builder(toBuilder = true)
public class NetworkConfig {
    static final String SWIFTIRC_ID = "swiftirc";
    static final String SWIFTIRC_NAME = "SwiftIRC";
    static final int DEFAULT_PORT = 6697;

    String id;
    String name;
    String host;
    @Builder.Default int port = DEFAULT_PORT;
    @Builder.Default boolean tls = true;
    /** False accepts any certificate for any host: still encrypted, but not authenticated. */
    @Builder.Default boolean verifyTls = true;
    /** Blank means "use the Username setting". */
    @Builder.Default String nick = "";
    /** Sent as PASS before registering; ZNC reads "user/network:password" from it. */
    @Builder.Default String serverPassword = "";
    @Builder.Default String saslAccount = "";
    @Builder.Default String saslPassword = "";
    /** Comma-separated channels joined on connect. */
    @Builder.Default String autojoin = "";
    @Builder.Default boolean enabled = true;

    boolean isBuiltIn() {
        return SWIFTIRC_ID.equals(id);
    }

    /** True when moving from this config to {@code other} needs a fresh connection. */
    boolean connectionDiffers(NetworkConfig other) {
        return !Objects.equals(host, other.host) || port != other.port || tls != other.tls
                || verifyTls != other.verifyTls
                || !Objects.equals(nick, other.nick)
                || !Objects.equals(serverPassword, other.serverPassword)
                || !Objects.equals(saslAccount, other.saslAccount)
                || !Objects.equals(saslPassword, other.saslPassword);
    }

    /** The autojoin list as channel names, each starting with # or &. */
    List<String> autojoinChannels() {
        List<String> channels = new ArrayList<>();
        for (String part : autojoin.split(",")) {
            String channel = part.trim();
            if (channel.isEmpty()) continue;
            channels.add(channel.startsWith("#") || channel.startsWith("&") ? channel : "#" + channel);
        }
        return channels;
    }

    /** The built-in network, from today's Connection settings. Its nick is seeded by the plugin. */
    static NetworkConfig swiftIrc(IrcConfig config) {
        String password = config.password();
        return NetworkConfig.builder()
                .id(SWIFTIRC_ID)
                .name(SWIFTIRC_NAME)
                .host(config.server().getHostname())
                .port(DEFAULT_PORT)
                .tls(true)
                .verifyTls(true)
                .saslAccount(config.accountName() == null ? "" : config.accountName())
                .saslPassword(password == null ? "" : password)
                .autojoin(config.channel() == null ? "" : config.channel())
                .enabled(config.swiftIrcEnabled())
                .build();
    }
}

package com.irc;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * Owns one {@link IrcAdapter} per running network and keeps that set in step with the saved
 * list. Synchronized: the EDT (buttons, dialog) and RuneLite's client thread (config changes,
 * chatbox commands) both call in.
 */
final class NetworkManager {
    /** Opens and closes connections; the plugin supplies the real one, tests a recorder. */
    interface Connector {
        IrcAdapter open(NetworkConfig network);

        /** {@code adapter} is null when the network was not running (e.g. removed while disabled). */
        void close(IrcAdapter adapter, NetworkConfig network, boolean removed, String reason);
    }

    private final Connector connector;
    /** Every saved network, in display order, enabled or not. */
    private final Map<String, NetworkConfig> known = new LinkedHashMap<>();
    private final Map<String, IrcAdapter> running = new LinkedHashMap<>();
    /** Networks the user disconnected by hand; a config change must not bring them back. */
    private final Set<String> paused = new HashSet<>();
    /**
     * Networks that don't connect automatically but that the user connected by hand this
     * session; a config change must not take them back down.
     */
    private final Set<String> manual = new HashSet<>();

    NetworkManager(Connector connector) {
        this.connector = connector;
    }

    synchronized void apply(List<NetworkConfig> configs) {
        Map<String, NetworkConfig> next = new LinkedHashMap<>();
        for (NetworkConfig config : configs) next.put(config.getId(), config);

        for (String id : new ArrayList<>(known.keySet())) {
            if (!next.containsKey(id)) {
                stop(id, true, "Network removed");
                known.remove(id);
                paused.remove(id);
                manual.remove(id);
            }
        }

        Map<String, NetworkConfig> previous = new LinkedHashMap<>(known);
        known.clear();
        known.putAll(next);
        for (NetworkConfig config : next.values()) {
            String id = config.getId();
            NetworkConfig before = previous.get(id);
            if (!config.isEnabled() && !manual.contains(id)) {
                stop(id, false, "Disconnecting");
            } else if (!config.isEnabled()) {
                if (running.containsKey(id) && before != null && before.connectionDiffers(config)) {
                    stop(id, false, "Reloading, brb");
                    start(config);
                }
            } else if (!running.containsKey(id)) {
                if (!paused.contains(id)) start(config);
            } else if (before != null && before.connectionDiffers(config)) {
                stop(id, false, "Reloading, brb");
                start(config);
            }
        }
    }

    synchronized IrcAdapter get(String id) {
        return running.get(id);
    }

    synchronized NetworkConfig config(String id) {
        return known.get(id);
    }

    synchronized List<NetworkConfig> configs() {
        return new ArrayList<>(known.values());
    }

    synchronized List<IrcAdapter> adapters() {
        return new ArrayList<>(running.values());
    }

    synchronized boolean isKnown(String id) {
        return known.containsKey(id);
    }

    synchronized boolean isRunning(String id) {
        return running.containsKey(id);
    }

    synchronized void reconnect(String id) {
        NetworkConfig config = known.get(id);
        if (config == null || (!config.isEnabled() && !manual.contains(id))) return;
        paused.remove(id);
        stop(id, false, "Reloading, brb");
        start(config);
    }

    /**
     * Reconnects with {@code fresh} (live settings, e.g. the SwiftIRC Connection config) in place of
     * the stored config. Ignored for a network that is not known.
     */
    synchronized void reconnect(NetworkConfig fresh) {
        String id = fresh.getId();
        if (!known.containsKey(id)) return;
        known.put(id, fresh);
        reconnect(id);
    }

    /** Replaces the stored config of a known network without touching its connection. */
    synchronized void update(NetworkConfig fresh) {
        if (known.containsKey(fresh.getId())) known.put(fresh.getId(), fresh);
    }

    /** Connects or disconnects for this session without touching the saved enabled flag. */
    synchronized void setConnected(String id, boolean connected) {
        NetworkConfig config = known.get(id);
        if (config == null) return;
        if (connected) {
            paused.remove(id);
            if (!config.isEnabled()) manual.add(id);
            if (!running.containsKey(id)) {
                start(config);
            } else {
                // Still listed but dropped (lost link, bad password, /quit): connect afresh.
                IrcAdapter adapter = running.get(id);
                if (adapter == null || !adapter.isConnected()) {
                    stop(id, false, "Reloading, brb");
                    start(config);
                }
            }
        } else {
            paused.add(id);
            manual.remove(id);
            stop(id, false, "Disconnecting");
        }
    }

    synchronized void shutdown() {
        for (String id : new ArrayList<>(running.keySet())) stop(id, false, "Plugin shutting down");
    }

    /** Test seam: treat {@code adapter} as the running connection for {@code config}. */
    synchronized void register(NetworkConfig config, IrcAdapter adapter) {
        known.put(config.getId(), config);
        running.put(config.getId(), adapter);
    }

    private void start(NetworkConfig config) {
        running.put(config.getId(), connector.open(config));
    }

    private void stop(String id, boolean removed, String reason) {
        IrcAdapter adapter = running.remove(id);
        NetworkConfig config = known.get(id);
        if (config == null) return;
        if (adapter != null || removed) connector.close(adapter, config, removed, reason);
    }
}

package com.irc;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import com.google.gson.reflect.TypeToken;
import lombok.extern.slf4j.Slf4j;

import java.lang.reflect.Type;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

/** Reads and writes the extra networks kept as JSON under the hidden {@code irc.networks} key. */
@Slf4j
final class NetworkStore {
    static final String CONFIG_KEY = "networks";
    private static final Type STORED_LIST = new TypeToken<List<Stored>>() {}.getType();

    private NetworkStore() {
    }

    /**
     * NetworkConfig's fields with boxed types. Gson bypasses constructors, so reading straight into
     * NetworkConfig would turn a missing "tls" into false instead of the default true.
     */
    private static final class Stored {
        String id;
        String name;
        String host;
        Integer port;
        Boolean tls;
        Boolean verifyTls;
        String nick;
        String serverPassword;
        String saslAccount;
        String saslPassword;
        String autojoin;
        Boolean enabled;
    }

    /**
     * The valid entries of {@code json}, in order. Unreadable JSON gives an empty list and is
     * logged, never thrown: a bad hand edit must not stop SwiftIRC from connecting.
     */
    static List<NetworkConfig> parse(Gson gson, String json) {
        if (json == null || json.trim().isEmpty()) return Collections.emptyList();
        List<Stored> stored;
        try {
            stored = gson.fromJson(json, STORED_LIST);
        } catch (JsonParseException | IllegalStateException e) {
            log.warn("Ignoring unreadable IRC network list", e);
            return Collections.emptyList();
        }
        if (stored == null) return Collections.emptyList();

        List<NetworkConfig> networks = new ArrayList<>();
        Set<String> ids = new HashSet<>();
        for (Stored s : stored) {
            if (s == null || isBlank(s.id) || isBlank(s.name) || isBlank(s.host)) {
                log.warn("Skipping an IRC network without an id, name or host");
                continue;
            }
            if (NetworkConfig.SWIFTIRC_ID.equals(s.id) || !ids.add(s.id)) {
                log.warn("Skipping IRC network {}: its id is reserved or already used", s.name);
                continue;
            }
            networks.add(NetworkConfig.builder()
                    .id(s.id)
                    .name(s.name.trim())
                    .host(s.host.trim())
                    .port(s.port != null ? s.port : NetworkConfig.DEFAULT_PORT)
                    .tls(s.tls == null || s.tls)
                    .verifyTls(s.verifyTls == null || s.verifyTls)
                    .nick(orEmpty(s.nick))
                    .serverPassword(orEmpty(s.serverPassword))
                    .saslAccount(orEmpty(s.saslAccount))
                    .saslPassword(orEmpty(s.saslPassword))
                    .autojoin(orEmpty(s.autojoin))
                    .enabled(s.enabled == null || s.enabled)
                    .build());
        }
        return networks;
    }

    static String serialize(Gson gson, List<NetworkConfig> networks) {
        List<Stored> stored = new ArrayList<>();
        for (NetworkConfig n : networks) {
            Stored s = new Stored();
            s.id = n.getId();
            s.name = n.getName();
            s.host = n.getHost();
            s.port = n.getPort();
            s.tls = n.isTls();
            s.verifyTls = n.isVerifyTls();
            s.nick = n.getNick();
            s.serverPassword = n.getServerPassword();
            s.saslAccount = n.getSaslAccount();
            s.saslPassword = n.getSaslPassword();
            s.autojoin = n.getAutojoin();
            s.enabled = n.isEnabled();
            stored.add(s);
        }
        return gson.toJson(stored, STORED_LIST);
    }

    private static boolean isBlank(String s) {
        return s == null || s.trim().isEmpty();
    }

    private static String orEmpty(String s) {
        return s == null ? "" : s;
    }
}

package com.irc;

import javax.swing.*;
import java.awt.*;
import java.util.ArrayList;
import java.util.List;
import java.util.UUID;

/**
 * Lists the built-in SwiftIRC network and the user's extra networks in the user's order, edits
 * the extras and reorders all of them.
 */
final class NetworksDialog extends JDialog {
    interface Callbacks {
        /** Persists the extra networks (SwiftIRC excluded), in display order. */
        void save(List<NetworkConfig> extras);

        /** Persists the order of every network, SwiftIRC included, as ids. */
        void saveOrder(List<String> ids);

        boolean isConnected(String networkId);

        void setConnected(String networkId, boolean connected);

        /** Persists whether SwiftIRC connects automatically. */
        default void saveBuiltIn(boolean enabled) {
        }

        /** Persists which network feeds the game chat. */
        default void saveInGameNetwork(String networkId) {
        }
    }

    private NetworkConfig builtIn;
    private final List<NetworkConfig> extras = new ArrayList<>();
    /** The saved network order; see {@link OrderStore#applyNetworkOrder}. */
    private final List<String> order = new ArrayList<>();
    private final Callbacks callbacks;
    /** The network whose chat is echoed in game; SwiftIRC unless the user picked another. */
    private String inGame = NetworkConfig.SWIFTIRC_ID;
    private final DefaultListModel<NetworkConfig> model = new DefaultListModel<>();
    private final JList<NetworkConfig> list = new JList<>(model);
    private final JButton edit = button("Edit…", "ircNetworkEdit", this::editSelected);
    private final JButton duplicate = button("Duplicate", "ircNetworkDuplicate", this::duplicateSelected);
    private final JButton remove = button("Remove", "ircNetworkRemove", this::removeSelected);
    private final JButton connect = button("Connect", "ircNetworkConnect", this::toggleConnection);
    private final JButton up = button("Move up", "ircNetworkUp", () -> moveSelected(-1));
    private final JButton down = button("Move down", "ircNetworkDown", () -> moveSelected(1));

    NetworksDialog(Window owner, NetworkConfig builtIn, List<NetworkConfig> extras, List<String> order,
                   Callbacks callbacks) {
        super(owner, "IRC networks", ModalityType.MODELESS);
        this.callbacks = callbacks;
        setDefaultCloseOperation(HIDE_ON_CLOSE);

        list.setName("ircNetworkList");
        list.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);
        list.setCellRenderer(new DefaultListCellRenderer() {
            @Override
            public Component getListCellRendererComponent(JList<?> l, Object value, int index,
                                                          boolean selected, boolean focused) {
                super.getListCellRendererComponent(l, value, index, selected, focused);
                NetworkConfig network = (NetworkConfig) value;
                setText(describe(network, callbacks.isConnected(network.getId()), network.getId().equals(inGame)));
                return this;
            }
        });
        list.addListSelectionListener(e -> updateButtons());

        JPanel buttons = new JPanel(new FlowLayout(FlowLayout.LEFT));
        buttons.add(button("Add…", "ircNetworkAdd", this::addNetwork));
        buttons.add(edit);
        buttons.add(duplicate);
        buttons.add(remove);
        buttons.add(connect);
        buttons.add(up);
        buttons.add(down);
        JPanel south = new JPanel(new BorderLayout());
        south.add(buttons, BorderLayout.NORTH);
        JLabel note = new JLabel("SwiftIRC's server, username and passwords are set in RuneLite's"
                + " Global Chat (IRC) settings.");
        note.setBorder(BorderFactory.createEmptyBorder(0, 8, 8, 8));
        south.add(note, BorderLayout.SOUTH);

        JPanel content = new JPanel(new BorderLayout());
        content.add(new JScrollPane(list), BorderLayout.CENTER);
        content.add(south, BorderLayout.SOUTH);
        setContentPane(content);

        setNetworks(builtIn, extras, order);
        setSize(640, 320);
        setLocationRelativeTo(owner);
    }

    /** Replaces what the list shows, keeping the selection where it can. */
    void setNetworks(NetworkConfig builtIn, List<NetworkConfig> extras, List<String> order) {
        this.builtIn = builtIn;
        this.extras.clear();
        this.extras.addAll(extras);
        this.order.clear();
        this.order.addAll(order);
        reload();
    }

    void setInGameNetwork(String id) {
        inGame = id != null ? id : NetworkConfig.SWIFTIRC_ID;
        list.repaint();
    }

    String inGameNetwork() {
        return inGame;
    }

    /**
     * Ticking "Show in game chat" makes that network the in-game one; unticking the current one
     * hands game chat back to SwiftIRC. Only one network is ever in game.
     */
    void applyInGameChoice(String id, boolean checked) {
        String next = inGame;
        if (checked) next = id;
        else if (id.equals(inGame)) next = NetworkConfig.SWIFTIRC_ID;
        if (next.equals(inGame)) return;
        inGame = next;
        callbacks.saveInGameNetwork(next);
        list.repaint();
    }

    void selectNetwork(String id) {
        if (id == null) return;
        for (int i = 0; i < model.size(); i++) {
            if (model.get(i).getId().equals(id)) {
                list.setSelectedIndex(i);
                return;
            }
        }
    }

    static String describe(NetworkConfig network, boolean connected) {
        return describe(network, connected, false);
    }

    static String describe(NetworkConfig network, boolean connected, boolean inGame) {
        return (connected ? "● " : "○ ") + network.getName() + "   " + network.getHost() + ":" + network.getPort()
                + (network.isEnabled() ? "" : "  (disabled)") + (inGame ? "  (in game)" : "");
    }

    /** Why {@code candidate} can't be saved, or null when it can. {@code others} may include it. */
    static String validate(NetworkConfig candidate, List<NetworkConfig> others) {
        String name = candidate.getName().trim();
        if (name.isEmpty()) return "Give the network a name.";
        if (candidate.getHost().trim().isEmpty()) return "Enter the server's host name.";
        if (candidate.getPort() < 1 || candidate.getPort() > 65535) return "The port must be between 1 and 65535.";
        if (name.equalsIgnoreCase(NetworkConfig.SWIFTIRC_NAME)) {
            return "The name SwiftIRC is reserved for the built-in network.";
        }
        for (NetworkConfig other : others) {
            if (!other.getId().equals(candidate.getId()) && other.getName().trim().equalsIgnoreCase(name)) {
                return "Another network is already called " + other.getName() + ".";
            }
        }
        return null;
    }

    static NetworkConfig duplicateOf(NetworkConfig source) {
        return source.toBuilder().id(UUID.randomUUID().toString()).name(source.getName() + " (copy)").build();
    }

    private NetworkConfig selected() {
        return list.getSelectedValue();
    }

    private void updateButtons() {
        NetworkConfig selected = selected();
        boolean extra = selected != null && !selected.isBuiltIn();
        edit.setEnabled(selected != null);
        duplicate.setEnabled(extra);
        remove.setEnabled(extra);
        // A network that doesn't connect automatically can still be connected by hand.
        connect.setEnabled(selected != null);
        connect.setText(selected != null && callbacks.isConnected(selected.getId()) ? "Disconnect" : "Connect");
        int index = list.getSelectedIndex();
        up.setEnabled(index > 0);
        down.setEnabled(index >= 0 && index < model.size() - 1);
    }

    private void reload() {
        String selectedId = selected() != null ? selected().getId() : null;
        model.clear();
        for (NetworkConfig network : OrderStore.applyNetworkOrder(all(), order)) model.addElement(network);
        selectNetwork(selectedId);
        updateButtons();
    }

    /** SwiftIRC, then the extras in their saved list order. */
    private List<NetworkConfig> all() {
        List<NetworkConfig> all = new ArrayList<>();
        all.add(builtIn);
        all.addAll(extras);
        return all;
    }

    /**
     * Swaps the selected network with its neighbour and saves both the full order and the extras
     * in the same relative order, so the stored list reads the way the dialog shows it.
     */
    private void moveSelected(int step) {
        int from = list.getSelectedIndex();
        int to = from + step;
        if (from < 0 || to < 0 || to >= model.size()) return;
        List<NetworkConfig> shown = new ArrayList<>();
        for (int i = 0; i < model.size(); i++) shown.add(model.get(i));
        NetworkConfig moved = shown.remove(from);
        shown.add(to, moved);
        order.clear();
        extras.clear();
        for (NetworkConfig network : shown) {
            order.add(network.getId());
            if (!network.isBuiltIn()) extras.add(network);
        }
        callbacks.save(new ArrayList<>(extras));
        callbacks.saveOrder(new ArrayList<>(order));
        reload();
        selectNetwork(moved.getId());
    }

    private int indexOf(String id) {
        for (int i = 0; i < extras.size(); i++) {
            if (extras.get(i).getId().equals(id)) return i;
        }
        return -1;
    }

    private void commit(String selectId) {
        callbacks.save(new ArrayList<>(extras));
        reload();
        selectNetwork(selectId);
    }

    private void addNetwork() {
        NetworkConfig fresh = NetworkConfig.builder().id(UUID.randomUUID().toString()).name("").host("").build();
        NetworkForm form = editNetwork(fresh, "Add network");
        if (form != null) {
            NetworkConfig edited = form.toConfig();
            extras.add(edited);
            commit(edited.getId());
            applyInGameChoice(edited.getId(), form.inGame.isSelected());
        }
    }

    private void editSelected() {
        NetworkConfig selected = selected();
        if (selected == null) return;
        if (selected.isBuiltIn()) {
            editBuiltIn();
            return;
        }
        NetworkForm form = editNetwork(selected, "Edit " + selected.getName());
        if (form != null) {
            NetworkConfig edited = form.toConfig();
            extras.set(indexOf(selected.getId()), edited);
            commit(edited.getId());
            applyInGameChoice(edited.getId(), form.inGame.isSelected());
        }
    }

    private void duplicateSelected() {
        NetworkConfig selected = selected();
        if (selected == null || selected.isBuiltIn()) return;
        NetworkForm form = editNetwork(duplicateOf(selected), "Duplicate " + selected.getName());
        if (form != null) {
            NetworkConfig edited = form.toConfig();
            extras.add(indexOf(selected.getId()) + 1, edited);
            commit(edited.getId());
            applyInGameChoice(edited.getId(), form.inGame.isSelected());
        }
    }

    private void removeSelected() {
        NetworkConfig selected = selected();
        if (selected == null || selected.isBuiltIn()) return;
        int choice = JOptionPane.showConfirmDialog(this,
                "Remove " + selected.getName() + "? Its buffers will close.", "Remove network",
                JOptionPane.YES_NO_OPTION);
        if (choice != JOptionPane.YES_OPTION) return;
        removeNetwork(selected.getId());
    }

    /** Drops an extra network; game chat falls back to SwiftIRC if it was the in-game one. */
    void removeNetwork(String id) {
        int index = indexOf(id);
        if (index < 0) return;
        extras.remove(index);
        commit(null);
        applyInGameChoice(id, false);
    }

    /** SwiftIRC's own short form: everything else about it lives in RuneLite's settings. */
    private void editBuiltIn() {
        BuiltInForm form = new BuiltInForm(builtIn.isEnabled(), NetworkConfig.SWIFTIRC_ID.equals(inGame));
        int choice = JOptionPane.showConfirmDialog(this, form, "Edit " + NetworkConfig.SWIFTIRC_NAME,
                JOptionPane.OK_CANCEL_OPTION, JOptionPane.PLAIN_MESSAGE);
        if (choice != JOptionPane.OK_OPTION) return;
        if (form.enabled.isSelected() != builtIn.isEnabled()) {
            builtIn = builtIn.toBuilder().enabled(form.enabled.isSelected()).build();
            callbacks.saveBuiltIn(builtIn.isEnabled());
            reload();
        }
        applyInGameChoice(NetworkConfig.SWIFTIRC_ID, form.inGame.isSelected());
    }

    private void toggleConnection() {
        NetworkConfig selected = selected();
        if (selected == null) return;
        callbacks.setConnected(selected.getId(), !callbacks.isConnected(selected.getId()));
        list.repaint();
        updateButtons();
    }

    /** Shows the form until it validates or is cancelled; null when cancelled. */
    private NetworkForm editNetwork(NetworkConfig initial, String title) {
        NetworkForm form = new NetworkForm(initial, initial.getId().equals(inGame));
        while (true) {
            int choice = JOptionPane.showConfirmDialog(this, form, title,
                    JOptionPane.OK_CANCEL_OPTION, JOptionPane.PLAIN_MESSAGE);
            if (choice != JOptionPane.OK_OPTION) return null;
            NetworkConfig candidate = form.toConfig();
            List<NetworkConfig> others = new ArrayList<>(extras);
            others.add(0, builtIn);
            String error = validate(candidate, others);
            if (error == null) return form;
            JOptionPane.showMessageDialog(this, error, "Network not saved", JOptionPane.WARNING_MESSAGE);
        }
    }

    private static JButton button(String text, String name, Runnable action) {
        JButton button = new JButton(text);
        button.setName(name);
        button.addActionListener(e -> action.run());
        return button;
    }

    /** SwiftIRC's form: whether it connects automatically and whether it feeds game chat. */
    static final class BuiltInForm extends JPanel {
        final JCheckBox enabled = new JCheckBox("Connect automatically");
        final JCheckBox inGame = new JCheckBox("Show in game chat");

        BuiltInForm(boolean connectAutomatically, boolean showInGame) {
            super(new GridLayout(0, 1, 0, 4));
            enabled.setSelected(connectAutomatically);
            inGame.setSelected(showInGame);
            add(enabled);
            add(inGame);
            add(new JLabel("Turn this off when you reach SwiftIRC through a ZNC instead."));
            add(new JLabel("Server, username and passwords are in RuneLite's Global Chat (IRC) settings."));
        }
    }

    /** The add/edit form. Package-private fields so tests can fill it in. */
    static final class NetworkForm extends JPanel {
        private final String id;
        final JTextField name = new JTextField(20);
        final JTextField host = new JTextField(20);
        final JTextField port = new JTextField(6);
        final JCheckBox tls = new JCheckBox("Use TLS");
        final JCheckBox verifyTls = new JCheckBox("Verify TLS certificate");
        final JLabel tlsWarning = new JLabel(
                "Not verified: someone between you and the server could read or change this connection.");
        final JTextField nick = new JTextField(20);
        final JPasswordField serverPassword = new JPasswordField(20);
        final JTextField saslAccount = new JTextField(20);
        final JPasswordField saslPassword = new JPasswordField(20);
        final JTextField autojoin = new JTextField(20);
        final JCheckBox enabled = new JCheckBox("Connect automatically");
        final JCheckBox inGame = new JCheckBox("Show in game chat");
        final JLabel zncHint = new JLabel("ZNC: Server password is username/network:password;"
                + " uncheck Verify TLS if your ZNC uses a self-signed certificate");

        NetworkForm(NetworkConfig initial) {
            this(initial, false);
        }

        NetworkForm(NetworkConfig initial, boolean showInGame) {
            super(new GridBagLayout());
            id = initial.getId();
            inGame.setSelected(showInGame);
            name.setText(initial.getName());
            host.setText(initial.getHost());
            port.setText(String.valueOf(initial.getPort()));
            tls.setSelected(initial.isTls());
            verifyTls.setSelected(initial.isVerifyTls());
            tlsWarning.setForeground(new Color(230, 140, 60));
            tls.addItemListener(e -> updateTlsControls());
            verifyTls.addItemListener(e -> updateTlsControls());
            updateTlsControls();
            nick.setText(initial.getNick());
            nick.setToolTipText("Leave blank to use your Username setting");
            serverPassword.setText(initial.getServerPassword());
            saslAccount.setText(initial.getSaslAccount());
            saslPassword.setText(initial.getSaslPassword());
            autojoin.setText(initial.getAutojoin());
            autojoin.setToolTipText("Comma-separated, e.g. #foo,#bar");
            enabled.setSelected(initial.isEnabled());
            zncHint.setVisible(false);
            JButton zncPreset = new JButton("ZNC preset");
            zncPreset.addActionListener(e -> applyZncPreset());

            int row = 0;
            row = addRow("Name", name, row);
            row = addRow("Host", host, row);
            row = addRow("Port", port, row);
            row = addRow("", tls, row);
            row = addRow("", verifyTls, row);
            row = addRow("", tlsWarning, row);
            row = addRow("Nick", nick, row);
            row = addRow("Server password", serverPassword, row);
            row = addRow("", zncHint, row);
            row = addRow("SASL account", saslAccount, row);
            row = addRow("SASL password", saslPassword, row);
            row = addRow("Autojoin", autojoin, row);
            row = addRow("", enabled, row);
            row = addRow("", inGame, row);
            addRow("", zncPreset, row);
        }

        /** Verification only means something with TLS on; warn while it is switched off. */
        private void updateTlsControls() {
            verifyTls.setEnabled(tls.isSelected());
            tlsWarning.setVisible(tls.isSelected() && !verifyTls.isSelected());
            refit();
        }

        /**
         * Resizes the dialog showing this form. It is sized once when it opens, so a row revealed
         * afterwards would otherwise push its OK/Cancel buttons out of view.
         */
        private void refit() {
            revalidate();
            Window window = SwingUtilities.getWindowAncestor(this);
            if (window != null) window.pack();
        }

        void applyZncPreset() {
            tls.setSelected(true);
            zncHint.setVisible(true);
            refit();
        }

        NetworkConfig toConfig() {
            int parsedPort;
            try {
                parsedPort = Integer.parseInt(port.getText().trim());
            } catch (NumberFormatException e) {
                parsedPort = -1;
            }
            return NetworkConfig.builder()
                    .id(id)
                    .name(name.getText().trim())
                    .host(host.getText().trim())
                    .port(parsedPort)
                    .tls(tls.isSelected())
                    .verifyTls(verifyTls.isSelected())
                    .nick(nick.getText().trim())
                    .serverPassword(new String(serverPassword.getPassword()))
                    .saslAccount(saslAccount.getText().trim())
                    .saslPassword(new String(saslPassword.getPassword()))
                    .autojoin(autojoin.getText().trim())
                    .enabled(enabled.isSelected())
                    .build();
        }

        private int addRow(String label, JComponent field, int row) {
            GridBagConstraints c = new GridBagConstraints();
            c.gridy = row;
            c.insets = new Insets(2, 4, 2, 4);
            c.anchor = GridBagConstraints.WEST;
            add(new JLabel(label), c);
            c.gridx = 1;
            c.fill = GridBagConstraints.HORIZONTAL;
            c.weightx = 1;
            add(field, c);
            return row + 1;
        }
    }
}

package com.irc;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import com.google.gson.reflect.TypeToken;
import lombok.extern.slf4j.Slf4j;

import java.lang.reflect.Type;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;

/**
 * Reads and writes the user's chosen order of networks ({@code irc.networkOrder}, comma-separated
 * ids) and of channels within each network ({@code irc.channelOrder}, JSON of id to names).
 */
@Slf4j
final class OrderStore {
    static final String NETWORK_ORDER_KEY = "networkOrder";
    static final String CHANNEL_ORDER_KEY = "channelOrder";
    private static final Type CHANNEL_ORDER = new TypeToken<Map<String, List<String>>>() {}.getType();

    private OrderStore() {
    }

    /** The ids in {@code value}, in order, without blanks or repeats. */
    static List<String> parseNetworkOrder(String value) {
        if (value == null) return Collections.emptyList();
        Set<String> ids = new LinkedHashSet<>();
        for (String part : value.split(",")) {
            String id = part.trim();
            if (!id.isEmpty()) ids.add(id);
        }
        return new ArrayList<>(ids);
    }

    static String serializeNetworkOrder(List<String> ids) {
        return String.join(",", ids);
    }

    /**
     * {@code networks} with the listed ids first, in listed order, then the rest in their given
     * order. Ids that match no network are ignored: a removed network may linger in the setting.
     */
    static List<NetworkConfig> applyNetworkOrder(List<NetworkConfig> networks, List<String> ids) {
        Map<String, NetworkConfig> remaining = new LinkedHashMap<>();
        for (NetworkConfig network : networks) remaining.put(network.getId(), network);
        List<NetworkConfig> ordered = new ArrayList<>();
        for (String id : ids) {
            NetworkConfig network = remaining.remove(id);
            if (network != null) ordered.add(network);
        }
        ordered.addAll(remaining.values());
        return ordered;
    }

    /**
     * Channel names by network id. Unreadable JSON gives an empty map and is logged, never thrown,
     * like {@link NetworkStore#parse}: a bad hand edit only loses the order.
     */
    static Map<String, List<String>> parseChannelOrder(Gson gson, String json) {
        if (json == null || json.trim().isEmpty()) return Collections.emptyMap();
        Map<String, List<String>> stored;
        try {
            stored = gson.fromJson(json, CHANNEL_ORDER);
        } catch (JsonParseException | IllegalStateException e) {
            log.warn("Ignoring unreadable IRC channel order", e);
            return Collections.emptyMap();
        }
        return channelsOnly(stored);
    }

    static String serializeChannelOrder(Gson gson, Map<String, List<String>> order) {
        return gson.toJson(channelsOnly(order), CHANNEL_ORDER);
    }

    /**
     * {@code names} with those in {@code order} first, in that order, then the rest as given.
     * Names match ignoring case: a server may echo a channel with different casing.
     */
    static List<String> sortByOrder(List<String> names, List<String> order) {
        List<String> remaining = new ArrayList<>(names);
        List<String> sorted = new ArrayList<>();
        for (String wanted : order) {
            for (int i = 0; i < remaining.size(); i++) {
                if (remaining.get(i).equalsIgnoreCase(wanted)) {
                    sorted.add(remaining.remove(i));
                    break;
                }
            }
        }
        sorted.addAll(remaining);
        return sorted;
    }

    /**
     * The full channel order after the user reordered the open channels: {@code open} in its new
     * order, with every saved channel that is not open kept straight after the channel saved
     * before it (at the front when it was first). A drag must not lose the place of a channel
     * that happens to be closed.
     */
    static List<String> merge(List<String> saved, List<String> open) {
        List<String> merged = new ArrayList<>(open);
        for (int i = 0; i < saved.size(); i++) {
            String name = saved.get(i);
            if (indexIn(merged, name) >= 0) continue;
            int at = i == 0 ? 0 : indexIn(merged, saved.get(i - 1)) + 1;
            merged.add(at, name);
        }
        return merged;
    }

    /** {@code ids} without those not in {@code known}: a removed network is pruned on the next save. */
    static List<String> retainKnown(List<String> ids, Set<String> known) {
        List<String> kept = new ArrayList<>();
        for (String id : ids) {
            if (known.contains(id)) kept.add(id);
        }
        return kept;
    }

    /**
     * A copy of {@code order} with {@code networkId}'s channels replaced by {@code channels} and
     * networks not in {@code known} dropped.
     */
    static Map<String, List<String>> withChannels(Map<String, List<String>> order, String networkId,
                                                  List<String> channels, Set<String> known) {
        Map<String, List<String>> next = new LinkedHashMap<>();
        for (Map.Entry<String, List<String>> entry : order.entrySet()) {
            if (known.contains(entry.getKey())) next.put(entry.getKey(), entry.getValue());
        }
        next.put(networkId, new ArrayList<>(channels));
        return next;
    }

    /** The position of {@code name} in {@code order} ignoring case, or -1. */
    static int indexIn(List<String> order, String name) {
        String folded = name.toLowerCase(Locale.ROOT);
        for (int i = 0; i < order.size(); i++) {
            if (order.get(i).toLowerCase(Locale.ROOT).equals(folded)) return i;
        }
        return -1;
    }

    /** Private chats and System are never ordered by the setting, only channels. */
    private static Map<String, List<String>> channelsOnly(Map<String, List<String>> order) {
        if (order == null) return Collections.emptyMap();
        Map<String, List<String>> kept = new LinkedHashMap<>();
        for (Map.Entry<String, List<String>> entry : order.entrySet()) {
            if (entry.getKey() == null || entry.getValue() == null) continue;
            List<String> channels = new ArrayList<>();
            for (String name : entry.getValue()) {
                if (name != null && (name.startsWith("#") || name.startsWith("&"))) channels.add(name);
            }
            kept.put(entry.getKey(), channels);
        }
        return kept;
    }
}

package com.irc;

import java.awt.Rectangle;
import java.util.List;

/**
 * Where the pop-out was and how big, saved in the config so it reopens the same after a restart.
 * {@link #bounds} are the window's normal (unmaximized) bounds, so un-maximizing a window that
 * reopened maximized still lands somewhere sensible.
 */
final class PopOutGeometry {
    static final String CONFIG_KEY = "popOutBounds";

    final Rectangle bounds;
    final boolean maximized;

    PopOutGeometry(Rectangle bounds, boolean maximized) {
        this.bounds = new Rectangle(bounds);
        this.maximized = maximized;
    }

    /** "x,y,width,height" with ",maximized" on the end when it was. */
    String serialize() {
        return bounds.x + "," + bounds.y + "," + bounds.width + "," + bounds.height
                + (maximized ? ",maximized" : "");
    }

    /** Null for anything unreadable, so a bad value falls back to the default placement. */
    static PopOutGeometry parse(String value) {
        if (value == null) return null;
        String[] parts = value.trim().split(",");
        if (parts.length != 4 && !(parts.length == 5 && "maximized".equals(parts[4]))) return null;
        try {
            Rectangle bounds = new Rectangle(Integer.parseInt(parts[0].trim()), Integer.parseInt(parts[1].trim()),
                    Integer.parseInt(parts[2].trim()), Integer.parseInt(parts[3].trim()));
            if (bounds.width <= 0 || bounds.height <= 0) return null;
            return new PopOutGeometry(bounds, parts.length == 5);
        } catch (NumberFormatException e) {
            return null;
        }
    }

    /** Whether the middle of the title bar is on one of {@code screens}, so the window can be dragged. */
    boolean titleBarVisible(List<Rectangle> screens) {
        for (Rectangle screen : screens) {
            if (screen.contains(bounds.x + bounds.width / 2, bounds.y + 10)) return true;
        }
        return false;
    }
}

package com.irc;

import net.runelite.client.ui.ColorScheme;
import net.runelite.client.util.ColorUtil;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.function.Function;

/**
 * A run of joins, parts, quits, kicks and nick changes, grouped by kind for the pop-out's one-line
 * summary: {@code Joins: alice, gina · Parts: carol · Quits: bob · Nicks: dave → dave_ · Kicks: frank (by eve)}.
 *
 * Each nick appears once per group, in the order first seen, so someone hopping in and out shows
 * once under Joins and once under Parts. Nick changes are the exception: every one is listed.
 * Reasons are dropped.
 *
 * The nicks are read back out of the lines {@link IrcAdapter} builds; a line that doesn't match
 * its wording isn't treated as presence at all, so it keeps its own line.
 */
final class PresenceRun {

    private static final String JOINED = " has joined.";
    private static final String PARTED = " parted";
    private static final String QUIT = " quit";
    private static final String RENAMED = " is now known as";
    private static final String KICKED = " kicked ";

    private static final String JOIN_COLOR = ColorUtil.toHexColor(ColorScheme.PROGRESS_INPROGRESS_COLOR);
    private static final String LEAVE_COLOR = ColorUtil.toHexColor(ColorScheme.PROGRESS_ERROR_COLOR);
    private static final String CHANGE_COLOR = ColorUtil.toHexColor(ColorScheme.BRAND_ORANGE);

    /** Nick by folded nick, so the first spelling seen is the one shown. */
    private final Map<String, String> joins = new LinkedHashMap<>();
    private final Map<String, String> parts = new LinkedHashMap<>();
    private final Map<String, String> quits = new LinkedHashMap<>();
    private final List<String[]> nicks = new ArrayList<>();
    /** {kicked, kicker} by folded kicked nick; a later kick replaces the kicker but not the position. */
    private final Map<String, String[]> kicks = new LinkedHashMap<>();

    /** Whether {@code message} is a join, part, quit, kick or nick change this class can read. */
    static boolean isPresence(IrcMessage message) {
        String sender = message.getSender();
        String content = message.getContent();
        if (sender == null) return false;
        switch (message.getType()) {
            case JOIN:
                return content != null && content.endsWith(JOINED) && content.length() > JOINED.length();
            case PART:
                return sender.endsWith(PARTED) && sender.length() > PARTED.length();
            case QUIT:
                return sender.endsWith(QUIT) && sender.length() > QUIT.length();
            case NICK_CHANGE:
                return sender.endsWith(RENAMED) && sender.length() > RENAMED.length()
                        && content != null && !content.isEmpty();
            case KICK:
                return sender.indexOf(KICKED) > 0 && !sender.endsWith(KICKED);
            default:
                return false;
        }
    }

    /** Adds one event; call only with messages {@link #isPresence} accepts. */
    void add(IrcMessage message) {
        String sender = message.getSender();
        String content = message.getContent();
        switch (message.getType()) {
            case JOIN:
                once(joins, content.substring(0, content.length() - JOINED.length()));
                break;
            case PART:
                once(parts, sender.substring(0, sender.length() - PARTED.length()));
                break;
            case QUIT:
                once(quits, sender.substring(0, sender.length() - QUIT.length()));
                break;
            case NICK_CHANGE:
                nicks.add(new String[]{sender.substring(0, sender.length() - RENAMED.length()), content});
                break;
            case KICK: {
                int at = sender.indexOf(KICKED);
                String kicked = sender.substring(at + KICKED.length());
                kicks.put(fold(kicked), new String[]{kicked, sender.substring(0, at)});
                break;
            }
            default:
                throw new IllegalArgumentException("Not a presence line: " + message.getType());
        }
    }

    /** The groups, each in its usual colour; {@code nick} turns one nick into HTML. */
    String toHtml(Function<String, String> nick) {
        List<String> groups = new ArrayList<>();
        group(groups, "Joins", JOIN_COLOR, names(joins.values(), nick));
        group(groups, "Parts", LEAVE_COLOR, names(parts.values(), nick));
        group(groups, "Quits", LEAVE_COLOR, names(quits.values(), nick));
        List<String> renames = new ArrayList<>();
        for (String[] change : nicks) renames.add(nick.apply(change[0]) + " → " + nick.apply(change[1]));
        group(groups, "Nicks", CHANGE_COLOR, renames);
        List<String> kicked = new ArrayList<>();
        for (String[] kick : kicks.values()) kicked.add(nick.apply(kick[0]) + " (by " + nick.apply(kick[1]) + ")");
        group(groups, "Kicks", CHANGE_COLOR, kicked);
        return String.join(" · ", groups);
    }

    private static void group(List<String> groups, String label, String color, List<String> items) {
        if (items.isEmpty()) return;
        groups.add("<font style=\"color:" + color + "\">" + label + ": " + String.join(", ", items) + "</font>");
    }

    private static List<String> names(Iterable<String> nicks, Function<String, String> nick) {
        List<String> names = new ArrayList<>();
        for (String name : nicks) names.add(nick.apply(name));
        return names;
    }

    private static void once(Map<String, String> group, String nick) {
        group.putIfAbsent(fold(nick), nick);
    }

    private static String fold(String nick) {
        return nick.toLowerCase(Locale.ROOT);
    }
}

package com.irc;

import com.google.common.cache.Cache;
import com.google.common.cache.CacheBuilder;
import lombok.extern.slf4j.Slf4j;
import okhttp3.*;

import javax.imageio.ImageIO;
import javax.inject.Inject;
import javax.swing.*;
import java.awt.*;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.image.BufferedImage;
import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.TimeUnit;
import java.util.regex.Pattern;

@Slf4j
public class PreviewManager {
    private final OkHttpClient okHttpClient;
    private static final int MAX_PREVIEW_WIDTH = 500;
    private static final int MAX_PREVIEW_HEIGHT = 500;
    private Popup currentImagePreview;
    private CompletableFuture<?> imagePreviewFuture;
    private final Timer debounceTimer;
    private Point pendingPoint;
    private String pendingUrl;
    private final IrcPanel.ChannelPane channelPane;
    private static final Pattern IMAGE_URL_PATTERN = Pattern.compile("\\.(png|jpe?g|bmp)(\\?.*)?$", Pattern.CASE_INSENSITIVE);
    private final Cache<String, byte[]> imageCache;

    public PreviewManager(IrcPanel.ChannelPane channelPane, OkHttpClient okHttpClient) {
        this.channelPane = channelPane;
        this.debounceTimer = new Timer(100, e -> queueShowPreview());
        this.debounceTimer.setRepeats(false);
        this.imageCache = CacheBuilder.newBuilder()
                .maximumSize(50)
                .expireAfterWrite(5, TimeUnit.MINUTES)
                .build();
        this.okHttpClient = okHttpClient;
    }

    public void requestShow(Point mousePoint, String url) {
        cancelPreview();
        this.pendingPoint = mousePoint;
        this.pendingUrl = url;
        debounceTimer.restart();
    }

    private void queueShowPreview() {
        if (pendingPoint != null && pendingUrl != null && channelPane.isShowing()) {
            showImagePreview(this.pendingPoint, this.pendingUrl);
        }
    }

    public void cancelPreview() {
        debounceTimer.stop();
        pendingPoint = null;
        pendingUrl = null;
        hideImagePreview();
    }

    public boolean isImageUrl(String url) {
        return IMAGE_URL_PATTERN.matcher(url).find();
    }

    public void showImagePreview(Point mousePoint, String imageUrl) {
        cancelPreviewManager();
        this.pendingPoint = mousePoint;

        if (imagePreviewFuture != null && !imagePreviewFuture.isDone()) {
            imagePreviewFuture.cancel(true);
        }

        imagePreviewFuture = CompletableFuture.runAsync(() -> {
            try {
                handleStaticImagePreview(imageUrl);
            } catch (Exception e) {
                log.warn("Failed to create image preview for {}", imageUrl, e);
            }
        });
    }

    private void handleStaticImagePreview(String imageUrl) throws IOException {
        if (okHttpClient == null) {
            log.warn("No OkHttp connection available");
            return;
        }

        byte[] imageBytes = imageCache.getIfPresent(imageUrl);

        if (imageBytes == null || imageBytes.length == 0) {
            log.debug("Cache miss for {}, fetching from network.", imageUrl);

            String encodedUrl = URLEncoder.encode(imageUrl, StandardCharsets.UTF_8);

            // CloudFlare worker to protect users from IP grabbers
            String url = "https://image-proxy.cold-pine-9570.workers.dev/?url=" + encodedUrl;
            // Discord doesn't support CloudFlare workers :(
            if (imageUrl.startsWith("https://cdn.discordapp.com/")) {
                url = imageUrl;
            }

            Request request = new Request.Builder().url(url).build();
            okHttpClient.newCall(request).enqueue(new Callback() {
                @Override
                public void onFailure(Call call, IOException e) {
                    log.warn("Failed to fetch image preview for {}", imageUrl, e);
                }

                @Override
                public void onResponse(Call call, Response response) throws IOException {
                    if (!response.isSuccessful()) {
                        log.warn("Failed to fetch image preview for {}", imageUrl);
                        return;
                    }

                    if (response.code() != 200) {
                        log.warn("Failed to fetch image: {} returned status {}", imageUrl, response.code());
                        return;
                    }

                    String contentType = response.header("Content-Type");
                    if (contentType == null || !contentType.toLowerCase().startsWith("image/")) {
                        log.warn("Invalid content-type for {}: {}", imageUrl, contentType);
                        return;
                    }

                    if (response.body() == null) {
                        log.warn("Empty body for: {}", imageUrl);
                        return;
                    }

                    try (InputStream in = response.body().byteStream();
                         ByteArrayOutputStream baos = new ByteArrayOutputStream()) {

                        byte[] buffer = new byte[4096];
                        int n;
                        while ((n = in.read(buffer)) != -1) {
                            baos.write(buffer, 0, n);
                        }
                        byte[] imageBytes = baos.toByteArray();
                        imageCache.put(imageUrl, imageBytes);
                        response.close();

                        showPreview(imageUrl, imageBytes);
                    }
                }
            });
        } else {
            log.debug("Cache hit for {}", imageUrl);
            showPreview(imageUrl, imageBytes);
        }
    }

    private void showPreview(String imageUrl, byte[] imageBytes) throws IOException {
        if (imageBytes != null) {
            BufferedImage originalImage = ImageIO.read(new ByteArrayInputStream(imageBytes));
            if (originalImage == null) {
                log.warn("Could not decode image from URL: {}", imageUrl);
                imageCache.invalidate(imageUrl);
                return;
            }

            ImageIcon imageIcon = new ImageIcon(scaleImage(originalImage));

            JLabel preview = new JLabel(imageIcon);
            preview.addMouseListener(new MouseAdapter() {
                @Override
                public void mouseExited(MouseEvent e) {
                    cancelPreviewManager();
                }
            });
            SwingUtilities.invokeLater(() -> displayPopup(this.pendingPoint, preview));
        }
    }

    private BufferedImage scaleImage(BufferedImage originalImage) {
        double scale = Math.min(1.0, Math.min(
                (double) MAX_PREVIEW_WIDTH / originalImage.getWidth(),
                (double) MAX_PREVIEW_HEIGHT / originalImage.getHeight()
        ));

        int scaledWidth = (int) (originalImage.getWidth() * scale);
        int scaledHeight = (int) (originalImage.getHeight() * scale);

        BufferedImage scaledImage = new BufferedImage(scaledWidth, scaledHeight, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g2d = scaledImage.createGraphics();
        g2d.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
        g2d.drawImage(originalImage, 0, 0, scaledWidth, scaledHeight, null);
        g2d.dispose();
        return scaledImage;
    }

    private void displayPopup(Point location, JComponent content) {
        try {
            cancelPreviewManager();
            if (!channelPane.isShowing()) {
                return;
            }

            Window topLevelWindow = SwingUtilities.getWindowAncestor(channelPane);
            if (topLevelWindow == null) return;

            if (location == null) {
                log.warn("Mouse location is null");
                return;
            }
            SwingUtilities.convertPointToScreen(location, channelPane);

            Dimension contentSize = content.getPreferredSize();
            Rectangle screenBounds = topLevelWindow.getGraphicsConfiguration().getBounds();

            // Adjust Y coordinate
            if (location.y + contentSize.height > screenBounds.y + screenBounds.height) {
                Point componentOnScreen = channelPane.getLocationOnScreen();
                int yAbove = componentOnScreen.y + location.y - contentSize.height;

                if (yAbove >= screenBounds.y) {
                    location.y = yAbove;
                } else {
                    location.y = screenBounds.y + screenBounds.height - contentSize.height;
                }
            }

            if (location.x + contentSize.width > screenBounds.x + screenBounds.width) {
                location.x = screenBounds.x + screenBounds.width - contentSize.width;
            }

            if (location.y < screenBounds.y) {
                location.y = screenBounds.y;
            }
            if (location.x < screenBounds.x) {
                location.x = screenBounds.x;
            }

            content.setBorder(BorderFactory.createLineBorder(Color.DARK_GRAY));
            content.setOpaque(true);

            currentImagePreview = PopupFactory.getSharedInstance().getPopup(channelPane, content, location.x, location.y);
            currentImagePreview.show();
        } catch (Exception e) {
            log.warn("Could not display popup", e);
        }
    }

    void hideImagePreview() {
        if (imagePreviewFuture != null && !imagePreviewFuture.isDone()) {
            imagePreviewFuture.cancel(true);
            imagePreviewFuture = null;
        }
        if (currentImagePreview != null) {
            currentImagePreview.hide();
            currentImagePreview = null;
        }
    }

    void cancelPreviewManager() {
        cancelPreview();
    }
}

package com.irc;

import lombok.Getter;
import lombok.extern.slf4j.Slf4j;

import javax.net.ssl.SSLParameters;
import javax.net.ssl.SSLSocket;
import javax.net.ssl.SSLContext;
import javax.net.ssl.SSLSocketFactory;
import javax.net.ssl.TrustManager;
import javax.net.ssl.X509TrustManager;
import java.io.BufferedReader;
import java.io.BufferedWriter;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.OutputStreamWriter;
import java.net.Socket;
import java.net.SocketTimeoutException;
import java.net.UnknownHostException;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Base64;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

@Slf4j
public class SimpleIrcClient {
    private static final Pattern MESSAGE_PATTERN =
            Pattern.compile("^(?:[:@](\\S+) )?(\\S+)(?: ((?:[^:\\s]\\S* ?)*))?(?: ?:(.*))?$");
    private static final Pattern NUMERIC = Pattern.compile("^[0-9]+$");

    private Socket socket;
    private BufferedWriter writer;
    private BufferedReader reader;
    private final ExecutorService executor = Executors.newFixedThreadPool(2);
    private final List<IrcEventListener> listeners = new CopyOnWriteArrayList<>();

    @Getter
    private String nick;
    private String username;
    private String realName;
    private String saslAccount;
    private String saslPassword;
    private boolean saslEnabled = false;
    @Getter
    private final Set<String> channels = new HashSet<>();
    private final ModeSpec modeSpec = ModeSpec.defaults();
    private final ChannelUserList channelUserList = new ChannelUserList(modeSpec);
    /**
     * LIST replies in flight. Mutated only inside a block synchronized on this list itself:
     * the reader thread appends rows on 322 and publishes on 323, while disconnect() (reachable
     * from the EDT via /quit) can clear it concurrently.
     */
    private final List<ChannelListEntry> channelListAccumulator = new ArrayList<>();
    /**
     * True from the first row of a run (321, or the first 322 if the server skips 321) until 323
     * or 263 closes it. Guarded by the channelListAccumulator lock.
     */
    private boolean channelListRunActive = false;
    /** The last completed LIST, published at 323. Immutable, safe to read from any thread. */
    private volatile List<ChannelListEntry> channelListSnapshot = Collections.emptyList();
    private volatile boolean channelListTruncated = false;
    private static final int CHANNEL_LIST_CAP = 20000;
    /** How long a silent socket is tolerated before the read fails. Also quoted in diagnostics. */
    private static final int READ_TIMEOUT_MS = 240000;

    private static final String REDACTED = "<redacted>";

    /**
     * Service commands whose remainder is a credential. Covers ChanServ as well as NickServ -
     * "/cs identify #chan <password>" is a channel password in plain sight - and treats the
     * PRIVMSG wrapper as optional so a bare "NS IDENTIFY" alias is caught too.
     *
     * Anchored, so it can only match a line we send: an incoming line starts with ":source",
     * which means ordinary conversation about identifying is never touched. Everything after the
     * verb goes, including ChanServ's channel argument - over-redacting one channel name is a
     * better trade than reasoning about each service's argument order.
     */
    private static final Pattern SERVICES_SECRET = Pattern.compile(
            "(?i)^(?:(?:PRIVMSG|NOTICE)\\s+)?(?:NickServ|ChanServ|NS|CS)\\s+:?\\s*"
                    + "(?:IDENTIFY|ID|LOGIN|AUTH|REGISTER|GHOST|RECOVER|RELEASE|DROP"
                    + "|SETPASS|SET(?:\\s+\\S+)?\\s+PASSWORD)\\b");

    private String host;
    private int port;
    private boolean secure;
    /** Sent as PASS before NICK/USER when non-empty. ZNC reads "user/network:password" from it. */
    private String serverPassword = "";

    public SimpleIrcClient serverPassword(String password) {
        this.serverPassword = password == null ? "" : password;
        return this;
    }

    /** False accepts any certificate for any host - for a self-signed bouncer, say. */
    private boolean verifyTls = true;

    public SimpleIrcClient verifyTls(boolean verify) {
        this.verifyTls = verify;
        return this;
    }

    boolean isVerifyingTls() { return verifyTls; }
    String getServerPassword() { return serverPassword; }
    String getHost() { return host; }
    int getPort() { return port; }
    boolean isSecure() { return secure; }

    private volatile boolean connected = false;
    private volatile boolean shuttingDown = false;
    /**
     * The socket of the attempt in progress, published before the TLS handshake so a disconnect
     * that arrives while still connecting can close it.
     */
    private volatile Socket pendingSocket;
    /**
     * Why the link went down, in the server's or the JDK's own words. Set by whichever path
     * noticed the failure and read by the DISCONNECT event, so "Disconnected from IRC" can say
     * what happened. Written on the reader thread, read from the EDT.
     */
    private volatile String disconnectReason = null;
    /** How far the current attempt got. Drives the wording of any failure we report. */
    private volatile ConnectPhase connectPhase = ConnectPhase.CONNECTING;
    /** Opt-in raw protocol logging, for diagnosing a failure we cannot reproduce. */
    private volatile boolean rawLogging = false;

    String currentTagTime;   // package-private: accessed by TestableIrcClient subclass
    String currentTagBatch;  // package-private: accessed by TestableIrcClient subclass

    private final Map<String, List<IrcEvent>> activeBatches = new HashMap<>();
    private final Map<String, String> activeBatchChannels = new HashMap<>();

    boolean capHistorySupported = false;  // package-private: accessed by TestableIrcClient subclass
    private boolean capEndSent = false;
    /** The server tells us when anyone sharing a channel goes away or comes back. */
    private boolean capAwayNotify = false;
    /** Channels whose WHO reply changed someone's away state, redrawn once at 315. */
    private final Set<String> whoChangedChannels = new HashSet<>();
    private final Set<String> advertisedCaps = new HashSet<>();

    public SimpleIrcClient server(String host, int port, boolean secure) {
        this.host = host;
        this.port = port;
        this.secure = secure;
        return this;
    }

    public SimpleIrcClient credentials(String nick, String username, String realName) {
        this.nick = nick;
        this.username = username;
        this.realName = realName;
        return this;
    }

    public void sasl(String account, String password) {
        this.saslAccount = account;
        this.saslPassword = password;
        this.saslEnabled = password != null && !password.isEmpty();
    }

    static String saslPlainResponse(String authcid, String password) {
        String payload = "\0" + authcid + "\0" + password;
        return Base64.getEncoder().encodeToString(payload.getBytes(StandardCharsets.UTF_8));
    }

    public void connect() {
        shuttingDown = false;
        pendingSocket = null;
        disconnectReason = null;
        connectPhase = ConnectPhase.CONNECTING;
        executor.submit(() -> {
            try {
                if (secure) {
                    SSLSocket sslSocket = openSecureSocket();
                    pendingSocket = sslSocket;
                    if (shuttingDown) {
                        closeQuietly(sslSocket);
                        return;
                    }
                    // Split from the socket open so a certificate failure is not reported as a
                    // refused connection.
                    connectPhase = ConnectPhase.TLS_HANDSHAKE;
                    sslSocket.startHandshake();
                    socket = sslSocket;
                } else {
                    socket = new Socket(host, port);
                    pendingSocket = socket;
                }
                if (shuttingDown) {
                    closeQuietly(socket);
                    return;
                }

                connectPhase = ConnectPhase.REGISTERING;
                writer = new BufferedWriter(new OutputStreamWriter(socket.getOutputStream(), StandardCharsets.UTF_8));
                reader = new BufferedReader(new InputStreamReader(socket.getInputStream(), StandardCharsets.UTF_8));

                advertisedCaps.clear();
                capEndSent = false;
                capHistorySupported = false;
                capAwayNotify = false;
                whoChangedChannels.clear();
                if (!beginRegistration()) {
                    closeQuietly(socket);
                    return;
                }

                connected = true;
                if (shuttingDown) {
                    // disconnect() slipped in between registering and here and saw us
                    // unconnected; it has closed the socket, so do not report a connection.
                    connected = false;
                    return;
                }
                fireEvent(new IrcEvent(IrcEvent.Type.CONNECT, null, null, null, null));

                String line;
                try {
                    while (!shuttingDown && (line = reader.readLine()) != null) {
                        processLine(line);
                    }

                    if (!shuttingDown) {
                        // readLine() returned null: the peer closed the socket without an ERROR
                        // line. Saying so beats a bare "Disconnected from IRC", which is
                        // indistinguishable from the user's own /quit. A close during
                        // registration is worth calling out separately - that is the shape of a
                        // silent rejection (K-line, throttle, bad CAP negotiation).
                        if (disconnectReason == null) {
                            String reason = connectPhase == ConnectPhase.REGISTERING
                                    ? "server closed the connection during registration, without saying why"
                                    : "server closed the connection without sending an error";
                            recordDisconnectReason(reason);
                            log.warn("IRC connection to {}:{} closed by peer during {} with no ERROR line",
                                    host, port, connectPhase);
                            fireEvent(new IrcEvent(IrcEvent.Type.ERROR, null, null,
                                    "Connection closed: " + reason, null));
                        }
                        disconnect();
                    }
                } catch (IOException e) {
                    if (!shuttingDown) {
                        String described = describeFailure(connectPhase, host, port, e);
                        recordDisconnectReason(described);
                        log.warn("IRC read from {}:{} failed during {}", host, port, connectPhase, e);
                        fireEvent(new IrcEvent(IrcEvent.Type.ERROR, null, null, described, null));
                    }
                }
            } catch (Exception e) {
                if (!shuttingDown) {
                    String described = describeFailure(connectPhase, host, port, e);
                    recordDisconnectReason(described);
                    log.error("IRC connection to {}:{} failed during {}", host, port, connectPhase, e);
                    fireEvent(new IrcEvent(IrcEvent.Type.ERROR, null, null, described, null));
                }
            } finally {
                if (!shuttingDown) {
                    disconnect();
                }
            }
        });
    }

    /** Sends the registration burst; false, sending nothing, when disconnect() came first. */
    boolean beginRegistration() {
        if (shuttingDown) return false;
        sendRegistration();
        return true;
    }

    private static void closeQuietly(Socket target) {
        if (target == null) return;
        try {
            target.close();
        } catch (IOException ignored) {
        }
    }

    /**
     * The registration burst. CAP LS opens it so the server holds registration until CAP END:
     * ZNC registers as soon as it has PASS, NICK and USER, and replays every JOIN before reading
     * a CAP LS sent after them, so caps acked that late miss those joins. PASS precedes NICK, as a
     * trailing parameter so spaces survive.
     */
    void sendRegistration() {
        sendRawLine("CAP LS 302");
        if (!serverPassword.isEmpty()) sendRawLine("PASS :" + serverPassword);
        sendRawLine("NICK " + nick);
        sendRawLine("USER " + username + " 0 * :" + realName);
    }

    /**
     * Turns on hostname verification, which SSLSocket does NOT do by default.
     *
     * A plain SSLSocket checks that the certificate chain is trusted, but not that the
     * certificate was issued for the host we asked for. Without endpoint identification any
     * CA-signed certificate - for any hostname at all - is accepted, which is exactly the
     * opening a man-in-the-middle needs on a hostile network. The credentials this client sends
     * during registration make that worth closing.
     *
     * Applied as a single SSLParameters update so the protocol list cannot be clobbered by
     * ordering between setSSLParameters and setEnabledProtocols.
     */
    static void applyTlsSettings(SSLSocket sslSocket) {
        applyTlsSettings(sslSocket, true);
    }

    /** As above; {@code verify} false leaves the hostname unchecked, for an unverified network. */
    static void applyTlsSettings(SSLSocket sslSocket, boolean verify) {
        SSLParameters params = sslSocket.getSSLParameters();
        params.setEndpointIdentificationAlgorithm(verify ? "HTTPS" : null);
        params.setProtocols(sslSocket.getSupportedProtocols());
        sslSocket.setSSLParameters(params);
    }

    /**
     * Trusts every certificate chain. Only for a network the user has marked "don't verify",
     * typically a bouncer with a self-signed certificate: the link stays encrypted, but anyone
     * on the path could impersonate the server.
     */
    static final X509TrustManager TRUST_ANY = new X509TrustManager() {
        @Override
        public void checkClientTrusted(java.security.cert.X509Certificate[] chain, String authType) {
        }

        @Override
        public void checkServerTrusted(java.security.cert.X509Certificate[] chain, String authType) {
        }

        @Override
        public java.security.cert.X509Certificate[] getAcceptedIssuers() {
            return new java.security.cert.X509Certificate[0];
        }
    };

    /** The JDK default when verifying; otherwise a factory that trusts any certificate. */
    static SSLSocketFactory socketFactory(boolean verify) {
        if (verify) return (SSLSocketFactory) SSLSocketFactory.getDefault();
        try {
            SSLContext context = SSLContext.getInstance("TLS");
            context.init(null, new TrustManager[]{TRUST_ANY}, null);
            return context.getSocketFactory();
        } catch (java.security.GeneralSecurityException e) {
            throw new IllegalStateException("TLS is unavailable", e);
        }
    }

    /** Opens the TLS socket without handshaking, so the caller can attribute each phase. */
    private SSLSocket openSecureSocket() throws IOException {
        SSLSocketFactory factory = socketFactory(verifyTls);
        if (!verifyTls) {
            log.warn("TLS certificate verification is off for {}:{}", host, port);
        }
        // Created with the hostname rather than an InetAddress: SNI and hostname verification
        // both need the name we dialled, and an InetAddress would strip it.
        SSLSocket sslSocket = (SSLSocket) factory.createSocket(host, port);
        applyTlsSettings(sslSocket, verifyTls);
        sslSocket.setSoTimeout(READ_TIMEOUT_MS);
        return sslSocket;
    }

    public void disconnect() {
        disconnect("");
    }

    public void disconnect(String reason) {
        if (shuttingDown) return;
        if (!connected) {
            // Still connecting: stop the attempt before it registers, or it would live on
            // unseen (and join channels) after the network was removed or reconnected.
            shuttingDown = true;
            closeQuietly(pendingSocket);
            return;
        }

        shuttingDown = true;
        try {
            if (writer != null) {
                try {
                    sendRawLine("QUIT :" + (reason.isEmpty() ? "Disconnecting" : reason));
                    writer.flush();
                    writer.close();
                } catch (IOException ignored) {
                }
            }
            if (reader != null) try {
                reader.close();
            } catch (IOException ignored) {
            }
            if (socket != null) try {
                socket.close();
            } catch (IOException ignored) {
            }
        } finally {
            activeBatches.clear();
            activeBatchChannels.clear();
            connected = false;
            List<String> joined = new ArrayList<>(channels);
            channelUserList.clear();
            synchronized (channelListAccumulator) {
                channelListAccumulator.clear();
                channelListRunActive = false;
            }
            channelListTruncated = false;
            for (String joinedChannel : joined) {
                fireUsersChanged(joinedChannel);
            }
            fireEvent(new IrcEvent(IrcEvent.Type.DISCONNECT, null, null, disconnectReason, null));
        }
    }

    public void joinChannel(String channel, String password) {
        if (connected) {
            String command = "JOIN " + channel;
            if (password != null && !password.isEmpty()) {
                command += " " + password;
            }
            sendRawLine(command);
            channels.add(channel);

        }
    }

    public void leaveChannel(String channel) {
        leaveChannel(channel, null);
    }

    public void leaveChannel(String channel, String reason) {
        if (connected && channels.contains(channel)) {
            String command = "PART " + channel;
            if (reason != null && !reason.isEmpty()) {
                command += " :" + reason;
            }
            sendRawLine(command);
            channels.remove(channel);
            channelUserList.removeChannel(channel);
            fireUsersChanged(channel);
        }
    }

    public void sendMessage(String target, String message) {
        if (connected) {
            sendRawLine("PRIVMSG " + target + " :" + message);
        }
    }

    public void sendAction(String target, String action) {
        if (connected) {
            sendRawLine("PRIVMSG " + target + " :\u0001ACTION " + action + "\u0001");
        }
    }

    public void sendNotice(String target, String message) {
        if (connected) {
            sendRawLine("NOTICE " + target + " :" + message);
        }
    }

    public void setNick(String newNick) {
        if (connected) {
            sendRawLine("NICK " + newNick);
        }
    }

    public synchronized void sendRawLine(String line) {
        if (rawLogging) log.info("IRC >> {}", redactForLog(line));
        if (writer == null) return;
        try {
            writer.write(line + "\r\n");
            writer.flush();
        } catch (IOException e) {
            log.error("Error sending IRC message", e);
        }
    }

    void processLine(String line) {
        if (rawLogging) log.info("IRC << {}", redactForLog(line));

        // Reset per-line tag state
        currentTagTime = null;
        currentTagBatch = null;

        // Strip and parse IRCv3 message tags (@key=value;...)
        if (line.startsWith("@")) {
            int spaceIdx = line.indexOf(' ');
            if (spaceIdx > 0) {
                String tagSegment = line.substring(1, spaceIdx);
                line = line.substring(spaceIdx + 1);
                for (String tag : tagSegment.split(";")) {
                    int eq = tag.indexOf('=');
                    if (eq > 0) {
                        String key = tag.substring(0, eq);
                        String value = tag.substring(eq + 1);
                        if ("time".equals(key)) currentTagTime = value;
                        else if ("batch".equals(key)) currentTagBatch = value;
                    }
                }
            }
        }

        Matcher matcher = MESSAGE_PATTERN.matcher(line);

        if (matcher.matches()) {
            String sourceRaw = matcher.group(1);
            String command = matcher.group(2);
            String paramsRaw = matcher.group(3);
            String trailing = matcher.group(4);

            String source = sourceRaw != null ? sourceRaw : "";
            List<String> params = new ArrayList<>();

            if (paramsRaw != null) {
                for (String param : paramsRaw.split(" ")) {
                    if (!param.isEmpty()) {
                        params.add(param);
                    }
                }
            }

            if (trailing != null) {
                params.add(trailing);
            }

            if (command.equals("PING")) {
                sendRawLine("PONG " + (params.isEmpty() ? "" : params.get(0)));
                return;
            }

            processCommand(source, command, params);
        }
    }

    private void processCommand(String source, String command, List<String> params) {
        String sourceNick = extractNick(source);

        // IRCv3 batch intercept: accumulate tagged messages instead of processing normally
        if (currentTagBatch != null && activeBatches.containsKey(currentTagBatch)) {
            String batchRef = currentTagBatch;
            if (command.equalsIgnoreCase("PRIVMSG") && params.size() >= 2) {
                String target = params.get(0);
                String msgBody = params.get(1);
                if (msgBody.startsWith("\u0001") && msgBody.endsWith("\u0001")) {
                    // CTCP — check for ACTION
                    String ctcp = msgBody.substring(1, msgBody.length() - 1);
                    String[] parts = ctcp.split(" ", 2);
                    if ("ACTION".equals(parts[0])) {
                        String actionText = parts.length > 1 ? parts[1] : "";
                        activeBatches.get(batchRef).add(
                            new IrcEvent(IrcEvent.Type.ACTION, sourceNick, target, actionText, currentTagTime)
                        );
                    }
                } else {
                    activeBatches.get(batchRef).add(
                        new IrcEvent(IrcEvent.Type.MESSAGE, sourceNick, target, msgBody, currentTagTime)
                    );
                }
                return;
            }
            // Non-PRIVMSG commands in a chathistory batch are silently ignored
            return;
        }

        switch (command.toUpperCase()) {
            case "PRIVMSG":
                if (params.size() >= 2) {
                    String target = params.get(0);
                    String message = params.get(1);

                    if (message.startsWith("\u0001") && message.endsWith("\u0001")) {
                        handleCtcp(source, target, message);
                    } else {
                        fireEvent(new IrcEvent(IrcEvent.Type.MESSAGE, sourceNick,
                                bufferFor(target, sourceNick), message, currentTagTime));
                    }
                }
                break;

            case "JOIN":
                if (!params.isEmpty()) {
                    String channel = params.get(0);
                    fireEvent(new IrcEvent(IrcEvent.Type.JOIN, sourceNick, channel, null, null));
                    channelUserList.join(channel, sourceNick);
                    fireUsersChanged(channel);
                    if (sourceNick.equals(nick) && capHistorySupported) {
                        sendRawLine("CHATHISTORY LATEST " + channel + " * 100");
                    }
                    // NAMES carries no away state, so ask once per join; away-notify keeps it
                    // current from then on. Without away-notify it would only go stale.
                    if (sourceNick.equals(nick) && capAwayNotify) {
                        sendRawLine("WHO " + channel);
                    }
                }
                break;

            case "PART":
                if (!params.isEmpty()) {
                    String channel = params.get(0);
                    String reason = params.size() > 1 ? params.get(1) : "";

                    if (!sourceNick.equals(nick)) {
                        fireEvent(new IrcEvent(IrcEvent.Type.PART, sourceNick, channel, reason, null));
                        channelUserList.part(channel, sourceNick);
                        fireUsersChanged(channel);
                    } else {
                        channelUserList.removeChannel(channel);
                        fireUsersChanged(channel);
                    }
                }
                break;

            case "QUIT":
                String quitMessage = params.isEmpty() ? "" : params.get(0);

                List<String> userChannels = channelUserList.quit(sourceNick);
                fireEvent(new IrcEvent(IrcEvent.Type.QUIT, sourceNick, null, quitMessage, String.join(",", userChannels)));
                for (String quitChannel : userChannels) {
                    fireUsersChanged(quitChannel);
                }
                break;

            case "NICK":
                if (!params.isEmpty()) {
                    String newNick = params.get(0);
                    if (sourceNick.equals(this.nick)) {
                        this.nick = newNick;
                    }

                    userChannels = channelUserList.rename(sourceNick, newNick);
                    fireEvent(new IrcEvent(IrcEvent.Type.NICK_CHANGE, sourceNick, null, newNick, String.join(",", userChannels)));
                    for (String renamedChannel : userChannels) {
                        fireUsersChanged(renamedChannel);
                    }
                }
                break;

            case "KICK":
                if (params.size() >= 2) {
                    String channel = params.get(0);
                    String kickedUser = params.get(1);
                    String kickMessage = params.size() > 2 ? params.get(2) : "";

                    fireEvent(new IrcEvent(IrcEvent.Type.KICK, sourceNick, channel, kickedUser + " " + kickMessage, null));
                    if (!kickedUser.equals(nick)) {
                        channelUserList.kick(channel, kickedUser);
                        fireUsersChanged(channel);
                    } else {
                        channelUserList.removeChannel(channel);
                        fireUsersChanged(channel);
                    }
                }
                break;

            case "NOTICE":
                if (params.size() >= 2) {
                    String target = params.get(0);
                    String message = params.get(1);
                    if (source.contains("!")) {
                        fireEvent(new IrcEvent(IrcEvent.Type.NOTICE, sourceNick, target, message, null));
                    } else {
                        fireEvent(new IrcEvent(IrcEvent.Type.SERVER_NOTICE, source, null, message, null));
                    }
                }
                break;

            case "MODE":
                if (params.size() >= 2) {
                    String target = params.get(0);
                    StringBuilder modeString = new StringBuilder();
                    for (int i = 1; i < params.size(); i++) {
                        modeString.append(" ").append(params.get(i));
                    }

                    if (target.startsWith("#")) {
                        fireEvent(new IrcEvent(IrcEvent.Type.CHANNEL_MODE, "* " + sourceNick + " sets mode(s)", target, modeString.toString().trim(), null));
                        channelUserList.applyModeChange(target, params.subList(1, params.size()));
                        fireUsersChanged(target);
                    } else {
                        fireEvent(new IrcEvent(IrcEvent.Type.USER_MODE, sourceNick, target, modeString.toString().trim(), null));
                    }
                }
                break;

            case "TOPIC":
                if (params.size() >= 2) {
                    String channel = params.get(0);
                    String topic = params.get(1);
                    fireEvent(new IrcEvent(IrcEvent.Type.TOPIC, sourceNick, channel, topic, null));
                }
                break;

            case "KILL":
                // Only our own KILL ends our link; another user's is not our disconnect.
                if (params.isEmpty() || !params.get(0).equals(nick)) break;
                String killReason = params.size() >= 2 ? params.get(params.size() - 1) : "";
                recordDisconnectReason("killed by " + sourceNick
                        + (killReason.isEmpty() ? "" : ": " + killReason));
                fireEvent(new IrcEvent(IrcEvent.Type.ERROR, null, null,
                        "Killed by " + sourceNick
                                + (killReason.isEmpty() ? "" : ": " + killReason), null));
                break;

            case "ERROR":
                // The server's last word before it drops the link - ping timeout, K-line, Killed.
                // Dropping it left the user with a bare "Disconnected from IRC" and nothing to
                // report, so this text is the single most valuable line the connection produces.
                String serverError = params.isEmpty() ? "server sent ERROR without a reason"
                        : params.get(params.size() - 1);
                recordDisconnectReason(serverError);
                fireEvent(new IrcEvent(IrcEvent.Type.ERROR, null, null,
                        "Server closed the link: " + serverError, null));
                break;

            case "BATCH":
                if (params.isEmpty()) break;
                String batchToken = params.get(0);
                if (batchToken.startsWith("+")) {
                    String ref = batchToken.substring(1);
                    // params = [+ref, type, channel]
                    String batchChannel = params.size() >= 3 ? params.get(2) : "";
                    activeBatches.put(ref, new ArrayList<>());
                    activeBatchChannels.put(ref, batchChannel);
                } else if (batchToken.startsWith("-")) {
                    String ref = batchToken.substring(1);
                    List<IrcEvent> accumulated = activeBatches.remove(ref);
                    String batchChannel = activeBatchChannels.remove(ref);
                    if (accumulated != null && batchChannel != null) {
                        fireEvent(new IrcEvent(IrcEvent.Type.HISTORY_BATCH, null, batchChannel, null, null, accumulated));
                    }
                }
                break;

            case "CAP":
                if (params.size() < 2) break;
                String capSubCommand = params.get(1).toUpperCase();
                switch (capSubCommand) {
                    case "LS": {
                        // Check for multi-line continuation: params = [clientNick, LS, *, cap-list] vs [clientNick, LS, cap-list]
                        boolean isContinuation = params.size() >= 4 && "*".equals(params.get(2));
                        String capList = isContinuation ? params.get(3) : (params.size() >= 3 ? params.get(2) : "");
                        for (String cap : capList.split(" ")) {
                            if (!cap.isEmpty()) {
                                int eq = cap.indexOf('=');
                                advertisedCaps.add(eq > 0 ? cap.substring(0, eq) : cap);
                            }
                        }
                        if (!isContinuation) {
                            // Final LS line: decide what to request
                            List<String> toRequest = new ArrayList<>();
                            if (advertisedCaps.contains("chathistory")) toRequest.add("chathistory");
                            if (advertisedCaps.contains("batch")) toRequest.add("batch");
                            if (advertisedCaps.contains("server-time")) toRequest.add("server-time");
                            // ZNC delivers lines typed in our other attached clients. Not
                            // echo-message: the adapter echoes our own sends locally already.
                            if (advertisedCaps.contains("znc.in/self-message")) toRequest.add("znc.in/self-message");
                            if (advertisedCaps.contains("away-notify")) toRequest.add("away-notify");
                            if (saslEnabled && advertisedCaps.contains("sasl")) toRequest.add("sasl");
                            if (!toRequest.isEmpty()) {
                                sendRawLine("CAP REQ :" + String.join(" ", toRequest));
                            } else if (!capEndSent) {
                                sendRawLine("CAP END");
                                capEndSent = true;
                            }
                        }
                        break;
                    }
                    case "ACK": {
                        String acked = params.size() >= 3 ? params.get(2) : "";
                        boolean saslAcked = false;
                        for (String cap : acked.split(" ")) {
                            String c = cap.trim();
                            if ("chathistory".equals(c)) capHistorySupported = true;
                            if ("away-notify".equals(c) && !capAwayNotify) {
                                capAwayNotify = true;
                                // Acked late (CAP NEW) after channels were joined: their JOINs
                                // went by without a WHO, so catch them up now.
                                for (String joined : channelUserList.channels()) {
                                    sendRawLine("WHO " + joined);
                                }
                            }
                            if ("sasl".equals(c)) saslAcked = true;
                        }
                        if (saslAcked) {
                            // Begin SASL PLAIN; hold CAP END until the SASL exchange completes
                            // (RPL_SASLSUCCESS or an error numeric).
                            sendRawLine("AUTHENTICATE PLAIN");
                        } else if (!capEndSent) {
                            sendRawLine("CAP END");
                            capEndSent = true;
                        }
                        break;
                    }
                    case "NEW": {
                        // cap-notify: ZNC offers the network's caps only once it knows who we
                        // are, after the CAP LS that opened registration was already answered.
                        String offered = params.size() >= 3 ? params.get(params.size() - 1) : "";
                        for (String cap : offered.split(" ")) {
                            int eq = cap.indexOf('=');
                            String name = eq > 0 ? cap.substring(0, eq) : cap;
                            if (name.isEmpty()) continue;
                            advertisedCaps.add(name);
                            if ("away-notify".equals(name) && !capAwayNotify) {
                                sendRawLine("CAP REQ :away-notify");
                            }
                        }
                        break;
                    }
                    case "DEL": {
                        String removed = params.size() >= 3 ? params.get(params.size() - 1) : "";
                        for (String cap : removed.split(" ")) {
                            advertisedCaps.remove(cap);
                            if ("away-notify".equals(cap) && capAwayNotify) {
                                // No more AWAY updates, so the marks we hold would only go stale.
                                capAwayNotify = false;
                                for (String channel : channelUserList.clearAway()) {
                                    fireUsersChanged(channel);
                                }
                            }
                        }
                        break;
                    }
                    case "NAK":
                        capHistorySupported = false;
                        if (!capEndSent) {
                            sendRawLine("CAP END");
                            capEndSent = true;
                        }
                        break;
                }
                break;

            case "AWAY":
                // away-notify: a message means away, none means back.
                markAway(sourceNick, !params.isEmpty() && !params.get(0).isEmpty());
                break;

            case "AUTHENTICATE":
                // Server replies "AUTHENTICATE +" when ready for the SASL PLAIN response.
                if (saslEnabled && !params.isEmpty() && "+".equals(params.get(0))) {
                    String authcid = (saslAccount != null && !saslAccount.isEmpty()) ? saslAccount : nick;
                    sendRawLine("AUTHENTICATE " + saslPlainResponse(authcid, saslPassword));
                }
                break;

            default:
                if (NUMERIC.matcher(command).matches()) {
                    int numeric = Integer.parseInt(command);
                    handleNumeric(numeric, source, params);
                }
                break;
        }
    }

    private void handleCtcp(String source, String target, String message) {
        String ctcp = message.substring(1, message.length() - 1);
        String[] parts = ctcp.split(" ", 2);
        String command = parts[0].toUpperCase();
        String param = parts.length > 1 ? parts[1] : "";
        String sourceNick = extractNick(source);

        switch (command) {
            case "ACTION":
                fireEvent(new IrcEvent(IrcEvent.Type.ACTION, sourceNick, bufferFor(target, sourceNick), param, currentTagTime));
                break;
            case "VERSION":
                sendRawLine("NOTICE " + sourceNick + " :\u0001VERSION RuneLite IRC Plugin\u0001");
                break;
            case "PING":
                sendRawLine("NOTICE " + sourceNick + " :\u0001PING " + param + "\u0001");
                break;
        }
    }

    /**
     * The buffer a PRIVMSG belongs in: the channel, else the other person. A line from our own
     * nick (ZNC self-message, typed in another client) belongs with its target, not with us.
     */
    private String bufferFor(String target, String sourceNick) {
        if (target.startsWith("#")) return target;
        return sourceNick.equalsIgnoreCase(nick) ? target : sourceNick;
    }

    private void handleNumeric(int numeric, String source, List<String> params) {
        switch (numeric) {
            case 1:
                // RPL_WELCOME: the server states our final, authoritative nick here.
                // This is how we learn our real nick after a 433/nick-in-use retry, as
                // the server does not echo a NICK during registration.
                if (!params.isEmpty()) {
                    nick = params.get(0);
                }
                connected = true;
                connectPhase = ConnectPhase.ESTABLISHED;
                fireEvent(new IrcEvent(IrcEvent.Type.REGISTERED, null, null, null, null));
                break;
            case 5: // RPL_ISUPPORT
                if (params.size() >= 2) {
                    modeSpec.applyIsupport(params.subList(1, params.size()));
                }
                break;
            case 263: // RPL_TRYAGAIN: only a throttled LIST concerns us here.
                if (params.size() >= 2 && "LIST".equalsIgnoreCase(params.get(1))) {
                    synchronized (channelListAccumulator) {
                        channelListAccumulator.clear();
                        channelListRunActive = false;
                    }
                    channelListTruncated = false;
                    fireEvent(new IrcEvent(IrcEvent.Type.CHANNEL_LIST_FAILED, null, null,
                            params.size() >= 3 ? params.get(params.size() - 1)
                                    : "Server asked us to try again later", null));
                }
                break;
            case 301:
                if (params.size() >= 2) markAway(params.get(1), true);
                if (params.size() >= 3)
                    fireEvent(new IrcEvent(IrcEvent.Type.WHOIS_REPLY, "System", params.get(1), String.format("%s is away: %s", params.get(1), params.get(2)), null));
                break;
            case 311:
                if (params.size() >= 5)
                    fireEvent(new IrcEvent(IrcEvent.Type.WHOIS_REPLY, "System", params.get(1), String.format("%s is %s@%s (%s)", params.get(1), params.get(2), params.get(3), params.get(5)), null));
                break;
            case 312:
                if (params.size() >= 4)
                    fireEvent(new IrcEvent(IrcEvent.Type.WHOIS_REPLY, "System", params.get(1), String.format("%s is connected to %s (%s)", params.get(1), params.get(2), params.get(3)), null));
                break;
            case 313:
                if (params.size() >= 2)
                    fireEvent(new IrcEvent(IrcEvent.Type.WHOIS_REPLY, "System", params.get(1), params.get(1) + " is an IRC operator", null));
                break;
            case 317:
                if (params.size() >= 3)
                    fireEvent(new IrcEvent(IrcEvent.Type.WHOIS_REPLY, "System", params.get(1), String.format("%s has been idle for %s seconds", params.get(1), params.get(2)), null));
                break;
            case 318:
                if (params.size() >= 2)
                    fireEvent(new IrcEvent(IrcEvent.Type.WHOIS_REPLY, "System", params.get(1), "End of WHOIS for " + params.get(1), null));
                break;
            case 319:
                if (params.size() >= 3)
                    fireEvent(new IrcEvent(IrcEvent.Type.WHOIS_REPLY, "System", params.get(1), String.format("%s is on channels: %s", params.get(1), params.get(2)), null));
                break;
            case 314: // RPL_WHOWASUSER
                if (params.size() >= 6)
                    fireEvent(new IrcEvent(IrcEvent.Type.WHOIS_REPLY, "System", params.get(1), String.format("%s was %s@%s (%s)", params.get(1), params.get(2), params.get(3), params.get(5)), null));
                break;
            case 338: // RPL_WHOISACTUALLY
            case 378: // RPL_WHOISHOST: the real host and IP, during WHOIS and WHOWAS alike.
                // Servers disagree on whether the IP is a middle parameter or in the text, so
                // show everything after the nick.
                if (params.size() >= 3)
                    fireEvent(new IrcEvent(IrcEvent.Type.WHOIS_REPLY, "System", params.get(1),
                            params.get(1) + " " + String.join(" ", params.subList(2, params.size())), null));
                break;
            case 369: // RPL_ENDOFWHOWAS
                if (params.size() >= 2)
                    fireEvent(new IrcEvent(IrcEvent.Type.WHOIS_REPLY, "System", params.get(1), "End of WHOWAS for " + params.get(1), null));
                break;
            case 406: // ERR_WASNOSUCHNICK: in the error range, but only WHOWAS finding nobody.
                if (params.size() >= 3)
                    fireEvent(new IrcEvent(IrcEvent.Type.WHOIS_REPLY, "System", params.get(1), params.get(1) + ": " + params.get(params.size() - 1), null));
                break;
            case 569: // RPL_WHOISASN (UnrealIRCd): in the error range, but only a WHOIS line.
                if (params.size() >= 3)
                    fireEvent(new IrcEvent(IrcEvent.Type.WHOIS_REPLY, "System", params.get(1), params.get(1) + " " + params.get(params.size() - 1), null));
                break;
            case 321: // RPL_LISTSTART: an explicit start always resets the run.
                synchronized (channelListAccumulator) {
                    channelListAccumulator.clear();
                    channelListRunActive = true;
                }
                channelListTruncated = false;
                break;
            case 322: // RPL_LIST: <me> <channel> <count> :<topic>
                if (params.size() >= 3) {
                    String listChannel = params.get(1);
                    if (listChannel != null && !listChannel.isEmpty()) {
                        synchronized (channelListAccumulator) {
                            if (!channelListRunActive) {
                                // Some servers skip 321; the first row starts the run and must
                                // not inherit a stale truncation flag from the previous one.
                                channelListAccumulator.clear();
                                channelListRunActive = true;
                                channelListTruncated = false;
                            }
                            if (channelListAccumulator.size() >= CHANNEL_LIST_CAP) {
                                channelListTruncated = true;
                            } else {
                                int userCount;
                                try {
                                    userCount = Integer.parseInt(params.get(2).trim());
                                } catch (NumberFormatException e) {
                                    // One odd row costs its count, not the rest of the list.
                                    userCount = 0;
                                }
                                String listTopic = params.size() >= 4 && params.get(3) != null
                                        ? params.get(3) : "";
                                channelListAccumulator.add(
                                        new ChannelListEntry(listChannel, userCount, listTopic));
                            }
                        }
                    }
                }
                break;
            case 323: { // RPL_LISTEND: publish one immutable snapshot, but only for a real run -
                         // an unpaired 323 must not clobber the previous snapshot.
                List<ChannelListEntry> completedRun = null;
                synchronized (channelListAccumulator) {
                    if (channelListRunActive) {
                        completedRun = new ArrayList<>(channelListAccumulator);
                        channelListAccumulator.clear();
                        channelListRunActive = false;
                    }
                }
                if (completedRun != null) {
                    channelListSnapshot = Collections.unmodifiableList(completedRun);
                    fireEvent(new IrcEvent(IrcEvent.Type.CHANNEL_LIST, null, null, null, null));
                }
                break;
            }
            case 324:
                if (params.size() >= 2) {
                    String target = params.get(1);
                    StringBuilder message = new StringBuilder();
                    for (int i = 2; i < params.size(); i++) message.append(" ").append(params.get(i));
                    fireEvent(new IrcEvent(IrcEvent.Type.CHANNEL_MODE, "* Modes", target, message.toString().trim(), null));
                }
                break;
            case 332:
                if (params.size() >= 3)
                    fireEvent(new IrcEvent(IrcEvent.Type.TOPIC, "System", params.get(1), params.get(2), null));
                break;
            case 333:
                if (params.size() >= 4)
                    fireEvent(new IrcEvent(IrcEvent.Type.TOPIC_INFO, "* Topic set by", params.get(1), params.get(2), null));
                break;
            case 305: // RPL_UNAWAY
                markAway(nick, false);
                break;
            case 306: // RPL_NOWAWAY
                markAway(nick, true);
                break;
            case 352: // RPL_WHOREPLY: <me> <channel> <user> <host> <server> <nick> <H|G>[*@+] :<hops> <real>
                if (params.size() >= 7) {
                    whoChangedChannels.addAll(channelUserList.setAway(params.get(5), params.get(6).startsWith("G")));
                }
                break;
            case 315: // RPL_ENDOFWHO
                for (String whoChannel : whoChangedChannels) {
                    fireUsersChanged(whoChannel);
                }
                whoChangedChannels.clear();
                break;
            case 353:
                if (params.size() >= 4) {
                    String channel = params.get(2);
                    String[] users = params.get(3).split(" ");
                    channelUserList.addNames(channel, java.util.Arrays.asList(users));
                    fireEvent(new IrcEvent(IrcEvent.Type.NAMES, null, channel, String.join(" ", users), null));
                }
                break;
            case 366: // RPL_ENDOFNAMES
                if (params.size() >= 2) {
                    String channel = params.get(1);
                    channelUserList.endNames(channel);
                    fireUsersChanged(channel);
                }
                break;
            case 433:
                if (params.size() >= 2)
                    fireEvent(new IrcEvent(IrcEvent.Type.NICK_IN_USE, null, null, params.get(1), null));
                break;
            case 475:
                if (params.size() >= 2)
                    fireEvent(new IrcEvent(IrcEvent.Type.BAD_CHANNEL_KEY, null, params.get(1), params.get(2), null));
                break;
            case 903: // RPL_SASLSUCCESS
                if (!capEndSent) {
                    sendRawLine("CAP END");
                    capEndSent = true;
                }
                fireEvent(new IrcEvent(IrcEvent.Type.SASL_SUCCESS, null, null,
                        params.size() >= 2 ? params.get(params.size() - 1) : "SASL authentication successful", null));
                break;
            case 902: // ERR_NICKLOCKED
            case 904: // ERR_SASLFAIL
            case 905: // ERR_SASLTOOLONG
            case 906: // ERR_SASLABORTED
            case 908: // RPL_SASLMECHS
                // Authentication failed; end capability negotiation so registration can proceed
                // unauthenticated rather than stalling.
                if (!capEndSent) {
                    sendRawLine("CAP END");
                    capEndSent = true;
                }
                fireEvent(new IrcEvent(IrcEvent.Type.SASL_FAILED, null, null,
                        params.size() >= 2 ? params.get(params.size() - 1) : "SASL authentication failed", null));
                break;
            default:
                // Every numeric we do not name above used to be discarded, which is how a refused
                // connection became a silent one. The error ranges always carry text the user
                // needs - "you are banned", "reconnecting too fast", "erroneous nickname" - so
                // report it verbatim rather than enumerating every numeric a server might send.
                if (numeric >= 400 && numeric <= 599 && params.size() >= 2) {
                    String errorText = params.get(params.size() - 1);
                    if (errorText != null && !errorText.isEmpty()) {
                        fireEvent(new IrcEvent(IrcEvent.Type.SERVER_ERROR, null, null,
                                "Server error " + numeric + ": " + errorText, null));
                    }
                }
                break;
        }
    }

    /**
     * Records the first reason seen for a teardown. First writer wins: a server ERROR explains a
     * drop better than the EOF that follows it a moment later.
     */
    private void recordDisconnectReason(String reason) {
        if (reason == null || reason.isEmpty()) return;
        if (disconnectReason == null) disconnectReason = reason;
    }

    /**
     * Strips credentials from a line before it reaches the log. Raw logging exists so a user can
     * send us the log, which makes this a correctness requirement rather than a nicety.
     *
     * What is kept matters as much as what is removed: the SASL mechanism and the server's
     * "AUTHENTICATE +" continuation carry no secret and are exactly what you need to see to
     * diagnose a stalled negotiation.
     */
    static String redactForLog(String line) {
        if (line == null || line.isEmpty()) return line;

        if (line.regionMatches(true, 0, "AUTHENTICATE ", 0, 13)) {
            String payload = line.substring(13).trim();
            boolean negotiation = payload.equals("+")
                    || payload.equalsIgnoreCase("PLAIN")
                    || payload.equalsIgnoreCase("EXTERNAL");
            return negotiation ? line : "AUTHENTICATE " + REDACTED;
        }

        if (line.regionMatches(true, 0, "PASS ", 0, 5)) {
            return "PASS " + REDACTED;
        }

        Matcher services = SERVICES_SECRET.matcher(line);
        if (services.find()) {
            return line.substring(0, services.end()) + " " + REDACTED;
        }

        if (line.regionMatches(true, 0, "JOIN ", 0, 5)) {
            // "JOIN <channels> [keys]" - a third token is always the key list.
            String[] tokens = line.split(" ");
            if (tokens.length >= 3) {
                return tokens[0] + " " + tokens[1] + " " + REDACTED;
            }
            return line;
        }

        return redactModeKeys(line);
    }

    /**
     * Redacts channel keys from MODE traffic, in both directions: "MODE #chan +k secret" going
     * out, and ":op MODE #chan -k secret" or the server's "324 me #chan +nk secret" coming back.
     * Removing a key names it on most ircds, so -k leaks as readily as +k.
     *
     * Rather than track which mode letters consume a parameter - which varies by ircd and would
     * have to stay in step with ISUPPORT - every parameter after a mode string containing 'k' is
     * dropped. Over-redacting a mode argument costs nothing; the mode string itself, which is the
     * part worth reading, is kept.
     */
    private static String redactModeKeys(String line) {
        String[] tokens = line.split(" ");
        int command = tokens.length > 0 && tokens[0].startsWith(":") ? 1 : 0;
        if (command >= tokens.length) return line;

        if (!tokens[command].equalsIgnoreCase("MODE") && !tokens[command].equals("324")) {
            return line;
        }

        for (int i = command + 1; i < tokens.length; i++) {
            boolean isModeSpec = tokens[i].startsWith("+") || tokens[i].startsWith("-");
            // Mode letters are case sensitive: 'K' is a different mode on some ircds.
            if (isModeSpec && tokens[i].indexOf('k') >= 0) {
                if (i + 1 >= tokens.length) return line;
                return String.join(" ", java.util.Arrays.copyOfRange(tokens, 0, i + 1))
                        + " " + REDACTED;
            }
        }
        return line;
    }

    /** Where a connection was when it failed. Shapes the message the user is shown. */
    enum ConnectPhase {
        CONNECTING("connecting to"),
        TLS_HANDSHAKE("completing the TLS handshake with"),
        REGISTERING("registering with"),
        ESTABLISHED("reading from");

        final String description;

        ConnectPhase(String description) {
            this.description = description;
        }
    }

    /**
     * Turns an exception into something a user can paste into a bug report. The JDK's own messages
     * are too terse to act on: UnknownHostException says only the hostname, and SocketTimeoutException
     * says only "Read timed out" with no hint that four minutes of silence went by.
     */
    static String describeFailure(ConnectPhase phase, String host, int port, Throwable e) {
        String where = host + ":" + port;
        String type = e.getClass().getSimpleName();
        String detail = e.getMessage();

        if (e instanceof UnknownHostException) {
            return "DNS lookup failed: " + host + " could not be resolved (" + type + ")";
        }
        if (e instanceof SocketTimeoutException) {
            return "Timed out " + phase.description + " " + where + " - no data for "
                    + (READ_TIMEOUT_MS / 1000) + "s (" + type + ")";
        }
        return "Failed while " + phase.description + " " + where + " - " + type
                + (detail == null || detail.isEmpty() ? "" : ": " + detail);
    }

    private String extractNick(String source) {
        if (source == null || source.isEmpty()) return "";
        int exclamation = source.indexOf('!');
        return exclamation > 0 ? source.substring(0, exclamation) : source;
    }

    /**
     * Mirrors every protocol line to the client log, credentials stripped. Off by default and
     * safe to flip mid-session, which matters because the failure worth capturing usually
     * happens during connect.
     */
    public void setRawLogging(boolean enabled) {
        this.rawLogging = enabled;
    }

    public void addEventListener(IrcEventListener listener) {
        listeners.add(listener);
    }

    public void removeEventListener(IrcEventListener listener) {
        listeners.remove(listener);
    }

    /** Current roster for a channel, sorted by rank then nick. Empty when unknown. */
    List<ChannelUserList.Entry> getChannelUsers(String channel) {
        return channelUserList.snapshot(channel);
    }

    /** The nick's highest channel prefix ("@", "+", ...), or "" when it has none. */
    String getChannelPrefix(String channel, String nick) {
        return channelUserList.prefixOf(channel, nick);
    }

    /** The last completed channel list. Immutable; empty until a LIST finishes. */
    List<ChannelListEntry> getChannelListSnapshot() {
        return channelListSnapshot;
    }

    /** True when the last LIST hit CHANNEL_LIST_CAP and rows were dropped. */
    boolean isChannelListTruncated() {
        return channelListTruncated;
    }

    /**
     * Clears any abandoned LIST run before a fresh request goes out. Without this, a run that
     * lost its 323 (the server's reply is cut short, but the connection survives) leaves
     * channelListRunActive true, so the next LIST's 322 rows would append onto the stale ones
     * instead of starting fresh. Does not touch channelListSnapshot - the previously displayed
     * list should survive until a new one completes, so Refresh does not blank the dialog
     * mid-flight.
     */
    void resetChannelListRun() {
        synchronized (channelListAccumulator) {
            channelListAccumulator.clear();
            channelListRunActive = false;
        }
        channelListTruncated = false;
    }

    /**
     * True once the socket is open and the NICK/USER/CAP handshake has been written, and until
     * the connection drops.
     *
     * This is deliberately NOT "registered": the flag is set as soon as those lines go out, well
     * before the server answers RPL_WELCOME (which only re-affirms it). A command sent in between
     * - the gap is sub-second on a fast connection but several seconds with SASL - reaches the
     * server and may come back as 451 ERR_NOTREGISTERED.
     */
    public boolean isConnected() {
        return connected;
    }

    /** Fires USERS_CHANGED for a channel whose roster just changed. */
    private void markAway(String who, boolean isAway) {
        if (who == null || who.isEmpty()) return;
        for (String channel : channelUserList.setAway(who, isAway)) {
            fireUsersChanged(channel);
        }
    }

    private void fireUsersChanged(String channel) {
        fireEvent(new IrcEvent(IrcEvent.Type.USERS_CHANGED, null, channel, null, null));
    }

    private final List<Runnable> pendingCommands = new CopyOnWriteArrayList<>();

    /**
     * Queue a command to be executed once fully registered with the server
     */
    public void executeWhenRegistered(Runnable command) {
        if (connected) {
            command.run();
        } else {
            pendingCommands.add(command);
        }
    }

    private void fireEvent(IrcEvent event) {
        if (event.getType() == IrcEvent.Type.REGISTERED) {
            for (Runnable command : pendingCommands) {
                command.run();
            }
            pendingCommands.clear();
        }

        for (IrcEventListener listener : listeners) {
            listener.onEvent(event);
        }
    }

    public interface IrcEventListener {
        void onEvent(IrcEvent event);
    }

    @Getter
    public static class IrcEvent {
        public enum Type {
            CONNECT, DISCONNECT, REGISTERED, MESSAGE, ACTION, JOIN, PART, QUIT,
            NICK_CHANGE, KICK, NOTICE, SERVER_NOTICE, CHANNEL_MODE, USER_MODE,
            TOPIC, NAMES, NICK_IN_USE, ERROR, TOPIC_INFO, BAD_CHANNEL_KEY, WHOIS_REPLY,
            HISTORY_BATCH, SASL_SUCCESS, SASL_FAILED, USERS_CHANGED,
            CHANNEL_LIST, CHANNEL_LIST_FAILED, SERVER_ERROR
        }

        private final Type type;
        private final String source;
        private final String target;
        private final String message;
        private final String additionalData;
        private final List<IrcEvent> historyMessages;

        public IrcEvent(Type type, String source, String target, String message,
                        String additionalData, List<IrcEvent> historyMessages) {
            this.type = type;
            this.source = source;
            this.target = target;
            this.message = message;
            this.additionalData = additionalData;
            this.historyMessages = historyMessages;
        }

        public IrcEvent(Type type, String source, String target, String message, String additionalData) {
            this(type, source, target, message, additionalData, null);
        }
    }
}

package com.irc;

import java.util.ArrayList;
import java.util.Collection;
import java.util.List;
import java.util.Locale;

/**
 * Tab completion for the input box: the word before the caret is completed from the nicks in
 * the focused buffer, or from the joined channels when it starts with '#'.
 *
 * Pressing Tab again straight away cycles through the other matches. That is detected by the
 * input still being exactly what the last completion produced; any edit, history recall or
 * caret move in between starts a fresh completion instead.
 */
class TabCompleter {

    /** The input box contents after a completion. */
    static final class Result {
        final String text;
        final int caret;

        Result(String text, int caret) {
            this.text = text;
            this.caret = caret;
        }
    }

    private List<String> matches = new ArrayList<>();
    private int index;
    /** The word the user typed before the first Tab. */
    private String word = "";
    private String head = "";
    private String tail = "";
    private boolean lineStart;
    private String lastText;
    private int lastCaret = -1;

    /**
     * Completes or cycles. Returns null when there is nothing to complete, leaving the input as it is.
     *
     * @param forward false steps backwards through the matches (Shift+Tab)
     */
    Result complete(String text, int caret, Collection<String> nicks, Collection<String> channels, boolean forward) {
        if (text.equals(lastText) && caret == lastCaret && !matches.isEmpty()) {
            // The input box is shared across buffers, so the candidates may have changed since the
            // last Tab. If the matches for the original word differ, start over with the new ones.
            List<String> current = findMatches(word, word.startsWith("#") ? channels : nicks);
            if (current.equals(matches)) {
                index = Math.floorMod(index + (forward ? 1 : -1), matches.size());
            } else if (current.isEmpty()) {
                matches = current;
                lastText = null;
                return null;
            } else {
                matches = current;
                index = forward ? 0 : matches.size() - 1;
            }
        } else {
            int wordStart = caret;
            while (wordStart > 0 && !Character.isWhitespace(text.charAt(wordStart - 1))) {
                wordStart--;
            }
            word = text.substring(wordStart, caret);
            if (word.isEmpty()) {
                return null;
            }
            matches = findMatches(word, word.startsWith("#") ? channels : nicks);
            if (matches.isEmpty()) {
                lastText = null;
                return null;
            }
            head = text.substring(0, wordStart);
            tail = text.substring(caret);
            lineStart = head.trim().isEmpty();
            index = forward ? 0 : matches.size() - 1;
        }

        String match = matches.get(index);
        // "bob: " addresses someone at the start of a line; elsewhere, and for channels, just a space.
        String suffix = lineStart && !match.startsWith("#") ? ": " : " ";
        if (tail.startsWith(" ")) {
            suffix = suffix.substring(0, suffix.length() - 1);
        }
        String completed = head + match + suffix;
        lastText = completed + tail;
        lastCaret = completed.length();
        return new Result(lastText, lastCaret);
    }

    private static List<String> findMatches(String word, Collection<String> candidates) {
        String lowerWord = word.toLowerCase(Locale.ROOT);
        List<String> found = new ArrayList<>();
        for (String candidate : candidates) {
            if (candidate.toLowerCase(Locale.ROOT).startsWith(lowerWord) && !found.contains(candidate)) {
                found.add(candidate);
            }
        }
        found.sort(String.CASE_INSENSITIVE_ORDER);
        return found;
    }
}

package com.irc;

import java.awt.Component;
import java.awt.Container;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.Insets;

/**
 * A FlowLayout whose preferred size wraps onto as many rows as the available width needs.
 * FlowLayout itself lays components out in rows but always asks for a single row's height, so the
 * rows past the first are cut off.
 *
 * The width comes from the parent where there is one: a BorderLayout sizes its parent before
 * asking for this container's preferred size, so the container's own width is still the old one
 * while the window is being resized.
 */
final class WrapLayout extends FlowLayout {
    WrapLayout(int align, int hgap, int vgap) {
        super(align, hgap, vgap);
    }

    @Override
    public Dimension preferredLayoutSize(Container target) {
        return layoutSize(target, true);
    }

    @Override
    public Dimension minimumLayoutSize(Container target) {
        return layoutSize(target, false);
    }

    private Dimension layoutSize(Container target, boolean preferred) {
        synchronized (target.getTreeLock()) {
            int available = availableWidth(target);
            Insets insets = target.getInsets();
            int maxRow = available - insets.left - insets.right - getHgap() * 2;
            int width = 0;
            int height = 0;
            int rowWidth = 0;
            int rowHeight = 0;
            for (Component component : target.getComponents()) {
                if (!component.isVisible()) continue;
                Dimension size = preferred ? component.getPreferredSize() : component.getMinimumSize();
                if (rowWidth > 0 && rowWidth + getHgap() + size.width > maxRow) {
                    width = Math.max(width, rowWidth);
                    height += rowHeight + getVgap();
                    rowWidth = 0;
                    rowHeight = 0;
                }
                if (rowWidth > 0) rowWidth += getHgap();
                rowWidth += size.width;
                rowHeight = Math.max(rowHeight, size.height);
            }
            width = Math.max(width, rowWidth);
            height += rowHeight;
            return new Dimension(width + insets.left + insets.right + getHgap() * 2,
                    height + insets.top + insets.bottom + getVgap() * 2);
        }
    }

    /** The width to wrap at; unbounded until something has been given a size. */
    private static int availableWidth(Container target) {
        Container parent = target.getParent();
        if (parent != null && parent.getWidth() > 0) {
            Insets insets = parent.getInsets();
            return parent.getWidth() - insets.left - insets.right;
        }
        return target.getWidth() > 0 ? target.getWidth() : Integer.MAX_VALUE;
    }
}

package com.irc.emoji;

import java.util.Collections;
import java.util.List;

public class Emoji {
    private final String unicode;
    private final List<String> aliases;
    private final boolean supportsFitzpatrick;

    public Emoji(String unicode, List<String> aliases, boolean supportsFitzpatrick) {
        this.unicode = unicode;
        this.aliases = Collections.unmodifiableList(aliases);
        this.supportsFitzpatrick = supportsFitzpatrick;
    }

    public String getUnicode() {
        return unicode;
    }

    public List<String> getAliases() {
        return aliases;
    }

    public boolean supportsFitzpatrick() {
        return supportsFitzpatrick;
    }

    public String getUnicode(Fitzpatrick fitzpatrick) {
        if (!supportsFitzpatrick) {
            throw new UnsupportedOperationException("This emoji doesn't support Fitzpatrick modifiers");
        }
        return fitzpatrick == null ? unicode : unicode + fitzpatrick.unicode;
    }
}

package com.irc.emoji;

import java.util.*;

public class EmojiManager {
    private static final Map<String, Emoji> EMOJI_BY_UNICODE = new HashMap<>();
    private static final Map<String, Emoji> EMOJI_BY_ALIAS = new HashMap<>();
    private static final List<Emoji> ALL_EMOJIS = new ArrayList<>();
    private static EmojiTrie EMOJI_TRIE;
    private static boolean initialized = false;

    static boolean isInitialized() {
        return initialized;
    }

    static void register(Emoji emoji) {
        EMOJI_BY_UNICODE.put(emoji.getUnicode(), emoji);
        ALL_EMOJIS.add(emoji);
        for (String alias : emoji.getAliases()) {
            EMOJI_BY_ALIAS.put(alias, emoji);
        }
    }

    static void finishInitialization() {
        EMOJI_TRIE = new EmojiTrie(ALL_EMOJIS);
        initialized = true;
    }

    public static Emoji getByUnicode(String unicode) {
        if (unicode == null) return null;
        return EMOJI_TRIE.getEmoji(unicode);
    }

    public static int getEmojiEndPos(char[] text, int startPos) {
        if (!initialized) {
            throw new IllegalStateException("EmojiManager has not been initialized. Call initialize() first.");
        }

        int best = -1;
        for (int j = startPos + 1; j <= text.length; j++) {
            EmojiTrie.Matches status = EMOJI_TRIE.isEmoji(text, startPos, j);
            if (status.exactMatch()) {
                best = j;
            } else if (status.impossibleMatch()) {
                return best;
            }
        }
        return best;
    }
}

package com.irc.emoji;

import java.util.ArrayList;
import java.util.List;

public class EmojiParser {
    public enum FitzpatrickAction {
        PARSE, REMOVE, IGNORE
    }

    public static String parseToAliases(String input) {
        return parseToAliases(input, FitzpatrickAction.PARSE);
    }

    public static String parseToAliases(String input, FitzpatrickAction fitzpatrickAction) {
        if (input == null || input.isEmpty()) return input;

        int prev = 0;
        StringBuilder sb = new StringBuilder(input.length());
        List<UnicodeCandidate> candidates = getUnicodeCandidates(input);

        for (UnicodeCandidate candidate : candidates) {
            sb.append(input, prev, candidate.getEmojiStartIndex());

            String replacement;
            switch (fitzpatrickAction) {
                case PARSE:
                    if (candidate.hasFitzpatrick()) {
                        replacement = ":" +
                                candidate.getEmoji().getAliases().get(0) +
                                "|" +
                                candidate.getFitzpatrickType() +
                                ":";
                    } else {
                        replacement = ":" + candidate.getEmoji().getAliases().get(0) + ":";
                    }
                    break;
                case REMOVE:
                    replacement = ":" + candidate.getEmoji().getAliases().get(0) + ":";
                    break;
                case IGNORE:
                default:
                    replacement = ":" +
                            candidate.getEmoji().getAliases().get(0) +
                            ":" +
                            candidate.getFitzpatrickUnicode();
                    break;
            }

            sb.append(replacement);
            prev = candidate.getFitzpatrickEndIndex();
        }

        return sb.append(input.substring(prev)).toString();
    }

    /**
     * Generates a list of UnicodeCandidate found in the input string.
     */
    protected static List<UnicodeCandidate> getUnicodeCandidates(String input) {
        char[] inputCharArray = input.toCharArray();
        List<UnicodeCandidate> candidates = new ArrayList<>();
        UnicodeCandidate next;

        for (int i = 0; (next = getNextUnicodeCandidate(inputCharArray, i)) != null;
             i = next.getFitzpatrickEndIndex()) {
            candidates.add(next);
        }

        return candidates;
    }

    /**
     * Finds the next UnicodeCandidate after a given starting index
     */
    protected static UnicodeCandidate getNextUnicodeCandidate(char[] chars, int start) {
        for (int i = start; i < chars.length; i++) {
            int emojiEnd = EmojiManager.getEmojiEndPos(chars, i);

            if (emojiEnd != -1) {
                Emoji emoji = EmojiManager.getByUnicode(new String(chars, i, emojiEnd - i));
                String fitzpatrickString = (emojiEnd + 2 <= chars.length) ?
                        new String(chars, emojiEnd, 2) :
                        null;
                return new UnicodeCandidate(emoji, fitzpatrickString, i);
            }
        }

        return null;
    }

    public static class UnicodeCandidate {
        private final Emoji emoji;
        private final Fitzpatrick fitzpatrick;
        private final int startIndex;

        private UnicodeCandidate(Emoji emoji, String fitzpatrick, int startIndex) {
            this.emoji = emoji;
            this.fitzpatrick = Fitzpatrick.fromUnicode(fitzpatrick);
            this.startIndex = startIndex;
        }

        public Emoji getEmoji() {
            return emoji;
        }

        public boolean hasFitzpatrick() {
            return getFitzpatrick() != null;
        }

        public Fitzpatrick getFitzpatrick() {
            return fitzpatrick;
        }

        public String getFitzpatrickType() {
            return hasFitzpatrick() ? fitzpatrick.name().toLowerCase() : "";
        }

        public String getFitzpatrickUnicode() {
            return hasFitzpatrick() ? fitzpatrick.unicode : "";
        }

        public int getEmojiStartIndex() {
            return startIndex;
        }

        public int getEmojiEndIndex() {
            return startIndex + emoji.getUnicode().length();
        }

        public int getFitzpatrickEndIndex() {
            return getEmojiEndIndex() + (fitzpatrick != null ? 2 : 0);
        }
    }
}

package com.irc.emoji;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import lombok.extern.slf4j.Slf4j;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;

@Slf4j
@Singleton
public class EmojiService {
    private static final String EMOJI_JSON_PATH = "/emojis.json";

    private final Gson gson;

    @Inject
    public EmojiService(Gson gson) {
        this.gson = gson;
    }

    public void initialize() {
        try {
            log.debug("Initializing emoji data");
            loadEmojis();
            log.debug("Successfully initialized emoji data");
        } catch (Exception e) {
            log.error("Failed to initialize emoji data", e);
            throw new RuntimeException("Failed to initialize emoji data", e);
        }
    }

    private void loadEmojis() throws Exception {
        if (EmojiManager.isInitialized()) {
            return;
        }

        try (InputStream is = EmojiManager.class.getResourceAsStream(EMOJI_JSON_PATH)) {
            if (is == null) {
                throw new RuntimeException("Could not find resource: " + EMOJI_JSON_PATH);
            }

            try (Reader reader = new InputStreamReader(is, StandardCharsets.UTF_8)) {
                JsonArray emojiArray = gson.fromJson(reader, JsonArray.class);

                if (emojiArray == null) {
                    throw new RuntimeException("Failed to parse emoji JSON or file is empty");
                }

                for (int i = 0; i < emojiArray.size(); i++) {
                    JsonObject emojiJson = emojiArray.get(i).getAsJsonObject();
                    if (!emojiJson.has("emoji")) continue;

                    String unicode = emojiJson.get("emoji").getAsString();
                    boolean supportsFitzpatrick = emojiJson.has("supports_fitzpatrick") ?
                            emojiJson.get("supports_fitzpatrick").getAsBoolean() : false;

                    List<String> aliases = new ArrayList<>();
                    if (emojiJson.has("aliases")) {
                        JsonArray aliasesJson = emojiJson.getAsJsonArray("aliases");
                        for (int j = 0; j < aliasesJson.size(); j++) {
                            aliases.add(aliasesJson.get(j).getAsString());
                        }
                    }

                    EmojiManager.register(new Emoji(unicode, aliases, supportsFitzpatrick));
                }
            }
        }

        EmojiManager.finishInitialization();
    }
}

package com.irc.emoji;

import java.util.Collection;
import java.util.HashMap;
import java.util.Map;

public class EmojiTrie {
    private final Node root = new Node();
    final int maxDepth;

    public EmojiTrie(Collection<Emoji> emojis) {
        int maxDepth = 0;
        for (Emoji emoji : emojis) {
            Node tree = root;
            char[] chars = emoji.getUnicode().toCharArray();
            maxDepth = Math.max(maxDepth, chars.length);
            for (char c : chars) {
                if (!tree.hasChild(c)) {
                    tree.addChild(c);
                }
                tree = tree.getChild(c);
            }
            tree.setEmoji(emoji);
        }
        this.maxDepth = maxDepth;
    }

    /**
     * Checks if sequence of chars contain an emoji.
     */
    public Matches isEmoji(char[] sequence) {
        return isEmoji(sequence, 0, sequence.length);
    }

    /**
     * Checks if the sequence of chars within the given bound indices contain an emoji.
     */
    public Matches isEmoji(char[] sequence, int start, int end) {
        if (start < 0 || start > end || end > sequence.length) {
            throw new ArrayIndexOutOfBoundsException(
                    "start " + start + ", end " + end + ", length " + sequence.length);
        }
        if (sequence == null) {
            return Matches.POSSIBLY;
        }
        Node tree = root;
        for (int i = start; i < end; i++) {
            if (!tree.hasChild(sequence[i])) {
                return Matches.IMPOSSIBLE;
            }
            tree = tree.getChild(sequence[i]);
        }
        return tree.isEndOfEmoji() ? Matches.EXACTLY : Matches.POSSIBLY;
    }

    /**
     * Finds Emoji instance from emoji unicode
     */
    public Emoji getEmoji(String unicode) {
        return getEmoji(unicode.toCharArray(), 0, unicode.length());
    }

    /**
     * Finds Emoji instance from emoji unicode chars.
     */
    public Emoji getEmoji(char[] sequence, int start, int end) {
        if (start < 0 || start > end || end > sequence.length) {
            throw new ArrayIndexOutOfBoundsException(
                    "start " + start + ", end " + end + ", length " + sequence.length);
        }
        Node tree = root;
        for (int i = start; i < end; i++) {
            if (!tree.hasChild(sequence[i])) {
                return null;
            }
            tree = tree.getChild(sequence[i]);
        }
        return tree.getEmoji();
    }

    public enum Matches {
        EXACTLY, POSSIBLY, IMPOSSIBLE;

        public boolean exactMatch() {
            return this == EXACTLY;
        }

        public boolean impossibleMatch() {
            return this == IMPOSSIBLE;
        }
    }

    private class Node {
        private Map<Character, Node> children = new HashMap<>();
        private Emoji emoji;

        private void setEmoji(Emoji emoji) {
            this.emoji = emoji;
        }

        private Emoji getEmoji() {
            return emoji;
        }

        private boolean hasChild(char child) {
            return children.containsKey(child);
        }

        private void addChild(char child) {
            children.put(child, new Node());
        }

        private Node getChild(char child) {
            return children.get(child);
        }

        private boolean isEndOfEmoji() {
            return emoji != null;
        }
    }
}

package com.irc.emoji;

public enum Fitzpatrick {
    TYPE_1_2("\uD83C\uDFFB"),
    TYPE_3("\uD83C\uDFFC"),
    TYPE_4("\uD83C\uDFFD"),
    TYPE_5("\uD83C\uDFFE"),
    TYPE_6("\uD83C\uDFFF");

    public final String unicode;

    Fitzpatrick(String unicode) {
        this.unicode = unicode;
    }

    public static Fitzpatrick fromUnicode(String unicode) {
        if (unicode == null) return null;
        for (Fitzpatrick f : values()) {
            if (f.unicode.equals(unicode)) {
                return f;
            }
        }
        return null;
    }
}

