package com.irc;

import org.junit.Test;

import static org.junit.Assert.*;

public class BufferHistoryTest {
    private static final BufferKey A = BufferKey.swiftIrc("#a");
    private static final BufferKey B = BufferKey.swiftIrc("#b");
    private static final BufferKey C = BufferKey.swiftIrc("#c");
    private static final BufferKey D = BufferKey.swiftIrc("#d");

    private final BufferHistory history = new BufferHistory(50);

    /** Shows what back()/forward() returned, as the panel does by focusing it. */
    private BufferKey show(BufferKey key) {
        history.visit(key);
        return key;
    }

    @Test
    public void lastIsTheBufferShownBeforeAndTogglesBetweenTwo() {
        assertNull(history.last());
        history.visit(A);
        assertNull(history.last());
        history.visit(B);
        assertEquals(A, history.last());
        history.visit(history.last());
        assertEquals(B, history.last());
        history.visit(history.last());
        assertEquals(A, history.last());
    }

    @Test
    public void revisitingTheShownBufferChangesNothing() {
        history.visit(A);
        history.visit(B);
        history.visit(B);
        assertEquals(A, history.last());
    }

    @Test
    public void backAndForwardWalkTheHistory() {
        history.visit(A);
        history.visit(B);
        history.visit(C);
        assertNull(history.forward());
        assertEquals(B, show(history.back()));
        assertEquals(A, show(history.back()));
        assertNull(history.back());
        assertEquals(B, show(history.forward()));
        assertEquals(C, show(history.forward()));
        assertNull(history.forward());
    }

    @Test
    public void walkingBackUpdatesLast() {
        history.visit(A);
        history.visit(B);
        history.visit(C);
        show(history.back());
        assertEquals(C, history.last());
    }

    @Test
    public void aBufferIsListedOnceAtItsLatestVisit() {
        history.visit(A);
        history.visit(B);
        history.visit(C);
        history.visit(A);
        assertEquals(C, show(history.back()));
        assertEquals(B, show(history.back()));
        assertNull(history.back());
    }

    @Test
    public void switchingAwayWhileWalkingKeepsTheWalkedToBufferNext() {
        history.visit(A);
        history.visit(B);
        history.visit(C);
        show(history.back());
        history.visit(D);
        assertEquals("back goes to the buffer just left", B, show(history.back()));
        assertEquals(C, show(history.back()));
        assertEquals(A, show(history.back()));
        assertNull(history.back());
    }

    @Test
    public void closedBuffersAreForgotten() {
        history.visit(A);
        history.visit(B);
        history.visit(C);
        history.remove(B);
        assertEquals(A, show(history.back()));
        assertNull(history.back());

        history.visit(C);
        history.remove(C);
        history.visit(D);
        assertEquals("closing the shown buffer leaves last alone", A, history.last());
        assertEquals(A, history.back());

        history.remove(A);
        assertNull(history.last());
    }

    @Test
    public void followsRenames() {
        BufferKey bob = BufferKey.swiftIrc("bob");
        BufferKey bob2 = BufferKey.swiftIrc("bob2");
        history.visit(bob);
        history.visit(A);
        history.rename(bob, bob2);
        assertEquals(bob2, history.last());
        assertEquals(bob2, show(history.back()));
        assertEquals(A, history.last());
    }

    @Test
    public void dropsTheOldestPastCapacity() {
        BufferHistory small = new BufferHistory(2);
        small.visit(A);
        small.visit(B);
        small.visit(C);
        assertEquals(B, small.back());
        assertNull(small.back());
    }
}

package com.irc;

import org.junit.Test;

import javax.swing.JTable;
import java.awt.GraphicsEnvironment;
import java.lang.reflect.Field;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.junit.Assume.assumeFalse;

/**
 * The Topic column's tooltip.
 *
 * The design requires the topic be "rendered with formatting codes stripped, full text in a
 * tooltip since the column truncates" - the column is 440px wide and most real topics are longer,
 * so without the tooltip the tail of a topic is simply unreadable. The column shipped with the
 * default renderer and no tooltip at all.
 *
 * The dialog itself cannot be built headless (it is a Window), but the renderer is an ordinary
 * JLabel subclass, so the tooltip is asserted directly without one.
 */
public class ChannelListDialogTopicRendererTest {

    private static String tooltipFor(Object value) {
        ChannelListDialog.TopicRenderer renderer = new ChannelListDialog.TopicRenderer();
        JTable table = new JTable(new ChannelListTableModel());
        renderer.getTableCellRendererComponent(table, value, false, false, 0, 2);
        return renderer.getToolTipText();
    }

    @Test
    public void tooltipCarriesTheWholeTopic() {
        String longTopic = "Ask about quest help here, and read the pinned guide before posting - "
                + "we answer faster when you say which quest and which step you are stuck on.";
        assertEquals(longTopic, tooltipFor(longTopic));
    }

    @Test
    public void shortTopicsGetATooltipToo() {
        assertEquals("General chatter", tooltipFor("General chatter"));
    }

    /** An empty tooltip still pops an empty box open on hover, so an empty topic gets none. */
    @Test
    public void emptyTopicHasNoTooltip() {
        assertNull(tooltipFor(""));
    }

    @Test
    public void nullValueHasNoTooltip() {
        assertNull(tooltipFor(null));
    }

    /** A row reused for a different channel must not keep the previous row's tooltip. */
    @Test
    public void tooltipIsReplacedWhenTheRendererIsReused() {
        ChannelListDialog.TopicRenderer renderer = new ChannelListDialog.TopicRenderer();
        JTable table = new JTable(new ChannelListTableModel());

        renderer.getTableCellRendererComponent(table, "first topic", false, false, 0, 2);
        renderer.getTableCellRendererComponent(table, "second topic", false, false, 1, 2);
        assertEquals("second topic", renderer.getToolTipText());

        renderer.getTableCellRendererComponent(table, "", false, false, 2, 2);
        assertNull("an empty topic must clear the stale tooltip", renderer.getToolTipText());
    }

    /**
     * A correct renderer nobody installed is worth nothing, and the tests above would not notice.
     *
     * The dialog is a Window, so this can only run where one can be created; JUnit reports it as
     * skipped rather than passed elsewhere, which is the honest outcome - a silent early return
     * would look like coverage that is not there.
     */
    @Test
    public void theTopicColumnIsWiredToTheRenderer() throws Exception {
        assumeFalse("needs a display to construct the dialog", GraphicsEnvironment.isHeadless());

        ChannelListDialog dialog = new ChannelListDialog(null, null, null);
        try {
            Field tableField = ChannelListDialog.class.getDeclaredField("table");
            tableField.setAccessible(true);
            JTable table = (JTable) tableField.get(dialog);

            assertTrue("the Topic column must use the tooltip renderer",
                    table.getColumnModel().getColumn(2).getCellRenderer()
                            instanceof ChannelListDialog.TopicRenderer);
            assertNull("the other columns keep the default renderer",
                    table.getColumnModel().getColumn(0).getCellRenderer());
        } finally {
            dialog.dispose();
        }
    }
}

package com.irc;

import org.junit.Test;

import java.util.Arrays;
import java.util.Collections;
import java.util.List;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

/**
 * The channel browser's data layer, kept out of the JDialog so it is testable without a Window.
 *
 * The Users column must report Integer.class: that is the single thing that makes TableRowSorter
 * sort it numerically rather than lexically, and lexical order would rank 9 above 412 - the exact
 * question a channel browser exists to answer. Topics arrive with IRC colour codes in them and are
 * stripped for display, so the filter has to match what the user can actually see.
 */
public class ChannelListTableModelTest {

    private static final String COLOR = String.valueOf((char) 0x03);

    private static List<ChannelListEntry> sample() {
        return Arrays.asList(
                new ChannelListEntry("#help", 412, "Get help here"),
                new ChannelListEntry("#chat", 380, "General chatter"),
                new ChannelListEntry("#quest", 9, "Quest guides and help"));
    }

    private static ChannelListTableModel modelWith(List<ChannelListEntry> entries) {
        ChannelListTableModel model = new ChannelListTableModel();
        model.setEntries(entries);
        return model;
    }

    /** The whole reason the browser is usable: 412 must outrank 9. */
    @Test
    public void usersColumnIsIntegerSoItSortsNumerically() {
        ChannelListTableModel model = modelWith(sample());
        assertEquals(Integer.class, model.getColumnClass(1));
        assertEquals(String.class, model.getColumnClass(0));
        assertEquals(String.class, model.getColumnClass(2));
    }

    @Test
    public void exposesThreeColumnsInOrder() {
        ChannelListTableModel model = modelWith(sample());
        assertEquals(3, model.getColumnCount());
        assertEquals("Channel", model.getColumnName(0));
        assertEquals("Users", model.getColumnName(1));
        assertEquals("Topic", model.getColumnName(2));
    }

    @Test
    public void rowsExposeNameCountAndTopic() {
        ChannelListTableModel model = modelWith(sample());
        assertEquals(3, model.getRowCount());
        assertEquals("#help", model.getValueAt(0, 0));
        assertEquals(412, model.getValueAt(0, 1));
        assertEquals("Get help here", model.getValueAt(0, 2));
    }

    @Test
    public void stripsFormattingCodesFromDisplayedTopics() {
        ChannelListTableModel model = modelWith(Collections.singletonList(
                new ChannelListEntry("#styled", 3, COLOR + "04,5Bright" + COLOR + " topic")));
        assertEquals("Bright topic", model.getValueAt(0, 2));
    }

    @Test
    public void filterMatchesChannelName() {
        ChannelListTableModel model = modelWith(sample());
        model.setFilter("quest");
        assertEquals(1, model.getRowCount());
        assertEquals("#quest", model.getValueAt(0, 0));
    }

    @Test
    public void filterMatchesTopicText() {
        ChannelListTableModel model = modelWith(sample());
        model.setFilter("chatter");
        assertEquals(1, model.getRowCount());
        assertEquals("#chat", model.getValueAt(0, 0));
    }

    @Test
    public void filterIsCaseInsensitive() {
        ChannelListTableModel model = modelWith(sample());
        model.setFilter("QUEST");
        assertEquals(1, model.getRowCount());
    }

    @Test
    public void emptyFilterShowsEverything() {
        ChannelListTableModel model = modelWith(sample());
        model.setFilter("quest");
        model.setFilter("");
        assertEquals(3, model.getRowCount());
    }

    /** A filter typed against a styled topic must match the stripped text the user sees. */
    @Test
    public void filterMatchesStrippedTopicNotRawCodes() {
        // The needle straddles the code: "Br" + code + "ight" is not a contiguous "Bright" in the
        // raw text, only in the stripped text. A fixture where the code sits wholly before or
        // after the needle would pass even if the filter searched the raw string.
        ChannelListTableModel model = modelWith(Collections.singletonList(
                new ChannelListEntry("#styled", 3, "Br" + COLOR + "04" + "ight topic")));
        model.setFilter("Bright");
        assertEquals(1, model.getRowCount());
    }

    @Test
    public void reportsTotalAndShownCounts() {
        ChannelListTableModel model = modelWith(sample());
        assertEquals(3, model.getTotalCount());
        assertEquals(3, model.getShownCount());

        model.setFilter("quest");
        assertEquals(3, model.getTotalCount());
        assertEquals(1, model.getShownCount());
    }

    /** Joining acts on the entry behind a row, so the mapping must survive filtering. */
    @Test
    public void getEntryAtTracksTheFilteredView() {
        ChannelListTableModel model = modelWith(sample());
        model.setFilter("quest");
        assertEquals("#quest", model.getEntryAt(0).getName());
    }

    @Test
    public void replacingEntriesReappliesTheActiveFilter() {
        ChannelListTableModel model = modelWith(sample());
        model.setFilter("quest");
        assertEquals(1, model.getRowCount());

        model.setEntries(Arrays.asList(
                new ChannelListEntry("#questing", 5, "more quests"),
                new ChannelListEntry("#other", 5, "unrelated")));
        assertEquals(1, model.getRowCount());
        assertEquals("#questing", model.getValueAt(0, 0));
    }

    @Test
    public void handlesEmptyResults() {
        ChannelListTableModel model = modelWith(Collections.emptyList());
        assertEquals(0, model.getRowCount());
        assertEquals(0, model.getTotalCount());
    }

    @Test
    public void matchesPredicateHandlesNullAndBlankFilters() {
        ChannelListEntry entry = new ChannelListEntry("#help", 1, "topic");
        assertTrue(ChannelListTableModel.matches(entry, null));
        assertTrue(ChannelListTableModel.matches(entry, ""));
        assertTrue(ChannelListTableModel.matches(entry, "   "));
        assertFalse(ChannelListTableModel.matches(entry, "nomatch"));
    }

    @Test
    public void toleratesNullTopics() {
        ChannelListTableModel model = modelWith(Collections.singletonList(
                new ChannelListEntry("#notopic", 2, null)));
        assertEquals("", model.getValueAt(0, 2));
        model.setFilter("notopic");
        assertEquals(1, model.getRowCount());
    }

    /**
     * Whole-branch review finding: the class doc claimed topics were stripped "once, up front" and
     * they were not - stripCodes ran on every getValueAt and on every entry inside applyFilter, so
     * a filter keystroke was one regex pass per row. At the 20,000-row cap that is 20,000 regex
     * passes per character typed, on the EDT.
     *
     * Identity is the observable consequence of the fix: stripCodes goes through
     * Matcher.replaceAll, which allocates a new String whenever it actually removes something, so
     * a topic that contains codes can only yield the same instance twice if it was computed once
     * and kept. A topic with no codes would pass either way (replaceAll returns the input), hence
     * the deliberately styled fixture.
     */
    @Test
    public void strippedTopicsAreComputedOncePerEntry() {
        ChannelListTableModel model = modelWith(Collections.singletonList(
                new ChannelListEntry("#styled", 3, COLOR + "04Bright" + COLOR + " topic")));

        Object first = model.getValueAt(0, 2);
        assertEquals("Bright topic", first);
        assertSame("repainting a cell must not re-run the stripper", first, model.getValueAt(0, 2));
    }

    /** Filtering must reuse the precomputed rows rather than rebuild them per keystroke. */
    @Test
    public void filteringDoesNotRecomputeStrippedTopics() {
        ChannelListTableModel model = modelWith(Collections.singletonList(
                new ChannelListEntry("#styled", 3, COLOR + "04Bright" + COLOR + " topic")));
        Object before = model.getValueAt(0, 2);

        model.setFilter("bright");
        model.setFilter("br");
        model.setFilter("");

        assertEquals(1, model.getRowCount());
        assertSame("each keystroke must reuse the row stripped when the entries were set",
                before, model.getValueAt(0, 2));
    }

    /** Replacing the entries must restrip: the new rows are different objects entirely. */
    @Test
    public void replacingEntriesRestripsTheNewTopics() {
        ChannelListTableModel model = modelWith(Collections.singletonList(
                new ChannelListEntry("#one", 1, COLOR + "04first")));
        assertEquals("first", model.getValueAt(0, 2));

        model.setEntries(Collections.singletonList(
                new ChannelListEntry("#two", 2, COLOR + "04second")));
        assertEquals("second", model.getValueAt(0, 2));
    }
}

package com.irc;

import org.junit.Before;
import org.junit.Test;

import javax.swing.*;
import java.awt.event.FocusEvent;
import java.awt.event.KeyEvent;
import java.awt.event.KeyListener;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

import static org.junit.Assert.*;

public class ChannelNumberKeysTest {
    private final JPanel root = new JPanel();
    private final JTextField input = new JTextField();
    private final JTextField outside = new JTextField();
    private final List<Integer> jumps = new ArrayList<>();
    private int markAllReads;
    private final List<String> navigations = new ArrayList<>();
    private ChannelNumberKeys keys;

    @Before
    public void setUp() {
        root.add(input);
        keys = new ChannelNumberKeys(root, jumps::add, () -> markAllReads++,
                () -> navigations.add("last"), () -> navigations.add("back"), () -> navigations.add("forward"),
                delta -> navigations.add("step " + delta));
        keys.install();
    }

    @Test
    public void altDigitJumpsAndSwallowsItsTypedCharacter() {
        assertTrue(press(input, KeyEvent.VK_3, KeyEvent.ALT_DOWN_MASK));
        assertTrue(type(input, '3', KeyEvent.ALT_DOWN_MASK));
        assertEquals(Collections.singletonList(3), jumps);

        assertFalse(press(input, KeyEvent.VK_A, 0));
        assertFalse(type(input, 'a', 0));
    }

    @Test
    public void altZeroJumpsToTheTenth() {
        assertTrue(press(input, KeyEvent.VK_0, KeyEvent.ALT_DOWN_MASK));
        assertTrue(type(input, '0', KeyEvent.ALT_DOWN_MASK));
        assertEquals(Collections.singletonList(10), jumps);
    }

    @Test
    public void altJThenTwoDigitsJumpsToThatNumber() {
        assertTrue(press(input, KeyEvent.VK_J, KeyEvent.ALT_DOWN_MASK));
        assertTrue(type(input, 'j', KeyEvent.ALT_DOWN_MASK));
        assertFalse(press(input, KeyEvent.VK_ALT, 0));
        assertTrue(press(input, KeyEvent.VK_1, 0));
        assertTrue(type(input, '1', 0));
        assertTrue(jumps.isEmpty());
        assertTrue(press(input, KeyEvent.VK_NUMPAD0, 0));
        assertTrue(type(input, '0', 0));
        assertEquals(Collections.singletonList(10), jumps);

        // The jump is over, so digits type normally again.
        assertFalse(press(input, KeyEvent.VK_5, 0));
        assertFalse(type(input, '5', 0));
    }

    @Test
    public void digitsHeldWithAltCountTowardsAPendingJump() {
        press(input, KeyEvent.VK_J, KeyEvent.ALT_DOWN_MASK);
        press(input, KeyEvent.VK_1, KeyEvent.ALT_DOWN_MASK);
        press(input, KeyEvent.VK_2, KeyEvent.ALT_DOWN_MASK);
        assertEquals(Collections.singletonList(12), jumps);
    }

    @Test
    public void otherKeysCancelAPendingJump() {
        press(input, KeyEvent.VK_J, KeyEvent.ALT_DOWN_MASK);
        assertTrue(press(input, KeyEvent.VK_ESCAPE, 0));
        assertFalse(press(input, KeyEvent.VK_1, 0));

        press(input, KeyEvent.VK_J, KeyEvent.ALT_DOWN_MASK);
        press(input, KeyEvent.VK_1, 0);
        assertFalse(press(input, KeyEvent.VK_X, 0));
        assertFalse(type(input, 'x', 0));
        assertFalse(press(input, KeyEvent.VK_2, 0));
        assertTrue(jumps.isEmpty());
    }

    @Test
    public void ignoresKeysOutsideThePanelAndAltGr() {
        assertFalse(press(outside, KeyEvent.VK_1, KeyEvent.ALT_DOWN_MASK));
        assertFalse(press(input, KeyEvent.VK_1, KeyEvent.ALT_DOWN_MASK | KeyEvent.CTRL_DOWN_MASK));
        assertFalse(press(input, KeyEvent.VK_1, KeyEvent.ALT_GRAPH_DOWN_MASK));
        assertTrue(jumps.isEmpty());
    }

    @Test
    public void losingFocusCancelsAPendingJump() {
        press(input, KeyEvent.VK_J, KeyEvent.ALT_DOWN_MASK);
        for (java.awt.event.FocusListener listener : input.getFocusListeners()) {
            listener.focusLost(new FocusEvent(input, FocusEvent.FOCUS_LOST, false, outside));
        }
        assertFalse(press(input, KeyEvent.VK_1, 0));
        assertFalse(press(input, KeyEvent.VK_2, 0));
        assertTrue(jumps.isEmpty());
    }

    @Test
    public void followsComponentsAddedAndRemovedAfterInstall() {
        JPanel tab = new JPanel();
        JTextField later = new JTextField();
        tab.add(later);
        root.add(tab);
        assertTrue(press(later, KeyEvent.VK_2, KeyEvent.ALT_DOWN_MASK));
        assertEquals(Collections.singletonList(2), jumps);

        root.remove(tab);
        assertFalse(press(later, KeyEvent.VK_2, KeyEvent.ALT_DOWN_MASK));
        root.add(tab);
        assertEquals(1, later.getKeyListeners().length);

        keys.uninstall();
        assertFalse(press(input, KeyEvent.VK_3, KeyEvent.ALT_DOWN_MASK));
        assertEquals(Collections.singletonList(2), jumps);
    }

    @Test
    public void altHMarksEverythingReadAndSwallowsItsTypedCharacter() {
        assertTrue(press(input, KeyEvent.VK_H, KeyEvent.ALT_DOWN_MASK));
        assertTrue(type(input, 'h', KeyEvent.ALT_DOWN_MASK));
        assertEquals(1, markAllReads);
        assertTrue(jumps.isEmpty());
    }

    @Test
    public void plainHAndAltGrHStillType() {
        assertFalse(press(input, KeyEvent.VK_H, 0));
        assertFalse(type(input, 'h', 0));
        assertFalse(press(input, KeyEvent.VK_H, KeyEvent.ALT_DOWN_MASK | KeyEvent.CTRL_DOWN_MASK));
        assertFalse(press(input, KeyEvent.VK_H, KeyEvent.ALT_GRAPH_DOWN_MASK));
        assertEquals(0, markAllReads);
    }

    @Test
    public void altHCancelsAPendingJump() {
        press(input, KeyEvent.VK_J, KeyEvent.ALT_DOWN_MASK);
        assertTrue(press(input, KeyEvent.VK_H, KeyEvent.ALT_DOWN_MASK));
        assertEquals(1, markAllReads);
        assertFalse("the jump is over, so digits type again", press(input, KeyEvent.VK_1, 0));
        assertTrue(jumps.isEmpty());
    }

    @Test
    public void altSlashGoesToTheLastBufferAndSwallowsItsTypedCharacter() {
        assertTrue(press(input, KeyEvent.VK_SLASH, KeyEvent.ALT_DOWN_MASK));
        assertTrue(type(input, '/', KeyEvent.ALT_DOWN_MASK));
        assertTrue(press(input, KeyEvent.VK_DIVIDE, KeyEvent.ALT_DOWN_MASK));
        assertEquals(java.util.Arrays.asList("last", "last"), navigations);

        assertFalse("a plain slash still starts a command", press(input, KeyEvent.VK_SLASH, 0));
        assertFalse(type(input, '/', 0));
    }

    @Test
    public void altLessAndGreaterWalkTheBufferHistoryAndSwallowTheirCharacters() {
        int altShift = KeyEvent.ALT_DOWN_MASK | KeyEvent.SHIFT_DOWN_MASK;
        assertTrue("US: Shift+comma", press(input, KeyEvent.VK_COMMA, altShift));
        assertTrue(type(input, '<', altShift));
        assertTrue("US: Shift+period", press(input, KeyEvent.VK_PERIOD, altShift));
        assertTrue(type(input, '>', altShift));
        assertTrue("European: the < key", press(input, KeyEvent.VK_LESS, KeyEvent.ALT_DOWN_MASK));
        assertTrue("European: Shift+<", press(input, KeyEvent.VK_LESS, altShift));
        assertTrue("going by the char", press(input, KeyEvent.VK_UNDEFINED, '<', KeyEvent.ALT_DOWN_MASK));
        assertEquals(java.util.Arrays.asList("back", "forward", "back", "forward", "back"), navigations);

        assertTrue("Alt+, aliases Alt+<", press(input, KeyEvent.VK_COMMA, KeyEvent.ALT_DOWN_MASK));
        assertTrue(type(input, ',', KeyEvent.ALT_DOWN_MASK));
        assertTrue("Alt+. aliases Alt+>", press(input, KeyEvent.VK_PERIOD, KeyEvent.ALT_DOWN_MASK));
        assertTrue(type(input, '.', KeyEvent.ALT_DOWN_MASK));
        assertEquals(7, navigations.size());
        assertEquals("back", navigations.get(5));
        assertEquals("forward", navigations.get(6));

        assertFalse("a plain comma still types", press(input, KeyEvent.VK_COMMA, 0));
        assertFalse("Alt+arrows are left to the text field", press(input, KeyEvent.VK_LEFT, KeyEvent.ALT_DOWN_MASK));
        assertFalse("a plain < still types", press(input, KeyEvent.VK_COMMA, KeyEvent.SHIFT_DOWN_MASK));
        assertFalse(type(input, '<', KeyEvent.SHIFT_DOWN_MASK));
        assertEquals(7, navigations.size());
    }

    @Test
    public void altUpAndDownStepThroughTheBuffers() {
        assertTrue(press(input, KeyEvent.VK_UP, KeyEvent.ALT_DOWN_MASK));
        assertTrue(press(input, KeyEvent.VK_DOWN, KeyEvent.ALT_DOWN_MASK));
        assertTrue(press(input, KeyEvent.VK_KP_DOWN, KeyEvent.ALT_DOWN_MASK));
        assertEquals(java.util.Arrays.asList("step -1", "step 1", "step 1"), navigations);

        assertFalse("plain Up still recalls input history", press(input, KeyEvent.VK_UP, 0));
        assertFalse(press(input, KeyEvent.VK_DOWN, KeyEvent.CTRL_DOWN_MASK | KeyEvent.ALT_DOWN_MASK));
        assertFalse("nothing to swallow after an arrow", type(input, 'x', 0));
        assertEquals(3, navigations.size());
    }

    private boolean press(JComponent source, int code, int mods) {
        return press(source, code, KeyEvent.CHAR_UNDEFINED, mods);
    }

    private boolean press(JComponent source, int code, char c, int mods) {
        return fire(source, new KeyEvent(source, KeyEvent.KEY_PRESSED, 0, mods, code, c));
    }

    private boolean type(JComponent source, char c, int mods) {
        return fire(source, new KeyEvent(source, KeyEvent.KEY_TYPED, 0, mods, KeyEvent.VK_UNDEFINED, c));
    }

    /** Delivers the event to the component's listeners, as Swing would; true when one consumed it. */
    private static boolean fire(JComponent source, KeyEvent e) {
        for (KeyListener listener : source.getKeyListeners()) {
            if (e.getID() == KeyEvent.KEY_PRESSED) listener.keyPressed(e);
            else if (e.getID() == KeyEvent.KEY_TYPED) listener.keyTyped(e);
        }
        return e.isConsumed();
    }
}

package com.irc;

import org.junit.Before;
import org.junit.Test;

import java.util.Arrays;
import java.util.Collections;
import java.util.List;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * Per-channel roster of who is present and what membership modes they hold.
 *
 * Fed by NAMES (353/366), JOIN, PART, QUIT, KICK, NICK and MODE. The interesting cases are
 * parameter alignment in compound MODE strings, NAMES replacing rather than merging, and
 * QUIT/NICK reporting which channels they touched so only those get redrawn.
 */
public class ChannelUserListTest {

    private ChannelUserList users;

    @Before
    public void setUp() {
        users = new ChannelUserList(ModeSpec.defaults());
    }

    /** Loads a roster the way the protocol does: one or more 353 lines, then a 366. */
    private void names(String channel, String... rawEntries) {
        users.addNames(channel, Arrays.asList(rawEntries));
        users.endNames(channel);
    }

    private List<String> nicks(String channel) {
        List<String> result = new java.util.ArrayList<>();
        for (ChannelUserList.Entry entry : users.snapshot(channel)) {
            result.add(entry.getPrefix() + entry.getNick());
        }
        return result;
    }

    @Test
    public void prefixOfReturnsTheHighestPrefixCaseInsensitively() {
        names("#Chan", "@+bob", "+dave", "erin");
        assertEquals("@", users.prefixOf("#chan", "BOB"));
        assertEquals("+", users.prefixOf("#chan", "dave"));
        assertEquals("", users.prefixOf("#chan", "erin"));
    }

    @Test
    public void prefixOfIsEmptyForUnknownNicksAndChannels() {
        names("#chan", "@bob");
        assertEquals("", users.prefixOf("#chan", "nobody"));
        assertEquals("", users.prefixOf("#other", "bob"));
        assertEquals("", users.prefixOf("bob", "bob"));
    }

    @Test
    public void namesPopulatesUsersAndTheirPrefixes() {
        names("#chan", "@bob", "+dave", "erin");
        assertEquals(Arrays.asList("@bob", "+dave", "erin"), nicks("#chan"));
    }

    @Test
    public void namesHandlesMultiplePrefixesAndShowsTheHighest() {
        names("#chan", "@+bob");
        assertEquals(Collections.singletonList("@bob"), nicks("#chan"));
    }

    @Test
    public void multiplePrefixesAreAllRetainedSoRevokingOneLeavesTheOther() {
        names("#chan", "@+bob");
        users.applyModeChange("#chan", Arrays.asList("-o", "bob"));
        assertEquals("voice survives losing op", Collections.singletonList("+bob"), nicks("#chan"));
    }

    @Test
    public void namesAcrossMultipleLinesAccumulateBeforeTheCommit() {
        users.addNames("#chan", Arrays.asList("@bob", "+dave"));
        users.addNames("#chan", Collections.singletonList("erin"));
        users.endNames("#chan");
        assertEquals(Arrays.asList("@bob", "+dave", "erin"), nicks("#chan"));
    }

    @Test
    public void aSecondNamesRoundReplacesRatherThanMerges() {
        names("#chan", "@bob", "+dave", "erin");
        names("#chan", "@bob");
        assertEquals("stale users are dropped", Collections.singletonList("@bob"), nicks("#chan"));
    }

    @Test
    public void endNamesWithoutPendingIsANoOp() {
        names("#chan", "@bob");
        users.endNames("#chan");
        assertEquals(Collections.singletonList("@bob"), nicks("#chan"));
    }

    @Test
    public void joinAddsAnUnprivilegedUser() {
        names("#chan", "@bob");
        users.join("#chan", "erin");
        assertEquals(Arrays.asList("@bob", "erin"), nicks("#chan"));
    }

    @Test
    public void partRemovesTheUser() {
        names("#chan", "@bob", "erin");
        users.part("#chan", "erin");
        assertEquals(Collections.singletonList("@bob"), nicks("#chan"));
    }

    @Test
    public void kickRemovesTheUser() {
        names("#chan", "@bob", "erin");
        users.kick("#chan", "erin");
        assertEquals(Collections.singletonList("@bob"), nicks("#chan"));
    }

    @Test
    public void quitRemovesTheUserFromEveryChannelAndReportsWhich() {
        names("#one", "erin", "bob");
        names("#two", "erin");
        names("#three", "bob");

        List<String> affected = users.quit("erin");

        assertEquals(2, affected.size());
        assertTrue(affected.contains("#one"));
        assertTrue(affected.contains("#two"));
        assertEquals(Collections.singletonList("bob"), nicks("#one"));
        assertEquals(Collections.emptyList(), nicks("#two"));
    }

    @Test
    public void renameKeepsModesAndReportsAffectedChannels() {
        names("#one", "@bob");
        names("#two", "+bob");

        List<String> affected = users.rename("bob", "robert");

        assertEquals(2, affected.size());
        assertEquals(Collections.singletonList("@robert"), nicks("#one"));
        assertEquals(Collections.singletonList("+robert"), nicks("#two"));
    }

    @Test
    public void quitReturnsTheChannelUsingTheServersCasing() {
        // Callers match these against UI state that compares case-sensitively, so the server's
        // casing must survive the lowercased internal key.
        names("#One", "erin");
        assertEquals(Collections.singletonList("#One"), users.quit("erin"));
    }

    @Test
    public void renameReturnsTheChannelUsingTheServersCasing() {
        names("#One", "bob");
        assertEquals(Collections.singletonList("#One"), users.rename("bob", "robert"));
    }

    @Test
    public void channelLookupIsCaseInsensitive() {
        names("#One", "@bob");
        assertEquals(Collections.singletonList("@bob"), nicks("#one"));
    }

    @Test
    public void modeGrantsOp() {
        names("#chan", "bob");
        users.applyModeChange("#chan", Arrays.asList("+o", "bob"));
        assertEquals(Collections.singletonList("@bob"), nicks("#chan"));
    }

    @Test
    public void modeRevokesVoice() {
        names("#chan", "+bob");
        users.applyModeChange("#chan", Arrays.asList("-v", "bob"));
        assertEquals(Collections.singletonList("bob"), nicks("#chan"));
    }

    @Test
    public void compoundModeSkipsTheParameterlessLetter() {
        // The regression this whole design exists to prevent: "m" takes no parameter, so "bob"
        // belongs to "o". Getting this wrong ops nobody, or the wrong person.
        names("#chan", "bob");
        users.applyModeChange("#chan", Arrays.asList("+mo", "bob"));
        assertEquals(Collections.singletonList("@bob"), nicks("#chan"));
    }

    @Test
    public void mixedSignModeAppliesEachLetterToItsOwnParameter() {
        names("#chan", "bob", "+carol");
        users.applyModeChange("#chan", Arrays.asList("+o-v", "bob", "carol"));
        assertEquals(Arrays.asList("@bob", "carol"), nicks("#chan"));
    }

    @Test
    public void removingATypeCModeConsumesNoParameter() {
        // "l" (limit) takes a parameter when set but not when removed, so the lone parameter
        // "bob" belongs to "+o". An implementation that wrongly consumed one for "-l" would
        // leave "+o" with nothing and fail to op anyone.
        names("#chan", "bob");
        users.applyModeChange("#chan", Arrays.asList("-l+o", "bob"));
        assertEquals(Collections.singletonList("@bob"), nicks("#chan"));
    }

    @Test
    public void settingATypeBModeConsumesItsParameter() {
        // "k" (key) always takes a parameter, so "secret" is the key and "bob" belongs to "o".
        names("#chan", "bob");
        users.applyModeChange("#chan", Arrays.asList("+ko", "secret", "bob"));
        assertEquals(Collections.singletonList("@bob"), nicks("#chan"));
    }

    @Test
    public void modeTargetingAnUnknownNickIsIgnored() {
        names("#chan", "bob");
        users.applyModeChange("#chan", Arrays.asList("+o", "nosuchuser"));
        assertEquals(Collections.singletonList("bob"), nicks("#chan"));
    }

    @Test
    public void modeWithMissingParametersDoesNotThrow() {
        names("#chan", "bob");
        users.applyModeChange("#chan", Collections.singletonList("+o"));
        assertEquals(Collections.singletonList("bob"), nicks("#chan"));
    }

    @Test
    public void modeOnAnUnknownChannelIsIgnored() {
        users.applyModeChange("#nosuchchannel", Arrays.asList("+o", "bob"));
        assertEquals(Collections.emptyList(), nicks("#nosuchchannel"));
    }

    @Test
    public void snapshotSortsByRankThenCaseInsensitiveAlphabetically() {
        names("#chan", "zoe", "@Bob", "+dave", "~founder", "Alice", "%carol");
        assertEquals(
                Arrays.asList("~founder", "@Bob", "%carol", "+dave", "Alice", "zoe"),
                nicks("#chan"));
    }

    @Test
    public void nickMatchingIsCaseInsensitiveButDisplayCasingIsKept() {
        names("#chan", "@Bob");
        users.applyModeChange("#chan", Arrays.asList("-o", "bob"));
        assertEquals(Collections.singletonList("Bob"), nicks("#chan"));
    }

    @Test
    public void snapshotIsImmutable() {
        names("#chan", "bob");
        List<ChannelUserList.Entry> snapshot = users.snapshot("#chan");
        try {
            snapshot.add(new ChannelUserList.Entry("evil", "", 0));
            org.junit.Assert.fail("snapshot must not be modifiable");
        } catch (UnsupportedOperationException expected) {
            // the EDT reads this while the socket thread mutates the source
        }
    }

    @Test
    public void snapshotOfAnUnknownChannelIsEmpty() {
        assertEquals(Collections.emptyList(), users.snapshot("#nope"));
    }

    @Test
    public void removeChannelDropsItsRoster() {
        names("#chan", "bob");
        users.removeChannel("#chan");
        assertEquals(Collections.emptyList(), users.snapshot("#chan"));
    }

    @Test
    public void clearDropsEverything() {
        names("#one", "bob");
        names("#two", "erin");
        users.clear();
        assertEquals(Collections.emptyList(), users.snapshot("#one"));
        assertEquals(Collections.emptyList(), users.snapshot("#two"));
    }

    // --- away ---

    private boolean awayIn(String channel, String nick) {
        for (ChannelUserList.Entry entry : users.snapshot(channel)) {
            if (entry.getNick().equalsIgnoreCase(nick)) {
                return entry.isAway();
            }
        }
        throw new AssertionError(nick + " is not in " + channel);
    }

    @Test
    public void awayShowsInEveryChannelTheNickIsIn() {
        names("#a", "bob", "carol");
        names("#b", "bob");
        List<String> affected = users.setAway("BOB", true);
        assertEquals(2, affected.size());
        assertTrue(awayIn("#a", "bob"));
        assertTrue(awayIn("#b", "bob"));
        assertEquals(false, awayIn("#a", "carol"));
    }

    @Test
    public void aRepeatedAwayChangesNothingAndRedrawsNothing() {
        names("#a", "bob");
        users.setAway("bob", true);
        assertTrue(users.setAway("bob", true).isEmpty());
        assertTrue(users.setAway("carol", false).isEmpty());
    }

    @Test
    public void comingBackClearsAway() {
        names("#a", "bob");
        users.setAway("bob", true);
        assertEquals(Collections.singletonList("#a"), users.setAway("bob", false));
        assertEquals(false, awayIn("#a", "bob"));
    }

    @Test
    public void awayFollowsANickChange() {
        names("#a", "bob");
        users.setAway("bob", true);
        users.rename("bob", "bobby");
        assertTrue(awayIn("#a", "bobby"));
        assertEquals(false, users.isAway("bob"));
    }

    @Test
    public void quitForgetsAway() {
        names("#a", "bob");
        users.setAway("bob", true);
        users.quit("bob");
        assertEquals(false, users.isAway("bob"));
    }

    @Test
    public void rejoiningStartsPresentUntilTheServerSaysOtherwise() {
        names("#a", "bob");
        users.setAway("bob", true);
        users.part("#a", "bob");
        users.join("#a", "bob");
        assertEquals(false, awayIn("#a", "bob"));
    }

    @Test
    public void leavingAChannelKeepsAwayForNicksStillSeenElsewhere() {
        names("#a", "bob", "carol");
        names("#b", "bob");
        users.setAway("bob", true);
        users.setAway("carol", true);
        users.removeChannel("#a");
        assertTrue(users.isAway("bob"));
        assertEquals(false, users.isAway("carol"));
    }
}

package com.irc;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

/**
 * Readline-style input history for the side-panel input box. Up walks back through recently
 * sent lines (stashing the unsent draft on the first press), Down walks forward and restores
 * the draft past the newest entry. Capacity-bounded; consecutive duplicates are collapsed.
 */
public class InputHistoryTest {

    @Test
    public void emptyHistoryReturnsNull() {
        InputHistory history = new InputHistory(20);
        assertNull(history.previous(""));
        assertNull(history.next());
    }

    @Test
    public void upFromLiveReturnsNewestEntry() {
        InputHistory history = new InputHistory(20);
        history.add("first");
        history.add("second");
        assertEquals("second", history.previous("draft"));
    }

    @Test
    public void repeatedUpWalksBackAndClampsAtOldest() {
        InputHistory history = new InputHistory(20);
        history.add("a");
        history.add("b");
        history.add("c");
        assertEquals("c", history.previous(""));
        assertEquals("b", history.previous(""));
        assertEquals("a", history.previous(""));
        assertEquals("a", history.previous("")); // clamped at oldest
    }

    @Test
    public void downWalksForwardAndRestoresStashedDraft() {
        InputHistory history = new InputHistory(20);
        history.add("a");
        history.add("b");
        assertEquals("b", history.previous("my draft"));
        assertEquals("a", history.previous("my draft"));
        assertEquals("b", history.next());
        assertEquals("my draft", history.next()); // past newest -> stashed draft restored
        assertNull(history.next());                // now live again
    }

    @Test
    public void downWithoutBrowsingReturnsNull() {
        InputHistory history = new InputHistory(20);
        history.add("a");
        assertNull(history.next());
    }

    @Test
    public void capacityDropsOldest() {
        InputHistory history = new InputHistory(2);
        history.add("a");
        history.add("b");
        history.add("c"); // "a" evicted
        assertEquals("c", history.previous(""));
        assertEquals("b", history.previous(""));
        assertEquals("b", history.previous("")); // "a" gone -> clamp at "b"
    }

    @Test
    public void skipsConsecutiveDuplicate() {
        InputHistory history = new InputHistory(20);
        history.add("same");
        history.add("same"); // collapsed
        assertEquals("same", history.previous(""));
        assertEquals("same", history.previous("")); // only one entry
    }

    @Test
    public void keepsNonConsecutiveDuplicate() {
        InputHistory history = new InputHistory(20);
        history.add("a");
        history.add("b");
        history.add("a"); // not consecutive -> kept
        assertEquals("a", history.previous(""));
        assertEquals("b", history.previous(""));
        assertEquals("a", history.previous(""));
    }

    @Test
    public void addResetsBrowsing() {
        InputHistory history = new InputHistory(20);
        history.add("a");
        history.add("b");
        assertEquals("b", history.previous("draft"));
        history.add("c");                       // sending resets browse state
        assertNull(history.next());             // no longer browsing
        assertEquals("c", history.previous("")); // fresh browse from newest
    }

    @Test
    public void ignoresBlankAndNullLines() {
        InputHistory history = new InputHistory(20);
        history.add("");
        history.add(null);
        assertNull(history.previous(""));
    }
}

package com.irc;

import org.junit.Test;

import javax.swing.JTabbedPane;
import javax.swing.SwingUtilities;
import javax.swing.Timer;
import java.lang.reflect.Field;
import java.util.ArrayList;
import java.util.List;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The adapter's LIST plumbing: turning a query into a wire command, and a completed reply into a
 * panel call.
 *
 * A bare /list must send "LIST" with no trailing space - some servers treat "LIST " as a filter
 * argument and return nothing.
 */
public class IrcAdapterListTest {

    /** Captures what the adapter puts on the wire. */
    private static class RecordingClient extends SimpleIrcClient {
        final List<String> sentLines = new ArrayList<>();

        @Override
        public synchronized void sendRawLine(String line) {
            sentLines.add(line);
        }
    }

    private static IrcAdapter adapterWith(RecordingClient client) throws Exception {
        IrcAdapter adapter = new IrcAdapter();
        java.lang.reflect.Field field = IrcAdapter.class.getDeclaredField("client");
        field.setAccessible(true);
        field.set(adapter, client);
        return adapter;
    }

    @Test
    public void bareListSendsNoTrailingSpace() throws Exception {
        RecordingClient client = new RecordingClient();
        IrcAdapter adapter = adapterWith(client);

        adapter.requestChannelList("");

        assertEquals(1, client.sentLines.size());
        assertEquals("LIST", client.sentLines.get(0));
    }

    @Test
    public void nullQueryIsTreatedAsBare() throws Exception {
        RecordingClient client = new RecordingClient();
        IrcAdapter adapter = adapterWith(client);

        adapter.requestChannelList(null);

        assertEquals("LIST", client.sentLines.get(0));
    }

    @Test
    public void argumentsArePassedThroughVerbatim() throws Exception {
        RecordingClient client = new RecordingClient();
        IrcAdapter adapter = adapterWith(client);

        adapter.requestChannelList(">50 *quest*");

        assertEquals("LIST >50 *quest*", client.sentLines.get(0));
    }

    @Test
    public void surroundingWhitespaceIsTrimmed() throws Exception {
        RecordingClient client = new RecordingClient();
        IrcAdapter adapter = adapterWith(client);

        adapter.requestChannelList("   >50   ");

        assertEquals("LIST >50", client.sentLines.get(0));
    }

    @Test
    public void reportsConnectionState() throws Exception {
        RecordingClient client = new RecordingClient();
        IrcAdapter adapter = adapterWith(client);

        assertTrue("a fresh client is not connected", !adapter.isConnected());
    }

    /**
     * Confirmed Task 2 review finding: a LIST run abandoned with no 323, no 263 and no
     * disconnect (the server truncates its reply but the connection survives) used to leave
     * channelListRunActive true, so the next LIST's rows appended onto the stale ones instead of
     * starting fresh. requestChannelList must reset the run before sending.
     *
     * Also covers a Task 6 review finding: the reset must NOT clear channelListSnapshot - the
     * dialog's currently displayed list has to survive until a new run actually completes, or
     * Refresh would blank it mid-flight.
     */
    @Test
    public void secondRequestDoesNotAppendToAnAbandonedRun() throws Exception {
        RecordingClient client = new RecordingClient();
        IrcAdapter adapter = adapterWith(client);

        // A prior LIST completed normally and published a snapshot the dialog is showing now.
        client.processLine(":server 322 me #old 3 :old topic");
        client.processLine(":server 323 me :End of /LIST");
        assertEquals("#old", client.getChannelListSnapshot().get(0).getName());

        // Second run starts but is abandoned - no 323 ever arrives.
        client.processLine(":server 322 me #stale 1 :stale topic");

        adapter.requestChannelList("");

        // Refresh must not blank the dialog mid-flight: the previous snapshot survives the reset,
        // even though the abandoned run's accumulator has just been cleared.
        List<ChannelListEntry> midFlight = client.getChannelListSnapshot();
        assertEquals(1, midFlight.size());
        assertEquals("#old", midFlight.get(0).getName());

        // Third run completes normally and replaces the snapshot; #stale never appears.
        client.processLine(":server 322 me #fresh 2 :fresh topic");
        client.processLine(":server 323 me :End of /LIST");

        List<ChannelListEntry> entries = client.getChannelListSnapshot();
        assertEquals(1, entries.size());
        assertEquals("#fresh", entries.get(0).getName());
    }

    private static IrcConfig stubConfig() {
        // IrcConfig only has two abstract methods; everything else is a default.
        return new IrcConfig() {
            @Override
            public String username() {
                return "mynick";
            }

            @Override
            public String password() {
                return "";
            }
        };
    }

    /** Same headless construction approach as IrcPanelChannelListTest. */
    private static IrcPanel headlessPanel() throws Exception {
        IrcPanel panel = new IrcPanel();
        Field configField = IrcPanel.class.getDeclaredField("config");
        configField.setAccessible(true);
        configField.set(panel, stubConfig());
        Field tabbedPaneField = IrcPanel.class.getDeclaredField("tabbedPane");
        tabbedPaneField.setAccessible(true);
        tabbedPaneField.set(panel, new JTabbedPane());
        panel.addChannel("System");
        panel.setFocusedChannel("System");
        return panel;
    }

    /**
     * Confirmed Task 5 review finding: the design invariant is that ANY outcome cancels the
     * pending 30s timeout, but previously only the success path (showChannelList) and the
     * explicit failure path (CHANNEL_LIST_FAILED) did. A disconnect while a timeout was armed
     * still fired a spurious "No channel list response from the server." message 30 seconds
     * later. The DISCONNECT case must cancel it too.
     */
    @Test
    public void disconnectCancelsThePendingChannelListTimeout() throws Exception {
        IrcPanel panel = headlessPanel();

        IrcAdapter adapter = new IrcAdapter();
        adapter.initialize(stubConfig(), message -> { }, panel, "mynick");
        SimpleIrcClient client = adapter.getClient();
        // Register so disconnect() (which requires `connected`) actually runs.
        client.processLine(":server 001 mynick :Welcome to IRC mynick!runelite@host");

        panel.armChannelListTimeout();

        adapter.disconnect();
        // Drain the EDT so the invokeLater posted by the DISCONNECT case has run before we assert.
        SwingUtilities.invokeAndWait(() -> { });

        Field timeoutField = IrcPanel.class.getDeclaredField("channelListTimeout");
        timeoutField.setAccessible(true);
        Timer timer = (Timer) timeoutField.get(panel);
        assertFalse("disconnect must cancel a pending channel list timeout", timer.isRunning());
    }

    /**
     * Records what the adapter delivers to the panel for a completed or failed LIST, without
     * needing a live Window - showChannelList's real implementation constructs a ChannelListDialog,
     * which throws HeadlessException on a headless machine. Same technique as RecordingClient
     * above: override the one method under test rather than exercise the real implementation.
     */
    private static class RecordingPanel extends IrcPanel {
        volatile List<ChannelListEntry> deliveredEntries;
        volatile String deliveredQuery;
        volatile Boolean deliveredTruncated;
        volatile boolean cancelCalled;

        @Override
        public void showChannelList(String networkId, List<ChannelListEntry> entries, String query, boolean truncated) {
            deliveredEntries = entries;
            deliveredQuery = query;
            deliveredTruncated = truncated;
        }

        @Override
        public void cancelChannelListTimeout() {
            cancelCalled = true;
        }
    }

    /**
     * Task 6 review finding: the task's headline deliverable - handing a completed LIST reply to
     * the panel - had no coverage. A mutation that disabled the CHANNEL_LIST branch entirely left
     * the full suite green. This pins the whole handoff: the right entries, the query that was in
     * flight, and the truncation flag all have to reach showChannelList.
     */
    @Test
    public void channelListDeliversTheSnapshotToThePanel() throws Exception {
        RecordingPanel panel = new RecordingPanel();
        IrcAdapter adapter = new IrcAdapter();
        adapter.initialize(stubConfig(), message -> { }, panel, "mynick");
        SimpleIrcClient client = adapter.getClient();

        adapter.requestChannelList(">50");
        client.processLine(":server 322 me #help 4 :Get help here");
        client.processLine(":server 323 me :End of /LIST");
        // CHANNEL_LIST hands off via invokeLater; drain the EDT before asserting.
        SwingUtilities.invokeAndWait(() -> { });

        assertEquals(1, panel.deliveredEntries.size());
        assertEquals("#help", panel.deliveredEntries.get(0).getName());
        assertEquals(">50", panel.deliveredQuery);
        assertEquals(Boolean.FALSE, panel.deliveredTruncated);
    }

    /**
     * Task 6 review finding, same gap for the failure path: CHANNEL_LIST_FAILED must also cancel
     * the panel's pending timeout, and nothing exercised that call either.
     */
    @Test
    public void channelListFailedCancelsThePendingTimeout() throws Exception {
        RecordingPanel panel = new RecordingPanel();
        IrcAdapter adapter = new IrcAdapter();
        adapter.initialize(stubConfig(), message -> { }, panel, "mynick");
        SimpleIrcClient client = adapter.getClient();

        client.processLine(":server 263 me LIST :Server load is too heavy, please try again later");
        SwingUtilities.invokeAndWait(() -> { });

        assertTrue("a failed channel list must cancel the pending timeout", panel.cancelCalled);
    }

    /**
     * Whole-branch review finding: the adapter held the panel forever, so a 323 that arrived while
     * the plugin was shutting down still drove showChannelList and popped the browser for a plugin
     * that no longer exists. shutDown() clears the reference before tearing the panel down.
     */
    @Test
    public void clearPanelStopsALateChannelListFromReachingTheUi() throws Exception {
        RecordingPanel panel = new RecordingPanel();
        IrcAdapter adapter = new IrcAdapter();
        adapter.initialize(stubConfig(), message -> { }, panel, "mynick");
        SimpleIrcClient client = adapter.getClient();

        // Sanity: without clearing, this delivery path is live.
        adapter.requestChannelList("");
        client.processLine(":server 322 me #before 4 :still wired up");
        client.processLine(":server 323 me :End of /LIST");
        SwingUtilities.invokeAndWait(() -> { });
        assertEquals(1, panel.deliveredEntries.size());

        adapter.clearPanel();

        adapter.requestChannelList("");
        client.processLine(":server 322 me #after 9 :arrived during shutdown");
        client.processLine(":server 323 me :End of /LIST");
        SwingUtilities.invokeAndWait(() -> { });

        assertEquals("a reply arriving after teardown must not reach the panel",
                "#before", panel.deliveredEntries.get(0).getName());
        assertEquals(1, panel.deliveredEntries.size());
    }

    /** The failure path holds the same reference and must respect the same teardown. */
    @Test
    public void clearPanelStopsALateFailureFromReachingTheUi() throws Exception {
        RecordingPanel panel = new RecordingPanel();
        IrcAdapter adapter = new IrcAdapter();
        adapter.initialize(stubConfig(), message -> { }, panel, "mynick");
        SimpleIrcClient client = adapter.getClient();

        adapter.clearPanel();
        client.processLine(":server 263 me LIST :Server load is too heavy, please try again later");
        SwingUtilities.invokeAndWait(() -> { });

        assertFalse("a 263 arriving after teardown must not touch the panel", panel.cancelCalled);
    }
}

package com.irc;

import org.junit.Test;

import javax.swing.JTabbedPane;
import javax.swing.SwingUtilities;
import java.lang.reflect.Field;
import java.time.Duration;
import java.time.Instant;
import java.util.ArrayList;
import java.util.List;

import static org.junit.Assert.*;

public class IrcAdapterNetworkTest {
    private static final String RIZON = "rizon-id";

    private static IrcConfig stubConfig() {
        return new IrcConfig() {
            @Override public String username() { return "me"; }
            @Override public String password() { return ""; }
        };
    }

    private static NetworkConfig rizon() {
        return NetworkConfig.builder().id(RIZON).name("Rizon").host("irc.rizon.net").port(6697).tls(true)
                .serverPassword("me/rizon:pw").build();
    }

    private static IrcMessage last(List<IrcMessage> messages, String content) {
        for (int i = messages.size() - 1; i >= 0; i--) {
            if (content.equals(messages.get(i).getContent())) return messages.get(i);
        }
        throw new AssertionError("no message " + content);
    }

    @Test
    public void usesTheNetworksAddressAndPassword() {
        IrcAdapter adapter = new IrcAdapter();
        adapter.initialize(stubConfig(), rizon(), m -> { }, null, "me");
        assertEquals("irc.rizon.net", adapter.getClient().getHost());
        assertEquals(6697, adapter.getClient().getPort());
        assertTrue(adapter.getClient().isSecure());
        assertEquals("me/rizon:pw", adapter.getClient().getServerPassword());
        assertEquals(RIZON, adapter.getNetworkId());
    }

    @Test
    public void messagesAreStampedWithTheNetwork() {
        List<IrcMessage> messages = new ArrayList<>();
        IrcAdapter adapter = new IrcAdapter();
        adapter.initialize(stubConfig(), rizon(), messages::add, null, "me");
        adapter.getClient().processLine(":Ash!u@h PRIVMSG #chan :hi");
        assertEquals(RIZON, last(messages, "hi").getNetworkId());
    }

    @Test
    public void legacyInitializeIsSwiftIrc() {
        List<IrcMessage> messages = new ArrayList<>();
        IrcAdapter adapter = new IrcAdapter();
        adapter.initialize(stubConfig(), messages::add, null, "me");
        adapter.getClient().processLine(":Ash!u@h PRIVMSG #chan :hi");
        assertEquals(NetworkConfig.SWIFTIRC_ID, last(messages, "hi").getNetworkId());
        assertEquals("fiery.swiftirc.net", adapter.getClient().getHost());
    }

    @Test
    public void linesTimestampedBeforeRegistrationAreHistory() {
        List<IrcMessage> messages = new ArrayList<>();
        IrcAdapter adapter = new IrcAdapter();
        adapter.initialize(stubConfig(), rizon(), messages::add, null, "me");
        adapter.getClient().processLine(":server 001 me :Welcome");
        Instant hourAgo = Instant.now().minus(Duration.ofHours(1));
        adapter.getClient().processLine("@time=" + hourAgo + " :Ash!u@h PRIVMSG #chan :old");
        adapter.getClient().processLine("@time=" + Instant.now() + " :Ash!u@h PRIVMSG #chan :new");
        IrcMessage old = last(messages, "old");
        assertEquals(IrcMessage.MessageType.HISTORY, old.getType());
        assertEquals(hourAgo, old.getTimestamp());
        assertEquals(IrcMessage.MessageType.CHAT, last(messages, "new").getType());
    }

    @Test
    public void liveTaggedLinesAreStampedWithOurClock() {
        List<IrcMessage> messages = new ArrayList<>();
        IrcAdapter adapter = new IrcAdapter();
        adapter.initialize(stubConfig(), rizon(), messages::add, null, "me");
        adapter.getClient().processLine(":server 001 me :Welcome");
        Instant serverClock = Instant.now().minus(Duration.ofSeconds(3));
        Instant before = Instant.now();
        adapter.getClient().processLine("@time=" + serverClock + " :Ash!u@h PRIVMSG #chan :live");
        adapter.getClient().processLine("@time=" + serverClock + " :Ash!u@h PRIVMSG #chan :\u0001ACTION waves\u0001");
        IrcMessage live = last(messages, "live");
        assertEquals(IrcMessage.MessageType.CHAT, live.getType());
        assertFalse(live.getTimestamp().isBefore(before));
        IrcMessage action = last(messages, "waves");
        assertEquals(IrcMessage.MessageType.CHAT, action.getType());
        assertFalse(action.getTimestamp().isBefore(before));
    }

    @Test
    public void unparseableTimeTagIsLive() {
        List<IrcMessage> messages = new ArrayList<>();
        IrcAdapter adapter = new IrcAdapter();
        adapter.initialize(stubConfig(), rizon(), messages::add, null, "me");
        adapter.getClient().processLine(":server 001 me :Welcome");
        Instant before = Instant.now();
        adapter.getClient().processLine("@time=yesterday :Ash!u@h PRIVMSG #chan :odd");
        IrcMessage odd = last(messages, "odd");
        assertEquals(IrcMessage.MessageType.CHAT, odd.getType());
        assertFalse(odd.getTimestamp().isBefore(before));
    }

    @Test
    public void futureTimeTagIsLiveAndStampedNow() {
        List<IrcMessage> messages = new ArrayList<>();
        IrcAdapter adapter = new IrcAdapter();
        adapter.initialize(stubConfig(), rizon(), messages::add, null, "me");
        adapter.getClient().processLine(":server 001 me :Welcome");
        Instant future = Instant.now().plus(Duration.ofHours(2));
        adapter.getClient().processLine("@time=" + future + " :Ash!u@h PRIVMSG #chan :skewed");
        IrcMessage skewed = last(messages, "skewed");
        assertEquals(IrcMessage.MessageType.CHAT, skewed.getType());
        assertTrue(skewed.getTimestamp().isBefore(future));
    }

    @Test
    public void ownLineFromAnotherClientLandsInTheQuery() {
        List<IrcMessage> messages = new ArrayList<>();
        IrcAdapter adapter = new IrcAdapter();
        adapter.initialize(stubConfig(), rizon(), messages::add, null, "me");
        adapter.getClient().processLine(":server 001 me :Welcome");
        adapter.getClient().processLine(":me!u@h PRIVMSG Luna :from my phone");
        IrcMessage line = last(messages, "from my phone");
        assertEquals("Luna", line.getChannel());
        assertEquals("me", line.getSender());
    }

    @Test
    public void nickChangeRenamesOnlyThisNetworksBuffer() throws Exception {
        IrcPanel panel = headlessPanel();
        panel.addChannel(BufferKey.swiftIrc("Luna"));
        panel.addChannel(BufferKey.of(RIZON, "Luna"));
        IrcAdapter adapter = new IrcAdapter();
        adapter.initialize(stubConfig(), rizon(), m -> { }, panel, "me");
        adapter.getClient().processLine(":Luna!u@h NICK Luna2");
        SwingUtilities.invokeAndWait(() -> { });
        assertTrue(panel.isPane(BufferKey.swiftIrc("Luna")));
        assertTrue(panel.isPane(BufferKey.of(RIZON, "Luna2")));
    }

    @Test
    public void privateMessageForAnotherNetworksBufferGoesToThisNetworksSystem() throws Exception {
        IrcPanel panel = headlessPanel();
        panel.addChannel("#rshelp");
        panel.setFocusedChannel("#rshelp");
        List<IrcMessage> messages = new ArrayList<>();
        IrcAdapter adapter = new IrcAdapter();
        adapter.initialize(stubConfig(), rizon(), messages::add, panel, "me");
        adapter.getClient().processLine(":Luna!u@h PRIVMSG me :psst");
        IrcMessage pm = last(messages, "psst");
        assertEquals("System", pm.getChannel());
        assertEquals(RIZON, pm.getNetworkId());
    }

    @Test
    public void detachedAdapterEmitsNothing() throws Exception {
        List<String> panelCalls = new ArrayList<>();
        IrcPanel panel = new IrcPanel() {
            @Override public void setNetworkConnected(String networkId, boolean connected) {
                panelCalls.add("connected " + connected);
            }
            @Override public void setChannelUsers(BufferKey channel, List<ChannelUserList.Entry> entries) {
                panelCalls.add("users " + channel.getName());
            }
        };
        List<IrcMessage> messages = new ArrayList<>();
        IrcAdapter adapter = new IrcAdapter();
        adapter.initialize(stubConfig(), rizon(), messages::add, panel, "me");
        adapter.getClient().processLine(":server 001 me :Welcome");
        adapter.getClient().processLine(":me!u@h JOIN #chan");
        markConnected(adapter.getClient());
        SwingUtilities.invokeAndWait(() -> { });
        messages.clear();
        panelCalls.clear();

        adapter.detach();
        adapter.getClient().processLine(":Ash!u@h PRIVMSG #chan :late");
        adapter.disconnect("Reloading, brb");
        SwingUtilities.invokeAndWait(() -> { });

        assertTrue(messages.toString(), messages.isEmpty());
        assertTrue(panelCalls.toString(), panelCalls.isEmpty());
    }

    private static void markConnected(SimpleIrcClient client) throws Exception {
        Field connected = SimpleIrcClient.class.getDeclaredField("connected");
        connected.setAccessible(true);
        connected.set(client, true);
    }

    private static IrcPanel headlessPanel() throws Exception {
        IrcPanel panel = new IrcPanel();
        Field config = IrcPanel.class.getDeclaredField("config");
        config.setAccessible(true);
        config.set(panel, stubConfig());
        Field tabs = IrcPanel.class.getDeclaredField("tabbedPane");
        tabs.setAccessible(true);
        tabs.set(panel, new JTabbedPane());
        panel.addChannel("System");
        panel.setFocusedChannel("System");
        return panel;
    }
}

package com.irc;

import org.junit.Test;

import static org.junit.Assert.assertEquals;

/**
 * Guards the contract that IrcPlugin relies on for /umode: the nick reported by the
 * adapter must follow the network's confirmed nick, i.e. it is driven by the raw NICK
 * event rather than an optimistic local guess. Previously IrcPlugin kept its own copy
 * of the nick that was set once at connect and never updated, so /nick desynced it from
 * the network.
 */
public class IrcAdapterNickTest {

    private static IrcConfig stubConfig() {
        // IrcConfig only has two abstract methods; everything else is a default.
        return new IrcConfig() {
            @Override
            public String username() {
                return "mynick";
            }

            @Override
            public String password() {
                return "";
            }
        };
    }

    @Test
    public void getNickFollowsRawNickEvent() {
        IrcAdapter adapter = new IrcAdapter();
        adapter.initialize(stubConfig(), message -> {}, null, "mynick");

        assertEquals("mynick", adapter.getNick());

        // The server echoes our own nick change back to us. The adapter must adopt the
        // new nick from this raw NICK line, not from any optimistic local update.
        adapter.getClient().processLine(":mynick!runelite@host NICK newnick");

        assertEquals("newnick", adapter.getNick());
    }

    @Test
    public void getNickIgnoresOtherUsersNickChanges() {
        IrcAdapter adapter = new IrcAdapter();
        adapter.initialize(stubConfig(), message -> {}, null, "mynick");

        // Someone else changing their nick must not move our own nick.
        adapter.getClient().processLine(":someoneelse!u@host NICK othernew");

        assertEquals("mynick", adapter.getNick());
    }

    @Test
    public void nickTakenDuringRegistrationAdoptsServerAssignedNick() {
        IrcAdapter adapter = new IrcAdapter();
        adapter.initialize(stubConfig(), message -> {}, null, "mynick");
        SimpleIrcClient client = adapter.getClient();

        // Server rejects our requested nick (433 ERR_NICKNAMEINUSE) ...
        client.processLine(":server 433 * mynick :Nickname is already in use");
        // ... we retry and the server welcomes us as mynick_ (001 RPL_WELCOME).
        client.processLine(":server 001 mynick_ :Welcome to IRC mynick_!runelite@host");

        assertEquals("mynick_", client.getNick());
        assertEquals("mynick_", adapter.getNick());
    }

    @Test
    public void welcomeNumericIsAuthoritativeForNick() {
        IrcAdapter adapter = new IrcAdapter();
        adapter.initialize(stubConfig(), message -> {}, null, "mynick");
        SimpleIrcClient client = adapter.getClient();

        // The server may register us under a nick that differs from what we asked for;
        // RPL_WELCOME is the network's authoritative statement of our nick.
        client.processLine(":server 001 ServerChosen :Welcome to IRC ServerChosen!runelite@host");

        assertEquals("ServerChosen", client.getNick());
        assertEquals("ServerChosen", adapter.getNick());
    }
}

