        return new IrcDesktopLayout.NetworkNode("rizon-id", "Rizon", connected, Arrays.asList(buffers));
    }

    private static void release(JTree tree, int x, int y) {
        tree.dispatchEvent(new java.awt.event.MouseEvent(tree, java.awt.event.MouseEvent.MOUSE_RELEASED,
                System.currentTimeMillis(), java.awt.event.InputEvent.BUTTON1_DOWN_MASK, x, y, 1, false,
                java.awt.event.MouseEvent.BUTTON1));
    }

    private static Component find(Container parent, String name) {
        for (Component child : parent.getComponents()) {
            if (name.equals(child.getName())) return child;
            if (child instanceof Container) {
                Component found = find((Container) child, name);
                if (found != null) return found;
            }
        }
        return null;
    }

    private static TreePath path(JTree tree, String name) {
        DefaultMutableTreeNode root = (DefaultMutableTreeNode) tree.getModel().getRoot();
        java.util.Enumeration<?> nodes = root.depthFirstEnumeration();
        while (nodes.hasMoreElements()) {
            DefaultMutableTreeNode node = (DefaultMutableTreeNode) nodes.nextElement();
            if (name.equals(String.valueOf(node.getUserObject()))) return new TreePath(node.getPath());
        }
        return null;
    }

    private static TreePath path(JTree tree, Object userObject) {
        DefaultMutableTreeNode root = (DefaultMutableTreeNode) tree.getModel().getRoot();
        java.util.Enumeration<?> nodes = root.depthFirstEnumeration();
        while (nodes.hasMoreElements()) {
            DefaultMutableTreeNode node = (DefaultMutableTreeNode) nodes.nextElement();
            if (userObject.equals(node.getUserObject())) return new TreePath(node.getPath());
        }
        return null;
    }

    private static void render(JPanel content) {
        BufferedImage image = new BufferedImage(content.getWidth(), content.getHeight(), BufferedImage.TYPE_INT_RGB);
        Graphics2D graphics = image.createGraphics();
        content.printAll(graphics);
        graphics.dispose();
        try {
            File target = new File("build/previews/irc-desktop.png");
            target.getParentFile().mkdirs();
            ImageIO.write(image, "png", target);
        } catch (java.io.IOException e) { throw new AssertionError(e); }
    }
}

package com.irc;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

/**
 * The shared IRC formatting stripper.
 *
 * The background group must accept one OR two digits. The two constants this class replaced both
 * required exactly two, which left a stray ",5" behind on text coloured foreground 04 on
 * background 5 - while the renderer (IrcPanel.COLORS) parsed that same text as a real background.
 * Stripper and renderer must agree on what counts as a colour code.
 */
public class IrcFormattingTest {

    private static final String BOLD = String.valueOf((char) 0x02);
    private static final String COLOR = String.valueOf((char) 0x03);
    private static final String ITALIC = String.valueOf((char) 0x1D);
    private static final String REVERSE = String.valueOf((char) 0x15);
    private static final String RESET = String.valueOf((char) 0x0F);

    @Test
    public void stripsBoldItalicReverseAndReset() {
        assertEquals("hello", IrcFormatting.stripCodes(BOLD + "hello" + RESET));
        assertEquals("hello", IrcFormatting.stripCodes(ITALIC + "hello" + ITALIC));
        assertEquals("hello", IrcFormatting.stripCodes(REVERSE + "hello" + REVERSE));
    }

    @Test
    public void stripsBareColorCode() {
        assertEquals("hello", IrcFormatting.stripCodes(COLOR + "hello"));
    }

    @Test
    public void stripsOneAndTwoDigitForeground() {
        assertEquals("hello", IrcFormatting.stripCodes(COLOR + "4hello"));
        assertEquals("hello", IrcFormatting.stripCodes(COLOR + "04hello"));
    }

    @Test
    public void stripsTwoDigitBackground() {
        assertEquals("hello", IrcFormatting.stripCodes(COLOR + "04,12hello"));
    }

    /** The bug this task fixes: a single-digit background used to leave ",5" behind. */
    @Test
    public void stripsSingleDigitBackground() {
        assertEquals("hello", IrcFormatting.stripCodes(COLOR + "04,5hello"));
        assertEquals("hello", IrcFormatting.stripCodes(COLOR + "4,5hello"));
    }

    /** A comma that is not part of a colour code is ordinary text and must survive. */
    @Test
    public void keepsCommasThatAreNotBackgroundCodes() {
        assertEquals("hi, there", IrcFormatting.stripCodes(COLOR + "04hi, there"));
        assertEquals("a,b", IrcFormatting.stripCodes("a,b"));
    }

    @Test
    public void leavesPlainTextUntouched() {
        assertEquals("nothing to strip", IrcFormatting.stripCodes("nothing to strip"));
    }

    @Test
    public void toleratesNullAndEmpty() {
        assertNull(IrcFormatting.stripCodes(null));
        assertEquals("", IrcFormatting.stripCodes(""));
    }
}

package com.irc;

import org.junit.Test;

import java.util.regex.Matcher;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

/**
 * The URL pattern behind both link surfaces - the side panel (IrcPanel) and the game chatbox
 * (IrcPlugin) share this one Pattern, so a gap in it breaks clickable links in both at once.
 *
 * The failure mode that matters is truncation, not rejection: a character missing from the trailing
 * class does not stop the URL matching, it just ends the match early. A wiki search link would still
 * light up as a link and still be clickable - it would simply go somewhere else. So these tests
 * assert the WHOLE url is captured, never merely that something matched.
 */
public class IrcLinkPatternTest {

    /** The full text the pattern claims, or null when it claims nothing. */
    private static String firstMatch(String text) {
        Matcher matcher = IrcPanel.VALID_LINK.matcher(text);
        return matcher.find() ? matcher.group() : null;
    }

    /** The reported case: the wiki encodes search spaces as '+'. */
    @Test
    public void keepsPlusInAQueryString() {
        String url = "https://oldschool.runescape.wiki/w/Special:Search?search=ocean+encounters";
        assertEquals(url, firstMatch(url));
    }

    @Test
    public void keepsSeveralPluses() {
        String url = "https://oldschool.runescape.wiki/w/Special:Search?search=a+b+c+d";
        assertEquals(url, firstMatch(url));
    }

    @Test
    public void keepsPlusInAPathSegment() {
        String url = "https://example.com/a+b/c+d";
        assertEquals(url, firstMatch(url));
    }

    @Test
    public void keepsPlusAlongsideOtherQuerySyntax() {
        String url = "https://example.com/s?q=ocean+encounters&lang=en-gb&page=2";
        assertEquals(url, firstMatch(url));
    }

    /** A link in the middle of a sentence stops at the space, not before it. */
    @Test
    public void stopsAtWhitespaceNotAtThePlus() {
        String url = "https://oldschool.runescape.wiki/w/Special:Search?search=ocean+encounters";
        assertEquals(url, firstMatch("look at " + url + " for details"));
    }

    // --- fragments ---

    /** Wiki section links are the common case: everything after '#' used to be dropped. */
    @Test
    public void keepsAFragment() {
        String url = "https://oldschool.runescape.wiki/w/Ocean#Locations";
        assertEquals(url, firstMatch(url));
    }

    @Test
    public void keepsAFragmentAlongsideAQueryAndPluses() {
        String url = "https://oldschool.runescape.wiki/w/Special:Search?search=ocean+encounters#results";
        assertEquals(url, firstMatch(url));
    }

    @Test
    public void keepsAFragmentContainingUnderscoresAndDashes() {
        String url = "https://example.com/page#some_section-two";
        assertEquals(url, firstMatch(url));
    }

    @Test
    public void stopsAtWhitespaceAfterAFragment() {
        String url = "https://oldschool.runescape.wiki/w/Ocean#Locations";
        assertEquals(url, firstMatch("see " + url + " for the table"));
    }

    /** A channel name is not a link, and must not become one. */
    @Test
    public void doesNotTreatAHashAsALinkByItself() {
        assertNull(firstMatch("#help"));
        assertNull(firstMatch("join #osrs please"));
        assertEquals("https://example.com/x", firstMatch("#chan https://example.com/x"));
    }

    // --- parentheses ---

    /** Wiki disambiguation pages put parens in the title: everything from '(' on used to be dropped. */
    @Test
    public void keepsParenthesesInAPath() {
        String url = "https://oldschool.runescape.wiki/w/Dragon_(disambiguation)";
        assertEquals(url, firstMatch(url));
    }

    @Test
    public void keepsParenthesesFollowedByMorePath() {
        String url = "https://example.com/a_(b)/c?d=(e)#f_(g)";
        assertEquals(url, firstMatch(url));
    }

    /** A link wrapped in parens in prose must not swallow the closing one. */
    @Test
    public void doesNotSwallowAWrappingCloseParen() {
        String url = "https://example.com/x";
        assertEquals(url, firstMatch("(see " + url + ")"));
        String wiki = "https://oldschool.runescape.wiki/w/Dragon_(disambiguation)";
        assertEquals(wiki, firstMatch("(see " + wiki + ")"));
    }

    // --- regressions: everything that worked before must still work ---

    @Test
    public void stillMatchesAPlainUrl() {
        assertEquals("https://example.com", firstMatch("https://example.com"));
        assertEquals("http://example.com/path", firstMatch("http://example.com/path"));
    }

    @Test
    public void stillMatchesTheExistingPunctuationSet() {
        String url = "https://example.com/a-b_c/d.e?f=g&h=i%20j,k;l:m";
        assertEquals(url, firstMatch(url));
    }

    @Test
    public void stillMatchesASubdomainedHost() {
        String url = "https://oldschool.runescape.wiki/w/Ocean";
        assertEquals(url, firstMatch(url));
    }

    @Test
    public void stillIgnoresNonUrlText() {
        assertNull(firstMatch("no link here"));
        assertNull(firstMatch("not a url: example"));
    }

    /**
     * A bare '+' must not become a link on its own, and must not extend a match backwards - the
     * plus is only ever valid in the trailing portion, after a host.
     */
    @Test
    public void doesNotTreatAPlusAsALinkByItself() {
        assertNull(firstMatch("1+1=2"));
        assertEquals("https://example.com/x", firstMatch("a+b https://example.com/x"));
    }
}

