package com.irc;

import org.junit.Test;

import java.awt.Color;
import java.util.Arrays;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * The palette nicks are colored from, shared by the chat pane and the nicklists so a nick looks
 * the same in both: 100 hues, all readable on the dark panel.
 */
public class IrcNickColorTest {

    /** Reflection-free access: the palette is exercised through nickColor's full range. */
    private static Set<String> allProducedColors() {
        Set<String> colors = new HashSet<>();
        for (int i = 0; i < 5000; i++) {
            colors.add(IrcPanel.ChannelPane.nickColor("nick" + i));
        }
        return colors;
    }

    @Test
    public void paletteHasOneHundredColors() {
        assertEquals(100, allProducedColors().size());
    }

    @Test
    public void everyPaletteEntryIsAHexColor() {
        for (String color : allProducedColors()) {
            assertTrue("expected #RRGGBB, got: " + color, color.matches("#[0-9A-F]{6}"));
        }
    }

    /** WCAG relative luminance of an sRGB colour. */
    private static double luminance(Color c) {
        double[] channels = {c.getRed(), c.getGreen(), c.getBlue()};
        for (int i = 0; i < 3; i++) {
            double v = channels[i] / 255;
            channels[i] = v <= 0.04045 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4);
        }
        return 0.2126 * channels[0] + 0.7152 * channels[1] + 0.0722 * channels[2];
    }

    /**
     * The 50 added colours were each chosen for at least 3:1; the floor is lower because three of
     * the original 50, the deep blues #434AE4, #6744F5 and #7643E4, sit between 2.6 and 2.9.
     */
    @Test
    public void everyPaletteEntryIsReadableOnTheDarkPanel() {
        double panel = luminance(new Color(0x1E, 0x1F, 0x22));
        for (String hex : allProducedColors()) {
            double contrast = (luminance(Color.decode(hex)) + 0.05) / (panel + 0.05);
            assertTrue(hex + " contrast is only " + contrast, contrast >= 2.5);
        }
    }

    @Test
    public void nickColorIsDeterministic() {
        assertEquals(IrcPanel.ChannelPane.nickColor("bob"), IrcPanel.ChannelPane.nickColor("bob"));
    }

    @Test
    public void nickColorHandlesTheMinimumHashCodeWithoutCrashing() {
        // Math.abs(Integer.MIN_VALUE) is still Integer.MIN_VALUE, so the old
        // "Math.abs(h) % length" produced a negative index here. Math.floorMod does not.
        assertEquals(Integer.MIN_VALUE, "polygenelubricants".hashCode());
        String color = IrcPanel.ChannelPane.nickColor("polygenelubricants");
        assertTrue("must return a palette colour, got: " + color, allProducedColors().contains(color));
    }

    @Test
    public void nickColorHandlesAnEmptyNick() {
        assertTrue(allProducedColors().contains(IrcPanel.ChannelPane.nickColor("")));
    }

    @Test
    public void nickColorSpreadsAcrossTheWholePalette() {
        List<String> sampled = Arrays.asList(
                IrcPanel.ChannelPane.nickColor("alice"),
                IrcPanel.ChannelPane.nickColor("bob"),
                IrcPanel.ChannelPane.nickColor("carol"));
        assertEquals("distinct nicks should not all collide", 3, new HashSet<>(sampled).size());
    }

    @Test
    public void dimmedIsHalfWayToTheBackground() {
        assertEquals(new Color(0x81, 0x31, 0x32),
                IrcPanel.dimmed(Color.decode("#E44343"), new Color(0x1E, 0x1F, 0x22)));
    }
}

package com.irc;

import org.junit.Before;
import org.junit.Test;

import javax.swing.JTabbedPane;
import javax.swing.JTextField;
import java.lang.reflect.Field;

import static org.junit.Assert.assertEquals;

/** Alt+/ and {@code Alt+<} / {@code Alt+>} follow the buffers the panel has shown. */
public class IrcPanelBufferHistoryTest {
    private final IrcPanel panel = new IrcPanel();
    private final JTabbedPane tabs = new JTabbedPane();

    @Before
    public void setUp() throws Exception {
        set("config", new IrcConfig() {
            @Override public String username() { return "tester"; }
            @Override public String password() { return ""; }
        });
        set("tabbedPane", tabs);
        set("inputField", new JTextField());
        // The GUI wires this up; headless tests have to do it themselves.
        tabs.addChangeListener(e -> panel.onFocusedBufferChanged());
        panel.addChannel("System");
        panel.addChannel("#a");
        panel.addChannel("#b");
        panel.addChannel("#c");
    }

    @Test
    public void altSlashTogglesBetweenTheLastTwoBuffers() {
        panel.setFocusedChannel("#a");
        panel.setFocusedChannel("#c");
        panel.jumpToLastBuffer();
        assertEquals("#a", current());
        panel.jumpToLastBuffer();
        assertEquals("#c", current());
    }

    @Test
    public void altArrowsWalkTheVisitedBuffers() {
        panel.setFocusedChannel("#a");
        panel.setFocusedChannel("#c");
        panel.jumpToChannel(3);
        panel.bufferHistoryBack();
        assertEquals("#c", current());
        panel.bufferHistoryBack();
        assertEquals("#a", current());
        panel.bufferHistoryForward();
        panel.bufferHistoryForward();
        assertEquals("#b", current());
        panel.bufferHistoryForward();
        assertEquals("#b", current());
    }

    @Test
    public void closedAndRenamedBuffersAreFollowed() {
        panel.setFocusedChannel("#a");
        panel.setFocusedChannel("#b");
        panel.setFocusedChannel("#c");
        panel.removeChannel("#b");
        panel.renameChannel("#a", "#a2");
        panel.setFocusedChannel("#c");
        panel.bufferHistoryBack();
        assertEquals("#a2", current());
    }

    @Test
    public void altUpAndDownStepThroughTheTabsAndWrap() {
        panel.setFocusedChannel("#b");
        panel.stepChannel(1);
        assertEquals("#c", current());
        panel.stepChannel(1);
        assertEquals("System", current());
        panel.stepChannel(-1);
        assertEquals("#c", current());
        panel.stepChannel(-1);
        assertEquals("#b", current());
    }

    private String current() {
        return panel.getCurrentBuffer().getName();
    }

    private void set(String name, Object value) throws Exception {
        Field field = IrcPanel.class.getDeclaredField(name);
        field.setAccessible(true);
        field.set(panel, value);
    }
}

package com.irc;

import org.junit.Test;

import javax.swing.JTabbedPane;
import javax.swing.Timer;
import java.lang.reflect.Field;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * The panel's side of the channel browser: firing the request and policing the response window.
 *
 * A LIST that never terminates would otherwise leave the user staring at nothing, so the request
 * arms a timer that must be cancelled by any outcome - success or an explicit failure. A timer
 * left running fires a "no response" message on top of a list that did arrive.
 *
 * The dialog itself is not built here: constructing a Window throws HeadlessException on a
 * headless machine, so showChannelList's dialog handling is covered by the manual smoke test.
 */
public class IrcPanelChannelListTest {

    private static IrcPanel headlessPanel() throws Exception {
        IrcPanel panel = new IrcPanel();
        set(panel, "config", stubConfig());
        set(panel, "tabbedPane", new JTabbedPane());
        panel.addChannel("System");
        panel.setFocusedChannel("System");
        return panel;
    }

    private static void set(Object target, String field, Object value) throws Exception {
        Field f = IrcPanel.class.getDeclaredField(field);
        f.setAccessible(true);
        f.set(target, value);
    }

    private static Object get(Object target, String field) throws Exception {
        Field f = IrcPanel.class.getDeclaredField(field);
        f.setAccessible(true);
        return f.get(target);
    }

    /**
     * IrcConfig is an interface whose methods are nearly all defaults, so only the two abstract
     * ones need overriding. Same shape as the stub in IrcPanelNickListTest.
     */
    private static IrcConfig stubConfig() {
        return new IrcConfig() {
            @Override
            public String username() {
                return "tester";
            }

            @Override
            public String password() {
                return "";
            }
        };
    }

    @Test
    public void requestChannelListForwardsTheQuery() throws Exception {
        IrcPanel panel = headlessPanel();
        List<String> requested = new ArrayList<>();
        panel.init(null, null, null, null, (network, query) -> requested.add(query), null);

        panel.requestChannelList(">50");

        assertEquals(1, requested.size());
        assertEquals(">50", requested.get(0));
    }

    @Test
    public void requestChannelListIsSafeWithoutACallback() throws Exception {
        IrcPanel panel = headlessPanel();
        panel.requestChannelList("");  // must not throw
    }

    @Test
    public void requestChannelListCoalescesNullToEmptyString() throws Exception {
        IrcPanel panel = headlessPanel();
        List<String> requested = new ArrayList<>();
        panel.init(null, null, null, null, (network, query) -> requested.add(query), null);

        panel.requestChannelList(null);

        assertEquals(1, requested.size());
        assertEquals("", requested.get(0));
    }

    @Test
    public void armingStartsATimer() throws Exception {
        IrcPanel panel = headlessPanel();
        panel.armChannelListTimeout();

        Timer timer = (Timer) get(panel, "channelListTimeout");
        assertNotNull(timer);
        assertTrue(timer.isRunning());
        assertFalse("a one-shot timeout must not repeat", timer.isRepeats());

        panel.cancelChannelListTimeout();
    }

    @Test
    public void cancellingStopsTheTimer() throws Exception {
        IrcPanel panel = headlessPanel();
        panel.armChannelListTimeout();
        panel.cancelChannelListTimeout();

        Timer timer = (Timer) get(panel, "channelListTimeout");
        assertFalse(timer.isRunning());
    }

    /** Re-arming must not leave the previous timer running behind the new one. */
    @Test
    public void rearmingReplacesTheRunningTimer() throws Exception {
        IrcPanel panel = headlessPanel();
        panel.armChannelListTimeout();
        Timer first = (Timer) get(panel, "channelListTimeout");

        panel.armChannelListTimeout();
        Timer second = (Timer) get(panel, "channelListTimeout");

        assertFalse("the superseded timer must be stopped", first.isRunning());
        assertTrue(second.isRunning());
        panel.cancelChannelListTimeout();
    }

    @Test
    public void cancellingWithoutArmingIsSafe() throws Exception {
        IrcPanel panel = headlessPanel();
        panel.cancelChannelListTimeout();  // must not throw
    }

    /** Fires the armed timer's action now rather than waiting 30 real seconds. */
    private static void fireTimeout(IrcPanel panel) throws Exception {
        Timer timer = (Timer) get(panel, "channelListTimeout");
        for (java.awt.event.ActionListener listener : timer.getActionListeners()) {
            listener.actionPerformed(null);
        }
        panel.cancelChannelListTimeout();
        // Twice: addMessage queues the document edit on a second invokeLater hop, so one drain
        // would leave the "must NOT contain" assertion below passing vacuously.
        javax.swing.SwingUtilities.invokeAndWait(() -> { });
        javax.swing.SwingUtilities.invokeAndWait(() -> { });
    }

    /**
     * Whole-branch review finding: the timeout was the one channel-list message that never reached
     * the game chatbox. "Requesting channel list..." and a 263 refusal both go through the
     * plugin's processMessage, which feeds the chatbox and the panel; the timeout called
     * addMessage directly, so a user with the sidebar collapsed saw the request announced in game
     * chat and never learned it had failed.
     *
     * The fix is that the panel reports the expiry to the plugin instead of writing it itself, so
     * what is pinned here is: the callback fires, and nothing lands in the System pane locally.
     * The second assertion is the one that fails if anyone reinstates the direct write.
     */
    @Test
    public void timeoutReportsThroughTheCallbackRatherThanWritingToThePanel() throws Exception {
        IrcPanel panel = headlessPanel();
        List<String> reported = new ArrayList<>();
        panel.init(null, null, null, null, null, () -> reported.add("timeout"));

        panel.armChannelListTimeout();
        fireTimeout(panel);

        assertEquals("the expiry must be reported exactly once", 1, reported.size());

        String text = panel.getPane("System").getText();
        assertFalse("the panel must not also write the notice itself - the plugin owns emitting it,"
                        + " so a direct write would double up in the panel and still skip the chatbox: "
                        + text,
                text.toLowerCase().contains("no channel list response"));
    }

    /** A panel that was never wired to a plugin must not blow up when its timeout expires. */
    @Test
    public void timeoutWithoutACallbackIsSafe() throws Exception {
        IrcPanel panel = headlessPanel();
        panel.armChannelListTimeout();
        fireTimeout(panel);  // must not throw
    }

    /**
     * Whole-branch review finding: the browser survived plugin shutdown as a zombie window.
     * shutDown() removed the nav button, nulled the panel and disconnected, but the JDialog is a
     * top-level Window that nothing disposed - it stayed on screen with Refresh and Join both
     * returning silently, and re-enabling the plugin leaked it (IrcPanel is not a singleton, so
     * the injector hands back a fresh panel and a fresh dialog) along with its sorter and up to
     * 20,000 entries.
     *
     * The dialog half needs a real Window, so it is asserted only where one can be created; the
     * timer half and the field-nulling are asserted unconditionally.
     */
    @Test
    public void shutdownStopsTheTimeoutAndReleasesTheDialog() throws Exception {
        IrcPanel panel = headlessPanel();
        panel.armChannelListTimeout();
        Timer armed = (Timer) get(panel, "channelListTimeout");

        ChannelListDialog dialog = null;
        try {
            dialog = new ChannelListDialog(null, null, null);
            set(panel, "channelListDialog", dialog);
        } catch (java.awt.HeadlessException noDisplayAvailable) {
            // Window construction needs a display; the rest of the teardown still has to hold.
        }

        panel.shutdown();

        assertFalse("shutdown must stop a pending timeout", armed.isRunning());
        assertNull("the timer field must be released", get(panel, "channelListTimeout"));
        assertNull("the dialog field must be nulled so a later showChannelList rebuilds cleanly",
                get(panel, "channelListDialog"));
        if (dialog != null) {
            assertFalse("the dialog's native window must be disposed, not merely dereferenced",
                    dialog.isDisplayable());
        }
    }

    /** Teardown runs on plugin shutdown regardless of whether /list was ever used. */
    @Test
    public void shutdownIsSafeWithNothingArmedOrShown() throws Exception {
        IrcPanel panel = headlessPanel();
        panel.shutdown();
        panel.shutdown();  // idempotent - must not throw
        assertNull(get(panel, "channelListDialog"));
    }

    /**
     * A LIST reply that does arrive must disarm the timeout, or the "no response" notice fires on
     * top of a list the user is already looking at. {@code cancelChannelListTimeout()} is the
     * first statement in {@code showChannelList}, before any {@link java.awt.Window} is
     * constructed, so this holds even though the dialog itself can't be built headless: the
     * {@link java.awt.HeadlessException} it throws is caught here and the timer state is asserted
     * regardless of whether that exception was thrown.
     */
    @Test
    public void showingTheChannelListCancelsThePendingTimeout() throws Exception {
        IrcPanel panel = headlessPanel();
        panel.armChannelListTimeout();

        try {
            panel.showChannelList(new ArrayList<>(), "", false);
        } catch (java.awt.HeadlessException expectedOnAHeadlessMachine) {
            // Dialog construction needs a real Window; the cancel already ran before this point.
        }

        Timer timer = (Timer) get(panel, "channelListTimeout");
        assertFalse("showChannelList must cancel the pending timeout", timer.isRunning());
    }
}

package com.irc;

import org.junit.Test;

import javax.swing.JFrame;
import javax.swing.SwingUtilities;
import javax.swing.text.Document;
import java.awt.Font;
import java.lang.reflect.Field;
import java.time.Instant;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.util.concurrent.atomic.AtomicReference;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * In the pop-out, a run of joins, parts, quits, kicks and nick changes is shown as one line
 * grouped by kind, so a netsplit or a channel of hoppers doesn't bury the conversation. The side
 * panel keeps one line per event.
 *
 * The lines are built exactly as IrcAdapter builds them, so a change to that wording breaks
 * these tests rather than silently ungrouping the pop-out.
 */
public class IrcPanelCompactPresenceTest {

    private static final IrcConfig NO_TIMESTAMPS = new IrcConfig() {
        @Override public String username() { return "tester"; }
        @Override public String password() { return ""; }
        @Override public boolean timestamp() { return false; }
    };

    private static final IrcConfig TIMESTAMPS = new IrcConfig() {
        @Override public String username() { return "tester"; }
        @Override public String password() { return ""; }
    };

    // --- the messages IrcAdapter produces ---

    private static IrcMessage join(String nick) {
        return new IrcMessage("#c", "*", nick + " has joined.", IrcMessage.MessageType.JOIN, Instant.now());
    }

    private static IrcMessage part(String nick, String reason) {
        return new IrcMessage("#c", nick + " parted", reason, IrcMessage.MessageType.PART, Instant.now());
    }

    private static IrcMessage quit(String nick, String reason) {
        return new IrcMessage("#c", nick + " quit", reason, IrcMessage.MessageType.QUIT, Instant.now());
    }

    private static IrcMessage nick(String oldNick, String newNick) {
        return new IrcMessage("#c", oldNick + " is now known as", newNick, IrcMessage.MessageType.NICK_CHANGE, Instant.now());
    }

    private static IrcMessage kick(String by, String nick, String reason) {
        return new IrcMessage("#c", by + " kicked " + nick, reason, IrcMessage.MessageType.KICK, Instant.now());
    }

    private static IrcMessage chat(String nick, String text) {
        return new IrcMessage("#c", nick, text, IrcMessage.MessageType.CHAT, Instant.now());
    }

    /** The pane's visible text once every queued render has run, one line per paragraph. */
    private static String render(IrcConfig config, boolean compact, IrcMessage... messages) throws Exception {
        AtomicReference<IrcPanel.ChannelPane> paneRef = new AtomicReference<>();
        SwingUtilities.invokeAndWait(() -> {
            IrcPanel.ChannelPane pane = new IrcPanel.ChannelPane(new Font("SansSerif", Font.PLAIN, 12), config, null);
            pane.setCompactPresence(compact);
            for (IrcMessage message : messages) pane.appendMessage(message, config);
            paneRef.set(pane);
        });
        return textOf(paneRef.get());
    }

    private static String textOf(IrcPanel.ChannelPane pane) throws Exception {
        SwingUtilities.invokeAndWait(() -> { });
        AtomicReference<String> text = new AtomicReference<>();
        SwingUtilities.invokeAndWait(() -> {
            try {
                Document doc = pane.getDocument();
                // Swing's HTML document keeps a non-breaking space after "sender:"; read it as a space.
                text.set(doc.getText(0, doc.getLength()).replace(' ', ' ').trim());
            } catch (Exception e) {
                throw new RuntimeException(e);
            }
        });
        return text.get();
    }

    private static int count(String haystack, String needle) {
        int n = 0;
        for (int i = haystack.indexOf(needle); i >= 0; i = haystack.indexOf(needle, i + 1)) n++;
        return n;
    }

    @Test
    public void groupsARunIntoOneLineByKind() throws Exception {
        String text = render(NO_TIMESTAMPS, true,
                join("alice"), quit("bob", "Ping timeout"), part("carol", "bye"),
                nick("dave", "dave_"), kick("eve", "frank", "spam"), join("gina"));
        assertEquals("* Joins: alice, gina · Parts: carol · Quits: bob · "
                + "Nicks: dave → dave_ · Kicks: frank (by eve)", text);
    }

    @Test
    public void leavesOutEmptyGroups() throws Exception {
        String text = render(NO_TIMESTAMPS, true, quit("bob", "x"), quit("carol", "y"));
        assertEquals("* Quits: bob, carol", text);
    }

    @Test
    public void aHopperShowsOncePerGroup() throws Exception {
        String text = render(NO_TIMESTAMPS, true,
                join("alice"), part("alice", " "), join("alice"), part("alice", " "), join("ALICE"));
        assertEquals("* Joins: alice · Parts: alice", text);
    }

    @Test
    public void everyNickChangeIsListed() throws Exception {
        String text = render(NO_TIMESTAMPS, true, nick("dave", "dave_"), nick("dave_", "dave"));
        assertEquals("* Nicks: dave → dave_, dave_ → dave", text);
    }

    @Test
    public void aNickKickedTwiceShowsTheLatestKicker() throws Exception {
        String text = render(NO_TIMESTAMPS, true,
                kick("eve", "frank", "a"), join("frank"), kick("zed", "frank", "b"));
        assertEquals("* Joins: frank · Kicks: frank (by zed)", text);
    }

    @Test
    public void aSingleEventKeepsItsNormalLine() throws Exception {
        String text = render(NO_TIMESTAMPS, true, chat("bob", "hi"), quit("carol", "Ping timeout"), chat("bob", "bye"));
        assertEquals("bob: hi\ncarol quit: Ping timeout\nbob: bye", text);
    }

    @Test
    public void otherLinesEndTheRun() throws Exception {
        String text = render(NO_TIMESTAMPS, true,
                join("a"), join("b"), chat("bob", "hi"), join("c"), join("d"));
        assertEquals("* Joins: a, b\nbob: hi\n* Joins: c, d", text);
    }

    @Test
    public void theLineIsStampedWhenTheRunStarted() throws Exception {
        Instant start = Instant.parse("2026-10-06T12:01:03Z");
        IrcMessage first = new IrcMessage("#c", "*", "a has joined.", IrcMessage.MessageType.JOIN, start);
        IrcMessage second = new IrcMessage("#c", "*", "b has joined.", IrcMessage.MessageType.JOIN, start.plusSeconds(90));
        String stamp = DateTimeFormatter.ofPattern("HH:mm:ss").withZone(ZoneId.systemDefault()).format(start);
        assertEquals("[" + stamp + "] * Joins: a, b", render(TIMESTAMPS, true, first, second));
    }

    @Test
    public void theSidePanelKeepsOneLinePerEvent() throws Exception {
        String text = render(NO_TIMESTAMPS, false, join("alice"), quit("bob", "Ping timeout"));
        assertEquals("*: alice has joined.\nbob quit: Ping timeout", text);
    }

    @Test
    public void switchingModesRerendersTheScrollback() throws Exception {
        AtomicReference<IrcPanel.ChannelPane> paneRef = new AtomicReference<>();
        SwingUtilities.invokeAndWait(() -> {
            IrcPanel.ChannelPane pane = new IrcPanel.ChannelPane(new Font("SansSerif", Font.PLAIN, 12), NO_TIMESTAMPS, null);
            pane.appendMessage(join("alice"), NO_TIMESTAMPS);
            pane.appendMessage(join("bob"), NO_TIMESTAMPS);
            paneRef.set(pane);
        });
        IrcPanel.ChannelPane pane = paneRef.get();
        assertEquals("*: alice has joined.\n*: bob has joined.", textOf(pane));

        SwingUtilities.invokeAndWait(() -> pane.setCompactPresence(true));
        assertEquals("* Joins: alice, bob", textOf(pane));

        SwingUtilities.invokeAndWait(() -> pane.setCompactPresence(false));
        assertEquals("*: alice has joined.\n*: bob has joined.", textOf(pane));
    }

    @Test
    public void scrollbackStillCountsEachEvent() throws Exception {
        IrcConfig small = new IrcConfig() {
            @Override public String username() { return "tester"; }
            @Override public String password() { return ""; }
            @Override public boolean timestamp() { return false; }
            @Override public int getMaxScrollback() { return 3; }
        };
        String text = render(small, true, join("a"), join("b"), join("c"), join("d"), join("e"));
        assertEquals("* Joins: c, d, e", text);
    }

    /** Popping out compacts every open pane, and panes opened while popped out; docking undoes it. */
    @Test
    public void thePopOutTurnsCompactingOnForItsPanes() throws Exception {
        org.junit.Assume.assumeFalse(java.awt.GraphicsEnvironment.isHeadless());
        AtomicReference<IrcPanel> panelRef = new AtomicReference<>();
        AtomicReference<JFrame> mainRef = new AtomicReference<>();
        SwingUtilities.invokeAndWait(() -> {
            IrcPanel panel = new IrcPanel();
            panelRef.set(panel);
            setField(panel, "config", NO_TIMESTAMPS);
            panel.init((channel, text) -> {}, (network, channel, password) -> {}, channel -> {},
                    reconnect -> {}, (network, query) -> {}, () -> {});
            panel.initializeGui();
            JFrame main = new JFrame();
            mainRef.set(main);
            main.add(panel.getWrappedPanel());
            main.setSize(260, 600);
            main.setVisible(true);
            panel.addChannel("#c");
        });
        try {
            IrcPanel panel = panelRef.get();
            SwingUtilities.invokeAndWait(() -> {
                panel.addMessage(join("alice"));
                panel.addMessage(join("bob"));
            });
            assertEquals(2, count(textOf(panel.getPane("#c")), "has joined."));

            SwingUtilities.invokeAndWait(() -> {
                panel.setDetached(true, false);
                panel.addChannel("#later");
                panel.addMessage(new IrcMessage("#later", "*", "x has joined.", IrcMessage.MessageType.JOIN, Instant.now()));
                panel.addMessage(new IrcMessage("#later", "*", "y has joined.", IrcMessage.MessageType.JOIN, Instant.now()));
            });
            assertTrue(textOf(panel.getPane("#c")).contains("* Joins: alice, bob"));
            assertTrue(textOf(panel.getPane("#later")).contains("* Joins: x, y"));

            SwingUtilities.invokeAndWait(() -> panel.setDetached(false, false));
            assertFalse(textOf(panel.getPane("#c")).contains("Joins:"));
            assertFalse(textOf(panel.getPane("#later")).contains("Joins:"));
        } finally {
            SwingUtilities.invokeAndWait(() -> {
                panelRef.get().setDetached(false, false);
                mainRef.get().dispose();
            });
        }
    }

    private static void setField(Object target, String name, Object value) {
        try {
            Field field = IrcPanel.class.getDeclaredField(name);
            field.setAccessible(true);
            field.set(target, value);
        } catch (ReflectiveOperationException e) {
            throw new AssertionError(e);
        }
    }
}

package com.irc;

import org.junit.Test;

import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicReference;

import static org.junit.Assert.assertNull;

/**
 * Regression test for the data race that produced:
 *
 *   java.lang.ArrayIndexOutOfBoundsException: Index 1 out of bounds for length 1
 *       at java.util.LinkedHashMap.keysToArray
 *       at com.irc.IrcPanel.getChannelNames(IrcPanel.java:67)
 *
 * getChannelNames() snapshots channelPanes.keySet() on the IRC reader thread while
 * the EDT concurrently adds/removes channels. With a non-thread-safe map the snapshot
 * (new ArrayList<>(keySet())) reads size(), allocates an array of that size, then
 * overflows it when another thread inserts mid-copy.
 */
public class IrcPanelConcurrencyTest {

    @Test
    public void getChannelNamesIsSafeUnderConcurrentMutation() throws Exception {
        IrcPanel panel = new IrcPanel();

        final AtomicReference<Throwable> failure = new AtomicReference<>();
        final AtomicBoolean stop = new AtomicBoolean(false);

        // Writer: churns the map the way addChannel()/removeChannel() do.
        Thread writer = new Thread(() -> {
            try {
                for (int round = 0; round < 100_000 && !stop.get(); round++) {
                    for (int i = 0; i < 16; i++) {
                        panel.getChannelPanes().put(BufferKey.swiftIrc("#chan" + i), null);
                    }
                    for (int i = 0; i < 16; i++) {
                        panel.getChannelPanes().remove(BufferKey.swiftIrc("#chan" + i));
                    }
                }
            } catch (Throwable t) {
                failure.compareAndSet(null, t);
            }
        }, "writer");

        // Reader: snapshots channel names the way processMessage() does on the IRC thread.
        Thread reader = new Thread(() -> {
            try {
                for (int round = 0; round < 100_000 && !stop.get(); round++) {
                    panel.getChannelNames();
                }
            } catch (Throwable t) {
                failure.compareAndSet(null, t);
            }
        }, "reader");

        writer.start();
        reader.start();
        writer.join(30_000);
        reader.join(30_000);
        stop.set(true);
        writer.join();
        reader.join();

        assertNull("getChannelNames() must not throw under concurrent mutation, but got: "
                + failure.get(), failure.get());
    }
}

package com.irc;

import org.junit.Test;

import javax.swing.Action;
import javax.swing.JTextField;
import java.awt.event.ActionEvent;
import java.lang.reflect.Field;
import java.lang.reflect.Method;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;

/**
 * Verifies the input box is actually wired to InputHistory: the VK_UP/VK_DOWN key bindings
 * installed by setupShortcuts must resolve to actions that recall history into inputField.
 * The InputHistory logic itself is covered by {@link InputHistoryTest}; this guards the glue
 * (matching action keys, caret handling) that unit tests can't see.
 */
public class IrcPanelInputHistoryTest {

    private static InputHistory history(IrcPanel panel) throws Exception {
        Field field = IrcPanel.class.getDeclaredField("inputHistory");
        field.setAccessible(true);
        return (InputHistory) field.get(panel);
    }

    private static void fire(JTextField input, String actionKey) {
        Action action = input.getActionMap().get(actionKey);
        assertNotNull("action '" + actionKey + "' must be bound", action);
        action.actionPerformed(new ActionEvent(input, ActionEvent.ACTION_PERFORMED, actionKey));
    }

    @Test
    public void upBindingRecallsLastSentMessageAndDownRestoresDraft() throws Exception {
        IrcPanel panel = new IrcPanel();
        panel.inputField = new JTextField();

        Method setupShortcuts = IrcPanel.class.getDeclaredMethod("setupShortcuts");
        setupShortcuts.setAccessible(true);
        setupShortcuts.invoke(panel);

        InputHistory history = history(panel);
        history.add("hello");
        history.add("world");

        // User has typed an unsent draft, then presses Up.
        panel.inputField.setText("draft");
        fire(panel.inputField, "historyPrevious");
        assertEquals("world", panel.inputField.getText());
        assertEquals("caret at end", "world".length(), panel.inputField.getCaretPosition());

        fire(panel.inputField, "historyPrevious");
        assertEquals("hello", panel.inputField.getText());

        // Down back down past the newest restores the stashed draft.
        fire(panel.inputField, "historyNext");
        assertEquals("world", panel.inputField.getText());
        fire(panel.inputField, "historyNext");
        assertEquals("draft", panel.inputField.getText());
    }
}

package com.irc;

import org.junit.Test;

import javax.swing.JComboBox;
import javax.swing.JTabbedPane;
import java.lang.reflect.Field;
import java.time.Instant;
import java.util.Arrays;
import java.util.Collections;

import static org.junit.Assert.*;

/** Buffers are identified by network and name; the same name on two networks is two buffers. */
public class IrcPanelNetworkTest {
    private static final String RIZON = "rizon-id";
    private static final IrcMessage.MessageType CHAT = IrcMessage.MessageType.CHAT;

    private static IrcPanel panel() throws Exception {
        IrcPanel panel = new IrcPanel();
        set(panel, "config", new IrcConfig() {
            @Override public String username() { return "tester"; }
            @Override public String password() { return ""; }
        });
        set(panel, "tabbedPane", new JTabbedPane());
        panel.addChannel("System");
        panel.setFocusedChannel("System");
        panel.setNetworkName(RIZON, "Rizon");
        return panel;
    }

    private static void set(Object target, String field, Object value) throws Exception {
        Field f = IrcPanel.class.getDeclaredField(field);
        f.setAccessible(true);
        f.set(target, value);
    }

    @SuppressWarnings("unchecked")
    private static <T> T get(Object target, String field) throws Exception {
        Field f = IrcPanel.class.getDeclaredField(field);
        f.setAccessible(true);
        return (T) f.get(target);
    }

    @Test
    public void markAllReadClearsEveryNetworksUnreadBuffers() throws Exception {
        IrcPanel panel = panel();
        panel.addChannel("#a"); // second buffer: gets focus
        panel.addMessage(new IrcMessage("#b", "Ash", "hi", CHAT, Instant.now()));
        panel.addMessage(new IrcMessage("#c", "Ash", "hi", CHAT, Instant.now()).withNetworkId(RIZON));
        assertTrue(panel.isUnread("#b"));
        assertTrue(panel.unreadMessages.get(BufferKey.of(RIZON, "#c")));

        panel.markAllRead();

        for (BufferKey key : panel.getBuffers()) {
            assertFalse(key + " should be read", panel.unreadMessages.getOrDefault(key, false));
        }
        assertEquals(panel.getBuffers().size(), panel.unreadMessages.size());
    }

    @Test
    public void channelNamesDifferingOnlyInCaseShareOneBuffer() throws Exception {
        IrcPanel panel = panel();
        panel.addMessage(new IrcMessage("#losthq", "Ash", "one", CHAT, Instant.now()).withNetworkId(RIZON));
        panel.addMessage(new IrcMessage("#LostHQ", "Ash", "two", CHAT, Instant.now()).withNetworkId(RIZON));
        panel.addChannel(BufferKey.of(RIZON, "#LOSTHQ"));
        assertEquals("one buffer, upgraded to the server's casing",
                Arrays.asList(BufferKey.swiftIrc("System"), BufferKey.of(RIZON, "#LostHQ")), panel.getBuffers());
    }

    @Test
    public void aProperlyCasedNameIsNeverDowngraded() throws Exception {
        IrcPanel panel = panel();
        panel.addMessage(new IrcMessage("#LostHQ", "Ash", "one", CHAT, Instant.now()).withNetworkId(RIZON));
        panel.addMessage(new IrcMessage("#losthq", "Ash", "two", CHAT, Instant.now()).withNetworkId(RIZON));
        assertEquals(Arrays.asList(BufferKey.swiftIrc("System"), BufferKey.of(RIZON, "#LostHQ")), panel.getBuffers());
    }

    @Test
    public void buffersAreFoundWhateverTheCasing() throws Exception {
        IrcPanel panel = panel();
        panel.addChannel(BufferKey.of(RIZON, "#LostHQ"));
        panel.addChannel(BufferKey.of(RIZON, "Luna"));
        assertTrue(panel.isPane(BufferKey.of(RIZON, "#losthq")));
        panel.setFocusedChannel(BufferKey.of(RIZON, "luna"));
        assertEquals(BufferKey.of(RIZON, "Luna"), panel.getCurrentBuffer());
        panel.removeChannel(BufferKey.of(RIZON, "#LOSTHQ"));
        assertFalse(panel.isPane(BufferKey.of(RIZON, "#LostHQ")));
        assertTrue("other networks are unaffected", !panel.isPane(BufferKey.swiftIrc("#losthq")));
    }

    @Test
    public void sameChannelNameOnTwoNetworksMakesTwoBuffers() throws Exception {
        IrcPanel panel = panel();
        panel.addMessage(new IrcMessage("#rshelp", "Ash", "on swift", CHAT, Instant.now()));
        panel.addMessage(new IrcMessage("#rshelp", "Ash", "on rizon", CHAT, Instant.now()).withNetworkId(RIZON));
        assertEquals(Arrays.asList(BufferKey.swiftIrc("System"), BufferKey.swiftIrc("#rshelp"),
                BufferKey.of(RIZON, "#rshelp")), panel.getBuffers());
        assertNotSame(panel.getChannelPanes().get(BufferKey.swiftIrc("#rshelp")),
                panel.getChannelPanes().get(BufferKey.of(RIZON, "#rshelp")));
    }

    @Test
    public void lateMessageForARemovedNetworkDoesNotRecreateItsBuffer() throws Exception {
        IrcPanel panel = panel();
        panel.addMessage(new IrcMessage("#foo", "Ash", "hi", CHAT, Instant.now()).withNetworkId(RIZON));
        panel.removeNetworkBuffers(RIZON);
        panel.forgetNetwork(RIZON);
        panel.addMessage(new IrcMessage("#foo", "Ash", "late", CHAT, Instant.now()).withNetworkId(RIZON));
        assertEquals(Collections.singletonList(BufferKey.swiftIrc("System")), panel.getBuffers());
    }

    @Test
    public void samePmNickOnTwoNetworksMakesTwoBuffers() throws Exception {
        IrcPanel panel = panel();
        panel.addMessage(new IrcMessage("Luna", "Luna", "hi", CHAT, Instant.now()));
        panel.addMessage(new IrcMessage("Luna", "Luna", "hi", CHAT, Instant.now()).withNetworkId(RIZON));
        assertTrue(panel.isPane(BufferKey.swiftIrc("Luna")));
        assertTrue(panel.isPane(BufferKey.of(RIZON, "Luna")));
        assertEquals(3, panel.getBuffers().size());
    }

    @Test
    public void extraNetworkBuffersAreTitledWithTheirNetwork() throws Exception {
        IrcPanel panel = panel();
        panel.addChannel(BufferKey.of(RIZON, "#foo"));
        panel.addChannel(BufferKey.swiftIrc("#foo"));
        JTabbedPane tabs = get(panel, "tabbedPane");
        JComboBox<String> dropdown = get(panel, "bufferDropdown");
        assertEquals("#foo (Rizon)", tabs.getTitleAt(1));
        assertEquals("#foo", tabs.getTitleAt(2));
        assertEquals("#foo (Rizon)", dropdown.getItemAt(1));

        panel.setNetworkName(RIZON, "Rizon2");
        assertEquals("#foo (Rizon2)", tabs.getTitleAt(1));
        assertEquals("#foo (Rizon2)", dropdown.getItemAt(1));
    }

    @Test
    public void renameTouchesOnlyThatNetwork() throws Exception {
        IrcPanel panel = panel();
        panel.addChannel(BufferKey.swiftIrc("Luna"));
        panel.addChannel(BufferKey.of(RIZON, "Luna"));
        panel.renameChannel(BufferKey.of(RIZON, "Luna"), "Luna2");
        assertTrue(panel.isPane(BufferKey.swiftIrc("Luna")));
        assertTrue(panel.isPane(BufferKey.of(RIZON, "Luna2")));
        assertFalse(panel.isPane(BufferKey.of(RIZON, "Luna")));
    }

    @Test
    public void removingANetworkDropsAllItsBuffersAndRefocuses() throws Exception {
        IrcPanel panel = panel();
        panel.addChannel(BufferKey.of(RIZON, "System"));
        panel.addChannel(BufferKey.of(RIZON, "#foo"));
        panel.setFocusedChannel(BufferKey.of(RIZON, "#foo"));
        panel.removeNetworkBuffers(RIZON);
        assertEquals(Collections.singletonList(BufferKey.swiftIrc("System")), panel.getBuffers());
        assertEquals(BufferKey.swiftIrc("System"), panel.getCurrentBuffer());
    }

    @Test
    public void historyDoesNotMarkABufferUnread() throws Exception {
        IrcPanel panel = panel();
        panel.addChannel("#a"); // second buffer: gets focus
        panel.addMessage(new IrcMessage("#old", "Ash", "replayed", IrcMessage.MessageType.HISTORY, Instant.now()));
        panel.addMessage(new IrcMessage("#new", "Ash", "live", CHAT, Instant.now()));
        assertFalse(panel.isUnread("#old"));
        assertTrue(panel.isUnread("#new"));
    }

    @Test
    public void currentChannelOnAnotherNetworkIsItsSystemBuffer() throws Exception {
        IrcPanel panel = panel();
        panel.addChannel("#a");
        panel.setFocusedChannel("#a");
        assertEquals("#a", panel.getCurrentChannelOn(NetworkConfig.SWIFTIRC_ID));
        assertEquals("System", panel.getCurrentChannelOn(RIZON));
    }

    @Test
    public void rostersAreKeptPerNetwork() throws Exception {
        IrcPanel panel = panel();
        panel.addChannel(BufferKey.of(RIZON, "#foo"));
        panel.addChannel(BufferKey.swiftIrc("#foo"));
        panel.setChannelUsers(BufferKey.of(RIZON, "#FOO"),
                Collections.singletonList(new ChannelUserList.Entry("Ash", "@", 0)));
        // Headless panels have no tab change listener, so drive the focus hook by hand.
        panel.setFocusedChannel(BufferKey.swiftIrc("#foo"));
        panel.onFocusedBufferChanged();
        JComboBox<String> nicks = get(panel, "nickDropdown");
        assertEquals("Users (0)", nicks.getItemAt(0));
        panel.setFocusedChannel(BufferKey.of(RIZON, "#foo"));
        panel.onFocusedBufferChanged();
        assertEquals("Users (1)", nicks.getItemAt(0));
    }
}

package com.irc;

import org.junit.Test;

import javax.swing.JComboBox;
import javax.swing.JTabbedPane;
import java.lang.reflect.Field;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.Map;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The nicklist dropdown: a compact action menu left of the buffer dropdown.
 *
 * Index 0 is a "Users (N)" header rather than a selectable user, and picking a real entry opens
 * that user's PM buffer then snaps back to the header - it is a menu, not a persistent selection.
 * The real protection against reentrant repopulation is the {@code index < 1} guard in
 * {@code openQueryFromNickDropdown} - every spurious action event a model mutation can fire
 * arrives at index -1 or 0, which that guard already rejects. The listener detach/reattach in
 * {@code repopulateNickDropdown} is defensive depth kept to match {@code renameBufferDropdownItem}'s
 * precedent, not something this test suite can exercise: {@code initializeGui} is the only place
 * the tab-change listener is installed, and it never runs in a headless test.
 */
public class IrcPanelNickListTest {

    /**
     * Builds a panel through addChannel so channelPanes stays index-aligned with tabbedPane -
     * setFocusedChannel maps a channel to a tab by position, so injecting tabs directly would
     * desync the two and getCurrentChannel() would report the wrong buffer.
     */
    private static IrcPanel panelWith(String... channels) throws Exception {
        IrcPanel panel = new IrcPanel();
        set(panel, "config", stubConfig());
        set(panel, "tabbedPane", new JTabbedPane());

        for (String channel : channels) {
            panel.addChannel(channel);
        }
        panel.setFocusedChannel(channels[0]);
        return panel;
    }

    /** Every IrcConfig method is default except username() and password(). */
    private static IrcConfig stubConfig() {
        return new IrcConfig() {
            @Override
            public String username() {
                return "tester";
            }

            @Override
            public String password() {
                return "";
            }
        };
    }

    private static void set(Object target, String field, Object value) throws Exception {
        Field f = IrcPanel.class.getDeclaredField(field);
        f.setAccessible(true);
        f.set(target, value);
    }

    @SuppressWarnings("unchecked")
    private static JComboBox<String> nickDropdown(IrcPanel panel) throws Exception {
        Field f = IrcPanel.class.getDeclaredField("nickDropdown");
        f.setAccessible(true);
        return (JComboBox<String>) f.get(panel);
    }

    private static List<ChannelUserList.Entry> roster() {
        return Arrays.asList(
                new ChannelUserList.Entry("bob", "@", 2),
                new ChannelUserList.Entry("dave", "+", 4),
                new ChannelUserList.Entry("erin", "", Integer.MAX_VALUE));
    }

    @Test
    public void headerReportsTheUserCount() throws Exception {
        IrcPanel panel = panelWith("#chan");
        panel.setChannelUsers("#chan", roster());
        assertEquals("Users (3)", nickDropdown(panel).getItemAt(0));
    }

    @Test
    public void entriesRenderWithTheirPrefix() throws Exception {
        IrcPanel panel = panelWith("#chan");
        panel.setChannelUsers("#chan", roster());

        JComboBox<String> dropdown = nickDropdown(panel);
        assertEquals(4, dropdown.getItemCount());
        assertEquals("@bob", dropdown.getItemAt(1));
        assertEquals("+dave", dropdown.getItemAt(2));
        assertEquals("erin", dropdown.getItemAt(3));
    }

    @Test
    public void headerIsSelectedAfterPopulating() throws Exception {
        IrcPanel panel = panelWith("#chan");
        panel.setChannelUsers("#chan", roster());
        assertEquals(0, nickDropdown(panel).getSelectedIndex());
    }

    @Test
    public void selectingANickOpensAndFocusesThatPmBuffer() throws Exception {
        IrcPanel panel = panelWith("#chan");
        panel.setChannelUsers("#chan", roster());

        nickDropdown(panel).setSelectedIndex(1); // "@bob"

        assertTrue("a PM buffer for bob should exist", panel.isPane("bob"));
        assertEquals("and it should be focused", "bob", panel.getCurrentChannel());
    }

    @Test
    public void selectingANickStripsThePrefixFromTheBufferName() throws Exception {
        IrcPanel panel = panelWith("#chan");
        panel.setChannelUsers("#chan", roster());

        nickDropdown(panel).setSelectedIndex(1); // "@bob"

        assertTrue(panel.isPane("bob"));
        assertFalse("the prefix is decoration, not part of the nick", panel.isPane("@bob"));
    }

    @Test
    public void selectingANickSnapsBackToTheHeader() throws Exception {
        IrcPanel panel = panelWith("#chan");
        panel.setChannelUsers("#chan", roster());

        nickDropdown(panel).setSelectedIndex(2); // "+dave"

        assertEquals("action menu, not a persistent selection", 0, nickDropdown(panel).getSelectedIndex());
    }

    @Test
    public void reSelectingTheHeaderAfterAnActionOpensNothingNew() throws Exception {
        IrcPanel panel = panelWith("#chan");
        panel.setChannelUsers("#chan", roster());

        nickDropdown(panel).setSelectedIndex(1);   // opens "bob", then snaps back to the header
        int buffersAfterPick = panel.getChannelNames().size();

        nickDropdown(panel).setSelectedIndex(0);   // the header is not an action

        assertEquals("header selection must not open a buffer", buffersAfterPick, panel.getChannelNames().size());
    }

    @Test
    public void anUpdateForAnUnfocusedChannelDoesNotRedrawTheDropdown() throws Exception {
        IrcPanel panel = panelWith("#chan", "#other");
        panel.setChannelUsers("#chan", roster());                       // #chan is tab 0, focused
        panel.setChannelUsers("#other", Collections.singletonList(
                new ChannelUserList.Entry("zoe", "", Integer.MAX_VALUE)));

        assertEquals("still showing #chan's roster", "Users (3)", nickDropdown(panel).getItemAt(0));
    }

    @Test
    public void aRosterPushedWithDifferentChannelCasingStillShows() throws Exception {
        // The tab title comes from a JOIN echo; the roster's channel comes from a 366 numeric.
        // A server that canonicalises those differently must not silently break the dropdown.
        IrcPanel panel = panelWith("#chan");
        panel.setChannelUsers("#CHAN", roster());
        assertEquals("Users (3)", nickDropdown(panel).getItemAt(0));
    }

    @Test
    public void dropdownIsDisabledOnNonChannelBuffers() throws Exception {
        IrcPanel panel = panelWith("System");
        panel.setChannelUsers("System", Collections.emptyList());
        assertFalse(nickDropdown(panel).isEnabled());
    }

    @Test
    public void dropdownEnablementFollowsTheFocusedBuffer() throws Exception {
        // A fresh JComboBox is enabled by default, so only a transition proves setEnabled runs.
        IrcPanel panel = panelWith("System", "#chan");

        panel.setFocusedChannel("System");
        panel.setChannelUsers("System", Collections.emptyList());
        assertFalse("System is not a channel", nickDropdown(panel).isEnabled());

        panel.setFocusedChannel("#chan");
        panel.setChannelUsers("#chan", roster());
        assertTrue("#chan is a channel", nickDropdown(panel).isEnabled());
    }

    @Test
    @SuppressWarnings("unchecked")
    public void aRosterArrivingBeforeTheGuiExistsIsStoredNotDropped() throws Exception {
        // setChannelUsers can arrive from the IRC thread before initializeGui has run. It must
        // skip the redraw without throwing, and still keep the roster for when the GUI catches up.
        IrcPanel panel = new IrcPanel(); // tabbedPane is still null
        panel.setChannelUsers("#chan", roster());

        Field field = IrcPanel.class.getDeclaredField("channelUserSnapshots");
        field.setAccessible(true);
        Map<BufferKey, List<ChannelUserList.Entry>> snapshots =
                (Map<BufferKey, List<ChannelUserList.Entry>>) field.get(panel);

        assertEquals("roster kept despite no GUI to draw it on", 3,
                snapshots.get(BufferKey.swiftIrc("#chan").folded()).size());
    }

    @Test
    public void anEmptyRosterLeavesOnlyTheHeader() throws Exception {
        IrcPanel panel = panelWith("#chan");
        panel.setChannelUsers("#chan", Collections.emptyList());

        JComboBox<String> dropdown = nickDropdown(panel);
        assertEquals(1, dropdown.getItemCount());
        assertEquals("Users (0)", dropdown.getItemAt(0));
    }

    @Test
    public void switchingToAPmBufferClearsAndDisablesTheDropdown() throws Exception {
        // The tab-change hook is the single path every buffer switch routes through, and
        // initializeGui (its only install site) cannot run headless - so drive it directly.
        IrcPanel panel = panelWith("#chan", "bob");
        panel.setFocusedChannel("#chan");
        panel.setChannelUsers("#chan", roster());
        assertEquals("Users (3)", nickDropdown(panel).getItemAt(0));

        panel.setFocusedChannel("bob");
        panel.onFocusedBufferChanged();

        assertEquals("a PM buffer has no roster", "Users (0)", nickDropdown(panel).getItemAt(0));
        assertEquals(1, nickDropdown(panel).getItemCount());
        assertFalse("and the dropdown is not usable there", nickDropdown(panel).isEnabled());
    }
}

package com.irc;

import org.junit.Test;

import javax.swing.JComboBox;
import javax.swing.JTabbedPane;
import java.awt.Color;
import java.lang.reflect.Field;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;

import static org.junit.Assert.*;

/** Buffers and networks can be reordered; the tab, pane, unread flag and dropdown move together. */
public class IrcPanelOrderTest {
    private static final String RIZON = "rizon-id";
    private static final String LIBERA = "libera-id";

    private final List<String> calls = new ArrayList<>();

    private IrcPanel panel() throws Exception {
        IrcPanel panel = new IrcPanel();
        set(panel, "config", new IrcConfig() {
            @Override public String username() { return "tester"; }
            @Override public String password() { return ""; }
        });
        set(panel, "tabbedPane", new JTabbedPane());
        panel.addChannel("System");
        panel.setFocusedChannel("System");
        panel.setNetworkName(RIZON, "Rizon");
        panel.setOrderListener(new IrcPanel.OrderListener() {
            @Override public void networkOrderChanged(List<String> ids) { calls.add("networks " + ids); }
            @Override public void channelOrderChanged(String id, List<String> names) { calls.add("channels " + id + " " + names); }
        });
        return panel;
    }

    private static void set(Object target, String field, Object value) throws Exception {
        Field f = IrcPanel.class.getDeclaredField(field);
        f.setAccessible(true);
        f.set(target, value);
    }

    @SuppressWarnings("unchecked")
    private static <T> T get(Object target, String field) throws Exception {
        Field f = IrcPanel.class.getDeclaredField(field);
        f.setAccessible(true);
        return (T) f.get(target);
    }

    private static List<String> tabTitles(IrcPanel panel) throws Exception {
        JTabbedPane tabs = get(panel, "tabbedPane");
        List<String> titles = new ArrayList<>();
        for (int i = 0; i < tabs.getTabCount(); i++) titles.add(tabs.getTitleAt(i));
        return titles;
    }

    private static List<String> dropdownItems(IrcPanel panel) throws Exception {
        JComboBox<String> dropdown = get(panel, "bufferDropdown");
        List<String> items = new ArrayList<>();
        for (int i = 0; i < dropdown.getItemCount(); i++) items.add(dropdown.getItemAt(i));
        return items;
    }

    private static List<BufferKey> keys(String... names) {
        List<BufferKey> keys = new ArrayList<>();
        for (String name : names) {
            int split = name.indexOf('/');
            keys.add(split < 0 ? BufferKey.swiftIrc(name) : BufferKey.of(name.substring(0, split), name.substring(split + 1)));
        }
        return keys;
    }

    @Test
    public void moveBufferKeepsTabsPanesUnreadAndDropdownInStep() throws Exception {
        IrcPanel panel = panel();
        panel.addChannel("#a");
        panel.addChannel("#b");
        panel.addChannel(BufferKey.of(RIZON, "#c"));
        panel.setFocusedChannel("#b");
        panel.unreadMessages.put(BufferKey.of(RIZON, "#c"), true);
        JTabbedPane tabs = get(panel, "tabbedPane");
        tabs.setForegroundAt(3, Color.CYAN);
        IrcPanel.ChannelPane paneC = panel.getChannelPanes().get(BufferKey.of(RIZON, "#c"));

        panel.moveBuffer(BufferKey.of(RIZON, "#c"), 1);

        assertEquals(keys("System", RIZON + "/#c", "#a", "#b"), panel.getBuffers());
        assertEquals(Arrays.asList("System", "#c (Rizon)", "#a", "#b"), tabTitles(panel));
        assertEquals(tabTitles(panel), dropdownItems(panel));
        assertEquals(new ArrayList<>(panel.getChannelPanes().keySet()), new ArrayList<>(panel.unreadMessages.keySet()));
        assertSame(paneC, ((javax.swing.JScrollPane) tabs.getComponentAt(1)).getViewport().getView());
        assertEquals(Color.CYAN, tabs.getForegroundAt(1));
        assertTrue(panel.unreadMessages.get(BufferKey.of(RIZON, "#c")));
        assertEquals(BufferKey.swiftIrc("#b"), panel.getCurrentBuffer());
        JComboBox<String> dropdown = get(panel, "bufferDropdown");
        assertEquals("#b", dropdown.getSelectedItem());
        assertTrue("a programmatic move does not report itself", calls.isEmpty());
    }

    @Test
    public void networkOrderPutsListedIdsFirstAndKeepsTheRest() throws Exception {
        IrcPanel panel = panel();
        panel.setNetworkName(LIBERA, "Libera");
        panel.setNetworkOrder(Arrays.asList(LIBERA, "unknown", NetworkConfig.SWIFTIRC_ID));
        assertEquals(Arrays.asList(LIBERA, NetworkConfig.SWIFTIRC_ID, RIZON), panel.networkOrder());
        assertTrue(calls.isEmpty());
    }

    @Test
    public void newChannelsTakeTheirSavedPlace() throws Exception {
        IrcPanel panel = panel();
        panel.setChannelOrder(RIZON, Arrays.asList("#c", "#a", "#b"));
        panel.addChannel(BufferKey.of(RIZON, "Luna"));
        panel.addChannel(BufferKey.of(RIZON, "#b"));
        // Before #b, which comes later in the saved order.
        panel.addChannel(BufferKey.of(RIZON, "#A"));
        // Nothing later is open: straight after the network's last channel.
        panel.addChannel("#swift");
        panel.addChannel(BufferKey.of(RIZON, "#zzz"));
        panel.addChannel(BufferKey.of(RIZON, "#c"));
        assertEquals(keys("System", RIZON + "/Luna", RIZON + "/#c", RIZON + "/#A", RIZON + "/#b", "#swift", RIZON + "/#zzz"),
                panel.getBuffers());
        assertEquals(tabTitles(panel), dropdownItems(panel));
        assertEquals(new ArrayList<>(panel.getChannelPanes().keySet()), new ArrayList<>(panel.unreadMessages.keySet()));
        assertTrue(calls.isEmpty());
    }

    @Test
    public void savedChannelGoesAfterTheNetworksLastChannelWhenNothingLaterIsOpen() throws Exception {
        IrcPanel panel = panel();
        panel.setChannelOrder(RIZON, Arrays.asList("#a", "#b"));
        panel.addChannel(BufferKey.of(RIZON, "#a"));
        panel.addChannel("#swift");
        panel.addChannel(BufferKey.of(RIZON, "#b"));
        assertEquals(keys("System", RIZON + "/#a", RIZON + "/#b", "#swift"), panel.getBuffers());
    }

    @Test
    public void withoutASavedOrderNewBuffersAreAppended() throws Exception {
        IrcPanel panel = panel();
        panel.addChannel("#b");
        panel.addChannel("#a");
        panel.addChannel(BufferKey.of(RIZON, "#c"));
        assertEquals(keys("System", "#b", "#a", RIZON + "/#c"), panel.getBuffers());
    }

    @Test
    public void sortChannelsReordersOpenChannelsQuietly() throws Exception {
        IrcPanel panel = panel();
        panel.addChannel("#a");
        panel.addChannel("Luna");
        panel.addChannel("#b");
        panel.addChannel("#other");
        panel.addChannel("#c");
        panel.setFocusedChannel("#b");
        panel.setChannelOrder(NetworkConfig.SWIFTIRC_ID, Arrays.asList("#c", "#b", "#a"));
        panel.sortChannels(NetworkConfig.SWIFTIRC_ID);
        // Listed channels swap among their own slots; unlisted buffers stay put.
        assertEquals(keys("System", "#c", "Luna", "#b", "#other", "#a"), panel.getBuffers());
        assertEquals(tabTitles(panel), dropdownItems(panel));
        assertEquals(BufferKey.swiftIrc("#b"), panel.getCurrentBuffer());
        assertTrue(calls.isEmpty());
    }

    @Test
    public void userMovesReorderAndReportTheNewOrder() throws Exception {
        IrcPanel panel = panel();
        panel.addChannel("#a");
        panel.addChannel("Luna");
        panel.addChannel("#b");
        panel.addChannel("Ash");
        panel.addChannel(BufferKey.of(RIZON, "#c"));

        panel.userMovedBuffer(BufferKey.swiftIrc("#b"), 0);
        assertEquals(keys("System", "#b", "#a", "Luna", "Ash", RIZON + "/#c"), panel.getBuffers());
        panel.userMovedBuffer(BufferKey.swiftIrc("Luna"), 1);
        assertEquals(keys("System", "#b", "#a", "Ash", "Luna", RIZON + "/#c"), panel.getBuffers());
        panel.userMovedNetwork(RIZON, 0);
        assertEquals(Arrays.asList(RIZON, NetworkConfig.SWIFTIRC_ID), panel.networkOrder());

        // Private chats are never saved, so moving one reports nothing.
        assertEquals(Arrays.asList("channels swiftirc [#b, #a]", "networks [rizon-id, swiftirc]"), calls);
    }

    @Test
    public void userMovedChannelIsUsedForLaterJoins() throws Exception {
        IrcPanel panel = panel();
        panel.addChannel("#a");
        panel.addChannel("#b");
        panel.userMovedBuffer(BufferKey.swiftIrc("#b"), 0);
        panel.removeChannel("#a");
        panel.addChannel("#a");
        assertEquals(keys("System", "#b", "#a"), panel.getBuffers());
        panel.removeChannel("#b");
        panel.addChannel("#b");
        assertEquals(keys("System", "#b", "#a"), panel.getBuffers());
    }

    @Test
    public void reorderingToTheSameOrderChangesNothing() throws Exception {
        IrcPanel panel = panel();
        panel.addChannel("#a");
        panel.addChannel("#b");
        panel.setNetworkOrder(Arrays.asList(NetworkConfig.SWIFTIRC_ID, RIZON));
        panel.setChannelOrder(NetworkConfig.SWIFTIRC_ID, Arrays.asList("#a", "#b"));
        panel.sortChannels(NetworkConfig.SWIFTIRC_ID);
        panel.moveBuffer(BufferKey.swiftIrc("#a"), 1);
        assertEquals(keys("System", "#a", "#b"), panel.getBuffers());
        assertEquals(Arrays.asList(NetworkConfig.SWIFTIRC_ID, RIZON), panel.networkOrder());
        assertEquals(Collections.emptyList(), calls);
    }

    @Test
    public void aDragKeepsTheSavedPlaceOfClosedChannels() throws Exception {
        IrcPanel panel = panel();
        panel.setChannelOrder(NetworkConfig.SWIFTIRC_ID, Arrays.asList("#a", "#rshelp", "#b"));
        panel.addChannel("#rshelp");
        panel.addChannel("#b");
        panel.userMovedBuffer(BufferKey.swiftIrc("#b"), 0);
        assertEquals(Collections.singletonList("channels swiftirc [#a, #b, #rshelp]"), calls);
        panel.addChannel("#a");
        assertEquals(keys("System", "#a", "#b", "#rshelp"), panel.getBuffers());
    }

    @Test
    public void insertingBeforeTheSelectedTabKeepsItSelected() throws Exception {
