        assertEquals(BufferKey.swiftIrc("#b"), panel.getCurrentBuffer());
        JComboBox<String> dropdown = get(panel, "bufferDropdown");
        assertEquals("#b", dropdown.getSelectedItem());
        assertEquals(2, dropdown.getSelectedIndex());
    }
}

package com.irc;

import com.google.common.cache.Cache;
import okhttp3.OkHttpClient;
import org.junit.Before;
import org.junit.Test;

import javax.imageio.ImageIO;
import javax.swing.JFrame;
import javax.swing.SwingUtilities;
import javax.swing.event.HyperlinkEvent;
import java.awt.event.MouseEvent;
import java.awt.image.BufferedImage;
import java.io.ByteArrayOutputStream;
import java.lang.reflect.Field;
import java.net.URL;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicReference;

import static org.junit.Assert.assertTrue;

public class IrcPanelPopOutPreviewTest {
    private static final String IMAGE_URL = "https://example.com/preview.png";

    @Before
    public void requiresDesktop() {
        org.junit.Assume.assumeFalse(java.awt.GraphicsEnvironment.isHeadless());
    }

    @Test
    public void previewShowsDocked() throws Exception {
        assertTrue("preview should show docked", previewShown(true, false));
    }

    @Test
    public void previewShowsInPopOutWithSidebarEnabled() throws Exception {
        assertTrue("preview should show in the pop-out", previewShown(true, true));
    }

    @Test
    public void previewShowsInPopOutWithSidebarDisabled() throws Exception {
        assertTrue("preview should show in the pop-out", previewShown(false, true));
    }

    private boolean previewShown(boolean sidebarInWindow, boolean poppedOut) throws Exception {
        AtomicReference<IrcPanel> panelRef = new AtomicReference<>();
        AtomicReference<JFrame> mainRef = new AtomicReference<>();
        SwingUtilities.invokeAndWait(() -> {
            IrcPanel panel = new IrcPanel();
            panelRef.set(panel);
            setField(IrcPanel.class, panel, "config", new IrcConfig() {
                @Override public String username() { return "tester"; }
                @Override public String password() { return ""; }
                @Override public boolean hoverPreviewImages() { return true; }
            });
            setField(IrcPanel.class, panel, "okHttpClient", new OkHttpClient());
            panel.init((channel, text) -> {}, (network, channel, password) -> {}, channel -> {},
                    reconnect -> {}, (network, query) -> {}, () -> {});
            panel.initializeGui();
            if (sidebarInWindow) {
                JFrame main = new JFrame();
                mainRef.set(main);
                main.add(panel.getWrappedPanel());
                main.setSize(260, 600);
                main.setVisible(true);
            }
            panel.addChannel("#test");
        });
        try {
            SwingUtilities.invokeAndWait(() -> {
                IrcPanel panel = panelRef.get();
                panel.setFocusedChannel("#test");
                if (poppedOut) panel.setDetached(true, false);
            });
            // Let window activation events from opening the frames arrive before hovering.
            Thread.sleep(1000);
            SwingUtilities.invokeAndWait(() -> {
                IrcPanel panel = panelRef.get();
                IrcPanel.ChannelPane pane = panel.getPane("#test");
                seedCache(pane);
                try {
                    MouseEvent move = new MouseEvent(pane, MouseEvent.MOUSE_MOVED,
                            System.currentTimeMillis(), 0, 10, 10, 0, false);
                    pane.fireHyperlinkUpdate(new HyperlinkEvent(pane, HyperlinkEvent.EventType.ENTERED,
                            new URL(IMAGE_URL), null, null, move));
                } catch (Exception e) {
                    throw new AssertionError(e);
                }
            });
            long deadline = System.currentTimeMillis() + 3000;
            AtomicBoolean shown = new AtomicBoolean();
            while (System.currentTimeMillis() < deadline) {
                SwingUtilities.invokeAndWait(() -> shown.set(currentPopup(panelRef.get()) != null));
                if (shown.get()) return true;
                Thread.sleep(50);
            }
            return false;
        } finally {
            SwingUtilities.invokeAndWait(() -> {
                panelRef.get().shutdown();
                if (mainRef.get() != null) mainRef.get().dispose();
            });
        }
    }

    @SuppressWarnings("unchecked")
    private static void seedCache(IrcPanel.ChannelPane pane) {
        try {
            BufferedImage image = new BufferedImage(40, 40, BufferedImage.TYPE_INT_RGB);
            ByteArrayOutputStream bytes = new ByteArrayOutputStream();
            ImageIO.write(image, "png", bytes);
            PreviewManager manager = (PreviewManager) getField(IrcPanel.ChannelPane.class, pane, "previewManager");
            ((Cache<String, byte[]>) getField(PreviewManager.class, manager, "imageCache"))
                    .put(IMAGE_URL, bytes.toByteArray());
        } catch (Exception e) {
            throw new AssertionError(e);
        }
    }

    private static Object currentPopup(IrcPanel panel) {
        IrcPanel.ChannelPane pane = panel.getPane("#test");
        PreviewManager manager = (PreviewManager) getField(IrcPanel.ChannelPane.class, pane, "previewManager");
        return getField(PreviewManager.class, manager, "currentImagePreview");
    }

    private static Object getField(Class<?> type, Object target, String name) {
        try {
            Field field = type.getDeclaredField(name);
            field.setAccessible(true);
            return field.get(target);
        } catch (ReflectiveOperationException e) {
            throw new AssertionError(e);
        }
    }

    private static void setField(Class<?> type, Object target, String name, Object value) {
        try {
            Field field = type.getDeclaredField(name);
            field.setAccessible(true);
            field.set(target, value);
        } catch (ReflectiveOperationException e) {
            throw new AssertionError(e);
        }
    }
}

package com.irc;

import org.junit.Test;
import org.junit.Before;

import javax.swing.JFrame;
import javax.swing.SwingUtilities;
import java.lang.reflect.Field;
import java.time.Instant;
import java.util.Collections;
import java.util.concurrent.atomic.AtomicReference;

import static org.junit.Assert.*;

public class IrcPanelPopOutTest {
    @Before
    public void requiresDesktop() {
        org.junit.Assume.assumeFalse(java.awt.GraphicsEnvironment.isHeadless());
    }

    @Test
    public void actualChatSendsInBothHostsAndBrowserFollowsItsOwner() throws Exception {
        AtomicReference<IrcPanel> panelRef = new AtomicReference<>();
        AtomicReference<JFrame> mainRef = new AtomicReference<>();
        AtomicReference<String> sent = new AtomicReference<>();
        SwingUtilities.invokeAndWait(() -> {
            IrcPanel panel = new IrcPanel();
            panelRef.set(panel);
            setField(panel, "config", new IrcConfig() {
                @Override public String username() { return "tester"; }
                @Override public String password() { return ""; }
            });
            panel.init((channel, text) -> sent.set(channel + ":" + text),
                    (network, channel, password) -> {}, channel -> {}, reconnect -> {}, (network, query) -> {}, () -> {});
            panel.initializeGui();
            JFrame main = new JFrame();
            mainRef.set(main);
            main.add(panel.getWrappedPanel());
            main.setSize(260, 600);
            main.setVisible(true);
            panel.addChannel("#test");
            panel.setFocusedChannel("#test");
            panel.addMessage(new IrcMessage("#test", "tester", "test scrollback",
                    IrcMessage.MessageType.CHAT, Instant.now()));
        });
        try {
            SwingUtilities.invokeAndWait(() -> {
                IrcPanel panel = panelRef.get();
                // initializeGui queues the System tab; select after that startup work completes.
                panel.setFocusedChannel("#test");
                IrcPanel.ChannelPane original = panel.getPane("#test");
                assertTrue(original.getText().contains("test scrollback"));
                panel.inputField.setText("my draft");
                panel.showChannelList(Collections.emptyList(), "", false);
                ChannelListDialog dockedBrowser = getBrowser(panel);
                assertSame(mainRef.get(), dockedBrowser.getOwner());

                panel.setDetached(true, false);
                JFrame popOut = (JFrame) SwingUtilities.getWindowAncestor(panel.getChatContent());
                assertNotSame(mainRef.get(), popOut);
                assertTrue(popOut.isVisible());
                assertFalse(dockedBrowser.isDisplayable());
                assertEquals("my draft", panel.inputField.getText());
                assertEquals("#test", panel.getCurrentChannel());
                assertSame(original, panel.getPane("#test"));
                panel.inputField.postActionEvent();
                assertEquals("#test:my draft", sent.get());
                assertEquals("", panel.inputField.getText());

                panel.showChannelList(Collections.emptyList(), "", false);
                ChannelListDialog floatingBrowser = getBrowser(panel);
                assertSame(popOut, floatingBrowser.getOwner());
                panel.setDetached(false, false);
                assertFalse(floatingBrowser.isDisplayable());
                assertFalse(popOut.isDisplayable());
                assertSame(mainRef.get(), SwingUtilities.getWindowAncestor(panel.getChatContent()));
                panel.inputField.setText("docked message");
                panel.inputField.postActionEvent();
                assertEquals("#test:docked message", sent.get());
                assertTrue(original.getText().contains("test scrollback"));
            });
        } finally {
            SwingUtilities.invokeAndWait(() -> {
                panelRef.get().shutdown();
                mainRef.get().dispose();
            });
        }
    }

    private static void setField(IrcPanel panel, String name, Object value) {
        try {
            Field field = IrcPanel.class.getDeclaredField(name);
            field.setAccessible(true);
            field.set(panel, value);
        } catch (ReflectiveOperationException e) {
            throw new AssertionError(e);
        }
    }

    private static ChannelListDialog getBrowser(IrcPanel panel) {
        try {
            Field field = IrcPanel.class.getDeclaredField("channelListDialog");
            field.setAccessible(true);
            return (ChannelListDialog) field.get(panel);
        } catch (ReflectiveOperationException e) {
            throw new AssertionError(e);
        }
    }
}

package com.irc;

import org.junit.Test;

import javax.swing.JComboBox;
import javax.swing.JPanel;
import javax.swing.JTabbedPane;
import java.lang.reflect.Field;
import java.util.List;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;

/**
 * Regression tests for renameChannel keeping every ordered UI structure consistent.
 *
 * Navigation maps a channel to a tab strictly by POSITION: setFocusedChannel computes
 * an index by iterating channelPanes, then calls tabbedPane.setSelectedIndex(index),
 * while getCurrentChannel()/getChannelNames() read the tab titles. That only works if
 * the channelPanes iteration order stays identical to the tabbedPane tab order.
 *
 * renameChannel() renamed the tab in place but did remove()+put() on the LinkedHashMap,
 * which moved the renamed channel to the END of the iteration order - diverging the two
 * orderings and sending navigation to the wrong tab. The bufferDropdown was also left with
 * the stale old label. A NICK change (e.g. a renamed query window) triggers this normally.
 */
public class IrcPanelRenameTest {

    private static JTabbedPane installTabbedPane(IrcPanel panel) throws Exception {
        JTabbedPane tabs = new JTabbedPane();
        Field tabbedPaneField = IrcPanel.class.getDeclaredField("tabbedPane");
        tabbedPaneField.setAccessible(true);
        tabbedPaneField.set(panel, tabs);
        return tabs;
    }

    @SuppressWarnings("unchecked")
    private static JComboBox<String> bufferDropdown(IrcPanel panel) throws Exception {
        Field field = IrcPanel.class.getDeclaredField("bufferDropdown");
        field.setAccessible(true);
        return (JComboBox<String>) field.get(panel);
    }

    private static void addChannel(IrcPanel panel, JTabbedPane tabs, JComboBox<String> dropdown, String name) {
        panel.getChannelPanes().put(BufferKey.swiftIrc(name), null);
        panel.unreadMessages.put(BufferKey.swiftIrc(name), false);
        tabs.addTab(name, new JPanel());
        if (dropdown != null) {
            dropdown.addItem(name);
        }
    }

    @Test
    public void renameKeepsChannelOrderAlignedWithTabs() throws Exception {
        IrcPanel panel = new IrcPanel();
        JTabbedPane tabs = installTabbedPane(panel);

        addChannel(panel, tabs, null, "System");
        addChannel(panel, tabs, null, "#alpha");
        addChannel(panel, tabs, null, "bob");
        addChannel(panel, tabs, null, "#gamma");

        // A NICK change renames a query window in place: bob -> bob2 (originally at index 2).
        panel.renameChannel("bob", "bob2");

        List<String> channelOrder = panel.getChannelNames();
        assertEquals("tab count and channel count must match", tabs.getTabCount(), channelOrder.size());
        for (int i = 0; i < tabs.getTabCount(); i++) {
            assertEquals("channelPanes order must match tab order at index " + i,
                    tabs.getTitleAt(i), channelOrder.get(i));
        }
        // The renamed channel must keep its position, not jump to the end.
        assertEquals("bob2", channelOrder.get(2));
    }

    @Test
    public void renameUpdatesBufferDropdownLabelInPlace() throws Exception {
        IrcPanel panel = new IrcPanel();
        JTabbedPane tabs = installTabbedPane(panel);
        JComboBox<String> dropdown = bufferDropdown(panel);

        addChannel(panel, tabs, dropdown, "System");
        addChannel(panel, tabs, dropdown, "#alpha");
        addChannel(panel, tabs, dropdown, "bob");
        addChannel(panel, tabs, dropdown, "#gamma");
        dropdown.setSelectedIndex(2); // "bob" is the active buffer

        panel.renameChannel("bob", "bob2");

        // The label is replaced in place: new label at the same index, old label gone.
        assertEquals("bob2", dropdown.getItemAt(2));
        for (int i = 0; i < dropdown.getItemCount(); i++) {
            assertNotEquals("stale old label must be gone", "bob", dropdown.getItemAt(i));
        }
        // Order preserved (matches tabs) and the active selection stays on the renamed buffer.
        for (int i = 0; i < tabs.getTabCount(); i++) {
            assertEquals(tabs.getTitleAt(i), dropdown.getItemAt(i));
        }
        assertEquals(2, dropdown.getSelectedIndex());
    }
}

package com.irc;

import org.junit.Test;

import javax.swing.SwingUtilities;
import javax.swing.text.Document;
import java.awt.Font;
import java.time.Instant;
import java.util.concurrent.atomic.AtomicReference;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * HTML collapses a run of spaces to one, which flattened ASCII art and aligned text. Every space
 * in a run but the last becomes a no-break space, so the spacing survives and the trailing plain
 * space still lets a long line wrap.
 */
public class IrcPanelSpacingTest {

    private static final IrcConfig CONFIG = new IrcConfig() {
        @Override public String username() { return "tester"; }
        @Override public String password() { return ""; }
        @Override public boolean timestamp() { return false; }
        @Override public boolean colorizedNicks() { return false; }
    };

    /** The pane's visible text for one chat line, once its render has run. */
    private static String rendered(String content) throws Exception {
        AtomicReference<IrcPanel.ChannelPane> paneRef = new AtomicReference<>();
        SwingUtilities.invokeAndWait(() -> {
            IrcPanel.ChannelPane pane = new IrcPanel.ChannelPane(new Font("SansSerif", Font.PLAIN, 12), CONFIG, null);
            pane.appendMessage(new IrcMessage("#c", "bob", content, IrcMessage.MessageType.CHAT, Instant.now()), CONFIG);
            paneRef.set(pane);
        });
        SwingUtilities.invokeAndWait(() -> { });
        AtomicReference<String> text = new AtomicReference<>();
        SwingUtilities.invokeAndWait(() -> {
            try {
                Document doc = paneRef.get().getDocument();
                text.set(doc.getText(0, doc.getLength()));
            } catch (Exception e) {
                throw new RuntimeException(e);
            }
        });
        return text.get();
    }

    @Test
    public void aRunOfSpacesKeepsItsWidth() throws Exception {
        assertTrue(rendered("a   b").contains("a   b"));
    }

    @Test
    public void singleSpacesAreUntouched() {
        assertEquals("one two three", IrcPanel.ChannelPane.keepSpaceRuns("one two three"));
    }

    /** Every run ends in a plain space, so there is still somewhere to wrap. */
    @Test
    public void everyRunStillEndsInABreakableSpace() {
        assertEquals("a&nbsp;&nbsp; b&nbsp; c", IrcPanel.ChannelPane.keepSpaceRuns("a   b  c"));
    }

    @Test
    public void tagsAreLeftAlone() {
        String html = "<font style=\"color:red\">x  y</font>  <a href=\"https://e.com\">https://e.com</a>";
        assertEquals("<font style=\"color:red\">x&nbsp; y</font>&nbsp; <a href=\"https://e.com\">https://e.com</a>",
                IrcPanel.ChannelPane.keepSpaceRuns(html));
    }

    @Test
    public void aLinkBeforeARunStopsAtTheUrl() throws Exception {
        AtomicReference<IrcPanel.ChannelPane> paneRef = new AtomicReference<>();
        SwingUtilities.invokeAndWait(() -> {
            IrcPanel.ChannelPane pane = new IrcPanel.ChannelPane(new Font("SansSerif", Font.PLAIN, 12), CONFIG, null);
            pane.appendMessage(new IrcMessage("#c", "bob", "see https://example.com/x   next",
                    IrcMessage.MessageType.CHAT, Instant.now()), CONFIG);
            paneRef.set(pane);
        });
        SwingUtilities.invokeAndWait(() -> { });
        AtomicReference<String> html = new AtomicReference<>();
        SwingUtilities.invokeAndWait(() -> html.set(paneRef.get().getText()));
        assertTrue(html.get(), html.get().contains("href=\"https://example.com/x\""));
        assertTrue(rendered("see https://example.com/x   next").contains("https://example.com/x   next"));
    }

    @Test
    public void runsNextToColorCodesKeepTheirWidth() throws Exception {
        String text = rendered("\u000304red\u000f   plain");
        assertTrue(text, text.contains("red   plain"));
    }
}

package com.irc;

import org.junit.Test;

import javax.swing.JTabbedPane;
import java.lang.reflect.Field;
import java.time.Instant;

import static com.irc.IrcMessage.MessageType.*;
import static org.junit.Assert.*;

/** Which messages mark a channel that isn't being looked at as unread. */
public class IrcPanelUnreadTest {
    private static IrcPanel panel(boolean quietConnectionMessages) throws Exception {
        IrcPanel panel = new IrcPanel();
        set(panel, "config", new IrcConfig() {
            @Override public String username() { return "tester"; }
            @Override public String password() { return ""; }
            @Override public boolean quietConnectionMessages() { return quietConnectionMessages; }
        });
        set(panel, "tabbedPane", new JTabbedPane());
        panel.addChannel("System");
        panel.addChannel("#a");
        // The second buffer takes focus; look away so #a can go unread.
        panel.setFocusedChannel("System");
        return panel;
    }

    private static void set(Object target, String field, Object value) throws Exception {
        Field f = IrcPanel.class.getDeclaredField(field);
        f.setAccessible(true);
        f.set(target, value);
    }

    private static void add(IrcPanel panel, IrcMessage.MessageType type) {
        panel.addMessage(new IrcMessage("#a", "Ash", "x", type, Instant.now()));
    }

    @Test
    public void quietByDefault() {
        assertTrue(new IrcConfig() {
            @Override public String username() { return "tester"; }
            @Override public String password() { return ""; }
        }.quietConnectionMessages());
    }

    @Test
    public void connectionMessagesLeaveAChannelReadWhenQuiet() throws Exception {
        IrcPanel panel = panel(true);
        for (IrcMessage.MessageType type : new IrcMessage.MessageType[]{JOIN, PART, QUIT, KICK, NICK_CHANGE, MODE}) {
            add(panel, type);
            assertFalse(type + " marked the channel unread", panel.isUnread("#a"));
        }
        add(panel, CHAT);
        assertTrue("conversation still marks it unread", panel.isUnread("#a"));
    }

    @Test
    public void connectionMessagesMarkAChannelUnreadWhenNotQuiet() throws Exception {
        for (IrcMessage.MessageType type : new IrcMessage.MessageType[]{JOIN, PART, QUIT, KICK, NICK_CHANGE, MODE}) {
            IrcPanel panel = panel(false);
            add(panel, type);
            assertTrue(type + " should mark the channel unread", panel.isUnread("#a"));
        }
    }

    /** Only channel modes are quiet; your own user modes still mark the System buffer. */
    @Test
    public void userModesStillMarkSystemUnread() throws Exception {
        IrcPanel panel = panel(true);
        panel.setFocusedChannel("#a");
        panel.addMessage(new IrcMessage("System", "tester", "+i", MODE, Instant.now()));
        assertTrue(panel.isUnread("System"));
    }
}

