import java.util.concurrent.atomic.AtomicReference;

import static org.junit.Assert.*;

/** Desktop tests with real Swing windows; no IRC connection or RuneLite login is needed. */
public class IrcPanelWindowTest {
    @Before
    public void requiresDesktop() {
        org.junit.Assume.assumeFalse(java.awt.GraphicsEnvironment.isHeadless());
    }

    @Test
    public void switchingHostsPreservesChatAndResizeFillsWindow() throws Exception {
        SwingUtilities.invokeAndWait(() -> {
            JPanel dock = new JPanel(new BorderLayout());
            JPanel content = new JPanel(new BorderLayout());
            JTextField draft = new JTextField("unfinished message");
            JTabbedPane tabs = new JTabbedPane();
            JTextArea history = new JTextArea("older message\nlatest message");
            tabs.addTab("System", new JPanel());
            tabs.addTab("#test", new JScrollPane(history));
            tabs.setSelectedIndex(1);
            content.add(tabs, BorderLayout.CENTER);
            content.add(draft, BorderLayout.SOUTH);
            dock.add(content, BorderLayout.CENTER);
            IrcPanelWindow host = new IrcPanelWindow(dock, content, () -> {}, () -> {}, () -> {});
            try {
                for (int i = 0; i < 3; i++) {
                    host.setDetached(true, false);
                    JFrame frame = (JFrame) SwingUtilities.getWindowAncestor(content);
                    assertTrue(frame.isVisible());
                    assertEquals(0, dock.getComponentCount());
                    frame.setSize(620, 680);
                    frame.validate();
                    assertEquals(frame.getContentPane().getWidth(), content.getWidth());
                    assertEquals(frame.getContentPane().getHeight(), content.getHeight());
                    assertEquals(1, tabs.getSelectedIndex());
                    assertEquals("unfinished message", draft.getText());
                    assertEquals("older message\nlatest message", history.getText());
                    host.setDetached(true, true);
                    assertSame(frame, SwingUtilities.getWindowAncestor(content));
                    assertTrue(frame.isAlwaysOnTop());
                    host.setDetached(false, false);
                    assertSame(dock, content.getParent());
                    assertFalse(frame.isDisplayable());
                }
            } finally {
                host.shutdown();
            }
        });
    }

    @Test
    public void closeRequestsDockAndShutdownRemovesWindowListeners() throws Exception {
        SwingUtilities.invokeAndWait(() -> {
            JFrame main = new JFrame();
            JPanel dock = new JPanel(new BorderLayout());
            JPanel content = new JPanel();
            dock.add(content, BorderLayout.CENTER);
            main.add(dock);
            main.setSize(300, 400);
            main.setVisible(true);
            int focusListeners = main.getWindowFocusListeners().length;
            int componentListeners = main.getComponentListeners().length;
            AtomicInteger dockRequests = new AtomicInteger();
            IrcPanelWindow host = new IrcPanelWindow(dock, content, () -> {}, () -> {},
                    dockRequests::incrementAndGet);
            try {
                assertEquals(focusListeners + 1, main.getWindowFocusListeners().length);
                host.setDetached(true, false);
                JFrame popOut = (JFrame) SwingUtilities.getWindowAncestor(content);
                assertEquals(focusListeners, main.getWindowFocusListeners().length);
                popOut.dispatchEvent(new WindowEvent(popOut, WindowEvent.WINDOW_CLOSING));
                assertEquals(1, dockRequests.get());
                // The config event performs the actual docking, not JFrame's close operation.
                host.setDetached(false, false);
                assertSame(dock, content.getParent());
                host.setDetached(true, false);
                JFrame reopened = (JFrame) SwingUtilities.getWindowAncestor(content);
                Rectangle bounds = reopened.getBounds();
                host.setDetached(false, false);
                host.setDetached(true, false);
                JFrame restored = (JFrame) SwingUtilities.getWindowAncestor(content);
                assertEquals(bounds, restored.getBounds());
                host.shutdown();
                assertFalse(restored.isDisplayable());
                assertEquals(focusListeners, main.getWindowFocusListeners().length);
                assertEquals(componentListeners, main.getComponentListeners().length);
                host.shutdown();
            } finally {
                host.shutdown();
                main.dispose();
            }
        });
    }

    @Test
    public void geometryIsSavedAndRestoredAcrossRestarts() throws Exception {
        AtomicReference<String> config = new AtomicReference<>();
        Rectangle moved = new Rectangle(120, 80, 700, 500);
        SwingUtilities.invokeAndWait(() -> {
            JPanel dock = new JPanel(new BorderLayout());
            JPanel content = new JPanel();
            dock.add(content, BorderLayout.CENTER);
            IrcPanelWindow host = new IrcPanelWindow(dock, content, () -> {}, () -> {}, () -> {},
                    config::get, config::set);
            try {
                host.setDetached(true, false);
                SwingUtilities.getWindowAncestor(content).setBounds(moved);
                // Docking saves at once rather than waiting for the move to settle.
                host.setDetached(false, false);
                PopOutGeometry saved = PopOutGeometry.parse(config.get());
                assertNotNull(config.get(), saved);
                assertFalse(saved.maximized);
            } finally {
                host.shutdown();
            }
        });
        Rectangle savedBounds = PopOutGeometry.parse(config.get()).bounds;
        SwingUtilities.invokeAndWait(() -> {
            // A new IrcPanelWindow, as after RuneLite restarts, reading the same config.
            JPanel dock = new JPanel(new BorderLayout());
            JPanel content = new JPanel();
            dock.add(content, BorderLayout.CENTER);
            IrcPanelWindow host = new IrcPanelWindow(dock, content, () -> {}, () -> {}, () -> {},
                    config::get, config::set);
            try {
                host.setDetached(true, false);
                assertEquals(savedBounds, SwingUtilities.getWindowAncestor(content).getBounds());
            } finally {
                host.shutdown();
            }
        });
    }

    @Test
    public void unusableSavedGeometryFallsBackToTheDefault() throws Exception {
        SwingUtilities.invokeAndWait(() -> {
            JPanel dock = new JPanel(new BorderLayout());
            JPanel content = new JPanel();
            dock.add(content, BorderLayout.CENTER);
            AtomicReference<String> config = new AtomicReference<>("-99999,-99999,700,500");
            IrcPanelWindow host = new IrcPanelWindow(dock, content, () -> {}, () -> {}, () -> {},
                    config::get, config::set);
            try {
                host.setDetached(true, false);
                Rectangle bounds = SwingUtilities.getWindowAncestor(content).getBounds();
                assertEquals(960, bounds.width);
                assertEquals(620, bounds.height);
            } finally {
                host.shutdown();
            }
        });
    }
}

package com.irc;

import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.ClientUI;
import org.junit.Test;

import javax.swing.JTabbedPane;
import javax.swing.SwingUtilities;
import javax.swing.Timer;
import java.lang.reflect.Constructor;
import java.lang.reflect.Field;
import java.lang.reflect.InvocationHandler;
import java.lang.reflect.Method;
import java.lang.reflect.Proxy;
import java.util.Map;
import java.util.concurrent.atomic.AtomicInteger;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * The plugin's half of the channel browser: the order it arms the response timeout in, how it
 * reports that timeout, and what it releases when it shuts down.
 *
 * IrcPlugin is normally built by Guice. Only three of its injected fields are reached on this path
 * - the RuneLite Client, the config and the panel - so they are set directly, and the Client is a
 * dynamic proxy because the real one is an interface with hundreds of methods of which exactly one
 * is called here.
 */
public class IrcPluginChannelListTest {

    private static IrcConfig stubConfig() {
        // IrcConfig has two abstract methods; everything else is a default.
        return new IrcConfig() {
            @Override
            public String username() {
                return "tester";
            }

            @Override
            public String password() {
                return "";
            }
        };
    }

    /**
     * Stands in for the RuneLite client and counts the one question the plugin asks it.
     *
     * That count is the signal two of these tests lean on: {@code getGameState()} is consulted by
     * {@code IrcPlugin.processMessage} and by nothing else reachable from here, so a non-zero count
     * means a message went through processMessage - the single funnel that feeds the game chatbox
     * as well as the panel - rather than being written straight into the panel.
     *
     * LOGIN_SCREEN keeps the chatbox branch itself out of the way: actually queueing a chat message
     * would need a ChatMessageManager, a RuneLite service with no usable constructor. Reaching the
     * gate is what is being asserted.
     */
    private static final class GameStateProbe implements InvocationHandler {
        final AtomicInteger gameStateQueries = new AtomicInteger();

        @Override
        public Object invoke(Object proxy, Method method, Object[] args) {
            switch (method.getName()) {
                case "getGameState":
                    gameStateQueries.incrementAndGet();
                    return GameState.LOGIN_SCREEN;
                case "hashCode":
                    return System.identityHashCode(proxy);
                case "equals":
                    return proxy == args[0];
                case "toString":
                    return "GameStateProbe";
                default:
                    throw new AssertionError("unexpected call to the RuneLite client: " + method);
            }
        }
    }

    private static Client clientProxy(GameStateProbe probe) {
        return (Client) Proxy.newProxyInstance(
                Client.class.getClassLoader(), new Class<?>[]{Client.class}, probe);
    }

    /** Same headless construction as IrcPanelChannelListTest: no Window, but real panes. */
    private static <T extends IrcPanel> T dressPanel(T panel) throws Exception {
        setField(IrcPanel.class, panel, "config", stubConfig());
        setField(IrcPanel.class, panel, "tabbedPane", new JTabbedPane());
        panel.addChannel("System");
        panel.setFocusedChannel("System");
        return panel;
    }

    private static void setField(Class<?> owner, Object target, String name, Object value) throws Exception {
        Field field = owner.getDeclaredField(name);
        field.setAccessible(true);
        field.set(target, value);
    }

    private static Object getField(Class<?> owner, Object target, String name) throws Exception {
        Field field = owner.getDeclaredField(name);
        field.setAccessible(true);
        return field.get(target);
    }

    /**
     * Drains the EDT twice. A message reaches a pane through two hops of invokeLater - the
     * plugin's processMessage queues panel.addMessage, and ChannelPane.appendMessage queues the
     * document edit - so a single drain runs the first hop and only enqueues the second. Draining
     * once would make every "the pane must NOT contain X" assertion pass vacuously.
     */
    private static void drainEdt() throws Exception {
        SwingUtilities.invokeAndWait(() -> { });
        SwingUtilities.invokeAndWait(() -> { });
    }

    private static Method privateMethod(String name, Class<?>... types) throws Exception {
        Method method = IrcPlugin.class.getDeclaredMethod(name, types);
        method.setAccessible(true);
        return method;
    }

    private static IrcPlugin pluginWith(IrcPanel panel, IrcAdapter adapter, GameStateProbe probe) throws Exception {
        IrcPlugin plugin = new IrcPlugin();
        setField(IrcPlugin.class, plugin, "config", stubConfig());
        setField(IrcPlugin.class, plugin, "client", clientProxy(probe));
        setField(IrcPlugin.class, plugin, "panel", panel);
        NetworkManager networks = new NetworkManager(new NetworkManager.Connector() {
            @Override public IrcAdapter open(NetworkConfig network) { throw new AssertionError("no real connections"); }
            @Override public void close(IrcAdapter a, NetworkConfig network, boolean removed, String reason) { a.disconnect(reason); }
        });
        networks.register(NetworkConfig.swiftIrc(stubConfig()), adapter);
        setField(IrcPlugin.class, plugin, "networks", networks);
        return plugin;
    }

    /** Records that the timeout was armed, without starting a real 30 second Swing Timer. */
    private static class ProbePanel extends IrcPanel {
        volatile boolean armed;
        volatile boolean tornDown;

        @Override
        public void armChannelListTimeout() {
            armed = true;
        }

        @Override
        public void shutdown() {
            tornDown = true;
        }
    }

    /**
     * Answers "was the timeout already armed at the moment the LIST hit the wire?".
     *
     * requestChannelList stands in for the real write-and-flush and drains the EDT before looking,
     * so anything the plugin queued with invokeLater beforehand has already run and anything queued
     * afterwards has not.
     */
    private static class WireProbeAdapter extends IrcAdapter {
        private final ProbePanel probePanel;
        volatile boolean sent;
        volatile boolean armedWhenSent;
        volatile boolean panelCleared;
        volatile boolean connected = true;

        WireProbeAdapter(ProbePanel probePanel) {
            this.probePanel = probePanel;
        }

        @Override
        public boolean isConnected() {
            return connected;
        }

        @Override
        public void requestChannelList(String query) {
            sent = true;
            try {
                SwingUtilities.invokeAndWait(() -> { });
            } catch (Exception e) {
                throw new AssertionError(e);
            }
            armedWhenSent = probePanel.armed;
        }

        @Override
        public void clearPanel() {
            panelCleared = true;
        }

        @Override
        public void disconnect(String reason) {
            // No socket in a unit test.
        }
    }

    /**
     * Whole-branch review finding (arm-after-send inversion): sendRawLine writes and flushes
     * synchronously, so arming afterwards left a window in which a 323 round-trips, queues its
     * cancel first, and the arm then lands on top of it - firing "no response" over a list the
     * user is already reading. Hoisting the arm above the send closes it.
     *
     * Not reachable over a real network (one invokeLater against a round trip), which is exactly
     * why the ordering needs pinning rather than trusting.
     */
    @Test
    public void theTimeoutIsArmedBeforeTheListGoesOnTheWire() throws Exception {
        ProbePanel panel = dressPanel(new ProbePanel());
        WireProbeAdapter adapter = new WireProbeAdapter(panel);
        IrcPlugin plugin = pluginWith(panel, adapter, new GameStateProbe());

        privateMethod("handleChannelListRequest", String.class, String.class).invoke(plugin, NetworkConfig.SWIFTIRC_ID, ">50");
        drainEdt();

        assertTrue("the request must reach the adapter", adapter.sent);
        assertTrue("the timeout must already be armed when the LIST is written",
                adapter.armedWhenSent);
    }

    /** An unconnected /list says so, sends nothing and arms nothing. */
    @Test
    public void anUnconnectedRequestNeitherSendsNorArms() throws Exception {
        ProbePanel panel = dressPanel(new ProbePanel());
        WireProbeAdapter adapter = new WireProbeAdapter(panel);
        adapter.connected = false;
        IrcPlugin plugin = pluginWith(panel, adapter, new GameStateProbe());

        privateMethod("handleChannelListRequest", String.class, String.class).invoke(plugin, NetworkConfig.SWIFTIRC_ID, "");
        drainEdt();

        assertFalse(adapter.sent);
        assertFalse(panel.armed);

        assertTrue("the user has to be told why nothing happened",
                panel.getPane("System").getText().toLowerCase().contains("not connected"));
    }

    /**
     * Whole-branch review finding: the 30 second timeout notice was the only channel-list message
     * that skipped the game chatbox. The request announces itself through processMessage (chatbox
     * and panel) and a 263 refusal does too, but the expiry called panel.addMessage directly - so a
     * user watching game chat with the sidebar collapsed saw the request and never its outcome.
     *
     * The plugin now owns emitting it. Two things are pinned: the notice still reaches the panel,
     * and getGameState() was consulted while producing it - which only happens inside
     * processMessage. Reinstating the direct panel write leaves the first assertion passing and
     * fails the second.
     */
    @Test
    public void theTimeoutNoticeGoesThroughTheSharedMessagePath() throws Exception {
        IrcPanel panel = dressPanel(new IrcPanel());
        GameStateProbe probe = new GameStateProbe();
        IrcPlugin plugin = pluginWith(panel, null, probe);

        // setupPanel wires exactly this callback; it cannot be called here because it also builds
        // the panel's Swing GUI, so the same method reference is bound by hand.
        Method report = privateMethod("reportChannelListTimeout");
        panel.init(null, null, null, null, null, () -> {
            try {
                report.invoke(plugin);
            } catch (Exception e) {
                throw new AssertionError(e);
            }
        });

        panel.armChannelListTimeout();
        probe.gameStateQueries.set(0);

        Timer timer = (Timer) getField(IrcPanel.class, panel, "channelListTimeout");
        for (java.awt.event.ActionListener listener : timer.getActionListeners()) {
            listener.actionPerformed(null);
        }
        panel.cancelChannelListTimeout();
        drainEdt();

        String text = panel.getPane("System").getText();
        assertTrue("the panel must still see the notice, got: " + text,
                text.toLowerCase().contains("no channel list response"));
        assertTrue("the notice must be emitted through processMessage, the same funnel that queues"
                        + " it to the game chatbox",
                probe.gameStateQueries.get() > 0);
    }

    /**
     * Whole-branch review finding: the browser outlived the plugin. shutDown() dropped the panel
     * reference but disposed nothing, so the JDialog stayed on screen with Refresh and Join both
     * returning silently; and the adapter kept its own panel reference, so a 323 arriving during
     * teardown could still pop the browser for a plugin that was already gone.
     */
    @Test
    public void shutdownTearsDownThePanelAndCutsTheAdapterLoose() throws Exception {
        ProbePanel panel = dressPanel(new ProbePanel());
        WireProbeAdapter adapter = new WireProbeAdapter(panel);
        IrcPlugin plugin = pluginWith(panel, adapter, new GameStateProbe());
        setField(IrcPlugin.class, plugin, "clientToolbar", clientToolbar());

        privateMethod("shutDown").invoke(plugin);
        drainEdt();

        assertTrue("the panel must be torn down, not merely dereferenced", panel.tornDown);
        assertTrue("the adapter must lose its panel reference before the panel goes",
                adapter.panelCleared);
        assertNull("and only then is the panel dropped",
                getField(IrcPlugin.class, plugin, "panel"));
        assertNull(getField(IrcPlugin.class, plugin, "networks"));
    }

    /**
     * ClientToolbar's only constructor is private and takes a ClientUI. shutDown() hands it the
     * panel's navigation button, which is null on a panel that never built its GUI, and the real
     * method marshals that onto the EDT - so an instance with no ClientUI gets through.
     */
    private static ClientToolbar clientToolbar() throws Exception {
        Constructor<ClientToolbar> constructor =
                ClientToolbar.class.getDeclaredConstructor(ClientUI.class);
        constructor.setAccessible(true);
        return constructor.newInstance((ClientUI) null);
    }
}

package com.irc;

import net.runelite.client.chat.ChatColorType;
import net.runelite.client.chat.ChatMessageBuilder;
import net.runelite.client.util.Text;
import org.junit.Test;

import java.awt.Color;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The in-game chat box colour is opt-in. Off, messages keep RuneLite's own chat colours (the
 * NORMAL colour type, which the Chat Colour plugin controls); on, they get the chosen colour.
 */
public class IrcPluginChatboxColorTest {

    private static IrcConfig config(boolean enabled, Color color) {
        return config(enabled, color, false);
    }

    private static IrcConfig config(boolean enabled, Color color, boolean ircColors) {
        return new IrcConfig() {
            @Override public String username() { return "tester"; }
            @Override public String password() { return ""; }
            @Override public boolean inGameTextColorEnabled() { return enabled; }
            @Override public Color inGameTextColor() { return color; }
            @Override public boolean ircColorsInGame() { return ircColors; }
        };
    }

    private static final IrcConfig IRC_COLORS = config(false, null, true);

    private static ChatMessageBuilder normal() {
        return new ChatMessageBuilder().append(ChatColorType.NORMAL);
    }

    @Test
    public void offByDefault() {
        IrcConfig defaults = new IrcConfig() {
            @Override public String username() { return "tester"; }
            @Override public String password() { return ""; }
        };
        assertFalse(defaults.inGameTextColorEnabled());
    }

    @Test
    public void disabledKeepsRuneLiteChatColours() {
        String expected = new ChatMessageBuilder().append(ChatColorType.NORMAL).append("hello").build();
        assertEquals(expected, IrcPlugin.chatboxMessage("hello", config(false, Color.RED)));
    }

    @Test
    public void enabledUsesTheChosenColour() {
        assertEquals("<col=123456>hello</col>", IrcPlugin.chatboxMessage("hello", config(true, new Color(0x12, 0x34, 0x56))));
    }

    @Test
    public void enabledWithNoColourFallsBackToRuneLiteChatColours() {
        String expected = new ChatMessageBuilder().append(ChatColorType.NORMAL).append("hello").build();
        assertEquals(expected, IrcPlugin.chatboxMessage("hello", config(true, null)));
    }

    @Test
    public void ircColoursOnByDefault() {
        IrcConfig defaults = new IrcConfig() {
            @Override public String username() { return "tester"; }
            @Override public String password() { return ""; }
        };
        assertTrue(defaults.ircColorsInGame());
    }

    @Test
    public void ircColoursOffStripsTheCodes() {
        assertEquals(normal().append("red plain").build(),
                IrcPlugin.chatboxMessage("\u00034red\u000F plain", config(false, null)));
    }

    @Test
    public void ircColourBecomesAColTag() {
        assertEquals(new ChatMessageBuilder().append(new Color(0xFF0000), "red").build(),
                IrcPlugin.chatboxMessage("\u00034red", IRC_COLORS));
    }

    @Test
    public void resetReturnsToTheBaseColour() {
        String expected = new ChatMessageBuilder().append(new Color(0xFF0000), "red")
                .append(ChatColorType.NORMAL).append(" plain").build();
        assertEquals(expected, IrcPlugin.chatboxMessage("\u00034red\u000F plain", IRC_COLORS));
    }

    @Test
    public void bareColourCodeAlsoResets() {
        String expected = normal().append("a ").append(new Color(0x00FF00), "green")
                .append(ChatColorType.NORMAL).append(" b").build();
        assertEquals(expected, IrcPlugin.chatboxMessage("a \u00039green\u0003 b", IRC_COLORS));
    }

    @Test
    public void backgroundIsDroppedBecauseTheChatBoxCannotDrawIt() {
        assertEquals(new ChatMessageBuilder().append(new Color(0xFF0000), "hi").build(),
                IrcPlugin.chatboxMessage("\u00034,8hi", IRC_COLORS));
    }

    @Test
    public void namedPaletteColoursBecomeHex() {
        // The panel palette names 0 and 1 "white" and "black"; the chat box needs hex.
        assertEquals(new ChatMessageBuilder().append(Color.WHITE, "w").append(Color.BLACK, "b").build(),
                IrcPlugin.chatboxMessage("\u00030w\u00031b", IRC_COLORS));
    }

    @Test
    public void extendedPaletteColour() {
        assertEquals(new ChatMessageBuilder().append(new Color(0x470000), "x").build(),
                IrcPlugin.chatboxMessage("\u000316x", IRC_COLORS));
    }

    @Test
    public void defaultColour99IsTheBaseColour() {
        assertEquals(normal().append("x").build(), IrcPlugin.chatboxMessage("\u000399x", IRC_COLORS));
    }

    @Test
    public void otherFormattingIsStripped() {
        assertEquals(normal().append("bold italic under").build(),
                IrcPlugin.chatboxMessage("\u0002bold\u0002 \u001Ditalic\u001D \u001Funder\u001F", IRC_COLORS));
    }

    @Test
    public void baseColourIsTheCustomInGameColourWhenSet() {
        Color custom = new Color(0x123456);
        String expected = new ChatMessageBuilder().append(new Color(0xFF0000), "red")
                .append(custom, " plain").build();
        assertEquals(expected, IrcPlugin.chatboxMessage("\u00034red\u000F plain", config(true, custom, true)));
    }

    /** Game tags from IRC text must be escaped on every path, or anyone can draw a mod crown in chat. */
    @Test
    public void tagsInAnIrcColouredRunAreEscaped() {
        String built = IrcPlugin.chatboxMessage("\u00034<img=1>Jagex <col=00ff00>x", IRC_COLORS);
        assertFalse(built, built.contains("<img=1>"));
        assertFalse(built, built.contains("<col=00ff00>"));
    }

    @Test
    public void tagsWithACustomInGameColourAreEscaped() {
        String built = IrcPlugin.chatboxMessage("<img=1>Jagex", config(true, Color.RED));
        assertFalse(built, built.contains("<img=1>"));
    }

    @Test
    public void escapedTextMatchesTheUncolouredPath() {
        String escaped = Text.escapeJagex("use <b> tags");
        assertEquals(new ChatMessageBuilder().append(new Color(0xFF0000), escaped).build(),
                IrcPlugin.chatboxMessage("\u00034use <b> tags", IRC_COLORS));
    }
}

package com.irc;

import org.junit.Test;

import javax.swing.JTabbedPane;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;

import static org.junit.Assert.*;

public class IrcPluginNetworkRoutingTest {
    private static final String RIZON = "rizon-id";

    private static class RecordingAdapter extends IrcAdapter {
        final List<String> sent = new ArrayList<>();
        @Override public void sendMessage(String target, String message) { sent.add("PRIVMSG " + target + " :" + message); }
        @Override public void sendRawLine(String line) { sent.add(line); }
        @Override public boolean isConnected() { return true; }
        @Override public void disconnect(String reason) { sent.add("QUIT " + reason); }
        @Override public void joinChannel(String channel, String password) { sent.add("JOIN " + channel); }
    }

    private static IrcConfig stubConfig() {
        return new IrcConfig() {
            @Override public String username() { return "me"; }
            @Override public String password() { return ""; }
        };
    }

    private static void set(Class<?> owner, Object target, String name, Object value) throws Exception {
        Field field = owner.getDeclaredField(name);
        field.setAccessible(true);
        field.set(target, value);
    }

    private final RecordingAdapter swift = new RecordingAdapter();
    private final RecordingAdapter rizon = new RecordingAdapter();

    private IrcPlugin plugin() throws Exception {
        IrcPanel panel = new IrcPanel();
        set(IrcPanel.class, panel, "config", stubConfig());
        set(IrcPanel.class, panel, "tabbedPane", new JTabbedPane());
        panel.addChannel("System");
        panel.addChannel(BufferKey.of(RIZON, "#foo"));

        NetworkManager networks = new NetworkManager(new NetworkManager.Connector() {
            @Override public IrcAdapter open(NetworkConfig network) { throw new AssertionError("no real connections"); }
            @Override public void close(IrcAdapter adapter, NetworkConfig network, boolean removed, String reason) { }
        });
        networks.register(NetworkConfig.swiftIrc(stubConfig()), swift);
        networks.register(NetworkConfig.builder().id(RIZON).name("Rizon").host("irc.rizon.net").build(), rizon);

        IrcPlugin plugin = new IrcPlugin();
        set(IrcPlugin.class, plugin, "config", stubConfig());
        set(IrcPlugin.class, plugin, "panel", panel);
        set(IrcPlugin.class, plugin, "networks", networks);
        return plugin;
    }

    private static void send(IrcPlugin plugin, BufferKey buffer, String text) throws Exception {
        Method m = IrcPlugin.class.getDeclaredMethod("handleMessageSend", BufferKey.class, String.class);
        m.setAccessible(true);
        m.invoke(plugin, buffer, text);
    }

    @Test
