        assertTrue(IrcPlugin.echoesInGame(live, NetworkConfig.SWIFTIRC_ID));
        assertFalse(IrcPlugin.echoesInGame(live.withNetworkId(RIZON), NetworkConfig.SWIFTIRC_ID));
