                IrcMessage.MessageType.HISTORY, Instant.now()), NetworkConfig.SWIFTIRC_ID));
    }

    @Test(timeout = 10000)
    public void connectorCloseDoesNotBlockOnAStalledDisconnect() throws Exception {
        IrcPlugin plugin = plugin();
        java.util.concurrent.CountDownLatch release = new java.util.concurrent.CountDownLatch(1);
        java.util.concurrent.CountDownLatch entered = new java.util.concurrent.CountDownLatch(1);
        RecordingAdapter stalled = new RecordingAdapter() {
            @Override public void disconnect(String reason) {
                entered.countDown();
                try { release.await(); } catch (InterruptedException ignored) { }
            }
        };
        Class<?> cls = Class.forName("com.irc.IrcPlugin$PluginConnector");
        java.lang.reflect.Constructor<?> ctor = cls.getDeclaredConstructor(IrcPlugin.class);
        ctor.setAccessible(true);
        NetworkManager.Connector connector = (NetworkManager.Connector) ctor.newInstance(plugin);
        try {
            connector.close(stalled, NetworkConfig.builder().id(RIZON).name("Rizon").host("irc.rizon.net").build(), false, "bye");
            assertTrue("disconnect should have started on another thread", entered.await(5, java.util.concurrent.TimeUnit.SECONDS));
            assertEquals(1, release.getCount());
        } finally {
            release.countDown();
        }
    }

    private static void joinOnOpen(IrcPlugin plugin, IrcAdapter adapter, NetworkConfig network) throws Exception {
        Method m = IrcPlugin.class.getDeclaredMethod("joinOnOpen", IrcAdapter.class, NetworkConfig.class);
        m.setAccessible(true);
        m.invoke(plugin, adapter, network);
    }

    private static IrcPanel panelOf(IrcPlugin plugin) throws Exception {
        Field field = IrcPlugin.class.getDeclaredField("panel");
        field.setAccessible(true);
        return (IrcPanel) field.get(plugin);
    }

    @Test
    public void defaultChannelIsJoinedOnlyOnTheFirstOpen() throws Exception {
        IrcPlugin plugin = plugin();
        NetworkConfig swiftIrc = NetworkConfig.swiftIrc(stubConfig());
        RecordingAdapter first = new RecordingAdapter();
        joinOnOpen(plugin, first, swiftIrc);
        assertEquals(Collections.singletonList("JOIN #rshelp"), first.sent);

        // The user parted it, then reconnected: it stays parted.
        RecordingAdapter second = new RecordingAdapter();
        joinOnOpen(plugin, second, swiftIrc);
        assertTrue(second.sent.toString(), second.sent.isEmpty());

        // Its buffer is open again: the reconnect rejoins it, once.
        panelOf(plugin).addChannel("#rshelp");
        RecordingAdapter third = new RecordingAdapter();
        joinOnOpen(plugin, third, swiftIrc);
        assertEquals(Collections.singletonList("JOIN #rshelp"), third.sent);
    }

    @Test
    public void normalizedDefaultChannelIsNotJoinedTwice() throws Exception {
        IrcPlugin plugin = plugin();
        IrcConfig bare = new IrcConfig() {
            @Override public String username() { return "me"; }
            @Override public String password() { return ""; }
            @Override public String channel() { return "RSHelp"; }
        };
        set(IrcPlugin.class, plugin, "config", bare);
        panelOf(plugin).addChannel("#rshelp");
        RecordingAdapter adapter = new RecordingAdapter();
        joinOnOpen(plugin, adapter, NetworkConfig.swiftIrc(bare));
        assertEquals(Collections.singletonList("JOIN #rshelp"), adapter.sent);
    }

    private static IrcConfig orderedConfig(String networks, String networkOrder, String channelOrder) {
        return new IrcConfig() {
            @Override public String username() { return "me"; }
            @Override public String password() { return ""; }
            @Override public String networks() { return networks; }
            @Override public String networkOrder() { return networkOrder; }
            @Override public String channelOrder() { return channelOrder; }
        };
    }

    @Test
    public void joinsFollowTheSavedChannelOrderThenTheRest() throws Exception {
        IrcPlugin plugin = plugin();
        set(IrcPlugin.class, plugin, "gson", new com.google.gson.Gson());
        set(IrcPlugin.class, plugin, "config", orderedConfig("", "", "{\"rizon-id\":[\"#b\",\"#A\"]}"));
        panelOf(plugin).addChannel(BufferKey.of(RIZON, "#b"));
        RecordingAdapter adapter = new RecordingAdapter();
        joinOnOpen(plugin, adapter, NetworkConfig.builder().id(RIZON).name("Rizon").host("irc.rizon.net")
                .autojoin("#x,#a,#b").build());
        assertEquals(Arrays.asList("JOIN #b", "JOIN #a", "JOIN #x", "JOIN #foo"), adapter.sent);
    }

    @Test
    public void networksAreAppliedInTheSavedOrder() throws Exception {
        IrcPlugin plugin = plugin();
        set(IrcPlugin.class, plugin, "gson", new com.google.gson.Gson());
        set(IrcPlugin.class, plugin, "config", orderedConfig(
                "[{\"id\":\"a1\",\"name\":\"Rizon\",\"host\":\"irc.rizon.net\"},"
                        + "{\"id\":\"b2\",\"name\":\"Libera\",\"host\":\"irc.libera.chat\"}]",
                "b2,gone,swiftirc", ""));
        Method m = IrcPlugin.class.getDeclaredMethod("networkConfigs");
        m.setAccessible(true);
        @SuppressWarnings("unchecked")
        List<NetworkConfig> configs = (List<NetworkConfig>) m.invoke(plugin);
        List<String> ids = new ArrayList<>();
        for (NetworkConfig network : configs) ids.add(network.getId());
        assertEquals(Arrays.asList("b2", "swiftirc", "a1"), ids);
    }

    @Test
    public void closingANetworkEmptiesItsUserListsOnly() throws Exception {
        IrcPlugin plugin = plugin();
        IrcPanel panel = panelOf(plugin);
        panel.addChannel("#rshelp");
        List<ChannelUserList.Entry> users = Collections.singletonList(new ChannelUserList.Entry("Ash", "@", 0));
        panel.setChannelUsers(BufferKey.of(RIZON, "#foo"), users);
        panel.setChannelUsers(BufferKey.swiftIrc("#rshelp"), users);
        Class<?> cls = Class.forName("com.irc.IrcPlugin$PluginConnector");
        java.lang.reflect.Constructor<?> ctor = cls.getDeclaredConstructor(IrcPlugin.class);
        ctor.setAccessible(true);
        NetworkManager.Connector connector = (NetworkManager.Connector) ctor.newInstance(plugin);
        connector.close(rizon, NetworkConfig.builder().id(RIZON).name("Rizon").host("irc.rizon.net").build(), false, "bye");
        javax.swing.SwingUtilities.invokeAndWait(() -> { });
        Field field = IrcPanel.class.getDeclaredField("channelUserSnapshots");
        field.setAccessible(true);
        @SuppressWarnings("unchecked")
        java.util.Map<BufferKey, List<ChannelUserList.Entry>> snapshots =
                (java.util.Map<BufferKey, List<ChannelUserList.Entry>>) field.get(panel);
        assertEquals(Collections.emptyList(), snapshots.get(BufferKey.of(RIZON, "#foo").folded()));
        assertEquals(users, snapshots.get(BufferKey.swiftIrc("#rshelp").folded()));
    }
}

package com.irc;

import org.junit.Test;

import static org.junit.Assert.assertEquals;

/**
 * Nick sanitising for /nick and its chatbox form ;;nick.
 *
 * Users routinely type a nick with a space in it. A space cannot reach the wire: setNick sends
 * "NICK " + nick as a single raw line, so "foo bar" would go out as NICK with two parameters and
 * the server would silently take only "foo". The old code dodged that by refusing multi-word input
 * outright, which looked to the user like the command did nothing at all.
 *
 * Runs of whitespace collapse to ONE underscore rather than one per character - "foo   bar" becomes
 * "foo_bar", not "foo___bar". A triple underscore is not what anyone typing three spaces meant, and
 * nicks are length-capped by the server.
 */
public class IrcPluginNickTest {

    @Test
    public void replacesASingleSpaceWithAnUnderscore() {
        assertEquals("foo_bar", IrcPlugin.sanitizeNick("foo bar"));
    }

    /** Each separate gap becomes its own underscore. */
    @Test
    public void replacesEverySeparateSpace() {
        assertEquals("a_b_c", IrcPlugin.sanitizeNick("a b c"));
    }

    /** A run of spaces is one gap, so it collapses to one underscore. */
    @Test
    public void collapsesRunsOfSpacesToASingleUnderscore() {
        assertEquals("foo_bar", IrcPlugin.sanitizeNick("foo   bar"));
    }

    /** Surrounding whitespace is not part of the name, so it is trimmed rather than converted. */
    @Test
    public void trimsSurroundingWhitespaceInsteadOfConvertingIt() {
        assertEquals("foo", IrcPlugin.sanitizeNick("  foo  "));
        assertEquals("foo_bar", IrcPlugin.sanitizeNick("  foo bar  "));
    }

    @Test
    public void leavesAValidNickUntouched() {
        assertEquals("Ryan", IrcPlugin.sanitizeNick("Ryan"));
        assertEquals("guthix_", IrcPlugin.sanitizeNick("guthix_"));
        assertEquals("[bot]", IrcPlugin.sanitizeNick("[bot]"));
    }

    /** Tabs are whitespace too and would break the wire format the same way a space does. */
    @Test
    public void convertsNonSpaceWhitespace() {
        assertEquals("foo_bar", IrcPlugin.sanitizeNick("foo\tbar"));
        assertEquals("foo_bar", IrcPlugin.sanitizeNick("foo \t bar"));
    }

    /** Nothing usable in, nothing out - the caller declines to send rather than sending "NICK _". */
    @Test
    public void yieldsEmptyForNothingUsable() {
        assertEquals("", IrcPlugin.sanitizeNick(""));
        assertEquals("", IrcPlugin.sanitizeNick("   "));
        assertEquals("", IrcPlugin.sanitizeNick("\t"));
        assertEquals("", IrcPlugin.sanitizeNick(null));
    }

    /** The result must never contain whitespace - that is the whole point. */
    @Test
    public void resultNeverContainsWhitespace() {
        String[] inputs = {"foo bar", "a b c", "foo   bar", "  x  y  ", "foo\tbar"};
        for (String input : inputs) {
            String result = IrcPlugin.sanitizeNick(input);
            assertEquals("whitespace survived sanitising of \"" + input + "\": \"" + result + "\"",
                    -1, indexOfWhitespace(result));
        }
    }

    private static int indexOfWhitespace(String value) {
        for (int i = 0; i < value.length(); i++) {
            if (Character.isWhitespace(value.charAt(i))) {
                return i;
            }
        }
        return -1;
    }
}

package com.irc;

import org.junit.Test;

import java.util.Arrays;
import java.util.Collections;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * The server's mode vocabulary, learned from RPL_ISUPPORT (numeric 005).
 *
 * PREFIX=(qaohv)~&@%+ maps membership mode letters to display prefixes positionally, and the
 * position is also the rank (0 = most privileged). CHANMODES=A,B,C,D says which mode letters
 * consume a parameter: A and B always, C only when adding, D never. Membership modes are absent
 * from CHANMODES and always consume one. Knowing this is what keeps "MODE #c +mo bob" from
 * opping the wrong user.
 */
public class ModeSpecTest {

    @Test
    public void defaultsRecognizeTheClassicFivePrefixes() {
        ModeSpec spec = ModeSpec.defaults();
        assertEquals('~', spec.prefixFor('q'));
        assertEquals('&', spec.prefixFor('a'));
        assertEquals('@', spec.prefixFor('o'));
        assertEquals('%', spec.prefixFor('h'));
        assertEquals('+', spec.prefixFor('v'));
    }

    @Test
    public void defaultsRankOwnerAboveVoice() {
        ModeSpec spec = ModeSpec.defaults();
        assertTrue(spec.rankOf('q') < spec.rankOf('o'));
        assertTrue(spec.rankOf('o') < spec.rankOf('v'));
    }

    @Test
    public void unknownModeLetterHasLowestRank() {
        assertEquals(Integer.MAX_VALUE, ModeSpec.defaults().rankOf('Z'));
    }

    @Test
    public void prefixCharMapsBackToItsModeLetter() {
        ModeSpec spec = ModeSpec.defaults();
        assertEquals(Character.valueOf('o'), spec.modeForPrefix('@'));
        assertNull(spec.modeForPrefix('x'));
    }

    @Test
    public void isupportReplacesThePrefixTable() {
        ModeSpec spec = ModeSpec.defaults();
        spec.applyIsupport(Collections.singletonList("PREFIX=(ov)@+"));
        assertEquals(0, spec.rankOf('o'));
        assertFalse("halfop is gone once the server says it has none", spec.isPrefixMode('h'));
    }

    @Test
    public void isupportSkipsTokensThatAreNotKeyValuePairs() {
        ModeSpec spec = ModeSpec.defaults();
        // A real 005 line: leading nick, then tokens, then a trailing description.
        spec.applyIsupport(Arrays.asList("mynick", "PREFIX=(ov)@+", "are supported by this server"));
        assertEquals('@', spec.prefixFor('o'));
        assertFalse(spec.isPrefixMode('h'));
    }

    @Test
    public void unparseablePrefixValueLeavesThePreviousTableIntact() {
        ModeSpec spec = ModeSpec.defaults();
        spec.applyIsupport(Collections.singletonList("PREFIX=garbage"));
        assertEquals('@', spec.prefixFor('o'));
    }

    @Test
    public void prefixModesAlwaysTakeAParameter() {
        ModeSpec spec = ModeSpec.defaults();
        assertTrue(spec.takesParameter('o', true));
        assertTrue(spec.takesParameter('o', false));
        assertTrue(spec.takesParameter('v', false));
    }

    @Test
    public void typeAAndTypeBModesAlwaysTakeAParameter() {
        ModeSpec spec = ModeSpec.defaults();
        assertTrue("b is a list mode", spec.takesParameter('b', true));
        assertTrue(spec.takesParameter('b', false));
        assertTrue("k is a settings mode", spec.takesParameter('k', true));
        assertTrue(spec.takesParameter('k', false));
    }

    @Test
    public void typeCModeTakesAParameterOnlyWhenAdding() {
        ModeSpec spec = ModeSpec.defaults();
        assertTrue(spec.takesParameter('l', true));
        assertFalse(spec.takesParameter('l', false));
    }

    @Test
    public void typeDModeNeverTakesAParameter() {
        ModeSpec spec = ModeSpec.defaults();
        assertFalse(spec.takesParameter('m', true));
        assertFalse(spec.takesParameter('m', false));
    }

    @Test
    public void unknownModeLetterIsAssumedParameterless() {
        // Stated assumption in the spec: type D is the largest class, so it is the safer guess.
        ModeSpec spec = ModeSpec.defaults();
        assertFalse(spec.takesParameter('Z', true));
        assertFalse(spec.takesParameter('Z', false));
    }

    @Test
    public void isupportReplacesTheChanmodesTable() {
        ModeSpec spec = ModeSpec.defaults();
        spec.applyIsupport(Collections.singletonList("CHANMODES=b,k,l,imnpstZ"));
        assertFalse("Z is now a known flag mode", spec.takesParameter('Z', true));
        assertTrue(spec.takesParameter('b', true));
    }

    @Test
    public void malformedChanmodesValueLeavesThePreviousTableIntact() {
        ModeSpec spec = ModeSpec.defaults();
        spec.applyIsupport(Collections.singletonList("CHANMODES=b,k"));
        assertTrue("type C mode l still takes a parameter when adding", spec.takesParameter('l', true));
        assertTrue("type A mode b still takes a parameter", spec.takesParameter('b', true));
    }
}

package com.irc;

import org.junit.Test;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;

import static org.junit.Assert.*;

public class NetworkManagerTest {
    private final List<String> calls = new ArrayList<>();
    private final NetworkManager manager = new NetworkManager(new NetworkManager.Connector() {
        @Override public IrcAdapter open(NetworkConfig network) {
            calls.add("open " + network.getId());
            return new IrcAdapter();
        }
        @Override public void close(IrcAdapter adapter, NetworkConfig network, boolean removed, String reason) {
            calls.add("close " + network.getId() + " " + (adapter != null) + " " + removed + " " + reason);
        }
    });

    private static NetworkConfig net(String id) {
        return NetworkConfig.builder().id(id).name(id.toUpperCase()).host(id + ".example").build();
    }

    @Test
    public void startsEnabledNetworksInOrderAndSkipsDisabled() {
        manager.apply(Arrays.asList(net("a"), net("b").toBuilder().enabled(false).build(), net("c")));
        assertEquals(Arrays.asList("open a", "open c"), calls);
        assertTrue(manager.isRunning("a"));
        assertFalse(manager.isRunning("b"));
        assertTrue(manager.isKnown("b"));
        assertEquals(Arrays.asList("a", "b", "c"), ids(manager.configs()));
    }

    @Test
    public void removingANetworkClosesItAndForgetsIt() {
        manager.apply(Arrays.asList(net("a"), net("b")));
        calls.clear();
        manager.apply(Collections.singletonList(net("a")));
        assertEquals(Collections.singletonList("close b true true Network removed"), calls);
        assertFalse(manager.isKnown("b"));
        assertNull(manager.get("b"));
    }

    @Test
    public void removingADisabledNetworkStillClosesItsBuffers() {
        manager.apply(Collections.singletonList(net("a").toBuilder().enabled(false).build()));
        manager.apply(Collections.emptyList());
        assertEquals(Collections.singletonList("close a false true Network removed"), calls);
    }

    @Test
    public void disablingDisconnectsButKeepsTheNetworkKnown() {
        manager.apply(Collections.singletonList(net("a")));
        calls.clear();
        manager.apply(Collections.singletonList(net("a").toBuilder().enabled(false).build()));
        assertEquals(Collections.singletonList("close a true false Disconnecting"), calls);
        assertTrue(manager.isKnown("a"));
        assertFalse(manager.isRunning("a"));
    }

    @Test
    public void connectionChangesReconnectWithAFreshAdapter() {
        manager.apply(Collections.singletonList(net("a")));
        IrcAdapter first = manager.get("a");
        calls.clear();
        manager.apply(Collections.singletonList(net("a").toBuilder().port(6667).build()));
        assertEquals(Arrays.asList("close a true false Reloading, brb", "open a"), calls);
        assertNotSame(first, manager.get("a"));
    }

    @Test
    public void nameOrAutojoinChangesKeepTheConnection() {
        manager.apply(Collections.singletonList(net("a")));
        IrcAdapter first = manager.get("a");
        calls.clear();
        manager.apply(Collections.singletonList(net("a").toBuilder().name("Renamed").autojoin("#x").build()));
        assertTrue(calls.isEmpty());
        assertSame(first, manager.get("a"));
        assertEquals("Renamed", manager.config("a").getName());
    }

    @Test
    public void reconnectRestartsOnlyEnabledKnownNetworks() {
        manager.apply(Arrays.asList(net("a"), net("b").toBuilder().enabled(false).build()));
        calls.clear();
        manager.reconnect("a");
        manager.reconnect("b");
        manager.reconnect("missing");
        assertEquals(Arrays.asList("close a true false Reloading, brb", "open a"), calls);
    }

    @Test
    public void reconnectWithAFreshConfigOpensWithIt() {
        List<NetworkConfig> opened = new ArrayList<>();
        NetworkManager recording = new NetworkManager(new NetworkManager.Connector() {
            @Override public IrcAdapter open(NetworkConfig network) {
                opened.add(network);
                return new IrcAdapter();
            }
            @Override public void close(IrcAdapter adapter, NetworkConfig network, boolean removed, String reason) {
            }
        });
        recording.apply(Collections.singletonList(net("a")));
        opened.clear();
        NetworkConfig fresh = net("a").toBuilder().host("new.example").build();
        recording.reconnect(fresh);
        assertEquals(Collections.singletonList(fresh), opened);
        assertSame(fresh, recording.config("a"));
    }

    @Test
    public void reconnectWithAFreshConfigSkipsDisabledAndUnknownNetworks() {
        manager.apply(Collections.singletonList(net("a")));
        calls.clear();
        manager.reconnect(net("a").toBuilder().enabled(false).build());
        manager.reconnect(net("missing"));
        assertFalse(manager.isKnown("missing"));
        assertTrue(calls.isEmpty());
    }

    @Test
    public void updateReplacesTheKnownConfigWithoutReconnecting() {
        manager.apply(Collections.singletonList(net("a")));
        IrcAdapter first = manager.get("a");
        calls.clear();
        manager.update(net("a").toBuilder().host("new.example").build());
        manager.update(net("missing"));
        assertTrue(calls.isEmpty());
        assertSame(first, manager.get("a"));
        assertEquals("new.example", manager.config("a").getHost());
        assertFalse(manager.isKnown("missing"));
    }

    @Test
    public void pausedNetworksStayDownUntilConnectedAgain() {
        manager.apply(Collections.singletonList(net("a")));
        manager.setConnected("a", false);
        calls.clear();
        manager.apply(Collections.singletonList(net("a").toBuilder().name("Renamed").build()));
        assertTrue(calls.isEmpty());
        manager.setConnected("a", true);
        assertEquals(Collections.singletonList("open a"), calls);
        assertTrue(manager.isRunning("a"));
    }

    @Test
    public void connectRestartsANetworkWhoseConnectionDropped() {
        NetworkConfig a = net("a");
        IrcAdapter dropped = new IrcAdapter() {
            @Override public boolean isConnected() {
                return false;
            }
        };
        manager.register(a, dropped);
        manager.setConnected("a", true);
        assertEquals(Arrays.asList("close a true false Reloading, brb", "open a"), calls);
        assertNotSame(dropped, manager.get("a"));
    }

    @Test
    public void shutdownClosesEverything() {
        manager.apply(Arrays.asList(net("a"), net("b")));
        calls.clear();
        manager.shutdown();
        assertEquals(Arrays.asList("close a true false Plugin shutting down", "close b true false Plugin shutting down"), calls);
        assertTrue(manager.adapters().isEmpty());
    }

    @Test
    public void aNetworkThatDoesNotConnectAutomaticallyCanBeConnectedByHand() {
        NetworkConfig manual = net("a").toBuilder().enabled(false).build();
        manager.apply(Collections.singletonList(manual));
        assertTrue(calls.isEmpty());
        manager.setConnected("a", true);
        assertEquals(Collections.singletonList("open a"), calls);
        assertTrue(manager.isRunning("a"));
    }

    @Test
    public void aHandConnectionSurvivesUnrelatedConfigChanges() {
        NetworkConfig manual = net("a").toBuilder().enabled(false).build();
        manager.apply(Collections.singletonList(manual));
        manager.setConnected("a", true);
        calls.clear();
        manager.apply(Arrays.asList(manual.toBuilder().name("Renamed").build(), net("b")));
        assertEquals(Collections.singletonList("open b"), calls);
        assertTrue(manager.isRunning("a"));
    }

    @Test
    public void aHandConnectionStillReconnectsWhenItsSettingsChange() {
        NetworkConfig manual = net("a").toBuilder().enabled(false).build();
        manager.apply(Collections.singletonList(manual));
        manager.setConnected("a", true);
        calls.clear();
        manager.apply(Collections.singletonList(manual.toBuilder().port(7000).build()));
        assertEquals(Arrays.asList("close a true false Reloading, brb", "open a"), calls);
        calls.clear();
        manager.reconnect("a");
        assertEquals(Arrays.asList("close a true false Reloading, brb", "open a"), calls);
    }

    @Test
    public void disconnectingByHandEndsAHandConnection() {
        NetworkConfig manual = net("a").toBuilder().enabled(false).build();
        manager.apply(Collections.singletonList(manual));
        manager.setConnected("a", true);
        manager.setConnected("a", false);
        calls.clear();
        manager.apply(Collections.singletonList(manual));
        manager.reconnect("a");
        assertTrue("stays down, and reconnect leaves it alone", calls.isEmpty());
        assertFalse(manager.isRunning("a"));
    }

    private static List<String> ids(List<NetworkConfig> configs) {
        List<String> ids = new ArrayList<>();
        for (NetworkConfig c : configs) ids.add(c.getId());
        return ids;
    }
}

package com.irc;

import com.google.gson.Gson;
import org.junit.Test;

import java.util.Arrays;
import java.util.Collections;
import java.util.List;

import static org.junit.Assert.*;

public class NetworkStoreTest {
    private final Gson gson = new Gson();

    private static NetworkConfig rizon() {
        return NetworkConfig.builder().id("a1").name("Rizon").host("irc.rizon.net").port(6697).tls(true)
                .nick("Mikey").serverPassword("").saslAccount("mikey").saslPassword("pw")
                .autojoin("#foo,#bar").enabled(true).build();
    }

    @Test
    public void roundTripsEveryField() {
