    private static NetworksDialog.Callbacks recorder(List<String> calls) {
        return new NetworksDialog.Callbacks() {
            @Override public void save(List<NetworkConfig> extras) { calls.add("save " + extras.size()); }
            @Override public void saveOrder(List<String> ids) { calls.add("order " + ids); }
            @Override public boolean isConnected(String id) { return "r1".equals(id); }
            @Override public void setConnected(String id, boolean c) { calls.add(id + " " + c); }
            @Override public void saveBuiltIn(boolean enabled) { calls.add("swiftirc enabled " + enabled); }
            @Override public void saveInGameNetwork(String id) { calls.add("in game " + id); }
        };
    }

    @Test
    public void moveUpAndDownReorderEveryNetworkAndSaveTheOrder() throws Exception {
        org.junit.Assume.assumeFalse(GraphicsEnvironment.isHeadless());
        List<String> calls = new ArrayList<>();
        NetworkConfig libera = rizon().toBuilder().id("l2").name("Libera").host("irc.libera.chat").build();
        SwingUtilities.invokeAndWait(() -> {
            NetworksDialog dialog = new NetworksDialog(null, builtIn(), Arrays.asList(rizon(), libera),
                    Arrays.asList("r1", "gone", NetworkConfig.SWIFTIRC_ID), new NetworksDialog.Callbacks() {
                        @Override public void save(List<NetworkConfig> extras) {
                            List<String> ids = new ArrayList<>();
                            for (NetworkConfig extra : extras) ids.add(extra.getId());
                            calls.add("save " + ids);
                        }
                        @Override public void saveOrder(List<String> ids) { calls.add("order " + ids); }
                        @Override public boolean isConnected(String id) { return false; }
                        @Override public void setConnected(String id, boolean c) { }
                    });
            try {
                JList<?> list = (JList<?>) find(dialog, "ircNetworkList");
                JButton up = (JButton) find(dialog, "ircNetworkUp");
                JButton down = (JButton) find(dialog, "ircNetworkDown");
                assertEquals(Arrays.asList("r1", NetworkConfig.SWIFTIRC_ID, "l2"), ids(list));

                dialog.selectNetwork("r1");
                assertFalse(up.isEnabled());
                assertTrue(down.isEnabled());
                dialog.selectNetwork("l2");
                assertTrue(up.isEnabled());
                assertFalse(down.isEnabled());

                // SwiftIRC moves like any other network.
                dialog.selectNetwork(NetworkConfig.SWIFTIRC_ID);
                down.doClick();
                assertEquals(Arrays.asList("r1", "l2", NetworkConfig.SWIFTIRC_ID), ids(list));
                assertEquals(NetworkConfig.SWIFTIRC_ID, ((NetworkConfig) list.getSelectedValue()).getId());
                dialog.selectNetwork("l2");
                up.doClick();
                assertEquals(Arrays.asList("l2", "r1", NetworkConfig.SWIFTIRC_ID), ids(list));
                assertEquals(Arrays.asList(
                        "save [r1, l2]", "order [r1, l2, swiftirc]",
                        "save [l2, r1]", "order [l2, r1, swiftirc]"), calls);

                // Reloading from the saved settings keeps the order.
                dialog.setNetworks(builtIn(), Arrays.asList(libera, rizon()), Arrays.asList("l2", "r1", NetworkConfig.SWIFTIRC_ID));
                assertEquals(Arrays.asList("l2", "r1", NetworkConfig.SWIFTIRC_ID), ids(list));
            } finally {
                dialog.dispose();
            }
        });
    }

    private static List<String> ids(JList<?> list) {
        List<String> ids = new ArrayList<>();
        for (int i = 0; i < list.getModel().getSize(); i++) ids.add(((NetworkConfig) list.getModel().getElementAt(i)).getId());
        return ids;
    }

    private static Component find(Container parent, String name) {
        for (Component child : parent.getComponents()) {
            if (name.equals(child.getName())) return child;
            if (child instanceof Container) {
                Component found = find((Container) child, name);
                if (found != null) return found;
            }
        }
        return null;
    }
}

package com.irc;

import com.google.gson.Gson;
import org.junit.Test;

import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

import static org.junit.Assert.*;

public class OrderStoreTest {
    private final Gson gson = new Gson();

    private static NetworkConfig network(String id) {
        return NetworkConfig.builder().id(id).name(id).host("irc." + id + ".net").build();
    }

    @Test
    public void networkOrderRoundTripsAndIgnoresBlanksAndRepeats() {
        assertEquals(Arrays.asList("a1", "swiftirc", "b2"), OrderStore.parseNetworkOrder(" a1, swiftirc,,b2 ,a1"));
        assertEquals(Collections.emptyList(), OrderStore.parseNetworkOrder(""));
        assertEquals(Collections.emptyList(), OrderStore.parseNetworkOrder(null));
        assertEquals("b2,swiftirc,a1", OrderStore.serializeNetworkOrder(Arrays.asList("b2", "swiftirc", "a1")));
        assertEquals(Arrays.asList("b2", "swiftirc", "a1"),
                OrderStore.parseNetworkOrder(OrderStore.serializeNetworkOrder(Arrays.asList("b2", "swiftirc", "a1"))));
    }

    @Test
    public void listedNetworksComeFirstThenTheRestInTheirNaturalOrder() {
        List<NetworkConfig> natural = Arrays.asList(network("swiftirc"), network("a1"), network("b2"), network("c3"));
        List<NetworkConfig> ordered = OrderStore.applyNetworkOrder(natural, Arrays.asList("b2", "gone", "swiftirc"));
        assertEquals(Arrays.asList(network("b2"), network("swiftirc"), network("a1"), network("c3")), ordered);
    }

    @Test
    public void noSavedNetworkOrderKeepsTheNaturalOrder() {
        List<NetworkConfig> natural = Arrays.asList(network("swiftirc"), network("a1"));
        assertEquals(natural, OrderStore.applyNetworkOrder(natural, Collections.emptyList()));
    }

    @Test
    public void channelOrderRoundTripsKeepingOnlyChannelNames() {
        Map<String, List<String>> order = new LinkedHashMap<>();
        order.put("swiftirc", Arrays.asList("#b", "Luna", "&a", "System", "#c"));
        order.put("a1", Collections.singletonList("#foo"));
        Map<String, List<String>> parsed = OrderStore.parseChannelOrder(gson, OrderStore.serializeChannelOrder(gson, order));
        Map<String, List<String>> expected = new LinkedHashMap<>();
        expected.put("swiftirc", Arrays.asList("#b", "&a", "#c"));
        expected.put("a1", Collections.singletonList("#foo"));
        assertEquals(expected, parsed);
    }

    @Test
    public void blankOrCorruptChannelOrderIsEmpty() {
        assertEquals(Collections.emptyMap(), OrderStore.parseChannelOrder(gson, ""));
        assertEquals(Collections.emptyMap(), OrderStore.parseChannelOrder(gson, null));
        assertEquals(Collections.emptyMap(), OrderStore.parseChannelOrder(gson, "{not json"));
        assertEquals(Collections.emptyMap(), OrderStore.parseChannelOrder(gson, "[\"#a\"]"));
        Map<String, List<String>> parsed = OrderStore.parseChannelOrder(gson, "{\"a1\":[\"#x\",null,\"pm\"],\"b2\":null}");
        assertEquals(Collections.singletonMap("a1", Collections.singletonList("#x")), parsed);
    }

    @Test
    public void sortByOrderPutsSavedNamesFirstIgnoringCase() {
        assertEquals(Arrays.asList("#C", "#a", "#b", "#d"),
                OrderStore.sortByOrder(Arrays.asList("#a", "#b", "#C", "#d"), Arrays.asList("#c", "#gone", "#a")));
        assertEquals(Arrays.asList("#a", "#b"),
                OrderStore.sortByOrder(Arrays.asList("#a", "#b"), Collections.emptyList()));
    }

    @Test
    public void savingANetworkOrderDropsRemovedNetworks() {
        assertEquals(Arrays.asList("b2", "swiftirc"), OrderStore.retainKnown(Arrays.asList("b2", "gone", "swiftirc"),
                new java.util.HashSet<>(Arrays.asList("swiftirc", "b2", "c3"))));
    }

    @Test
    public void savingAChannelOrderReplacesThatNetworkAndDropsRemovedOnes() {
        Map<String, List<String>> current = new LinkedHashMap<>();
        current.put("gone", Collections.singletonList("#x"));
        current.put("swiftirc", Arrays.asList("#a", "#b"));
        current.put("b2", Collections.singletonList("#old"));
        Map<String, List<String>> next = OrderStore.withChannels(current, "b2", Arrays.asList("#new", "#old"),
                new java.util.HashSet<>(Arrays.asList("swiftirc", "b2")));
        Map<String, List<String>> expected = new LinkedHashMap<>();
        expected.put("swiftirc", Arrays.asList("#a", "#b"));
        expected.put("b2", Arrays.asList("#new", "#old"));
        assertEquals(expected, next);
        assertEquals(3, current.size());
    }

    @Test
    public void mergeKeepsClosedChannelsAfterTheirSavedPredecessor() {
        assertEquals(Arrays.asList("#a", "#b", "#rshelp"),
                OrderStore.merge(Arrays.asList("#a", "#rshelp", "#b"), Arrays.asList("#b", "#rshelp")));
        assertEquals(Arrays.asList("#rshelp", "#a", "#b"),
                OrderStore.merge(Arrays.asList("#rshelp", "#a", "#b"), Arrays.asList("#rshelp", "#b")));
    }

    @Test
    public void mergeKeepsConsecutiveClosedChannelsTogether() {
        assertEquals(Arrays.asList("#x", "#y", "#c", "#b", "#p", "#q"),
                OrderStore.merge(Arrays.asList("#x", "#y", "#b", "#p", "#q", "#c"), Arrays.asList("#c", "#b")));
    }

    @Test
    public void mergeAddsNewChannelsAndHandlesNoSavedOrder() {
        assertEquals(Arrays.asList("#new", "#A", "#gone"),
                OrderStore.merge(Arrays.asList("#a", "#gone"), Arrays.asList("#new", "#A")));
        assertEquals(Arrays.asList("#b", "#a"), OrderStore.merge(Collections.emptyList(), Arrays.asList("#b", "#a")));
    }
}

package com.irc;

import org.junit.Test;

import java.awt.Rectangle;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;

import static org.junit.Assert.*;

public class PopOutGeometryTest {
    @Test
    public void roundTrips() {
        PopOutGeometry normal = PopOutGeometry.parse(new PopOutGeometry(new Rectangle(-1200, 40, 900, 600), false).serialize());
        assertEquals(new Rectangle(-1200, 40, 900, 600), normal.bounds);
        assertFalse(normal.maximized);

        PopOutGeometry maximized = PopOutGeometry.parse(new PopOutGeometry(new Rectangle(10, 20, 700, 500), true).serialize());
        assertEquals(new Rectangle(10, 20, 700, 500), maximized.bounds);
        assertTrue(maximized.maximized);
    }

    @Test
    public void unreadableValuesAreNull() {
        for (String value : Arrays.asList(null, "", "1,2,3", "1,2,3,4,5", "1,2,3,4,max", "a,2,3,4", "1,2,0,4", "1,2,3,-4")) {
            assertNull(value, PopOutGeometry.parse(value));
        }
    }

    @Test
    public void titleBarMustBeOnAScreen() {
        List<Rectangle> screens = Arrays.asList(new Rectangle(0, 0, 1920, 1080), new Rectangle(1920, 0, 1280, 1024));
        assertTrue(geometry(100, 100).titleBarVisible(screens));
        assertTrue("on the second monitor", geometry(2200, 100).titleBarVisible(screens));
        assertFalse("its monitor was unplugged", geometry(3400, 100).titleBarVisible(screens));
        assertFalse("title bar above the top", geometry(100, -50).titleBarVisible(screens));
        assertFalse(geometry(100, 100).titleBarVisible(Collections.emptyList()));
    }

    private static PopOutGeometry geometry(int x, int y) {
        return new PopOutGeometry(new Rectangle(x, y, 800, 600), false);
    }
}

package com.irc;

import org.junit.Test;

import java.util.ArrayList;
import java.util.List;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Diagnostics for the two failure modes users actually report: a connection that never comes up,
 * and one that is torn down without explanation.
 *
 * The server almost always says why - in an ERROR line, a KILL, or an error numeric - and the
 * client used to drop all of it on the floor. These tests pin down that the text survives as far
 * as a fired event, because that text is the whole of what a reporting user can give us.
 */
public class SimpleIrcClientDiagnosticsTest {

    /** Feeds raw lines without a socket and records what came back out. */
    private static class RecordingClient extends SimpleIrcClient {
        final List<IrcEvent> events = new ArrayList<>();

        RecordingClient() {
            addEventListener(events::add);
        }

        @Override
        public synchronized void sendRawLine(String line) {
            // no socket in tests
        }

        IrcEvent firstOf(IrcEvent.Type type) {
            return events.stream().filter(e -> e.getType() == type).findFirst().orElse(null);
        }

        IrcEvent lastOf(IrcEvent.Type type) {
            return events.stream().filter(e -> e.getType() == type)
                    .reduce((a, b) -> b).orElse(null);
        }
    }

    @Test
    public void serverErrorLineSurfacesTheServersOwnReason() {
        RecordingClient client = new RecordingClient();

        client.processLine("ERROR :Closing Link: someone[1.2.3.4] (Ping timeout: 240 seconds)");

        SimpleIrcClient.IrcEvent event = client.firstOf(SimpleIrcClient.IrcEvent.Type.ERROR);
        assertNotNull("server ERROR must fire an ERROR event", event);
        assertTrue("the server's reason must survive: " + event.getMessage(),
                event.getMessage().contains("Ping timeout: 240 seconds"));
    }

    @Test
    public void killNamesTheOperatorAndTheReason() {
        RecordingClient client = new RecordingClient();
        client.credentials("me", "runelite", "me");

        client.processLine(":oper!o@staff.example KILL me :staff.example (spamming)");

        SimpleIrcClient.IrcEvent event = client.firstOf(SimpleIrcClient.IrcEvent.Type.ERROR);
        assertNotNull("a KILL against us must fire an ERROR event", event);
        assertTrue("the killing operator must be named: " + event.getMessage(),
                event.getMessage().contains("oper"));
        assertTrue("the kill reason must survive: " + event.getMessage(),
                event.getMessage().contains("spamming"));
    }

    @Test
    public void killAgainstAnotherUserIsNotOurDisconnect() {
        RecordingClient client = new RecordingClient();
        client.credentials("me", "runelite", "me");

        client.processLine(":oper!o@staff.example KILL someoneelse :staff.example (spamming)");

        assertNull("another user being killed must not report our own link as dead",
                client.firstOf(SimpleIrcClient.IrcEvent.Type.ERROR));
    }

    @Test
    public void unhandledErrorNumericSurfacesItsText() {
        RecordingClient client = new RecordingClient();

        client.processLine(":server 465 me :You are banned from this server: spamming");

        SimpleIrcClient.IrcEvent event = client.firstOf(SimpleIrcClient.IrcEvent.Type.SERVER_ERROR);
        assertNotNull("an error numeric we do not handle explicitly must still be reported", event);
        assertTrue("the server's explanation must survive: " + event.getMessage(),
                event.getMessage().contains("You are banned from this server: spamming"));
    }

    @Test
    public void informationalNumericsAreNotReportedAsErrors() {
        RecordingClient client = new RecordingClient();

        client.processLine(":server 372 me :- welcome to the message of the day");
        client.processLine(":server 251 me :There are 4000 users on the network");

        assertNull("MOTD and stats numerics are not failures and must stay quiet",
                client.firstOf(SimpleIrcClient.IrcEvent.Type.SERVER_ERROR));
    }

    /** UnrealIRCd's RPL_WHOISASN sits in the error range but is just another WHOIS line. */
    @Test
    public void whoisAsnIsAWhoisLineNotAnError() {
        RecordingClient client = new RecordingClient();

        client.processLine(":server 569 me bob 7922 :is connecting from AS7922 [Comcast Cable Communications, LLC]");

        assertNull("569 is not a failure",
                client.firstOf(SimpleIrcClient.IrcEvent.Type.SERVER_ERROR));
        SimpleIrcClient.IrcEvent event = client.firstOf(SimpleIrcClient.IrcEvent.Type.WHOIS_REPLY);
        assertNotNull("569 is shown with the rest of the WHOIS", event);
        assertEquals("bob is connecting from AS7922 [Comcast Cable Communications, LLC]", event.getMessage());
    }

    /** A WHOWAS answer, found or not, is shown with the WHOIS lines and is never an error. */
    @Test
    public void whowasRepliesAreWhoisLinesNotErrors() {
        RecordingClient client = new RecordingClient();

        client.processLine(":server 314 me bob ~bob host.example * :Bob Smith");
        client.processLine(":server 369 me bob :End of WHOWAS");
        client.processLine(":server 406 me ghost :There was no such nickname");

        assertNull("WHOWAS replies are not failures",
                client.firstOf(SimpleIrcClient.IrcEvent.Type.SERVER_ERROR));
        List<String> lines = new ArrayList<>();
        for (SimpleIrcClient.IrcEvent event : client.events) {
            if (event.getType() == SimpleIrcClient.IrcEvent.Type.WHOIS_REPLY) lines.add(event.getMessage());
        }
        assertEquals(java.util.Arrays.asList(
                "bob was ~bob@host.example (Bob Smith)",
                "End of WHOWAS for bob",
                "ghost: There was no such nickname"), lines);
    }

    /**
     * The real host and IP come in their own line - 378, or 338 on some servers, in either the
     * middle parameters or the text - during both WHOIS and WHOWAS. They used to be dropped.
     */
    @Test
    public void hostAndIpLinesAreShown() {
        RecordingClient client = new RecordingClient();

        client.processLine(":server 378 me bob :is connecting from *@cpe.example.net 203.0.113.7");
        client.processLine(":server 338 me bob :is actually ~bob@cpe.example.net [203.0.113.7]");
        client.processLine(":server 338 me bob 203.0.113.7 :actually using host");

        List<String> lines = new ArrayList<>();
        for (SimpleIrcClient.IrcEvent event : client.events) {
            if (event.getType() == SimpleIrcClient.IrcEvent.Type.WHOIS_REPLY) lines.add(event.getMessage());
        }
        assertEquals(java.util.Arrays.asList(
                "bob is connecting from *@cpe.example.net 203.0.113.7",
                "bob is actually ~bob@cpe.example.net [203.0.113.7]",
                "bob 203.0.113.7 actually using host"), lines);
    }

    @Test
    public void numericWithItsOwnHandlerIsNotAlsoReportedGenerically() {
        RecordingClient client = new RecordingClient();

        client.processLine(":server 433 me takenNick :Nickname is already in use");

        assertNotNull("433 keeps its dedicated handling",
                client.firstOf(SimpleIrcClient.IrcEvent.Type.NICK_IN_USE));
        assertNull("a numeric we handle explicitly must not be double-reported",
                client.firstOf(SimpleIrcClient.IrcEvent.Type.SERVER_ERROR));
    }

    @Test
    public void unknownHostIsExplainedRatherThanEchoedBack() {
        // UnknownHostException.getMessage() is just the hostname, so surfacing it raw showed the
        // user "Error: irc.swiftirc.net" and nothing else.
        String described = SimpleIrcClient.describeFailure(
                SimpleIrcClient.ConnectPhase.CONNECTING, "irc.swiftirc.net", 6697,
                new java.net.UnknownHostException("irc.swiftirc.net"));

        assertTrue("must say what went wrong, not just echo the host: " + described,
                described.toLowerCase().contains("dns"));
        assertTrue("must still name the host: " + described,
                described.contains("irc.swiftirc.net"));
    }

    @Test
    public void readTimeoutIsExplainedAsALostConnectionWithItsDuration() {
        String described = SimpleIrcClient.describeFailure(
                SimpleIrcClient.ConnectPhase.ESTABLISHED, "irc.swiftirc.net", 6697,
                new java.net.SocketTimeoutException("Read timed out"));

        assertTrue("must explain the silence, not just relay 'Read timed out': " + described,
                described.contains("240"));
    }

    @Test
    public void failureNamesThePhaseAndTheExceptionType() {
        String described = SimpleIrcClient.describeFailure(
                SimpleIrcClient.ConnectPhase.TLS_HANDSHAKE, "irc.swiftirc.net", 6697,
                new javax.net.ssl.SSLHandshakeException("certificate unknown"));

        assertTrue("must name the phase: " + described,
                described.toLowerCase().contains("tls"));
        assertTrue("must name the exception type: " + described,
                described.contains("SSLHandshakeException"));
        assertTrue("must carry the underlying message: " + described,
                described.contains("certificate unknown"));
        assertTrue("must name where we were connecting: " + described,
                described.contains("irc.swiftirc.net:6697"));
    }

    // Raw line logging exists so a user can hand us the log. That makes redaction a correctness
    // requirement, not a nicety: the SASL exchange and NickServ traffic carry the password.

    @Test
    public void saslResponseIsRedactedFromTheLog() {
        String redacted = SimpleIrcClient.redactForLog("AUTHENTICATE AGFjY291bnQAaHVudGVyMg==");

        assertFalse("the SASL PLAIN payload decodes to the password: " + redacted,
                redacted.contains("AGFjY291bnQAaHVudGVyMg=="));
        assertTrue("the exchange must still be visible: " + redacted,
                redacted.startsWith("AUTHENTICATE"));
    }

    @Test
    public void saslMechanismAndContinuationAreKept() {
        // These carry no secret and are exactly what you need to see to debug a stalled CAP/SASL.
        assertEquals("AUTHENTICATE PLAIN", SimpleIrcClient.redactForLog("AUTHENTICATE PLAIN"));
        assertEquals("AUTHENTICATE +", SimpleIrcClient.redactForLog("AUTHENTICATE +"));
    }

    @Test
    public void nickServPasswordIsRedactedFromTheLog() {
        String redacted = SimpleIrcClient.redactForLog("PRIVMSG NickServ :IDENTIFY hunter2");

        assertFalse("the NickServ password must not reach the log: " + redacted,
                redacted.contains("hunter2"));
        assertTrue("the fact that we identified must still be visible: " + redacted,
                redacted.contains("NickServ"));
    }

    @Test
    public void serverPasswordIsRedactedFromTheLog() {
        String redacted = SimpleIrcClient.redactForLog("PASS s3rverp4ss");

        assertFalse("the server password must not reach the log: " + redacted,
                redacted.contains("s3rverp4ss"));
    }

    @Test
    public void ordinaryTrafficIsLoggedVerbatim() {
        String line = ":nick!user@host PRIVMSG #rshelp :hello there";
        assertEquals("redaction must not damage the lines we actually want to read",
                line, SimpleIrcClient.redactForLog(line));
    }

    @Test
    public void disconnectCarriesTheReasonTheServerGave() {
        RecordingClient client = new RecordingClient();
        client.credentials("me", "runelite", "me");
        client.processLine(":server 001 me :Welcome to SwiftIRC");
        client.processLine("ERROR :Closing Link: me[1.2.3.4] (Ping timeout: 240 seconds)");

        client.disconnect();

        SimpleIrcClient.IrcEvent event = client.firstOf(SimpleIrcClient.IrcEvent.Type.DISCONNECT);
        assertNotNull("disconnecting must still announce itself", event);
        assertNotNull("a disconnect with a known cause must carry it", event.getMessage());
        assertTrue("the cause must reach the disconnect message: " + event.getMessage(),
                event.getMessage().contains("Ping timeout: 240 seconds"));
    }

    @Test
    public void deliberateQuitReportsNoFailureReason() {
        RecordingClient client = new RecordingClient();
        client.credentials("me", "runelite", "me");
        client.processLine(":server 001 me :Welcome to SwiftIRC");

        client.disconnect();

        SimpleIrcClient.IrcEvent event = client.firstOf(SimpleIrcClient.IrcEvent.Type.DISCONNECT);
        assertNotNull(event);
        assertNull("a clean /quit has no failure to report", event.getMessage());
    }

    @Test
    public void serverErrorReportsItsOwnTextNotAnEarlierReason() {
        // The recorded disconnect reason is first-writer-wins, so reporting the field rather than
        // the line's own text made the ERROR event repeat the KILL reason under "closed the link".
        RecordingClient client = new RecordingClient();
        client.credentials("me", "runelite", "me");
        client.processLine(":oper!o@staff.example KILL me :staff.example (spamming)");

        client.processLine("ERROR :Closing Link: me[1.2.3.4] (Killed)");

        SimpleIrcClient.IrcEvent last = client.lastOf(SimpleIrcClient.IrcEvent.Type.ERROR);
        assertTrue("the ERROR line must report its own text: " + last.getMessage(),
                last.getMessage().contains("Closing Link"));
    }

    @Test
    public void tlsSocketIsConfiguredToVerifyTheServerHostname() throws Exception {
        // SSLSocket validates the certificate chain but does NOT check that the certificate
        // belongs to the host we asked for, unless endpoint identification is turned on. Without
        // it, any certificate signed by a trusted CA - for any hostname at all - is accepted.
        javax.net.ssl.SSLSocket socket = (javax.net.ssl.SSLSocket)
                javax.net.ssl.SSLSocketFactory.getDefault().createSocket();

        SimpleIrcClient.applyTlsSettings(socket);

        assertEquals("the socket must verify the hostname against the certificate",
                "HTTPS", socket.getSSLParameters().getEndpointIdentificationAlgorithm());
    }

    @Test
    public void anUnconfiguredTlsSocketWouldNotVerifyTheHostname() throws Exception {
        // Pins the JDK default this guards against, so the test above cannot silently start
        // passing for the wrong reason.
        javax.net.ssl.SSLSocket socket = (javax.net.ssl.SSLSocket)
                javax.net.ssl.SSLSocketFactory.getDefault().createSocket();

        assertNull("JDK default is no hostname verification",
                socket.getSSLParameters().getEndpointIdentificationAlgorithm());
    }

    // Channel keys are passwords too, and they travel in both directions: we send them on JOIN
    // and MODE, and the server hands them back in a MODE change and in RPL_CHANNELMODEIS.

    @Test
    public void joinKeyIsRedactedFromTheLog() {
        String redacted = SimpleIrcClient.redactForLog("JOIN #secret hunter2");

        assertFalse("the channel key must not reach the log: " + redacted,
                redacted.contains("hunter2"));
        assertTrue("which channel we joined must still be visible: " + redacted,
                redacted.contains("#secret"));
    }

    @Test
    public void multipleJoinKeysAreRedacted() {
        String redacted = SimpleIrcClient.redactForLog("JOIN #a,#b key1,key2");

        assertFalse("no key may survive: " + redacted, redacted.contains("key1"));
        assertFalse("no key may survive: " + redacted, redacted.contains("key2"));
    }

    @Test
    public void joinWithoutAKeyIsLoggedVerbatim() {
        assertEquals("an ordinary join must not be damaged",
                "JOIN #rshelp", SimpleIrcClient.redactForLog("JOIN #rshelp"));
    }

    @Test
    public void modeKeyWeSetIsRedacted() {
        String redacted = SimpleIrcClient.redactForLog("MODE #chan +k hunter2");

        assertFalse("the key we set must not reach the log: " + redacted,
                redacted.contains("hunter2"));
        assertTrue("the mode change itself must stay visible: " + redacted,
                redacted.contains("+k"));
    }

    @Test
    public void modeKeyFromAnotherUserIsRedacted() {
        String redacted = SimpleIrcClient.redactForLog(":op!u@host MODE #chan +k hunter2");

        assertFalse("an incoming key must not reach the log either: " + redacted,
                redacted.contains("hunter2"));
    }

    @Test
    public void modeKeyRemovalIsRedacted() {
        // Removing a key names it on most ircds, so -k leaks just as readily as +k.
        String redacted = SimpleIrcClient.redactForLog(":op!u@host MODE #chan -k hunter2");

        assertFalse("the key must not reach the log: " + redacted, redacted.contains("hunter2"));
    }

    @Test
    public void channelModeReplyKeyIsRedacted() {
        // RPL_CHANNELMODEIS: the server volunteers the key when we join a keyed channel.
        String redacted = SimpleIrcClient.redactForLog(":server 324 me #chan +nk hunter2");

        assertFalse("the server's echo of the key must not reach the log: " + redacted,
                redacted.contains("hunter2"));
        assertTrue("the mode string must stay visible: " + redacted, redacted.contains("+nk"));
    }

    @Test
    public void modeChangesWithoutAKeyAreLoggedVerbatim() {
        String line = ":op!u@host MODE #chan +o someone";
        assertEquals("ordinary mode changes must not be damaged",
                line, SimpleIrcClient.redactForLog(line));
    }

    @Test
    public void chanServPasswordIsRedactedFromTheLog() {
        // Reachable today: /cs routes to ChanServ, whose IDENTIFY carries a channel password.
        String redacted = SimpleIrcClient.redactForLog("PRIVMSG ChanServ :IDENTIFY #chan hunter2");

        assertFalse("the channel password must not reach the log: " + redacted,
                redacted.contains("hunter2"));
        assertTrue("the service we talked to must stay visible: " + redacted,
                redacted.contains("ChanServ"));
    }

    @Test
    public void bareServiceAliasPasswordIsRedacted() {
        // Not reachable through the current command set, but the log is only safe to hand over
        // if this holds regardless of how the line was produced.
        assertFalse("bare NS alias must be redacted too",
                SimpleIrcClient.redactForLog("NS IDENTIFY hunter2").contains("hunter2"));
        assertFalse("bare CS alias must be redacted too",
                SimpleIrcClient.redactForLog("CS IDENTIFY #chan hunter2").contains("hunter2"));
    }

    @Test
    public void harmlessServiceCommandsAreLoggedVerbatim() {
        String line = "PRIVMSG ChanServ :INFO #rshelp";
        assertEquals("a service command with no secret must not be damaged",
                line, SimpleIrcClient.redactForLog(line));
    }

    @Test
    public void ordinaryChannelTalkAboutIdentifyingIsNotRedacted() {
        String line = "PRIVMSG #rshelp :you need to identify to nickserv first";
        assertEquals("redaction must not fire on ordinary conversation",
                line, SimpleIrcClient.redactForLog(line));
    }

    @Test
    public void setPasswordIsRedactedForBothServices() {
        // ChanServ puts the channel between the verb and the keyword: SET <chan> PASSWORD <pw>,
        // while NickServ has no middle argument. Both must be caught.
        assertFalse("ChanServ SET PASSWORD must be redacted",
                SimpleIrcClient.redactForLog("PRIVMSG ChanServ :SET #chan PASSWORD hunter2")
                        .contains("hunter2"));
        assertFalse("NickServ SET PASSWORD must be redacted",
                SimpleIrcClient.redactForLog("PRIVMSG NickServ :SET PASSWORD hunter2")
                        .contains("hunter2"));
    }

    @Test
    public void nonPasswordSettingsAreLoggedVerbatim() {
        String line = "PRIVMSG ChanServ :SET #chan SECURE on";
        assertEquals("settings that carry no secret must not be damaged",
                line, SimpleIrcClient.redactForLog(line));
    }
}

package com.irc;

import org.junit.Test;

import java.util.ArrayList;
import java.util.List;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The protocol layer for LIST (numerics 321/322/323, plus 263 when the server throttles us).
 *
 * Replies accumulate on the reader thread and are published as one immutable snapshot at 323, so
 * the EDT never observes a half-filled list. Two rules matter most: a run must not inherit rows
 * from the previous run, and a malformed row must never abort the rest of the list - servers send
 * a lot of channels and one bad line should cost one row, not the whole reply.
 */
public class SimpleIrcClientListTest {

    /** Feeds raw lines without a socket and records what came back out. */
    private static class RecordingClient extends SimpleIrcClient {
        final List<IrcEvent> events = new ArrayList<>();

        RecordingClient() {
            addEventListener(events::add);
        }

        @Override
        public synchronized void sendRawLine(String line) {
            // no socket in tests
        }

        boolean firedType(IrcEvent.Type type) {
            return events.stream().anyMatch(e -> e.getType() == type);
        }

        long countOf(IrcEvent.Type type) {
            return events.stream().filter(e -> e.getType() == type).count();
        }
    }

    private static void listReply(RecordingClient client, String channel, String count, String topic) {
        client.processLine(":server 322 me " + channel + " " + count + " :" + topic);
    }

    @Test
    public void collectsChannelsBetweenStartAndEnd() {
        RecordingClient client = new RecordingClient();
        client.processLine(":server 321 me Channel :Users  Name");
        listReply(client, "#help", "412", "Get help here");
        listReply(client, "#chat", "380", "General chat");
        client.processLine(":server 323 me :End of /LIST");

        List<ChannelListEntry> entries = client.getChannelListSnapshot();
        assertEquals(2, entries.size());
        assertEquals("#help", entries.get(0).getName());
        assertEquals(412, entries.get(0).getUserCount());
        assertEquals("Get help here", entries.get(0).getTopic());
        assertEquals("#chat", entries.get(1).getName());
        assertEquals(380, entries.get(1).getUserCount());
        assertTrue(client.firedType(SimpleIrcClient.IrcEvent.Type.CHANNEL_LIST));
    }

    /** Some servers never send 321, so 322 has to be able to start a run by itself. */
    @Test
    public void collectsWhenListStartIsNeverSent() {
        RecordingClient client = new RecordingClient();
        listReply(client, "#help", "412", "Get help here");
        client.processLine(":server 323 me :End of /LIST");

        assertEquals(1, client.getChannelListSnapshot().size());
        assertEquals("#help", client.getChannelListSnapshot().get(0).getName());
    }

    @Test
    public void keepsTopicsContainingSpacesAndColons() {
        RecordingClient client = new RecordingClient();
        listReply(client, "#help", "5", "Ask here: we answer 9-5, mostly");
        client.processLine(":server 323 me :End of /LIST");

        assertEquals("Ask here: we answer 9-5, mostly",
                client.getChannelListSnapshot().get(0).getTopic());
    }

    @Test
    public void treatsMissingTopicAsEmpty() {
        RecordingClient client = new RecordingClient();
        client.processLine(":server 322 me #notopic 7");
        client.processLine(":server 323 me :End of /LIST");

        List<ChannelListEntry> entries = client.getChannelListSnapshot();
        assertEquals(1, entries.size());
        assertEquals("", entries.get(0).getTopic());
        assertEquals(7, entries.get(0).getUserCount());
    }

    /** One unparseable count costs that row its number, not its place in the list. */
    @Test
    public void treatsUnparseableCountAsZeroAndKeepsTheRow() {
        RecordingClient client = new RecordingClient();
        listReply(client, "#weird", "many", "Odd server");
        listReply(client, "#fine", "12", "Normal");
        client.processLine(":server 323 me :End of /LIST");

        List<ChannelListEntry> entries = client.getChannelListSnapshot();
        assertEquals(2, entries.size());
        assertEquals(0, entries.get(0).getUserCount());
        assertEquals(12, entries.get(1).getUserCount());
    }

    @Test
    public void consecutiveRunsDoNotBleedTogether() {
        RecordingClient client = new RecordingClient();
        listReply(client, "#first", "1", "one");
        client.processLine(":server 323 me :End of /LIST");
        assertEquals(1, client.getChannelListSnapshot().size());

        listReply(client, "#second", "2", "two");
        client.processLine(":server 323 me :End of /LIST");

        List<ChannelListEntry> entries = client.getChannelListSnapshot();
        assertEquals(1, entries.size());
        assertEquals("#second", entries.get(0).getName());
        assertEquals(2, client.countOf(SimpleIrcClient.IrcEvent.Type.CHANNEL_LIST));
    }

    /** 321 arriving mid-flight resets, so a retried LIST never doubles up. */
    @Test
    public void listStartClearsPartialRun() {
        RecordingClient client = new RecordingClient();
        listReply(client, "#stale", "1", "stale");
        client.processLine(":server 321 me Channel :Users  Name");
        listReply(client, "#fresh", "2", "fresh");
        client.processLine(":server 323 me :End of /LIST");

        List<ChannelListEntry> entries = client.getChannelListSnapshot();
        assertEquals(1, entries.size());
        assertEquals("#fresh", entries.get(0).getName());
    }

    @Test
    public void tryAgainReportsFailureWithoutFiringChannelList() {
        RecordingClient client = new RecordingClient();
        client.processLine(":server 263 me LIST :Server load is too heavy, please try again later");

        assertTrue(client.firedType(SimpleIrcClient.IrcEvent.Type.CHANNEL_LIST_FAILED));
        assertFalse(client.firedType(SimpleIrcClient.IrcEvent.Type.CHANNEL_LIST));
    }

    /** 263 must not fire ERROR - IrcAdapter's ERROR case disconnects the client. */
    @Test
    public void tryAgainDoesNotFireError() {
        RecordingClient client = new RecordingClient();
        client.processLine(":server 263 me LIST :Try again later");

        assertFalse(client.firedType(SimpleIrcClient.IrcEvent.Type.ERROR));
    }

    @Test
    public void tryAgainDiscardsAPartialRun() {
        RecordingClient client = new RecordingClient();
        listReply(client, "#partial", "3", "partial");
        client.processLine(":server 263 me LIST :Try again later");
        client.processLine(":server 323 me :End of /LIST");

        assertTrue(client.getChannelListSnapshot().isEmpty());
    }

    @Test
    public void rowWithNoChannelNameIsSkipped() {
        RecordingClient client = new RecordingClient();
        client.processLine(":server 322 me");
        listReply(client, "#good", "4", "good");
        client.processLine(":server 323 me :End of /LIST");

        List<ChannelListEntry> entries = client.getChannelListSnapshot();
        assertEquals(1, entries.size());
        assertEquals("#good", entries.get(0).getName());
    }

    @Test
    public void stopsAccumulatingAtTheCapAndReportsTruncation() {
        RecordingClient client = new RecordingClient();
        for (int i = 0; i < 20005; i++) {
            listReply(client, "#chan" + i, "1", "topic");
        }
        client.processLine(":server 323 me :End of /LIST");

        assertEquals(20000, client.getChannelListSnapshot().size());
        assertTrue(client.isChannelListTruncated());
    }

    /**
     * The second run here deliberately omits 321, since not every server sends it. The flag must
     * still reset on the first 322 of a fresh run - it must not depend on 321 arriving to clear it.
     */
    @Test
    public void truncationFlagIsClearedByAFreshRun() {
        RecordingClient client = new RecordingClient();
        for (int i = 0; i < 20005; i++) {
            listReply(client, "#chan" + i, "1", "topic");
        }
        client.processLine(":server 323 me :End of /LIST");
        assertTrue(client.isChannelListTruncated());

        listReply(client, "#small", "1", "topic");
        client.processLine(":server 323 me :End of /LIST");

        assertFalse(client.isChannelListTruncated());
        assertEquals(1, client.getChannelListSnapshot().size());
    }

    /** A 323 with no preceding 321/322 must not wipe out the last good snapshot or re-fire CHANNEL_LIST. */
    @Test
    public void unpairedListEndDoesNotClobberThePreviousSnapshot() {
        RecordingClient client = new RecordingClient();
        listReply(client, "#good", "4", "good");
        client.processLine(":server 323 me :End of /LIST");
        assertEquals(1, client.countOf(SimpleIrcClient.IrcEvent.Type.CHANNEL_LIST));

        client.processLine(":server 323 me :End of /LIST");

        List<ChannelListEntry> entries = client.getChannelListSnapshot();
        assertEquals(1, entries.size());
        assertEquals("#good", entries.get(0).getName());
        assertEquals(1, client.countOf(SimpleIrcClient.IrcEvent.Type.CHANNEL_LIST));
    }

    /** disconnect() must clear a partial run so it can't bleed into the connection's next LIST. */
    @Test
    public void disconnectClearsAPartialRun() {
        RecordingClient client = new RecordingClient();
        client.processLine(":server 001 me :Welcome");
        listReply(client, "#partial", "3", "partial");

        client.disconnect();

        listReply(client, "#fresh", "1", "fresh");
        client.processLine(":server 323 me :End of /LIST");

        List<ChannelListEntry> entries = client.getChannelListSnapshot();
        assertEquals(1, entries.size());
        assertEquals("#fresh", entries.get(0).getName());
    }

    /** 263 only concerns LIST; a throttled WHO must not touch LIST state or fire CHANNEL_LIST_FAILED. */
    @Test
    public void tryAgainForADifferentCommandLeavesListStateAlone() {
        RecordingClient client = new RecordingClient();
        listReply(client, "#inflight", "1", "still going");

        client.processLine(":server 263 me WHO :Server load is too heavy, please try again later");

        assertFalse(client.firedType(SimpleIrcClient.IrcEvent.Type.CHANNEL_LIST_FAILED));

        client.processLine(":server 323 me :End of /LIST");

        List<ChannelListEntry> entries = client.getChannelListSnapshot();
        assertEquals(1, entries.size());
        assertEquals("#inflight", entries.get(0).getName());
    }

    @Test
    public void snapshotIsImmutable() {
        RecordingClient client = new RecordingClient();
        listReply(client, "#help", "1", "topic");
        client.processLine(":server 323 me :End of /LIST");

        try {
            client.getChannelListSnapshot().add(new ChannelListEntry("#injected", 0, ""));
            org.junit.Assert.fail("snapshot handed to the EDT must not be mutable");
        } catch (UnsupportedOperationException expected) {
            // the EDT holds this list; nothing may mutate it after publication
        }
    }
}

package com.irc;

import org.junit.Test;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Base64;
import java.util.List;
import static org.junit.Assert.*;

public class SimpleIrcClientTest {

    /** Records sent lines instead of writing to a socket. */
    private static SimpleIrcClient recordingClient(List<String> sent) {
        SimpleIrcClient client = new SimpleIrcClient() {
            @Override
            public synchronized void sendRawLine(String line) {
                sent.add(line);
            }
        };
        client.credentials("me", "runelite", "me");
        return client;
    }

    @Test
    public void disconnectWhileConnectingStopsRegistration() {
        List<String> sent = new ArrayList<>();
        SimpleIrcClient client = recordingClient(sent);
        client.disconnect("Network removed");
        assertFalse(client.beginRegistration());
        assertTrue(sent.toString(), sent.isEmpty());
    }

    @Test
    public void registrationProceedsWhenNotStopped() {
        List<String> sent = new ArrayList<>();
        SimpleIrcClient client = recordingClient(sent);
        assertTrue(client.beginRegistration());
        assertEquals("CAP LS 302", sent.get(0));
        assertEquals("NICK me", sent.get(1));
    }

    @Test
    public void historyBatchEventCarriesMessages() {
        SimpleIrcClient.IrcEvent inner = new SimpleIrcClient.IrcEvent(
            SimpleIrcClient.IrcEvent.Type.MESSAGE, "nick", "#chan", "hello", "2024-01-01T12:00:00.000Z"
        );
        List<SimpleIrcClient.IrcEvent> batch = List.of(inner);

        SimpleIrcClient.IrcEvent batchEvent = new SimpleIrcClient.IrcEvent(
            SimpleIrcClient.IrcEvent.Type.HISTORY_BATCH, null, "#chan", null, null, batch
        );

        assertEquals(SimpleIrcClient.IrcEvent.Type.HISTORY_BATCH, batchEvent.getType());
        assertEquals("#chan", batchEvent.getTarget());
        assertNotNull(batchEvent.getHistoryMessages());
        assertEquals(1, batchEvent.getHistoryMessages().size());
        assertEquals("hello", batchEvent.getHistoryMessages().get(0).getMessage());
    }

    @Test
    public void existingFiveArgConstructorSetsHistoryMessagesToNull() {
        SimpleIrcClient.IrcEvent event = new SimpleIrcClient.IrcEvent(
            SimpleIrcClient.IrcEvent.Type.MESSAGE, "nick", "#chan", "hello", null
        );
        assertNull(event.getHistoryMessages());
    }

    @Test
    public void tagParsingExtractsTimeAndBatch() {
        TestableIrcClient client = new TestableIrcClient();
        client.processLine("@time=2024-01-01T12:00:00.000Z;batch=ref1 :nick!user@host PRIVMSG #chan :hello");
        assertEquals("2024-01-01T12:00:00.000Z", client.getLastTagTime());
        assertEquals("ref1", client.getLastTagBatch());
    }

    @Test
    public void noTagsLeavesFieldsNull() {
        TestableIrcClient client = new TestableIrcClient();
        client.processLine(":nick!user@host PRIVMSG #chan :hello");
        assertNull(client.getLastTagTime());
        assertNull(client.getLastTagBatch());
    }

    @Test
    public void capLsWithChathistoryRequestsCaps() {
        TestableIrcClient client = new TestableIrcClient();
        // Final LS line (no continuation *): params = [*, LS, cap-list]
        client.processLine(":server CAP * LS :chathistory batch server-time");
        assertTrue(client.sentLines.stream().anyMatch(l -> l.startsWith("CAP REQ")));
        assertTrue(client.sentLines.stream().anyMatch(l -> l.contains("chathistory")));
    }

    @Test
    public void capLsWithCapValueStillRequestsChathistory() {
        TestableIrcClient client = new TestableIrcClient();
        // Server advertises chathistory with a value (e.g. max limit)
        client.processLine(":server CAP * LS :chathistory=50 batch server-time");
        assertTrue(client.sentLines.stream().anyMatch(l -> l.startsWith("CAP REQ")));
        assertTrue(client.sentLines.stream().anyMatch(l -> l.contains("chathistory")));
    }

    @Test
    public void capLsWithoutChathistorySendsCapEnd() {
        TestableIrcClient client = new TestableIrcClient();
        client.processLine(":server CAP * LS :multi-prefix");
        assertTrue(client.sentLines.contains("CAP END"));
        assertFalse(client.isCapHistorySupported());
    }

    @Test
    public void capAckWithChathistorySetsFlag() {
        TestableIrcClient client = new TestableIrcClient();
        client.processLine(":server CAP * LS :chathistory batch server-time");
        client.sentLines.clear();
        client.processLine(":server CAP * ACK :chathistory batch server-time");
        assertTrue(client.isCapHistorySupported());
        assertTrue(client.sentLines.contains("CAP END"));
    }

    @Test
    public void capNakSendsCapEndAndLeavesHistoryUnsupported() {
        TestableIrcClient client = new TestableIrcClient();
        client.processLine(":server CAP * LS :chathistory");
        client.sentLines.clear();
        client.processLine(":server CAP * NAK :chathistory batch server-time");
        assertFalse(client.isCapHistorySupported());
        assertTrue(client.sentLines.contains("CAP END"));
    }

    @Test
    public void capEndSentOnlyOnce() {
        TestableIrcClient client = new TestableIrcClient();
        client.processLine(":server CAP * LS :chathistory");
        client.processLine(":server CAP * ACK :chathistory");
        client.processLine(":server CAP * ACK :batch"); // second ACK line
        long count = client.sentLines.stream().filter("CAP END"::equals).count();
        assertEquals(1, count);
    }

    @Test
    public void multiLineCapLsAccumulatesBeforeSendingReq() {
        TestableIrcClient client = new TestableIrcClient();
        // Continuation line — has * before the cap list
        client.processLine(":server CAP * LS * :batch server-time");
        assertTrue(client.sentLines.isEmpty()); // no CAP REQ yet
        // Final line — no continuation *
        client.processLine(":server CAP * LS :chathistory");
        assertTrue(client.sentLines.stream().anyMatch(l -> l.contains("chathistory")));
    }

    @Test
    public void batchAccumulatesMessagesAndFiresHistoryBatchEvent() {
        TestableIrcClient client = new TestableIrcClient();
        List<SimpleIrcClient.IrcEvent> received = new ArrayList<>();
        client.addEventListener(event -> {
            if (event.getType() == SimpleIrcClient.IrcEvent.Type.HISTORY_BATCH) {
                received.add(event);
            }
        });

        client.processLine(":server BATCH +ref1 chathistory #chan");
        client.processLine("@time=2024-01-01T10:00:00.000Z;batch=ref1 :alice!a@host PRIVMSG #chan :hello");
        client.processLine("@time=2024-01-01T10:01:00.000Z;batch=ref1 :bob!b@host PRIVMSG #chan :world");
        client.processLine(":server BATCH -ref1");

        assertEquals(1, received.size());
        SimpleIrcClient.IrcEvent batch = received.get(0);
        assertEquals("#chan", batch.getTarget());
        assertEquals(2, batch.getHistoryMessages().size());
        assertEquals("hello", batch.getHistoryMessages().get(0).getMessage());
        assertEquals("2024-01-01T10:00:00.000Z", batch.getHistoryMessages().get(0).getAdditionalData());
        assertEquals("world", batch.getHistoryMessages().get(1).getMessage());
    }

    @Test
    public void batchTaggedMessageDoesNotFireNormalMessageEvent() {
        TestableIrcClient client = new TestableIrcClient();
        List<SimpleIrcClient.IrcEvent> messages = new ArrayList<>();
        client.addEventListener(event -> {
            if (event.getType() == SimpleIrcClient.IrcEvent.Type.MESSAGE) {
                messages.add(event);
            }
        });

        client.processLine(":server BATCH +ref1 chathistory #chan");
        client.processLine("@batch=ref1 :alice!a@host PRIVMSG #chan :hello");
        client.processLine(":server BATCH -ref1");

        assertTrue("Batch-tagged PRIVMSG should not fire a normal MESSAGE event", messages.isEmpty());
    }

    @Test
    public void actionInBatchUsesSourceWithoutStarPrefix() {
        TestableIrcClient client = new TestableIrcClient();
        List<SimpleIrcClient.IrcEvent> received = new ArrayList<>();
        client.addEventListener(event -> {
            if (event.getType() == SimpleIrcClient.IrcEvent.Type.HISTORY_BATCH) received.add(event);
        });

        client.processLine(":server BATCH +ref1 chathistory #chan");
        client.processLine("@batch=ref1 :alice!a@host PRIVMSG #chan :\u0001ACTION waves\u0001");
        client.processLine(":server BATCH -ref1");

        SimpleIrcClient.IrcEvent batch = received.get(0);
        assertEquals(SimpleIrcClient.IrcEvent.Type.ACTION, batch.getHistoryMessages().get(0).getType());
        assertEquals("alice", batch.getHistoryMessages().get(0).getSource()); // no "* " prefix
        assertEquals("waves", batch.getHistoryMessages().get(0).getMessage());
    }

    @Test
    public void disconnectClearsBatchState() {
        TestableIrcClient client = new TestableIrcClient();
        client.processLine(":server BATCH +ref1 chathistory #chan");
        client.disconnect();
        List<SimpleIrcClient.IrcEvent> received = new ArrayList<>();
        client.addEventListener(event -> {
            if (event.getType() == SimpleIrcClient.IrcEvent.Type.HISTORY_BATCH) received.add(event);
        });
        client.processLine(":server BATCH +ref1 chathistory #chan");
        client.processLine("@batch=ref1 :alice!a@host PRIVMSG #chan :hello");
        client.processLine(":server BATCH -ref1");
        assertEquals(1, received.size());
    }

    @Test
    public void selfJoinRequestsChatHistoryWhenSupported() {
        TestableIrcClient client = new TestableIrcClient();
        client.credentials("TestUser", "user", "user");
        client.setCapHistorySupportedForTest(true);
        client.processLine(":TestUser!u@host JOIN #chan");
        assertTrue(client.sentLines.stream().anyMatch(l -> l.equals("CHATHISTORY LATEST #chan * 100")));
    }

    @Test
    public void selfJoinDoesNotRequestHistoryWhenUnsupported() {
        TestableIrcClient client = new TestableIrcClient();
        client.credentials("TestUser", "user", "user");
        client.processLine(":TestUser!u@host JOIN #chan");
        assertFalse(client.sentLines.stream().anyMatch(l -> l.startsWith("CHATHISTORY")));
    }

    @Test
    public void otherUserJoinDoesNotRequestHistory() {
        TestableIrcClient client = new TestableIrcClient();
        client.credentials("TestUser", "user", "user");
        client.setCapHistorySupportedForTest(true);
        client.processLine(":OtherUser!u@host JOIN #chan");
        assertFalse(client.sentLines.stream().anyMatch(l -> l.startsWith("CHATHISTORY")));
    }

    @Test
    public void capLsWithSaslRequestsSaslWhenPasswordSet() {
        TestableIrcClient client = new TestableIrcClient();
        client.credentials("TestUser", "user", "user");
        client.sasl("acct", "secret");
        client.processLine(":server CAP * LS :sasl chathistory batch");
        assertTrue(client.sentLines.stream().anyMatch(l -> l.startsWith("CAP REQ") && l.contains("sasl")));
    }

    @Test
    public void capLsDoesNotRequestSaslWhenNoPassword() {
        TestableIrcClient client = new TestableIrcClient();
        client.credentials("TestUser", "user", "user");
        // No sasl() call, so SASL is disabled.
        client.processLine(":server CAP * LS :sasl chathistory");
        assertTrue(client.sentLines.stream().noneMatch(l -> l.contains("sasl")));
    }

    @Test
    public void capAckWithSaslSendsAuthenticatePlainAndDefersCapEnd() {
        TestableIrcClient client = new TestableIrcClient();
        client.credentials("TestUser", "user", "user");
        client.sasl("acct", "secret");
        client.processLine(":server CAP * LS :sasl chathistory");
        client.sentLines.clear();
        client.processLine(":server CAP * ACK :sasl chathistory");
        assertTrue(client.sentLines.contains("AUTHENTICATE PLAIN"));
        assertFalse("CAP END must wait until SASL completes", client.sentLines.contains("CAP END"));
    }

    @Test
    public void authenticatePlusSendsBase64PlainCredentials() {
        TestableIrcClient client = new TestableIrcClient();
        client.credentials("TestUser", "user", "user");
        client.sasl("myaccount", "secret");
        client.processLine("AUTHENTICATE +");

        String authLine = client.sentLines.stream()
                .filter(l -> l.startsWith("AUTHENTICATE ") && !l.equals("AUTHENTICATE PLAIN"))
                .reduce((a, b) -> b).orElse(null);
        assertNotNull("client should send an AUTHENTICATE payload", authLine);

        String decoded = new String(
                Base64.getDecoder().decode(authLine.substring("AUTHENTICATE ".length())),
                StandardCharsets.UTF_8);
        assertEquals("\0myaccount\0secret", decoded);
    }

    @Test
    public void authenticateUsesNickAsAuthcidWhenAccountBlank() {
        TestableIrcClient client = new TestableIrcClient();
        client.credentials("TestUser", "user", "user");
        client.sasl("", "secret");
        client.processLine("AUTHENTICATE +");

        String authLine = client.sentLines.stream()
                .filter(l -> l.startsWith("AUTHENTICATE ") && !l.equals("AUTHENTICATE PLAIN"))
                .reduce((a, b) -> b).orElse(null);
        assertNotNull(authLine);

        String decoded = new String(
                Base64.getDecoder().decode(authLine.substring("AUTHENTICATE ".length())),
                StandardCharsets.UTF_8);
        assertEquals("\0TestUser\0secret", decoded);
    }

    @Test
    public void saslSuccessNumericSendsCapEndAndFiresEvent() {
        TestableIrcClient client = new TestableIrcClient();
        client.credentials("TestUser", "user", "user");
        client.sasl("acct", "secret");
        List<SimpleIrcClient.IrcEvent> events = new ArrayList<>();
        client.addEventListener(e -> {
            if (e.getType() == SimpleIrcClient.IrcEvent.Type.SASL_SUCCESS) events.add(e);
        });
        client.processLine(":server CAP * LS :sasl");
        client.processLine(":server CAP * ACK :sasl");
        client.sentLines.clear();
        client.processLine(":server 903 TestUser :SASL authentication successful");
        assertTrue(client.sentLines.contains("CAP END"));
        assertEquals(1, events.size());
    }

    @Test
    public void saslFailureNumericSendsCapEndAndFiresEvent() {
        TestableIrcClient client = new TestableIrcClient();
        client.credentials("TestUser", "user", "user");
        client.sasl("acct", "secret");
        List<SimpleIrcClient.IrcEvent> events = new ArrayList<>();
        client.addEventListener(e -> {
            if (e.getType() == SimpleIrcClient.IrcEvent.Type.SASL_FAILED) events.add(e);
        });
        client.processLine(":server CAP * LS :sasl");
        client.processLine(":server CAP * ACK :sasl");
        client.sentLines.clear();
        client.processLine(":server 904 TestUser :SASL authentication failed");
        assertTrue("must send CAP END to continue registration even on SASL failure",
                client.sentLines.contains("CAP END"));
        assertEquals(1, events.size());
    }

    /** Test subclass that captures sent lines and exposes internal state. */
    static class TestableIrcClient extends SimpleIrcClient {
        final List<String> sentLines = new ArrayList<>();

        @Override
        public synchronized void sendRawLine(String line) {
            sentLines.add(line);
        }

        String getLastTagTime() { return currentTagTime; }
        String getLastTagBatch() { return currentTagBatch; }
        boolean isCapHistorySupported() { return capHistorySupported; }

        void setCapHistorySupportedForTest(boolean val) {
            capHistorySupported = val;
        }
    }
}

package com.irc;

import org.junit.Test;

import java.util.ArrayList;
import java.util.List;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The protocol layer feeding ChannelUserList and announcing changes.
 *
 * Every membership event must both update the roster and fire USERS_CHANGED for each channel it
 * touched, so the panel redraws exactly the affected buffers. Display events (NAMES, CHANNEL_MODE)
 * must keep firing unchanged so /names and mode messages still print to chat.
 */
public class SimpleIrcClientUsersTest {

    /** Feeds raw lines without a socket and records what came back out. */
    private static class RecordingClient extends SimpleIrcClient {
        final List<String> sentLines = new ArrayList<>();
        final List<IrcEvent> events = new ArrayList<>();

        RecordingClient() {
            addEventListener(events::add);
        }

        @Override
        public synchronized void sendRawLine(String line) {
            sentLines.add(line);
        }

        List<String> usersChangedChannels() {
            List<String> channels = new ArrayList<>();
            for (IrcEvent event : events) {
                if (event.getType() == IrcEvent.Type.USERS_CHANGED) {
                    channels.add(event.getTarget());
                }
            }
            return channels;
        }

        List<String> nicksIn(String channel) {
            List<String> nicks = new ArrayList<>();
            for (ChannelUserList.Entry entry : getChannelUsers(channel)) {
                nicks.add(entry.getPrefix() + entry.getNick());
            }
            return nicks;
        }

        boolean firedType(IrcEvent.Type type) {
            return events.stream().anyMatch(e -> e.getType() == type);
        }
    }

    /** A 353 followed by its 366 terminator, as the server sends them. */
    private static void loadNames(RecordingClient client, String channel, String names) {
        client.processLine(":server 353 me = " + channel + " :" + names);
        client.processLine(":server 366 me " + channel + " :End of /NAMES list");
    }

    @Test
    public void namesReplyPopulatesTheRosterWithPrefixesIntact() {
        RecordingClient client = new RecordingClient();
        loadNames(client, "#chan", "@bob +dave erin");
        assertEquals(java.util.Arrays.asList("@bob", "+dave", "erin"), client.nicksIn("#chan"));
    }

    @Test
    public void namesReplyStillFiresTheDisplayEventSoSlashNamesKeepsPrinting() {
        RecordingClient client = new RecordingClient();
        client.processLine(":server 353 me = #chan :@bob +dave");
        assertTrue(client.firedType(SimpleIrcClient.IrcEvent.Type.NAMES));
    }

    @Test
    public void endOfNamesAnnouncesTheChannel() {
        RecordingClient client = new RecordingClient();
        loadNames(client, "#chan", "@bob");
        assertEquals(java.util.Collections.singletonList("#chan"), client.usersChangedChannels());
    }

    @Test
    public void isupportRetunesThePrefixTable() {
        RecordingClient client = new RecordingClient();
        client.processLine(":server 005 me PREFIX=(ov)@+ CHANMODES=b,k,l,imnpst :are supported");
        loadNames(client, "#chan", "@bob %carol");
        // With PREFIX=(ov)@+ the server has no halfop, so "%carol" is a nick starting with '%'.
        assertEquals(java.util.Arrays.asList("@bob", "%carol"), client.nicksIn("#chan"));
    }

    @Test
    public void joinAddsTheUserAndAnnounces() {
        RecordingClient client = new RecordingClient();
        loadNames(client, "#chan", "@bob");
        client.events.clear();

        client.processLine(":erin!user@host JOIN #chan");

        assertEquals(java.util.Arrays.asList("@bob", "erin"), client.nicksIn("#chan"));
        assertEquals(java.util.Collections.singletonList("#chan"), client.usersChangedChannels());
    }

    @Test
    public void partRemovesTheUserAndAnnounces() {
        RecordingClient client = new RecordingClient();
        loadNames(client, "#chan", "@bob erin");
        client.events.clear();

        client.processLine(":erin!user@host PART #chan :bye");

        assertEquals(java.util.Collections.singletonList("@bob"), client.nicksIn("#chan"));
        assertEquals(java.util.Collections.singletonList("#chan"), client.usersChangedChannels());
    }

    @Test
    public void quitAnnouncesEveryChannelTheUserWasIn() {
        RecordingClient client = new RecordingClient();
        loadNames(client, "#one", "erin bob");
        loadNames(client, "#two", "erin");
        loadNames(client, "#three", "bob");
        client.events.clear();

        client.processLine(":erin!user@host QUIT :gone");

        List<String> announced = client.usersChangedChannels();
        assertEquals(2, announced.size());
        assertTrue(announced.contains("#one"));
        assertTrue(announced.contains("#two"));
        assertFalse("#three had no erin", announced.contains("#three"));
    }

    @Test
    public void quitStillCarriesTheAffectedChannelsOnTheQuitEvent() {
        RecordingClient client = new RecordingClient();
        loadNames(client, "#one", "erin");
        client.events.clear();

        client.processLine(":erin!user@host QUIT :gone");

        SimpleIrcClient.IrcEvent quit = client.events.stream()
                .filter(e -> e.getType() == SimpleIrcClient.IrcEvent.Type.QUIT)
                .findFirst().orElseThrow(AssertionError::new);
        assertEquals("#one", quit.getAdditionalData());
    }

    @Test
    public void nickChangeRenamesInPlaceAndKeepsModes() {
        RecordingClient client = new RecordingClient();
        loadNames(client, "#chan", "@bob");
        client.events.clear();

        client.processLine(":bob!user@host NICK robert");

        assertEquals(java.util.Collections.singletonList("@robert"), client.nicksIn("#chan"));
        assertEquals(java.util.Collections.singletonList("#chan"), client.usersChangedChannels());
    }

    @Test
    public void kickRemovesTheUserAndAnnounces() {
        RecordingClient client = new RecordingClient();
        loadNames(client, "#chan", "@bob erin");
        client.events.clear();

        client.processLine(":bob!user@host KICK #chan erin :out");

        assertEquals(java.util.Collections.singletonList("@bob"), client.nicksIn("#chan"));
        assertTrue(client.usersChangedChannels().contains("#chan"));
    }

    @Test
    public void partingOurselvesDropsTheWholeRoster() {
        RecordingClient client = new RecordingClient();
        client.processLine(":server 001 me :Welcome"); // registers our own nick as "me"
        loadNames(client, "#chan", "@bob me");
        client.events.clear();

        client.processLine(":me!user@host PART #chan :bye");

        assertTrue("leaving drops the channel, not just us",
                client.nicksIn("#chan").isEmpty());
    }

    @Test
    public void beingKickedDropsTheWholeRoster() {
        RecordingClient client = new RecordingClient();
        client.processLine(":server 001 me :Welcome");
        loadNames(client, "#chan", "@bob me");
        client.events.clear();

        client.processLine(":bob!user@host KICK #chan me :out");

        assertTrue("being kicked drops the channel, not just us",
                client.nicksIn("#chan").isEmpty());
    }

    @Test
    public void channelModeIsAppliedToTheRoster() {
        RecordingClient client = new RecordingClient();
        loadNames(client, "#chan", "bob");
        client.events.clear();

        client.processLine(":op!user@host MODE #chan +o bob");

        assertEquals(java.util.Collections.singletonList("@bob"), client.nicksIn("#chan"));
        assertTrue(client.usersChangedChannels().contains("#chan"));
    }

    @Test
    public void compoundChannelModeAlignsItsParameters() {
        RecordingClient client = new RecordingClient();
        loadNames(client, "#chan", "bob");
        client.events.clear();

        client.processLine(":op!user@host MODE #chan +mo bob");

        assertEquals(java.util.Collections.singletonList("@bob"), client.nicksIn("#chan"));
    }

    @Test
    public void channelModeStillFiresTheDisplayEvent() {
        RecordingClient client = new RecordingClient();
        loadNames(client, "#chan", "bob");
        client.events.clear();

        client.processLine(":op!user@host MODE #chan +o bob");

        assertTrue(client.firedType(SimpleIrcClient.IrcEvent.Type.CHANNEL_MODE));
    }

    @Test
    public void userModeOnANickIsNotTreatedAsAChannel() {
        RecordingClient client = new RecordingClient();
        client.processLine(":me!user@host MODE me +i");
        assertTrue("no channel changed", client.usersChangedChannels().isEmpty());
    }

    // --- away ---

    private static boolean awayIn(RecordingClient client, String channel, String nick) {
        for (ChannelUserList.Entry entry : client.getChannelUsers(channel)) {
            if (entry.getNick().equals(nick)) return entry.isAway();
        }
        throw new AssertionError(nick + " is not in " + channel);
    }

    @Test
    public void requestsAwayNotifyWhenAdvertised() {
        RecordingClient client = new RecordingClient();
        client.processLine(":server CAP * LS :batch away-notify");
        assertTrue(client.sentLines.contains("CAP REQ :batch away-notify"));
    }

    @Test
    public void joiningAsksWhoOnlyWithAwayNotify() {
        RecordingClient with = new RecordingClient();
        with.credentials("me", "me", "me");
        with.processLine(":server CAP me ACK :away-notify");
        with.processLine(":me!u@h JOIN #chan");
        assertTrue(with.sentLines.contains("WHO #chan"));

        RecordingClient without = new RecordingClient();
        without.credentials("me", "me", "me");
        without.processLine(":me!u@h JOIN #chan");
        assertFalse(without.sentLines.contains("WHO #chan"));
    }

    @Test
    public void whoRepliesMarkGoneUsersAwayAndRedrawOnceAtTheEnd() {
        RecordingClient client = new RecordingClient();
        loadNames(client, "#chan", "@bob erin");
        client.events.clear();
        client.processLine(":server 352 me #chan ~b host server bob G@ :0 Bob");
        client.processLine(":server 352 me #chan ~e host server erin H :0 Erin");
        assertTrue("no redraw per reply", client.usersChangedChannels().isEmpty());
        client.processLine(":server 315 me #chan :End of /WHO list.");
        assertEquals(java.util.Collections.singletonList("#chan"), client.usersChangedChannels());
        assertTrue(awayIn(client, "#chan", "bob"));
        assertFalse(awayIn(client, "#chan", "erin"));
    }

    @Test
    public void awayNotifyTogglesAwayAndRedraws() {
        RecordingClient client = new RecordingClient();
        loadNames(client, "#chan", "bob");
        client.events.clear();
        client.processLine(":bob!u@h AWAY :lunch");
        assertTrue(awayIn(client, "#chan", "bob"));
        assertEquals(java.util.Collections.singletonList("#chan"), client.usersChangedChannels());
        client.processLine(":bob!u@h AWAY");
        assertFalse(awayIn(client, "#chan", "bob"));
    }

    @Test
    public void ourOwnAwayNumericsMarkUs() {
        RecordingClient client = new RecordingClient();
        client.credentials("me", "me", "me");
        loadNames(client, "#chan", "me");
        client.processLine(":server 306 me :You have been marked as being away");
        assertTrue(awayIn(client, "#chan", "me"));
        client.processLine(":server 305 me :You are no longer marked as being away");
        assertFalse(awayIn(client, "#chan", "me"));
    }

    /**
     * ZNC answers a CAP LS sent before login with its core caps only, then offers the network's
     * via CAP NEW once it knows who we are - after which it replays every JOIN at once.
     */
    @Test
    public void requestsAwayNotifyWhenOfferedLaterThroughCapNew() {
        RecordingClient client = new RecordingClient();
        client.processLine(":irc.znc.in CAP me NEW :account-notify away-notify extended-join");
        assertTrue(client.sentLines.contains("CAP REQ :away-notify"));

        RecordingClient other = new RecordingClient();
        other.processLine(":irc.znc.in CAP me NEW :account-notify extended-join");
        assertTrue(other.sentLines.isEmpty());
    }

    @Test
    public void awayNotifyAckedAfterJoiningAsksWhoForEveryChannelAlreadyJoined() {
        RecordingClient client = new RecordingClient();
        client.credentials("me", "me", "me");
        client.processLine(":irc.znc.in CAP unknown-nick LS :batch");
        client.processLine(":irc.znc.in CAP me ACK :batch");
        client.processLine(":me!u@h JOIN #a");
        loadNames(client, "#a", "me bob");
        client.processLine(":me!u@h JOIN #b");
        loadNames(client, "#b", "me");
        assertFalse(client.sentLines.contains("WHO #a"));

        client.processLine(":irc.znc.in CAP me ACK :away-notify");
        assertTrue(client.sentLines.contains("WHO #a"));
        assertTrue(client.sentLines.contains("WHO #b"));
        assertEquals("CAP END is sent once, at registration", 1,
                client.sentLines.stream().filter("CAP END"::equals).count());
    }

    @Test
    public void capDelOfAwayNotifyForgetsAwayMarksSinceTheyWouldGoStale() {
        RecordingClient client = new RecordingClient();
        client.credentials("me", "me", "me");
        client.processLine(":server CAP me ACK :away-notify");
        loadNames(client, "#chan", "bob");
        client.processLine(":bob!u@h AWAY :lunch");
        client.events.clear();

        client.processLine(":server CAP me DEL :away-notify");
        assertFalse(awayIn(client, "#chan", "bob"));
        assertEquals(java.util.Collections.singletonList("#chan"), client.usersChangedChannels());
        client.processLine(":me!u@h JOIN #other");
        assertFalse(client.sentLines.contains("WHO #other"));
    }
}

package com.irc;

import org.junit.Test;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

import static org.junit.Assert.*;

public class SimpleIrcClientZncTest {

    /** Feeds raw lines without a socket and records what came back out. */
    private static class RecordingClient extends SimpleIrcClient {
        final List<String> sentLines = new ArrayList<>();
        final List<IrcEvent> events = new ArrayList<>();

        RecordingClient() {
            addEventListener(events::add);
            credentials("me", "runelite", "me");
        }

        @Override
        public synchronized void sendRawLine(String line) {
            sentLines.add(line);
        }

        IrcEvent last(IrcEvent.Type type) {
            IrcEvent found = null;
            for (IrcEvent e : events) if (e.getType() == type) found = e;
            return found;
        }
    }

    /**
     * CAP LS opens the burst so the server holds registration until CAP END. ZNC registers the
     * moment it has PASS, NICK and USER, so a CAP LS sent after them was answered only after the
     * JOIN replay - too late for away-notify to trigger WHO on those joins.
     */
    @Test
    public void capLsOpensTheBurstThenPassPrecedesNickAndKeepsSpaces() {
        RecordingClient client = new RecordingClient();
        client.serverPassword("me/rizon:pass word");
        client.sendRegistration();
        assertEquals(Arrays.asList("CAP LS 302", "PASS :me/rizon:pass word", "NICK me", "USER runelite 0 * :me"),
                client.sentLines);
    }

    @Test
    public void noPassWithoutAPassword() {
        RecordingClient client = new RecordingClient();
        client.serverPassword(null);
        client.sendRegistration();
        assertEquals(Arrays.asList("CAP LS 302", "NICK me", "USER runelite 0 * :me"), client.sentLines);
    }

    @Test
    public void requestsSelfMessageOnlyWhenAdvertisedAndNeverEchoMessage() {
        RecordingClient znc = new RecordingClient();
        znc.processLine(":irc.znc.in CAP * LS :batch server-time znc.in/self-message echo-message");
        assertTrue(znc.sentLines.contains("CAP REQ :batch server-time znc.in/self-message"));
        for (String line : znc.sentLines) assertFalse(line, line.contains("echo-message"));

        RecordingClient plain = new RecordingClient();
        plain.processLine(":server CAP * LS :batch");
        assertTrue(plain.sentLines.contains("CAP REQ :batch"));
    }

    @Test
    public void ownPrivmsgIsFiledUnderItsTarget() {
        RecordingClient client = new RecordingClient();
        client.processLine(":server 001 me :Welcome");
        client.processLine(":me!u@h PRIVMSG Luna :sent from my phone");
        SimpleIrcClient.IrcEvent event = client.last(SimpleIrcClient.IrcEvent.Type.MESSAGE);
        assertEquals("Luna", event.getTarget());
        assertEquals("me", event.getSource());
    }

    @Test
    public void ownActionIsFiledUnderItsTarget() {
        RecordingClient client = new RecordingClient();
        client.processLine(":server 001 me :Welcome");
        client.processLine(":me!u@h PRIVMSG Luna :\u0001ACTION waves\u0001");
        assertEquals("Luna", client.last(SimpleIrcClient.IrcEvent.Type.ACTION).getTarget());
    }

    @Test
    public void othersPrivmsgIsStillFiledUnderTheSender() {
        RecordingClient client = new RecordingClient();
        client.processLine(":server 001 me :Welcome");
        client.processLine(":Luna!u@h PRIVMSG me :hey");
        assertEquals("Luna", client.last(SimpleIrcClient.IrcEvent.Type.MESSAGE).getTarget());
    }

    @Test
    public void liveTimeTagIsPassedThrough() {
        RecordingClient client = new RecordingClient();
        client.processLine("@time=2026-10-01T12:00:00.000Z :Ash!u@h PRIVMSG #chan :old news");
        assertEquals("2026-10-01T12:00:00.000Z",
                client.last(SimpleIrcClient.IrcEvent.Type.MESSAGE).getAdditionalData());
        client.processLine(":Ash!u@h PRIVMSG #chan :no tag");
        assertNull(client.last(SimpleIrcClient.IrcEvent.Type.MESSAGE).getAdditionalData());
    }

    @Test
    public void zncPlaybackBatchBecomesAHistoryBatch() {
        RecordingClient client = new RecordingClient();
        client.processLine(":irc.znc.in BATCH +pb1 znc.in/playback #chan");
        client.processLine("@batch=pb1;time=2026-10-01T12:00:00.000Z :Ash!u@h PRIVMSG #chan :while you were away");
        client.processLine(":irc.znc.in BATCH -pb1");
        SimpleIrcClient.IrcEvent batch = client.last(SimpleIrcClient.IrcEvent.Type.HISTORY_BATCH);
        assertNotNull(batch);
        assertEquals("#chan", batch.getTarget());
        assertEquals(1, batch.getHistoryMessages().size());
        assertEquals("while you were away", batch.getHistoryMessages().get(0).getMessage());
    }
}

package com.irc;

import com.google.gson.Gson;
import net.runelite.client.events.ConfigChanged;
import org.junit.Test;

import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

import static org.junit.Assert.*;

/** Turning SwiftIRC's own connection off, and choosing which network feeds the game chat. */
public class SwiftIrcSwitchTest {
    private static final String ZNC = "znc-id";

    /** A config whose two new settings can be flipped between calls. */
    private static class Settings implements IrcConfig {
        boolean swiftIrcEnabled = true;
        String inGameNetwork = NetworkConfig.SWIFTIRC_ID;
        String networks = "";

        @Override public String username() { return "me"; }
        @Override public String password() { return ""; }
        @Override public boolean swiftIrcEnabled() { return swiftIrcEnabled; }
        @Override public String inGameNetwork() { return inGameNetwork; }
        @Override public String networks() { return networks; }
    }

    private final List<String> calls = new ArrayList<>();
    private final Settings settings = new Settings();

    private IrcPlugin plugin() throws Exception {
        NetworkManager networks = new NetworkManager(new NetworkManager.Connector() {
            @Override public IrcAdapter open(NetworkConfig network) {
                calls.add("open " + network.getId());
                return new IrcAdapter();
            }
            @Override public void close(IrcAdapter adapter, NetworkConfig network, boolean removed, String reason) {
                calls.add("close " + network.getId());
            }
        });
        IrcPlugin plugin = new IrcPlugin();
        set(plugin, "config", settings);
        set(plugin, "gson", new Gson());
        set(plugin, "networks", networks);
        return plugin;
    }

    private static void set(Object target, String name, Object value) throws Exception {
        Field field = IrcPlugin.class.getDeclaredField(name);
        field.setAccessible(true);
        field.set(target, value);
    }

    private static Object call(IrcPlugin plugin, String name) throws Exception {
        Method method = IrcPlugin.class.getDeclaredMethod(name);
        method.setAccessible(true);
        return method.invoke(plugin);
    }

    private static ConfigChanged changed(String key) {
        ConfigChanged event = new ConfigChanged();
        event.setGroup("irc");
        event.setKey(key);
        return event;
    }

    @Test
    public void swiftIrcFollowsItsConnectAutomaticallySetting() {
        assertTrue(NetworkConfig.swiftIrc(settings).isEnabled());
        settings.swiftIrcEnabled = false;
        assertFalse(NetworkConfig.swiftIrc(settings).isEnabled());
    }

    @Test
    public void aDisabledSwiftIrcDoesNotConnectAndTheSwitchTakesEffectLive() throws Exception {
        settings.swiftIrcEnabled = false;
        IrcPlugin plugin = plugin();
        call(plugin, "applyNetworks");
        assertTrue(calls.isEmpty());

        settings.swiftIrcEnabled = true;
        plugin.onConfigChanged(changed("swiftIrcEnabled"));
        assertEquals(Collections.singletonList("open swiftirc"), calls);

        settings.swiftIrcEnabled = false;
        plugin.onConfigChanged(changed("swiftIrcEnabled"));
        assertEquals("close swiftirc", calls.get(calls.size() - 1));
    }

    @Test
    public void onlyTheChosenNetworksLiveTrafficEchoesInGame() {
        IrcMessage live = new IrcMessage("#rshelp", "Ash", "hi", IrcMessage.MessageType.CHAT, Instant.now());
        assertTrue(IrcPlugin.echoesInGame(live, NetworkConfig.SWIFTIRC_ID));
        assertFalse(IrcPlugin.echoesInGame(live, ZNC));
        assertTrue(IrcPlugin.echoesInGame(live.withNetworkId(ZNC), ZNC));
        assertFalse(IrcPlugin.echoesInGame(new IrcMessage("#rshelp", "Ash", "old",
                IrcMessage.MessageType.HISTORY, Instant.now()).withNetworkId(ZNC), ZNC));
    }

    @Test
    public void theInGameNetworkFallsBackToSwiftIrcWhenItIsGone() throws Exception {
        settings.networks = "[{\"id\":\"" + ZNC + "\",\"name\":\"ZNC\",\"host\":\"znc.example\",\"enabled\":false}]";
        IrcPlugin plugin = plugin();
        call(plugin, "applyNetworks");

        settings.inGameNetwork = ZNC;
        assertEquals(ZNC, call(plugin, "inGameNetwork"));
        settings.inGameNetwork = "removed-id";
        assertEquals(NetworkConfig.SWIFTIRC_ID, call(plugin, "inGameNetwork"));
    }
}

package com.irc;

import org.junit.Before;
import org.junit.Test;

import java.util.Arrays;
import java.util.List;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

public class TabCompleterTest {

    private static final List<String> NICKS = Arrays.asList("bob", "Bobby", "alice");
    private static final List<String> CHANNELS = Arrays.asList("#runescape", "#rs", "#help");

    private TabCompleter completer;

    @Before
    public void setUp() {
        completer = new TabCompleter();
    }

    private String complete(String text, int caret, boolean forward) {
        TabCompleter.Result result = completer.complete(text, caret, NICKS, CHANNELS, forward);
        return result == null ? null : result.text + "|" + result.caret;
    }

    private String complete(String text) {
        return complete(text, text.length(), true);
    }

    @Test
    public void nickAtLineStartGetsAColon() {
        assertEquals("alice: |7", complete("al"));
    }

    @Test
    public void nickMidLineGetsASpace() {
        assertEquals("hi alice |9", complete("hi al"));
    }

    @Test
    public void matchingIsCaseInsensitiveAndKeepsTheNicksCasing() {
        assertEquals("Bobby: |7", complete("BOBB"));
    }

    @Test
    public void channelsCompleteFromHash() {
        assertEquals("join #help |11", complete("join #he"));
    }

    @Test
    public void channelAtLineStartGetsNoColon() {
        assertEquals("#help |6", complete("#he"));
    }

    @Test
    public void repeatedTabCyclesThroughMatchesAndWraps() {
        assertEquals("bob: |5", complete("bo"));
        assertEquals("Bobby: |7", complete("bob: ", 5, true));
        assertEquals("bob: |5", complete("Bobby: ", 7, true));
    }

    @Test
    public void shiftTabCyclesBackwards() {
        assertEquals("Bobby: |7", complete("bo", 2, false));
        assertEquals("bob: |5", complete("Bobby: ", 7, false));
    }

    @Test
    public void anEditStartsAFreshCompletion() {
        assertEquals("bob: |5", complete("bo"));
        assertEquals("bob: alice |11", complete("bob: al"));
    }

    @Test
    public void completesTheWordBeforeTheCaretAndKeepsTheRest() {
        assertEquals("alice: how are you|6", complete("al how are you", 2, true));
        assertEquals("hi alice how are you|8", complete("hi al how are you", 5, true));
    }

    @Test
    public void nothingToCompleteLeavesTheInputAlone() {
        assertNull(complete(""));
        assertNull(complete("hello "));
        assertNull(complete("zed"));
    }

    /** The input box is shared, so Tab after switching buffers must complete from the new buffer's nicks. */
    @Test
    public void cyclingAfterABufferSwitchUsesTheNewBuffersNicks() {
        assertEquals("bob: |5", complete("bo"));
        TabCompleter.Result result = completer.complete("bob: ", 5, Arrays.asList("boris", "alice"), CHANNELS, true);
        assertEquals("boris: |7", result.text + "|" + result.caret);
    }

    @Test
    public void cyclingStopsWhenNoMatchesAreLeft() {
        assertEquals("bob: |5", complete("bo"));
        assertNull(completer.complete("bob: ", 5, Arrays.asList("alice"), CHANNELS, true));
    }

    /** Someone unrelated joining mid-cycle must not restart the cycle. */
    @Test
    public void anUnrelatedRosterChangeKeepsCycling() {
        assertEquals("bob: |5", complete("bo"));
        TabCompleter.Result result = completer.complete("bob: ", 5, Arrays.asList("bob", "Bobby", "alice", "zed"), CHANNELS, true);
        assertEquals("Bobby: |7", result.text + "|" + result.caret);
    }
}

package com.irc;

import com.google.gson.Gson;
import org.junit.Test;

import javax.net.ssl.SSLSocket;
import javax.net.ssl.SSLSocketFactory;
import java.security.cert.X509Certificate;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

import static org.junit.Assert.*;

/** The per-network "Verify TLS certificate" option, from storage down to the socket. */
public class TlsVerificationTest {
    private static final String WARNING = "TLS certificate verification is off for this network.";

    private static NetworkConfig znc() {
        return NetworkConfig.builder().id("z1").name("ZNC").host("10.0.0.5").port(1025).build();
    }

    private static IrcConfig stubConfig() {
        return new IrcConfig() {
            @Override public String username() { return "me"; }
            @Override public String password() { return ""; }
        };
    }

    @Test
    public void verificationIsOnByDefaultAndForSwiftIrc() {
        assertTrue(znc().isVerifyTls());
        assertTrue(NetworkConfig.swiftIrc(stubConfig()).isVerifyTls());
    }

    @Test
    public void aSavedNetworkWithoutTheSettingStillVerifies() {
        List<NetworkConfig> parsed = NetworkStore.parse(new Gson(),
                "[{\"id\":\"z1\",\"name\":\"ZNC\",\"host\":\"10.0.0.5\"}]");
        assertTrue(parsed.get(0).isVerifyTls());
    }

    @Test
    public void theSettingRoundTrips() {
        Gson gson = new Gson();
        NetworkConfig unverified = znc().toBuilder().verifyTls(false).build();
        assertEquals(Collections.singletonList(unverified),
                NetworkStore.parse(gson, NetworkStore.serialize(gson, Collections.singletonList(unverified))));
    }

    @Test
    public void changingItNeedsAReconnect() {
        assertTrue(znc().connectionDiffers(znc().toBuilder().verifyTls(false).build()));
    }

    @Test
    public void unverifiedSocketsSkipTheHostnameCheck() throws Exception {
        SSLSocket verified = (SSLSocket) SSLSocketFactory.getDefault().createSocket();
        SimpleIrcClient.applyTlsSettings(verified, true);
        assertEquals("HTTPS", verified.getSSLParameters().getEndpointIdentificationAlgorithm());

        SSLSocket unverified = (SSLSocket) SimpleIrcClient.socketFactory(false).createSocket();
        SimpleIrcClient.applyTlsSettings(unverified, false);
        assertNull(unverified.getSSLParameters().getEndpointIdentificationAlgorithm());
    }

    @Test
    public void theUnverifiedTrustManagerAcceptsAnyChain() throws Exception {
        SimpleIrcClient.TRUST_ANY.checkServerTrusted(new X509Certificate[0], "RSA");
        assertEquals(0, SimpleIrcClient.TRUST_ANY.getAcceptedIssuers().length);
    }

    @Test
    public void theAdapterPassesTheSettingToItsClient() {
        IrcAdapter adapter = new IrcAdapter();
        adapter.initialize(stubConfig(), znc().toBuilder().verifyTls(false).build(), m -> { }, null, "me");
        assertFalse(adapter.getClient().isVerifyingTls());
    }

    @Test
    public void anUnverifiedConnectionWarnsInItsSystemBufferOnRegistration() {
        assertEquals(1, warningsOnConnect(znc().toBuilder().verifyTls(false).build()));
        assertEquals(0, warningsOnConnect(znc()));
        // Without TLS there is no certificate to verify, so nothing to warn about.
        assertEquals(0, warningsOnConnect(znc().toBuilder().tls(false).verifyTls(false).build()));
    }

    private static int warningsOnConnect(NetworkConfig network) {
        List<IrcMessage> messages = new ArrayList<>();
        IrcAdapter adapter = new IrcAdapter();
        adapter.initialize(stubConfig(), network, messages::add, null, "me");
        adapter.getClient().processLine(":server 001 me :Welcome");
        int warnings = 0;
        for (IrcMessage message : messages) {
            if (WARNING.equals(message.getContent())) {
                assertEquals("System", message.getChannel());
                assertEquals(network.getId(), message.getNetworkId());
                warnings++;
            }
        }
        return warnings;
    }
}

package com.irc;

import org.junit.Test;

import javax.swing.JPanel;
import java.awt.BorderLayout;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.FlowLayout;

import static org.junit.Assert.assertEquals;

public class WrapLayoutTest {
    /** Four 50x10 items, 4px gaps: one row needs 4*50 + 3*4 + 2*4 = 220 wide. */
    private static JPanel items() {
        JPanel panel = new JPanel(new WrapLayout(FlowLayout.LEFT, 4, 4));
        for (int i = 0; i < 4; i++) {
            JPanel item = new JPanel();
            item.setPreferredSize(new Dimension(50, 10));
            panel.add(item);
        }
        return panel;
    }

    /** Lays {@code panel} out along the bottom of a parent {@code width} wide, as the pop-out does. */
    private static JPanel inParent(JPanel panel, int width) {
        JPanel parent = new JPanel(new BorderLayout());
        parent.add(panel, BorderLayout.SOUTH);
        parent.setSize(width, 300);
        parent.doLayout();
        return parent;
    }

    @Test
    public void staysOnOneRowWhenThereIsRoom() {
        JPanel panel = items();
        assertEquals(new Dimension(220, 18), panel.getPreferredSize());
        inParent(panel, 400);
        assertEquals(18, panel.getPreferredSize().height);
    }

    @Test
    public void wrapsOntoMoreRowsAsTheParentNarrows() {
        JPanel panel = items();
        inParent(panel, 200);
        assertEquals("two rows of three and one", 32, panel.getPreferredSize().height);
        inParent(panel, 100);
        assertEquals("one item a row", 60, panel.getPreferredSize().height);
    }

    @Test
    public void theWrappedRowsAreLaidOutBelowEachOther() {
        JPanel panel = items();
        JPanel parent = inParent(panel, 120);
        panel.doLayout();
        Component first = panel.getComponent(0);
        Component third = panel.getComponent(2);
        assertEquals(parent.getHeight() - panel.getHeight(), panel.getY());
        assertEquals(first.getX(), third.getX());
        assertEquals(first.getY() + 14, third.getY());
    }
}

